UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Garrick Padfoot - a cutthroat who''s plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain''s head, and earn his bounty!$B$BBut be wary, $n.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.', `VerifiedBuild`=19034 WHERE `ID`=6; -- Bounty on Garrick Padfoot
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `AllowableRaces`=-1, `QuestDescription`='Your first task is one of cleansing, $n.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.', `VerifiedBuild`=19034 WHERE `ID`=7; -- [DEPRECATED] Kobold Camp Cleanup
