UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `AllowableRaces`=-1, `QuestDescription`='$n, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.$B$BGo to the mine and remove them.  We know there are at least 8.  Kill them, see if there are more, then report back to me.', `VerifiedBuild`=19034 WHERE `ID`=15; -- [DEPRECATED] Investigate Echo Ridge
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.$B$BWaste no time, $n.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.', `VerifiedBuild`=19034 WHERE `ID`=21; -- [DEPRECATED] Skirmish at Echo Ridge
