UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Please, $n, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.$B$BShe''s inside our house east of here.', `VerifiedBuild`=19034 WHERE `ID`=111; -- Speak with Gramma
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='I find myself in quite a pinch here, $n.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.$b$bPerhaps you can go to work for me?$b$bI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.', `VerifiedBuild`=19034 WHERE `ID`=116; -- Dry Times
