UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (164 /*Deliveries to Sven*/, 291 /*The Reports*/, 333 /*Harlan Needs a Resupply*/, 360 /*Return to the Magistrate*/, 1184 /*Parts of the Swarm*/, 3568 /*Seeping Corruption*/, 4723 /*Beached Sea Creature*/, 4727 /*Beached Sea Turtle*/, 5881 /*Calling in the Reserves*/, 6281 /*Continue to Stormwind*/, 6323 /*Ride to the Undercity*/, 6362 /*Ride to Thunder Bluff*/, 6384 /*Ride to Orgrimmar*/, 6391 /*Ride to Ironforge*/, 14221 /*Never Surrender, Sometimes Retreat*/, 14293 /*Save Krennan Aranas*/, 14367 /*The Allens' Storm Cellar*/, 14400 /*I Can't Wear This*/, 14403 /*The Hayward Brothers*/, 24578 /*The Blackwald*/);
UPDATE `quest_template` SET `RewardChoiceItemID5`=116202, `RewardChoiceItemQuantity5`=1, `AllowableRaces`=18875469, `QuestDescription`='You have been so very kind to me, $n.  I never dreamed that I''d have so much fun during Children''s Week.  Thank you.$B$BI wish all the orphans were lucky enough to get to do the stuff we did. Do you think we could find Craggle Wobbletop again and get a foam sword rack from him? I think he''s still pushing that cart in the Canals outside the Trade District. That way, everyone else at the orphanage could do something fun too!$B$BAfter that, it''ll be time for me to go home.', `VerifiedBuild`=19034 WHERE `ID`=171; -- A Warden of the Alliance
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='You''re willing to help us here at the orphanage?  Bless you, friend; your aid during Children''s Week will be invaluable.$B$BTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children''s Week itself.  When you use it, you will be able to talk with the child you''ve agreed to look after.  Using it again will dismiss the child.$B$BBy all means $n - use the whistle and meet your ward!  I''m sure the child will be most eager to meet you.', `VerifiedBuild`=19034 WHERE `ID`=172; -- Children's Week
