UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `Flags`=134742016, `QuestDescription`='I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, $n. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn''t hesitate to read it before you go about any other business here in the Abbey.', `VerifiedBuild`=19034 WHERE `ID`=3100; -- Simple Letter
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `Flags`=134742016, `QuestDescription`='I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, $n. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn''t hesitate to read it before you go about any other business here in the Abbey.', `VerifiedBuild`=19034 WHERE `ID`=3101; -- Consecrated Letter
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `Flags`=134742016, `AllowableRaces`=1, `QuestDescription`='I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, $n. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn''t hesitate to read it before you go about any other business here in the Abbey.', `VerifiedBuild`=19034 WHERE `ID`=3102; -- Encrypted Letter
