UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `QuestDescription`='$n, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I''m thinkin'' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar.', `VerifiedBuild`=19034 WHERE `ID`=3106; -- Simple Rune
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `QuestDescription`='$n, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I''m thinkin'' it came from the paladin trainer Bromos. Take a gander at it and go find him inside Anvilmar.', `VerifiedBuild`=19034 WHERE `ID`=3107; -- Consecrated Rune
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `QuestDescription`='$n, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I''m thinkin'' it came from the hunter trainer Thorgas. Take a gander at it and go find him inside Anvilmar.', `VerifiedBuild`=19034 WHERE `ID`=3108; -- Etched Rune
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `AllowableRaces`=4, `QuestDescription`='$n, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I''m thinkin'' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar.', `VerifiedBuild`=19034 WHERE `ID`=3109; -- Encrypted Rune
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `QuestDescription`='$n, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I''m thinkin'' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar.', `VerifiedBuild`=19034 WHERE `ID`=3110; -- Hallowed Rune
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `AllowableRaces`=4, `QuestDescription`='While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I''m thinkin'' it came from the warlock trainer Saripal. Take a gander at it and go find her inside Anvilmar when you''ve a chance.$B$BAnd watch yerself, $n, your kind ain''t too trusted ''round these parts.', `VerifiedBuild`=19034 WHERE `ID`=3115; -- Tainted Rune
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `Flags`=786432, `AllowableRaces`=8, `VerifiedBuild`=19034 WHERE `ID` IN (3116 /*Simple Sigil*/, 3120 /*Verdant Sigil*/);
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `Flags`=786432, `VerifiedBuild`=19034 WHERE `ID` IN (3117 /*Etched Sigil*/, 3118 /*Encrypted Sigil*/, 3119 /*Hallowed Sigil*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, $n. With it, you will have the power to shrink and capture a creature inside of it.$B$BTravel to the wilderness east of here and look for beasts. The vicious, ironfur bears and longtooth runners are your targets, $n. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.', `VerifiedBuild`=19034 WHERE `ID`=3123; -- Testing the Vessel
UPDATE `quest_template` SET `QuestDescription`='$n, I''m a scientist, but also a treasure hunter at heart!$B$BLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz''rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call "Gahz''ridian," after the hydra god.$B$BI did find some myself, but I''d like to have some more to study -- maybe you can find some?$B$BI even invented a detector that makes finding the Gahz''ridian a snap! Just put it on, and the search begins! ', `VerifiedBuild`=19034 WHERE `ID`=3161; -- Gahz'ridian
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Your time with me is over, $n.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.', `VerifiedBuild`=19034 WHERE `ID`=3261; -- [DEPRECATED in 4.x] Jorn Skyseer
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...$B$BThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.$B$BAmnennar has a direct telepathic link to Ner''zhul; we must sever this bond, $n. An end must come to the Coldbringer.', `VerifiedBuild`=19034 WHERE `ID`=3341; -- Bring the End
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='I was on my way to join my fellow gnomes at Gnomeregan, but then it all went so horribly wrong!$b$bI left Anvilmar, bags packed and wading through waist-deep snow.  Then we had this ridiculous earthquake, and I got all turned around.  I ended up here, and what''s worse: the trolls stole all my stuff!$b$b$n, I''ve obviously proven myself to be quite incompetent over the last day and a half.  Would you mind infiltrating the troll camps southwest of here and returning my stuff to me?', `VerifiedBuild`=19034 WHERE `ID`=3361; -- A Refugee's Quandary
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='Have you ever seen Thistleshrub Valley? It''s a mighty dangerous place, $n.$B$BThose strange beasts there, I don''t trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that''s what I think they were called...$B$BAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there''s no way I''m going back there. But here''s where you come in -- if you clear some of them out, I just might think about going back. What do you think, $n? Help me out?', `VerifiedBuild`=19034 WHERE `ID`=3362; -- Thistleshrub Valley
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I''ll never make it to Anvilmar before the brew runs cold!$B$BYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn''t order "chilly" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.$B$BThanks, $n, and don''t forget to bring me back my mug!', `VerifiedBuild`=19034 WHERE `ID`=3364; -- Scalding Mornbrew Delivery
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=-1, `QuestDescription`='Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter''s day to warm your cackles of yer soul.$B$BHere ya go $n - be a pal and take this empty mug back to Nori for me, would ya now.', `VerifiedBuild`=19034 WHERE `ID`=3365; -- Bring Back the Mug
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.$B$BI do not wish to alarm you, $n, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.$B$BHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more. ', `VerifiedBuild`=19034 WHERE `ID`=3369; -- In Nightmares
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.$B$BI do not wish to alarm you, $n, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... $B$BMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.', `VerifiedBuild`=19034 WHERE `ID`=3370; -- In Nightmares
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='There is an empty, vacuous hole, where my heart used to be, $n. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.$B$BReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius'' men.', `VerifiedBuild`=19034 WHERE `ID`=3371; -- Dwarven Justice
UPDATE `quest_template` SET `QuestDescription`='$n - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.$B$BWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief''s head!$B$BHe will be found in the ravine to the east in their makeshift village.', `VerifiedBuild`=19034 WHERE `ID`=3376; -- Break Sharptusk!
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='There are restless spirits in this world, $n. There are spirits that have been tainted by their isolation, bound to an ancient evil...$B$BI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.$B$BIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.', `VerifiedBuild`=19034 WHERE `ID`=3380; -- The Sunken Temple
UPDATE `quest_template` SET `QuestDescription`='We were just off the coast looking for a safe haven to make anchor. The sun hadn''t been down for more than an hour when they attacked... those damned naga!$B$BI''m not sure what they were looking for, but it''s clear they didn''t find it--they''ve already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.$B$BI''m sorry you''ve come along now, $n, but it''s out of my hands.$B$BAre you ready for the fight of your life?', `VerifiedBuild`=19034 WHERE `ID`=3382; -- A Crew Under Fire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='You have made the right decision, $n.$B$BWe must strike where we will do the most damage: the four sentry towers.$B$BWith the four towers in flames, we can initiate an offensive before they have time to react.$B$BYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.$B$BBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.$B$BThe golems and elementals in these lands should be your first target.', `VerifiedBuild`=19034 WHERE `ID`=3442; -- The Flawless Flame
UPDATE `quest_template` SET `QuestDescription`='My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.$B$BFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.$B$BI warn you though, $n. Great evil lies in the temple. It''s likely that anything valuable will be fervently guarded...', `VerifiedBuild`=19034 WHERE `ID`=3447; -- Secret of the Circle
UPDATE `quest_template` SET `QuestDescription`='Betraying, thieving woman! That''s what I call her--that''s all she''ll ever be!$B$BI may have made a grave mistake, $n. I trusted a blood elf. What''s worse, I trusted a woman!$B$BShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who''s the fool--she''s killed them all.$B$BI want vengeance, $n, but I can''t afford to send anyone else. Find Ag''tor at Valormok, north of the Haldarr Encampment. He''ll tell you more.', `VerifiedBuild`=19034 WHERE `ID`=3504; -- Betrayed
UPDATE `quest_template` SET `QuestDescription`='I admit, $n, I''ve made the most of my situation in Azshara. Belgrom''s punishment has had its share of benefits.$B$BBefore I left, I did some research and you would be surprised how many valuable items are lying around.$B$BI''ll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.$B$BThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we''ll talk some more.', `VerifiedBuild`=19034 WHERE `ID`=3517; -- Stealing Knowledge
UPDATE `quest_template` SET `QuestDescription`='The antidote is ready, $n. Please see that Iverron drinks it.$B$BThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.$B$BSpeed be with you, $n.', `VerifiedBuild`=19034 WHERE `ID`=3522; -- Iverron's Antidote
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!$B$B$n, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.', `VerifiedBuild`=19034 WHERE `ID`=3526; -- Goblin Engineering
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `QuestDescription`='This final tablet goes to someone very dangerous, $n. Heed me when I tell you that I trust this person far less than anyone else I''ve asked you to meet with.$B$BArchmage Xylem has a tower up in the hills overlooking Azshara. He''s human, but he acts like no human I''ve met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.$B$BHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.', `VerifiedBuild`=19034 WHERE `ID`=3561; -- Delivery to Archmage Xylem
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `QuestDescription`='Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.$B$BYou tell her she come back to Orgrimmar fast and Jes''rimon make sure he take good care of her.$B$BTell her that, and maybe in the future I have need of your services again, $n.', `VerifiedBuild`=19034 WHERE `ID`=3563; -- Jes'rimon's Payment to Jediga
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `QuestDescription`='Kim''jael indeed!! Do you know what Kim''jael means to the Blood elves, $n? Little rat... or something like that. The big bullies!$B$BThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said "treasure" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!$B$BGoes to show you, you can''t trust a Blood elf.$B$BThe problem is, they still have my equipment and I can''t get it back. Help me out?', `VerifiedBuild`=19034 WHERE `ID`=3601; -- Kim'jael Indeed!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=85200, `QuestDescription`='Razelikh''s lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $n. Use it on the Altar of the Defiler.$B$BShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.
', `VerifiedBuild`=19034 WHERE `ID`=3628; -- You Are Rakh'likh, Demon
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I''m a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.$B$B$n, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.', `VerifiedBuild`=19034 WHERE `ID`=3629; -- Goblin Engineering
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It''s about the construction of wonderful gadgets and devices that make life better!$B$B$n, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!', `VerifiedBuild`=19034 WHERE `ID`=3630; -- Gnome Engineering
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, $n.$B$BIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.$B$BAlign yourself with the Light, $n; put an end to this evil union.', `VerifiedBuild`=19034 WHERE `ID`=3636; -- Bring the Light
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `QuestDescription`='The gleam in your eye tells me everything; you want to blow things up.  You have budding talent, $n, but I''d like to get some samples of your work so I might examine it for ways to emphasize goblin-oriented techniques.  I''ll need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!$b$bSubmit these items to me and you''ll be an official goblin engineer!', `VerifiedBuild`=19034 WHERE `ID`=3639; -- Show Your Work
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='Wildkin are quite unpredictable creatures, $n. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.$B$BThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.$B$BRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?', `VerifiedBuild`=19034 WHERE `ID`=3661; -- Favored of Elune?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.$B$BIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, $n. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.', `VerifiedBuild`=19034 WHERE `ID`=3701; -- The Smoldering Ruins of Thaurissan
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Let me to be frank with you, $n.  I''m interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle''s resources to procure vast amounts of morrowgrain.  I''m a researcher - curses are my specialty.  I''ve heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.$B$BI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.', `VerifiedBuild`=19034 WHERE `ID`=3791; -- The Mystery of Morrowgrain
UPDATE `quest_template` SET `QuestDescription`='Greetings, $n. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.$B$BYou are probably wondering why I am here and what it is that I want from you - both valid questions.$B$BI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.', `VerifiedBuild`=19034 WHERE `ID`=3801; -- Dark Iron Legacy
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='We must strike at our enemies before they strike at us!$B$BI''ll make this brief, soldier.$B$BThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.$B$BLeave your mark, $n. Cripple their forces and return to me when the job is done.$B$B<Oralius grabs at the air and makes a choking motion.>$B$BI WILL KILL YOU, WINKY!', `VerifiedBuild`=19034 WHERE `ID`=3823; -- Extinguish the Firegut
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='You''ve shown your potential to the Forsaken under normal circumstances $n - now let''s see you under pressure.$B$BThe Rattlecage skeletons, more mindless minions of menace, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.', `VerifiedBuild`=19034 WHERE `ID`=3901; -- Rattling the Rattlecages
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='You''ve shown yourself a dependable $c, $n.  Dependable, and not afraid to get your hands dirty, eh?$B$BI have a friend, Milly Osworth, who''s in some trouble.  She''s over with her wagon on the other side of the abbey, near the stable.  I''m sure she could use a pair of hands like yours.', `VerifiedBuild`=19034 WHERE `ID`=3903; -- Milly Osworth
UPDATE `quest_template` SET `QuestDescription`='Thinking... Thinking... I know I came here for something important...$B$BI have an idea, $n. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.$B$BWhy don''t you go ask her if she knows anything? Oh, but be careful -- she''s always messing with those crazy glowing crystals I''ve seen in the crater. I''m not quite sure what she''s up to in there!', `VerifiedBuild`=19034 WHERE `ID`=3941; -- A Gnome's Assistance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!$B$BFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom''zar, appears.  Defeat him and bring me a piece of his banner as proof.$B$BWe''re counting on you, $n.', `VerifiedBuild`=19034 WHERE `ID`=4021; -- Counterattack!
UPDATE `quest_template` SET `QuestDescription`='I do not know the one you speak of, $n.$B$BBut worry not; if your friend was on a journey to find me, I do know what it was he desired.$B$BIn the heart of Un''Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...$B$BNone... except those with enough power to do so. I can teach you of this power, $n.$B$BFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return.', `VerifiedBuild`=19034 WHERE `ID`=4084; -- Silver Heart
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, $n.$B$BIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.$B$BGo, $n. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.', `VerifiedBuild`=19034 WHERE `ID`=4120; -- The Strength of Corruption
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew''s best recipes, Thunderbrew Lager.  The villains!  They don''t deserve such a fine brew!$B$B$n, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!$B$BPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!', `VerifiedBuild`=19034 WHERE `ID`=4126; -- Hurley Blackbreath
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='To tell you the truth, $n, I''ve never seen any plants like this in my travels. Perhaps I should take a trip to this crater...$B$BAt any rate, I think I know just the thing Muigin''s looking for -- Atal''ai haze. It''s horrid stuff, hard to collect, but it''s just what he needs to control the little monsters.$B$BYou''ll need to visit the temple of Atal''Hakkar in the Swamp of Sorrows. The Atal''ai Haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, $n!', `VerifiedBuild`=19034 WHERE `ID`=4143; -- Haze of Evil
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `QuestDescription`='Long ago, the night elves were called the kaldorei, a name that means "children of the stars." Learning of the past is an important step in your path as a $c, $n, so listen well to what I have to tell you.$B$BThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, $n.$B$BGo out and collect seven small spider legs -- no more than that, and return to me.', `VerifiedBuild`=19034 WHERE `ID`=4161; -- Recipe of the Kaldorei
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It''s maddening!$B$BYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot''s heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un''Goro.  You can place the water in this vial.$B$BPlease, $n, help a poor soul in her quest for happiness!', `VerifiedBuild`=19034 WHERE `ID`=4201; -- The Love Potion
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='<Magistrate Solomon sighs.>$B$BYou must return to the Burning Steppes, $n. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.', `VerifiedBuild`=19034 WHERE `ID`=4223; -- The True Masters
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='What? You thought you were the first? How many soldiers must we lose before Stormwind acts?$B$BWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.$B$BWhat we need is that documentation. Speak with Ragged John, $n. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.', `VerifiedBuild`=19034 WHERE `ID`=4224; -- The True Masters
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Are you sure Pyron said ''Incendius'' when he died?$B$B<Jalinda swallows hard.>$B$BLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?$B$BDo you think you can handle another mission? I don''t have anybody else to send, $n!$B$BWe will never get a team in if Incendius continues to raise Pyron from the ashes.$B$BYou''ll have to find and destroy Lord Incendius!
', `VerifiedBuild`=19034 WHERE `ID`=4263; -- Incendius!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='I''m sure you''ve noticed ''em, $n. They''re everywhere!$B$BWhat am I talking about? Why, the crystals, of course!$B$BThe crystals... They''re all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I''ve been doing experiments here with them for a while, but I can''t seem to find anything. Well, I haven''t yet, anyway.$B$BSay, I''m running a little low on the crystals I have here -- think you might be able to collect some more for me?', `VerifiedBuild`=19034 WHERE `ID`=4284; -- Crystals of Power
UPDATE `quest_template` SET `QuestDescription`='What could they be for? I can''t get the thought out of my head!$B$BIt''s driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I''ll usually believe anything people tell me.$B$BAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, $n. I just know they exist.', `VerifiedBuild`=19034 WHERE `ID`=4285; -- The Northern Pylon
UPDATE `quest_template` SET `QuestDescription`='During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, $n. I guess that they are quite large, with crystals lining their interiors.$B$BAlthough I''ve never seen one, I can''t help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found$B$BSo why don''t you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?', `VerifiedBuild`=19034 WHERE `ID`=4287; -- The Eastern Pylon
UPDATE `quest_template` SET `QuestDescription`='My experiments so far have not yielded any positive results, $n. I can''t help but hope that you can find a solution by searching for one of the pylons that I have heard exist.$B$BPerhaps if we combine certain colors at them... but I get ahead of myself. Let''s find them first!$B$B$n, search the western area of the crater; a pylon is said to be somewhere in that area.', `VerifiedBuild`=19034 WHERE `ID`=4288; -- The Western Pylon
UPDATE `quest_template` SET `QuestDescription`='I''m actually surprised he has not come for you yet, $n. But all is well, for I have a final plan that will bring the monster to us.$B$BBeing the dominant male gives Lar''korwi rights to breed with any female he chooses--and he chooses many of them. You''ll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.', `VerifiedBuild`=19034 WHERE `ID`=4291; -- The Scent of Lar'korwi
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!$B$B<The King sobs.>$B$BAnd now she''s gone, $n!$B$BI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!$B$BKharan is supposedly being held prisoner there... find him! I want answers!', `VerifiedBuild`=19034 WHERE `ID`=4341; -- Kharan Mighthammer
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.$B$BYou may be my last hope, $n. You must rescue my dear daughter, Moira!$B$BThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.$B$BAnd $n, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan''s evil spell!', `VerifiedBuild`=19034 WHERE `ID`=4362; -- The Fate of the Kingdom
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='It sure gets hot out here in the Valley of Trials.$B$B<Galgar wipes his brow.>$B$BIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.$B$BI''ll tell you what, $n. If you bring me 6 cactus apples, I''ll make you a few portions of cactus apple surprise to take with you on your adventures. If you''re interested, you can find cactus apples growing near the cactus plants around here.', `VerifiedBuild`=19034 WHERE `ID` IN (4402 /*Galgar's Cactus Apple Surprise*/, 25136 /*Galgar's Cactus Apple Surprise*/);
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.$B$BThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.$B$BWe must try to purify the flute, $n. Bring me blessed water from the Temple of the Moon in Darnassus.', `VerifiedBuild`=19034 WHERE `ID`=4441; -- [DEPRECATED]Felbound Ancients
UPDATE `quest_template` SET `QuestDescription`='You''ve got to help me, $n! My friend, Ringo left earlier to explore the volcano to the south of here, and he has been gone way too long. I am really worried about him.$B$BDo you think you could find him? Why don''t you take my canteen with you -- if you do find Ringo, I''m sure he''ll need it!', `VerifiedBuild`=19034 WHERE `ID`=4492; -- Lost!
UPDATE `quest_template` SET `QuestDescription`='A friend of mine named Iverron usually visits me at the same time every day. The strange thing is that he hasn''t been by today at all -- he''s several hours late, in fact.$B$BI admit, I am a little worried, $n. Iverron spends a lot of time over by the cave to the north, and I''m sure you know how dangerous it is there -- spiders, everywhere!$B$BIf you happen to be going that way, though, will you keep an eye out for him?', `VerifiedBuild`=19034 WHERE `ID`=4495; -- A Good Friend
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='I''m always looking for a quick way to earn a gold, $n. If you help me with my newest idea, I''ll let you in on a little of the profit. How does that sound to you?$B$BI thought so!$B$BHead to the tar pits in northern Un''Goro Crater, and collect me some tar. Not just any tar, now, you''ll need to get it from the beasts that live around the tar pits. Regular tar just simply isn''t sticky enough.$B$BThe plant-like creatures contain chlorophyll in their skin, and mixed with the tar, it''s super sticky!', `VerifiedBuild`=19034 WHERE `ID`=4504; -- Super Sticky
UPDATE `quest_template` SET `QuestDescription`='Here''s the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I''d say try the hatcheries inside the hive.$B$BUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, $n!', `VerifiedBuild`=19034 WHERE `ID`=4507; -- Pawn Captures Queen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=-1, `QuestDescription`='I''m going to need more samples, $n. But--and I don''t know how to put this--they have to be pure samples. I know, I know. "What does ''pure'' mean, Laris?" I''m not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they''re in. I''ll need to find samples that haven''t been polluted. But where? Where?!$B$BBah! $n, take these containers just in case you find any on your own.', `VerifiedBuild`=19034 WHERE `ID`=4513; -- A Little Slime Goes a Long Way
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Finally, you are of age, $n... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.$B$BYes...$B$B<Kaltunk looks you over.>$B$BYou will do nicely.$B$BNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.$B$B<Kaltunk laughs.>$B$BReport to Gornek, he should be able to assign a task better suited to a young $c. You will find Gornek in the Den, to the west.
', `VerifiedBuild`=19034 WHERE `ID`=4641; -- Your Place In The World
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='You have no doubt seen the worgs which the Blackrock orcs command.$B$BIt is curious - no matter how many we destroy, their numbers never dwindle. My scouts have reported that the worgs are bred, trained, and ultimately exported from Blackrock Spire: capital city of the Blackrock orcs. You must travel to Blackrock Spire and discover the source of this menace. Discover... and destroy.$B$BGood luck, $n. May Cenarius protect you...
', `VerifiedBuild`=19034 WHERE `ID`=4701; -- Put Her Down
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=85200, `QuestDescription`='$n, I''m finally ready for real samples of dragon eggs!  Here, take this collectronic module.  It''s designed to extract a dragon egg and prepare it for transport.  Go back to the Rookery and use the module to collect eggs.$B$BAnd don''t forget to freeze them first, or they might hatch before you can collect them!$B$BWhen you have enough eggs, bring them to me! ', `VerifiedBuild`=19034 WHERE `ID`=4735; -- Egg Collection
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Ah, hello, $n. You''re progressing well in your training. So well in fact that I think you should be rewarded for your hard work--and for not becoming corrupted by the arcane yet.$B$BIf you''re interested, seek out Menara Voidrender in Ratchet. She is currently staying at Strahad Farsan''s tower overlooking the town.$B$BShe''s not very friendly, $n, so don''t expect any praise. But if you work hard, she''ll make sure you''re taken care of.', `VerifiedBuild`=19034 WHERE `ID`=4736; -- In Search of Menara Voidrender
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=-1, `QuestDescription`='There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art.$B$BThat was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there.$B$BOne such relic is Doomrigger''s clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.$B$BThat clasp, $n, is your goal.', `VerifiedBuild`=19034 WHERE `ID`=4764; -- Doomrigger's Clasp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `AllowableRaces`=-1, `QuestDescription`='I''ve been tasked to recruit more wyverns for the master wind riders. Their numbers are growing and I myself hope to become a wind rider one day. However, we cannot train enough wyverns to keep up with the demand. Perhaps you can help me, $n.$B$BI need you to travel to Highperch to gather some wyvern eggs. From here, head northwest along the canyon walls to a ramp that will lead you into Highperch. Be careful, wyverns are very protective over their eggs and they will not be kind to intruders.', `VerifiedBuild`=19034 WHERE `ID`=4767; -- Wind Rider
UPDATE `quest_template` SET `QuestDescription`='I need only three things now, $n, then we can finish your robe.$B$BFirst, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it.$B$BSecond, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin''s Wall.$B$BFinally, a soul shard created by you.$B$BAfter you have all the components, return here to the tower and I will complete the robe for you.', `VerifiedBuild`=19034 WHERE `ID`=4784; -- Components for the Enchanted Gold Bloodrobe
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='$n, I entreat you to hunt these centaur down. They shall feel the wrath of our revenge. Attack the centaur camp to the north of Freewind Post!  Let wrath guide your hand!
', `VerifiedBuild`=19034 WHERE `ID`=4841; -- Pacify the Centaur
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='Believe it or not, there are people out there willing to pay for the most vile of domesticated beast!$B$BI''d sent Bijou into the Spire to try and collect some of those spire spider eggs but I haven''t heard from her in weeks. Maybe you can help me out?$B$BI''ll tell you what, $n. Go to Blackrock Spire and collect some spire spider eggs for me. Bring them back here and not only will I give you a little cash, but I''ll even domesticate one for you!', `VerifiedBuild`=19034 WHERE `ID`=4862; -- En-Ay-Es-Tee-Why
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles!$B$B<Hagar wipes his brow.>$B$B$n, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!', `VerifiedBuild`=19034 WHERE `ID`=4865; -- Serpent Wild
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=85200, `VerifiedBuild`=19034 WHERE `ID` IN (4866 /*Mother's Milk*/, 5243 /*Houses of the Holy*/, 5282 /*The Restless Souls*/, 12052 /*Harp on This!*/, 12150 /*Reclusive Runemaster*/, 12456 /*The Plume of Alystros*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=85200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (4903 /*Warlord's Command*/, 5341 /*Barov Family Fortune*/, 5343 /*Barov Family Fortune*/, 6163 /*Ramstein*/, 7481 /*Elven Legends*/, 12427 /*The Conquest Pit: Bear Wrestling!*/);
UPDATE `quest_template` SET `QuestDescription`='Hi, $n.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons.$B$BYou should speak to her in the Burning Steppes, at the Flame Crest.', `VerifiedBuild`=19034 WHERE `ID`=4907; -- Tinkee Steamboil
UPDATE `quest_template` SET `QuestDescription`='Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal!  I can try to keep the passage of time here intact and mend what has been damaged, but I''ll need your help to do so uninterrupted.$B$BTemporal parasites - carrion that feed on the strands of time''s altered flow - now infest the silos of Andorhal.  A blue pulse of distortion is their only visual marker.  They slow my auguries; please $n, help me by using this temporal displacer to root out these parasites.', `VerifiedBuild`=19034 WHERE `ID`=4971; -- A Matter of Time
UPDATE `quest_template` SET `QuestDescription`='While there was little I could do alone to thwart the Scourge, I nevertheless came to these lands to try and heal the damage done to nature.  Animals suffer from the plague that continues to choke these lands, unable to find mercy and peace.  I ask for you to continue what I could not finish here.$B$BThere is no salvation for the suffering animals but a sweet and merciful release.  Seek out diseased wolves nearby and put them down.  Please $n, end their misery - doing so will surely soothe mine.', `VerifiedBuild`=19034 WHERE `ID`=4984; -- The Wildlife Suffers Too
UPDATE `quest_template` SET `RewardBonusMoney`=70800, `VerifiedBuild`=19034 WHERE `ID` IN (5056 /*Shy-Rotam*/, 6821 /*Eye of the Emberseer*/);
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='$n, you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks. We discovered that separate chests in Darkcloud Pinnacle hold these guarded messages.$b$b$n, if you succeed in this dangerous mission, I will reward you in kind.
', `VerifiedBuild`=19034 WHERE `ID`=5064; -- Grimtotem Spying
UPDATE `quest_template` SET `QuestDescription`='This greenish liquid... it reminds me a bit of the sludge I saw when traveling through Felwood. And I have seen some Winterfall Runners passing into Timbermaw... Perhaps these things have something to do with the flask you found, $n.$B$BThere is a large group of furbolg just past Timbermaw Hold, in Felwood. Called the Deadwood tribe, they have been corrupted and driven mad by the fel. Why don''t you look around there and see if you can find any evidence of dealings between the Winterfall and the Deadwood?', `VerifiedBuild`=19034 WHERE `ID`=5084; -- [DEPRECATED]Falling to Corruption
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead.$B$BThe enchantment that I have weaved into the Incendia powder will summon Arikara to you, $n.$B$BI fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, $c!', `VerifiedBuild`=19034 WHERE `ID`=5088; -- Arikara
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (5089 /*General Drakkisath's Command*/, 7202 /*Korrak the Bloodrager*/, 7782 /*The Lord of Blackrock*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `VerifiedBuild`=19034 WHERE `ID` IN (5101 /*Lee's Ultimate Test Quest... of Doom!*/, 11917 /*Striking Back*/, 11947 /*Striking Back*/, 11948 /*Striking Back*/, 11952 /*Striking Back*/, 14341 /*Smeed's Harnesses*/, 24463 /*Probing into Ashenvale*/, 24921 /*Report to Aubrey*/, 25035 /*Breaking the Line*/, 26385 /*Breaking Waves of Change*/, 26408 /*Ashes in Ashenvale*/, 26957 /*The Long Trip Home*/);
UPDATE `quest_template` SET `QuestDescription`='Oh, I''m so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him?$B$BMaybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill.$B$BPlease, $n.  You''re my new friend!  Will you talk to my Auntie for me?', `VerifiedBuild`=19034 WHERE `ID`=5152; -- Auntie Marlene
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='To the north, along the east of the road in what''s called Shatter Scar Vale, is an area where infernals were called down during the last great war--the craters still scar the land, as do the infernals themselves.$B$BI am curious about two things. First, are there still entropic elementals roaming the area? And second, are the craters still filled with the corrupt, fetid water that gathered there years ago? Will you help me and check, $n? Be careful though, the infernals destroy anything in their path.', `VerifiedBuild`=19034 WHERE `ID`=5156; -- [DEPRECATED]Verifying the Corruption
UPDATE `quest_template` SET `QuestDescription`='Take the corrupt water to the Barrens, $n. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task.$B$BYou should find her at a small camp right along the water''s edge. And, $n, ignore the pirates... they are but a nuisance and no threat to you.', `VerifiedBuild`=19034 WHERE `ID`=5158; -- [DEPRECATED]Seeking Spiritual Aid
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `VerifiedBuild`=19034 WHERE `ID` IN (5160 /*The Matron Protectorate*/, 8053 /*Paragons of Power: The Freethinker's Armguards*/, 8054 /*Paragons of Power: The Freethinker's Belt*/, 8055 /*Paragons of Power: The Freethinker's Breastplate*/, 8056 /*Paragons of Power: The Augur's Bracers*/, 8057 /*Paragons of Power: The Haruspex's Bracers*/, 8058 /*Paragons of Power: The Vindicator's Armguards*/, 8059 /*Paragons of Power: The Demoniac's Wraps*/, 8060 /*Paragons of Power: The Illusionist's Wraps*/, 8061 /*Paragons of Power: The Confessor's Wraps*/, 8062 /*Paragons of Power: The Predator's Bracers*/, 8063 /*Paragons of Power: The Madcap's Bracers*/, 8064 /*Paragons of Power: The Haruspex's Belt*/, 8066 /*Paragons of Power: The Predator's Belt*/, 8067 /*Paragons of Power: The Predator's Mantle*/, 8068 /*Paragons of Power: The Illusionist's Mantle*/, 8070 /*Paragons of Power: The Confessor's Bindings*/, 8071 /*Paragons of Power: The Confessor's Mantle*/, 8072 /*Paragons of Power: The Madcap's Mantle*/, 8073 /*Paragons of Power: The Madcap's Tunic*/, 8074 /*Paragons of Power: The Augur's Belt*/, 8075 /*Paragons of Power: The Augur's Hauberk*/, 8076 /*Paragons of Power: The Demoniac's Mantle*/, 8077 /*Paragons of Power: The Demoniac's Robes*/, 8078 /*Paragons of Power: The Vindicator's Belt*/, 8288 /*Only One May Rise*/, 8301 /*The Path of the Righteous*/, 8579 /*Mortal Champions*/, 8697 /*Ring of Infinite Wisdom*/, 8747 /*The Path of the Protector*/, 8748 /*The Path of the Protector*/, 8749 /*The Path of the Protector*/, 8750 /*The Path of the Protector*/, 8752 /*The Path of the Conqueror*/, 8753 /*The Path of the Conqueror*/, 8754 /*The Path of the Conqueror*/, 8755 /*The Path of the Conqueror*/, 8757 /*The Path of the Invoker*/, 8758 /*The Path of the Invoker*/, 8759 /*The Path of the Invoker*/, 8760 /*The Path of the Invoker*/, 9023 /*The Perfect Poison*/, 9033 /*Echoes of War*/, 9126 /*Bonescythe Digs*/, 9128 /*The Elemental Equation*/, 9131 /*Binding the Dreadnaught*/, 9136 /*Savage Flora*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='It''s all ready, $n!$B$BNow, I sent some mail to my friends already, telling them that I have a surprise for them. This is where you come in!$B$BI''m going to give you my mechanical yeti, and you need to surprise them by paying each of my friends a visit, turning the yeti on and sending it towards them.$B$B Once you have shown Legacki in Everlook, Sprinkle in Gadgetzan, and Quixxil in Marshal''s Refuge, come back and tell me what happened!$B$BPlease bring my yeti back to me then, too.', `VerifiedBuild`=19034 WHERE `ID`=5163; -- [DEPRECATED]Are We There, Yeti?
UPDATE `quest_template` SET `QuestDescription`='The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales.$B$BIt tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen.$B$BIts passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron''s Withering.$B$BGather these relics, $n.  For fate and tragedy surrounds them.', `VerifiedBuild`=19034 WHERE `ID`=5168; -- Heroes of Darrowshire
UPDATE `quest_template` SET `QuestDescription`='The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin''s Crossing, and his skull remains there.$B$BMarduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin''s Crossing.$B$BRetrieve these items, $n.  I know not why, but I am certain their fate lies with you.', `VerifiedBuild`=19034 WHERE `ID`=5181; -- Villains of Darrowshire
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='My presence goes unnoticed by most, $n. However, there is an annoyance that seems firmly rooted here in Winterspring: the Winterfall furbolg.$B$BAlthough I have never directly attacked the furbolg, they seem crazed, fearful of anything in their path. I have watched them slay countless creatures that had the misfortune to simply be in the wrong place at the wrong time.$B$BI am weary of their meddling -- please, help me by fighting back. Slay the furbolg and keep them away from Frostsaber Rock.', `VerifiedBuild`=19034 WHERE `ID`=5201; -- Winterfall Intrusion
UPDATE `quest_template` SET `QuestDescription`='She would like to pretend that she''s fine. She''d love for me to think that she''s strong enough to deal with all of this on her own, but I know better than that. Trey''s death and hearing the torture he was put through is going to haunt her for a long time, and there''s nothing we can do to stop that. But we can give her some peace!$B$B$n, return to Shadow Hold, kill Trey''s torturer and find his remains. There is no reason we can''t tie off all these loose ends while Arko''narin mourns in her own private way.', `VerifiedBuild`=19034 WHERE `ID`=5204; -- [DEPRECATEDRetribution of the Light
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=85200, `QuestDescription`='The Forsaken apothecaries are not the only beings in this world schooled in the sciences.$B$BI have been studying the plague for years, $r. We had previously thought that the potency of the plague was dwindling, but what I have discovered here in the Plaguelands is startling. The plague seems to be growing in strength!$B$BI need to run more tests! The most potent source of the plague is from the tainted flesh of the most recently infected. Travel to Stratholme and bring me samples, $n.
', `VerifiedBuild`=19034 WHERE `ID`=5212; -- The Flesh Does Not Lie
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='You will have to delve deeper into Stratholme, $n.$B$BBeyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover.
', `VerifiedBuild`=19034 WHERE `ID`=5213; -- The Active Agent
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='Terrible thing... what happened to Fras. You see, the town was sacked and Fras didn''t want to leave his precious goods behind. The last thing I remember him saying was, ''I''ll burn every last leaf before they get their damned, dirty hands on them!''$B$BI may love a good stogie but I''m no fool. I left Fras and his delightful store that day. I assume he went down in flames but if there''s a chance that even one box of his famous tobacco is still intact...$B$BWhat do you say, $n? Find a box for ol'' Smokey?', `VerifiedBuild`=19034 WHERE `ID`=5214; -- The Great Fras Siabi
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Two cauldrons have been successfully opened; while you will be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!$B$BThis time, you''ll be hitting the Writhing Haunt''s cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.$B$BGood hunting, $n!', `VerifiedBuild`=19034 WHERE `ID`=5222; -- Target: Writhing Haunt
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='The last cauldron that remains is located on a farm now called Gahrron''s Withering.  It is guarded by some of the Scourge''s tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $n.$B$BGahrron''s Withering is due northeast of our position here, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the Light protect you in this dangerous mission, $c.', `VerifiedBuild`=19034 WHERE `ID`=5225; -- Target: Gahrron's Withering
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='The last cauldron that remains is located on a farm now called Gahrron''s Withering.  It is guarded by some of the Scourge''s tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $n.$B$BGahrron''s Withering is far to the east of the Bulwark, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the shadows cloak you in safety for this dangerous mission, $c.', `VerifiedBuild`=19034 WHERE `ID`=5235; -- Target: Gahrron's Withering
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=85200, `QuestDescription`='Anything taken to an extreme is hazardous to our world, $n. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?$B$BBlasphemers, one and all!$B$BOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade''s most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded.', `VerifiedBuild`=19034 WHERE `ID`=5251; -- The Archivist
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='There are those that died tragically in the fall of Stratholme. Many took their own lives, opting to hurl themselves into the myriad flames of the smoldering city rather than become one of the Scourge.$B$BThey now walk the streets of Stratholme as restless spirits.$B$BWe must aid them, $n!$B$BI have an associate named Egan who has been doing miraculous work with ghosts and souls. Seek him out. He walks the eastern Plaguelands, near Stratholme, testing his innovations.', `VerifiedBuild`=19034 WHERE `ID`=5281; -- The Restless Souls
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='As a weaponsmith you''ll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.$B$BOh yes, $n, weaponsmiths are the ones with all the gold!$B$BIf you wish to join our ranks, you''ll need to show me that you can make me a silver or two - I mean, show me that you''ve got what it takes to be the go to $g guy:girl; when people need superior quality weapons. Get to work!', `VerifiedBuild`=19034 WHERE `ID`=5284; -- The Way of the Weaponsmith
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=70800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=5344; -- The Last Barov
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='This is it, $n.$B$B<Eva points to the vial inside the bag.>$B$BThe blood of innocents. The purest blood, used to appease Krastinov''s master.$B$BIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.$B$BTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.$B$BShould you succeed, you will earn more than just our gratitude.', `VerifiedBuild`=19034 WHERE `ID`=5384; -- Kirtonos the Herald
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='So you can see the predicament that I''m in, $n. That thing is out there collecting the wrong weeds! I''ll make it worth your while to gather what I need. Bring back to me enough doom weed and I''ll give you a suitable reward.$B$BIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.', `VerifiedBuild`=19034 WHERE `ID`=5482; -- Doom Weed
UPDATE `quest_template` SET `RewardBonusMoney`=2340, `RewardChoiceItemID5`=116202, `RewardChoiceItemQuantity5`=1, `AllowableRaces`=33555378, `QuestDescription`='You have been so very kind to me, $n.  I never dreamed that I''d have so much fun during Children''s Week.  Thank you.$B$BI wish all the orphans were lucky enough to get to see all the stuff we did. Do you think we find Blax Bottlerocket again and get a foam sword rack from him? I think he''s still pushing that cart up and down the main road in the Drag. That way, everyone else at the orphanage could do something fun too!$B$BAfter that, it''ll be time for me to go home.', `VerifiedBuild`=19034 WHERE `ID`=5502; -- A Warden of the Horde
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='A great weight has been lifted from our hearts, $n, but your task is not yet complete. Krastinov''s master, Kirtonos, still lives.$B$BBefore you may face Kirtonos, however, you must first secure a method in which to summon him.$B$BIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.$B$BFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.', `VerifiedBuild`=19034 WHERE `ID`=5515; -- Krastinov's Bag of Horrors
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=5518; -- The Gordok Ogre Suit
UPDATE `quest_template` SET `RewardBonusMoney`=70800, `QuestDescription`='$G Brother : Sister; $n - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I''ll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn''s heroes!$B$BBring to me twenty-five valor tokens as a sign of tribute, and I''ll give you the finest of all our mantles.', `VerifiedBuild`=19034 WHERE `ID`=5521; -- Chromatic Mantle of the Dawn
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='Your knowledge of Eldre''Thalas - Dire Maul - in Feralas will now come into play, $n.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you.$B$BThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me.$B$BGood luck, and Cenarion''s speed.', `VerifiedBuild`=19034 WHERE `ID`=5526; -- Shards of the Felvine
UPDATE `quest_template` SET `RewardMoney`=-149999, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=5538; -- Mold Rhymes With...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he''s always needing fresh ammunition.$B$BBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot''s ammo behind!$B$B$n, can you get that ammo and take it to Rumbleshot?  He''s been waiting on it and I''m sure he''s running low.', `VerifiedBuild`=19034 WHERE `ID`=5541; -- Ammo for Rumbleshot
UPDATE `quest_template` SET `AllowableRaces`=4, `VerifiedBuild`=19034 WHERE `ID` IN (5625 /*Garments of the Light*/, 14083 /*Learn to Ride in Dun Morogh*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='Time''s come for you to head to Stormwind, $n. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin'' really good or really bad for the High Priestess to want you there personally, but I''m guessin'' you''ve only done well for yourself and it''s a good thing that she wants to speak to ya.$B$BBut don''t waste too much time ''round here. I''d head there as soon as you can.', `VerifiedBuild`=19034 WHERE `ID`=5637; -- Desperate Prayer
UPDATE `quest_template` SET `AllowableRaces`=128, `QuestDescription`='You be ready for your first test, $n. South of Razor Hill, just outta town, one of our grunts be hurt fightin'' off some o'' Proudmoore''s old troops. She not doin'' too well, an'' she benefit much if one of our kind could help her. Find her--her name be Kor''ja--heal her wounds, an'' give her the blessin'' of our ancestors.$B$BYou do this, an'' me thinks that be sufficient proof that you ready to move on in our ways.', `VerifiedBuild`=19034 WHERE `ID`=5648; -- Garments of Spirituality
UPDATE `quest_template` SET `RewardBonusMoney`=70800, `QuestDescription`='Now, $n, you will take part in battle of Darrowshire, and you will save Joseph Redpath.$B$BPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.$B$BAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.', `VerifiedBuild`=19034 WHERE `ID`=5721; -- The Battle of Darrowshire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=-1, `QuestDescription`='One thing I will not tolerate are traitors in our midst, $n. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.$B$BBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.$B$BIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant''s insignia off one of the Burning Blade there, and return to me.', `VerifiedBuild`=19034 WHERE `ID`=5726; -- Hidden Enemies
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.$B$BReturn to the Cleft of Shadow and enter Ragefire Chasm, $n. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his $gbrothers:sisters; in arms.', `VerifiedBuild`=19034 WHERE `ID`=5728; -- Hidden Enemies
UPDATE `quest_template` SET `RewardBonusMoney`=42600, `AllowableRaces`=-1, `QuestDescription`='Araj the Summoner lords over Andorhal from the ruined city''s heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.$B$BMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!$B$BThe Key to Scholomance awaits, $n!', `VerifiedBuild`=19034 WHERE `ID` IN (5803 /*Araj's Scarab*/, 5804 /*Araj's Scarab*/);
UPDATE `quest_template` SET `FlagsEx`=8, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (5805 /*Welcome!*/, 5841 /*Welcome!*/, 5842 /*Welcome!*/, 5843 /*Welcome!*/, 5844 /*Welcome!*/, 5847 /*Welcome!*/);
UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `AllowableRaces`=18875469, `QuestDescription`='Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren''t much of a problem when we had spare troops to guard the mine, but now that we''re fighting with the Horde we can''t maintain control of Irondeep.$B$BWe need the supplies in Irondeep, $n.  Enter the mine and bring me a load of them.', `VerifiedBuild`=19034 WHERE `ID`=5892; -- Irondeep Supplies
UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `AllowableRaces`=33555378, `QuestDescription`='The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...$B$BBut we still need our supplies, $n!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...', `VerifiedBuild`=19034 WHERE `ID`=5893; -- Coldtooth Supplies
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='So, to bring pain and strife to the Scarlet Crusade, I want to take their precious lumber mill from them. I''m sure the loss of such a resource will cause them a great deal of harm in defending and rebuilding the town for their own reasons. Will you help me, $n?$B$BStart by taking this jar to Plaguewood in the Eastern Plaguelands. Fill it with the termites you find in their mounds throughout the woods. Come back when you have enough.', `VerifiedBuild`=19034 WHERE `ID`=5901; -- A Plague Upon Thee
UPDATE `quest_template` SET `QuestDescription`='Directly east of Auberdine lay many moonkin caves.  The one closest to Auberdine has a Moonkin Stone inside it.  Lunaclaw, the defender of the stone, will face you only when Cenarion Moondust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.$B$BYou''ve earned the right to use this Cenarion Moondust, $n... now show me that you''ve earned the right to possess the strength of body and the strength of heart needed as a druid!', `VerifiedBuild`=19034 WHERE `ID`=6001; -- Body and Heart
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='Can you believe that, after all the trouble we have in the plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.$B$BAnd not just normal troll thieves.  Dead troll thieves!$B$BThey''re led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from the pit below, then take them back to their evil, dead troll hideout--the Undercroft to the west.$B$BGo there and take out Zaeldarr, $n.  I''m sick to death of his mischief!', `VerifiedBuild`=19034 WHERE `ID`=6021; -- Zaeldarr the Outcast
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='What? Really? You want to know more? But you''ve already done so much for me, $n. I couldn''t possibly ask you to enter Hearthglen itself on my behalf.$B$BAre you sure, $n? Hearthglen is much more dangerous than the Pass--I cannot provide you any protection  or even information about what you might face.$B$BWell, if you really are willing to help, then enter the town and find a high place to gain a good view of the town. From there you can gauge their numbers and report them back to me. But be careful....', `VerifiedBuild`=19034 WHERE `ID`=6025; -- Unfinished Business
UPDATE `quest_template` SET `RewardBonusMoney`=48900, `VerifiedBuild`=19034 WHERE `ID`=6032; -- Sacred Cloth
UPDATE `quest_template` SET `QuestDescription`='You have a fiery spirit, hunter, readily awaiting your next challenge.$B$BYour next task is to gain the companionship of a wolf known as the prairie stalker. This creature is swift and fearless; in taking this beast as your pet, you must also take on these qualities.$B$BDuring a battle, you will learn how you and your pet will become a team. In the end you must work as one, muscle to muscle.$B$BHere is the taming rod, $n. Tame a prairie stalker and practice your skills.', `VerifiedBuild`=19034 WHERE `ID`=6087; -- Taming the Beast
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='Get me out of here!$B$BI came up to the Valley of Spears to talk to the Maraudines.  I thought I could do a little business with them... but they don''t want to talk!  I think they want to eat me!$B$BGet me out of here and my brother Hornizz will pay you big!  He''s at our camp next to the kodo graveyard, to the east.$B$BLet''s hurry, $n.  Not two minutes ago I heard some centaurs talking about getting wood for their cookpot... ', `VerifiedBuild`=19034 WHERE `ID`=6132; -- Get Me Out of Here!
UPDATE `quest_template` SET `RewardBonusMoney`=42600, `AllowableRaces`=-1, `QuestDescription`='The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.$B$BFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.$B$BGood luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=6184; -- Flint Shadowmore
UPDATE `quest_template` SET `RewardBonusMoney`=70800, `AllowableRaces`=-1, `QuestDescription`='As I said, your first mission is one of reconnaissance. Nothing fancy, $n. You must travel to the Eastern Plaguelands and look for any clues as to this Blightcaller.$B$BBe on the lookout for information about our missing operatives. We have to assume that they are dead and if they are dead, they must have a corpse... somewhere.$B$B<Flint swallows hard.>$B$BAll SI:7 agents carry this insignia.$B$B<Flint shows you his SI:7 insignia.>$B$BBring any of those that you may find back to me.', `VerifiedBuild`=19034 WHERE `ID`=6185; -- The Eastern Plagues
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=-1, `LogDescription`='Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.$B$BKeep your wits about you, $n. The Horde will defend the ranger lord with their very lives.', `QuestDescription`='Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?$B$BNathanos'' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.$B$BAnd now... the champion of the Forsaken.$B$BNo. This cannot be. Order must be restored.$B$BGather an army, $n. Return to the Plagues with your army and destroy the Blightcaller.$B$BI wish you luck, $n. Truly, you will need it for this battle.', `VerifiedBuild`=19034 WHERE `ID`=6187; -- Order Must Be Restored
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='The Timbermaw tend to stay to themselves, $n. While we do allow safe passage to those that have proven they can be trusted, we try to avoid other furbolg tribes if at all possible.$B$BLately I have noticed that the Winterfall tribe has become increasingly hostile towards us. They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.$B$BIf you could reduce their numbers this would help us greatly, $n.', `VerifiedBuild`=19034 WHERE `ID`=6241; -- Winterfall Activity
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='$n, I gathered into this crate everything Lewis asked for.  Can you take it to him?$B$BIf you''ve already spoken to Thor in Westfall, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.$B$BSpeak with Dungar, then get this crate to Lewis as fast as you can.  We don''t want our fighting men and women in Westfall to go without fresh equipment!', `VerifiedBuild`=19034 WHERE `ID`=6261; -- Dungar Longdrink
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Tauren take pride as the protector of these lands. Undoubtedly you can guess why I am alarmed with the number of harpies that dwell here in Stonetalon.$B$BThe Bloodfuries are the source of the increasing number of harpies in Kalimdor; they encroach upon all likes of life preventing the innocent from leaving their boundaries.$B$BI need you to cull the harpies, $n!', `VerifiedBuild`=19034 WHERE `ID`=6282; -- Harpies Threaten
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `AllowableRaces`=-1, `QuestDescription`='Industrial greed and continuous war have wrecked the lands of Stonetalon. Only the blessings of the Earthmother can cure such injury.$B$B$n, I will require you to seek a special seed, the Gaea seed. They are only found here in Stonetalon Mountain, north of Sun Rock Retreat at Mirkfallon Lake, near the water''s edge.$B$BOnce you bring me the seeds I will imbue them with shamanistic power to speed their growth.', `VerifiedBuild`=19034 WHERE `ID`=6301; -- Cycle of Rebirth
UPDATE `quest_template` SET `Flags`=262144, `AllowableRaces`=130, `VerifiedBuild`=19034 WHERE `ID`=6365; -- Meats to Orgrimmar
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='As you have seen, $c, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale. Beware, for harpies and angry fire elementals still plague the scarred land.$B$B$n, take these enchanted Gaea seeds and plant them in fertile mounds of soil. The cycle of life must go on!', `VerifiedBuild`=19034 WHERE `ID`=6381; -- New Life
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='The Tribunal of the Tides has sent me to wage war on the fire elementals here in Stonetalon Mountain. Neptulon the Tidehunter, Lord of all water elementals, has taken a personal interest in seeing our fiery cousins extinguished.$B$B$n, you can help me gain favor with the Tribunal by destroying the fire elementals in Charred Vale. When destroyed, the fire elementals leave Incendrites. Return these to me and be rewarded.', `VerifiedBuild`=19034 WHERE `ID`=6393; -- Elemental War
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='You are to meet with Windsor at the gates of Stormwind.$B$BWhat Windsor is about to unveil will shake the very foundation of the kingdom!$B$BDo not attempt to venture there alone, $n. You must amass an army! Gather your compatriots. To arms! 

', `VerifiedBuild`=19034 WHERE `ID`=6402; -- Stormwind Rendezvous
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Something is amiss here in Stonetalon. Can you feel the tension in the air, $n?$B$BSoutheast of here lies a deep cave in Boulderslide Ravine. The kobolds there are frantically mining a rare crystal called Resonite. I need you to bring back some ore samples so that I can understand what''s happening in that cave.  I also need you to investigate the depth of that cave.$B$BGo young $c, it''s imperative I know what evil lurks under these mountains.', `VerifiedBuild`=19034 WHERE `ID`=6421; -- Boulderslide Ravine
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram''gar!  Those vile furbolgs!$B$BI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!$B$B$n, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.', `VerifiedBuild`=19034 WHERE `ID`=6462; -- Troll Charm
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='You have uncovered a dark threat to the land, $c. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc.$B$BI have changed the mixture of the Resonite crystals that you gathered with my shamanistic powers. Take the enchanted Resonite crystal and smash open the Resonite cask, which houses the Earthen.$B$BWhen awakened, Goggeroc will be weakened... Slay him, $n!', `VerifiedBuild`=19034 WHERE `ID`=6481; -- Earthen Arise
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Eh?  Who are you?$B$B$n?  You''re no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...$B$BHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.$B$B$n! I must escape!', `VerifiedBuild`=19034 WHERE `ID`=6482; -- Freedom to Ruul
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `AllowableRaces`=-1, `QuestDescription`='A fragment of the shattered medallion is all that I can offer.$B$BYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, $n.$B$BWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck.
', `VerifiedBuild`=19034 WHERE `ID`=6501; -- The Dragon's Eye
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (6502 /*Drakefire Amulet*/, 12229 /*A Possible Link*/, 12246 /*A Possible Link*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=-1, `QuestDescription`='Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.$B$BHis presence there does explain much of what we''ve discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they''ve struck.$B$BFind Malcin and slay him, $n. Return to me after the deed is done.', `VerifiedBuild`=19034 WHERE `ID`=6521; -- An Unholy Alliance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Hey!  $C!  Come here!$B$BMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!$B$BDo you want to share in the glory, $n, and aid us?  If so, then when it''s over you can report our success to my superior, Ertog Ragetusk in Splintertree.$B$BWhat do you say.  Are you with us?', `VerifiedBuild`=19034 WHERE `ID`=6544; -- Torek's Assault
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=33555378, `QuestDescription`='Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.$b$bAku''Mai, servant of the Old God, rose from the waters.$b$bThe Twilight''s Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku''Mai for power.$b$bSlay Kelris and bring his head to Bashana in Thunder Bluff, $n, please.', `VerifiedBuild`=19034 WHERE `ID`=6561; -- Blackfathom Villainy
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Je''neu Sancrea is in need of aid. He waits just inside Blackfathom Deeps in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, $n. There are forces there that will not take to your presence kindly.', `VerifiedBuild`=19034 WHERE `ID`=6562; -- Trouble in the Deeps
UPDATE `quest_template` SET `RewardXPDifficulty`=8, `Float10`=0.25, `RewardMoney`=1500, `RewardMoneyDifficulty`=8, `Float13`=0.25, `RewardBonusMoney`=5250, `AllowableRaces`=-1, `QuestDescription`='Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.$B$BWill you help me, $n? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.', `VerifiedBuild`=19034 WHERE `ID`=6563; -- The Essence of Aku'Mai
UPDATE `quest_template` SET `RewardBonusMoney`=33300, `VerifiedBuild`=19034 WHERE `ID`=6607; -- Nat Pagle, Angler Extreme
UPDATE `quest_template` SET `RewardBonusMoney`=8400, `AllowableRaces`=-1, `QuestDescription`='Lumak no can teach $n no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.$B$BYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!', `VerifiedBuild`=19034 WHERE `ID`=6608; -- You Too Good.
UPDATE `quest_template` SET `RewardBonusMoney`=33300, `QuestDescription`='Ever heard of a clamlette? Of course you haven''t! It''s my latest and greatest culinary masterpiece. Oh, $n, just thinking about a clamlette makes my mouth water.$B$BUnfortunately, I''m all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I''ll teach you the finer points of exotic cuisine and I''ll even throw in a couple of clamlettes to boot! Deal??$B$BHere''s what I need:', `VerifiedBuild`=19034 WHERE `ID`=6610; -- Clamlette Surprise
UPDATE `quest_template` SET `RewardBonusMoney`=8400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=6611; -- To Gadgetzan You Go!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='My research has paid off.$b$bI believe that with a show of force, we can diminish the furbolgs'' aggressiveness.$B$BTake this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.$B$BGather your allies, $n. This is no task for a single $c.', `VerifiedBuild`=19034 WHERE `ID`=6621; -- King of the Foulweald
UPDATE `quest_template` SET `RewardBonusMoney`=8400, `AllowableRaces`=-1, `QuestDescription`='Doctor $n, I presume. It is a pleasure to see you again.$B$BI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!', `VerifiedBuild`=19034 WHERE `ID`=6623; -- Horde Trauma
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Doctor $n, I presume. It is a pleasure to see you.$B$BI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!', `VerifiedBuild`=19034 WHERE `ID`=6625; -- Alliance Trauma
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='$n, you''ve done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.$b$bYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.
', `VerifiedBuild`=19034 WHERE `ID`=6629; -- Kill Grundig Darkcloud
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Vorsha the Lasher... the fiendish hydra that roams the seas...$B$BShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.$B$BBut I am ready, $n. I have prepared to best the hydra and end these attacks on Zoram''gar.$B$BThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.$B$BWe will need help, so be sure to bring some strong allies.', `VerifiedBuild`=19034 WHERE `ID`=6641; -- Vorsha the Lasher
UPDATE `quest_template` SET `QuestDescription`='$n,$B$BRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn''t fix.$B$BShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin''s League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.$B$BYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.$B$BRegards,$B$BFahrad', `VerifiedBuild`=19034 WHERE `ID`=6681; -- The Manor, Ravenholdt
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='The Twilight''s Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.$B$B$n, go into Blackfathom and find the ruin''s fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!', `VerifiedBuild`=19034 WHERE `ID`=6921; -- Amongst the Ruins
UPDATE `quest_template` SET `RewardXPDifficulty`=8, `Float10`=0.25, `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=6922; -- Baron Aquanis
UPDATE `quest_template` SET `RewardBonusMoney`=2340, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=6962; -- Treats for Great-father Winter
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='The Coldtooth mine is a storage depot for the Horde.  I can''t stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.$B$BEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde''s warriors.$B$BGood luck, $n.  The mine is to the distant south, deep in Horde territory.', `VerifiedBuild`=19034 WHERE `ID`=6982; -- Coldtooth Supplies
UPDATE `quest_template` SET `RewardBonusMoney`=4650, `RewardItem1`=116762, `AllowableRaces`=33555378, `QuestDescription`='A creature called "The Abominable Greench" stole our shipment of treats, $n.  Be careful though!  He''s vicious and a bunch of those little green gnomes do his bidding!$B$BYou''re gonna need some help in facing him.  Rumor has it he''s holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats $n and bring them back before the celebration is ruined and all the children of Orgrimmar are disappointed!', `VerifiedBuild`=19034 WHERE `ID`=6983; -- You're a Mean One...
UPDATE `quest_template` SET `QuestDescription`='We at Smokywood Pastures appreciate the recovery of the stolen treats, $n.  For that, we''d like to offer you a special gift... presented by none other than Great-father Winter himself!$B$BPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it''s always Smokywood Pastures wholesome goodness... thanks to you, of course!', `VerifiedBuild`=19034 WHERE `ID`=6984; -- A Smokywood Pastures' Thank You!
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes'' efforts in Alterac Valley, and will provide us with needed equipment!$B$BBe wary, $n.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.', `VerifiedBuild`=19034 WHERE `ID`=6985; -- Irondeep Supplies
UPDATE `quest_template` SET `RewardBonusMoney`=2340, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=7025; -- Treats for Greatfather Winter
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='Just look at the stables, $n! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.$B$BYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.$B$BWhen we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!', `VerifiedBuild`=19034 WHERE `ID`=7027; -- Empty Stables
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.$B$BTake this vial, $n. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.$B$BFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...', `VerifiedBuild`=19034 WHERE `ID`=7041; -- Vyletongue Corruption
UPDATE `quest_template` SET `RewardItem1`=116762, `AllowableRaces`=18875469, `QuestDescription`='A creature called "The Abominable Greench" stole our shipment of treats, $n.  Be careful though!  He''s vicious and a bunch of those little green gnomes do his bidding!$B$BYou''re gonna need some help in facing him.  Rumor has it he''s holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats $n and bring them back before the celebration is ruined and all the children of Stormwind are disappointed!', `VerifiedBuild`=19034 WHERE `ID`=7043; -- You're a Mean One...
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='We at Smokywood Pastures appreciate the recovery of the stolen treats, $n.  For that, we''d like to offer you a special gift... presented by none other than Greatfather Winter himself!$B$BPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it''s always Smokywood Pastures wholesome goodness... thanks to you, of course!', `VerifiedBuild`=19034 WHERE `ID`=7045; -- A Smokywood Pastures' Thank You!
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=7061; -- The Feast of Winter Veil
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='In the depths of Maraudon lives a creature of chaos and evil, $n. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar''s remains before returning to Stonetalon.', `VerifiedBuild`=19034 WHERE `ID`=7065; -- Corruption of Earth and Seed
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=18875469, `QuestDescription`='The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, $n, ready to join that fight?$B$BI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....$B$BBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.', `VerifiedBuild`=19034 WHERE `ID`=7081; -- Alterac Valley Graveyards
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=33555378, `QuestDescription`='The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, $n, are where battles rage most fierce.$B$BI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.$B$BDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.', `VerifiedBuild`=19034 WHERE `ID`=7082; -- The Graveyards of Alterac
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (7101 /*Towers and Bunkers*/, 11923 /*Torch Catching*/, 11925 /*More Torch Catching*/, 13503 /*A Tisket, a Tasket, a Noblegarden Basket*/, 25181 /*Tablets of Fire*/, 25480 /*Dance Of De Spirits*/, 28935 /*Crushing the Crown*/, 29317 /*Fish Head*/, 29319 /*Tadpole Terror*/, 29320 /*Like Pike?*/, 29322 /*Time for Slime*/, 29354 /*Shiny Baubles*/, 29361 /*Moat Monster!*/);
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (7102 /*Towers and Bunkers*/, 7122 /*Capture a Mine*/, 13502 /*A Tisket, a Tasket, a Noblegarden Basket*/, 28934 /*Crushing the Crown*/);
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=18875469, `QuestDescription`='$n, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he''ll probably send you to get them.$B$BFollow the road.  You''ll find our quartermaster to the west.', `VerifiedBuild`=19034 WHERE `ID`=7121; -- The Quartermaster
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=33555378, `QuestDescription`='$n, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.$B$BFollow the road west into the bunker, then take the west exit and you''ll find our quartermaster.', `VerifiedBuild`=19034 WHERE `ID`=7123; -- Speak with our Quartermaster
UPDATE `quest_template` SET `RewardMoney`=150, `RewardMoneyDifficulty`=6, `RewardBonusMoney`=9300, `AllowableRaces`=33555378, `QuestDescription`='As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it''s no wonder they are so highly valued!$B$BHelp our war effort, $n!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we''ll send troops to protect it!', `VerifiedBuild`=19034 WHERE `ID`=7124; -- Capture a Mine
UPDATE `quest_template` SET `RewardMoney`=225, `RewardMoneyDifficulty`=7, `RewardBonusMoney`=14100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=7141; -- The Battle of Alterac
UPDATE `quest_template` SET `RewardMoney`=225, `RewardMoneyDifficulty`=7, `RewardBonusMoney`=14100, `AllowableRaces`=33555378, `QuestDescription`='The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!$B$BYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.$B$BDestroy him, $n, and then return to me.', `VerifiedBuild`=19034 WHERE `ID`=7142; -- The Battle for Alterac
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (7161 /*Proving Grounds*/, 7224 /*Enemy Booty*/, 10945 /*Hch'uu and the Mushroom People*/, 10951 /*A Trip to the Dark Portal*/, 10953 /*Visit the Throne of the Elements*/, 10963 /*Time to Visit the Caverns*/, 11975 /*Now, When I Grow Up...*/, 29146 /*Ridin' the Rocketway*/, 29176 /*The Fallen Chieftain*/, 29190 /*Let's Go Fly a Kite*/, 29191 /*You Scream, I Scream...*/, 29427 /*The Collector's Agent*/);
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (7162 /*Proving Grounds*/, 7223 /*Armor Scraps*/, 29032 /*Get Them While They're Young*/, 29093 /*Cruisin' the Chasm*/, 29106 /*The Biggest Diamond Ever!*/, 29107 /*Malfurion Has Returned!*/, 29117 /*Let's Go Fly a Kite*/, 29119 /*You Scream, I Scream...*/);
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=7181; -- The Legend of Korrak
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Our air support is in shambles, $n. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!$B$BGuse was last seen flying over the Icewing Bunker. Jeztor''s War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun''Baldar North Bunker.$B$BThat''s all the information I have. Move out! Search through the areas thoroughly.', `VerifiedBuild`=19034 WHERE `ID`=7302; -- Fallen Sky Lords
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=56700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (7361 /*Favor Amongst the Darkspear*/, 7363 /*The Human Condition*/, 10809 /*Wanted: Worg Master Kruush*/);
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='There''s something not quite right about all of this... Did anybody think to burn Korrak''s corpse? Those trolls will stop at nothing to revive their fallen leader - as blue skinned pagan man-beasts often do.$B$BJust keep your eyes out, $n. Don''t be alarmed if Korrak makes a surprise appearance; and if he does, I want him executed - his corpse burned to ashes.$B$BFor good measure, lop off his head and bring me his skull before you ignite the lifeless mass.', `VerifiedBuild`=19034 WHERE `ID`=7382; -- Korrak the Everliving
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!$B$BStop her, $n.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...', `VerifiedBuild`=19034 WHERE `ID`=7488; -- Lethtendris's Web
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `FlagsEx`=8, `AllowableRaces`=-1, `LogDescription`='Take the Head of Onyxia to Vol''jin in Orgrimmar.', `QuestDescription`='You have accomplished the impossible.

The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to your Warchief.', `VerifiedBuild`=19034 WHERE `ID`=7490; -- Victory for the Horde
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=-1, `LogDescription`='Seek out Overlord Natoj in the Valley of Strength.', `QuestDescription`='Overlord Natoj awaits ya arrival in da Valley of Strength.$B$B<The Warchief salutes you.>$B$BDo not keep ya public waitin'', hero.', `VerifiedBuild`=19034 WHERE `ID`=7491; -- For All To See
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.$B$BServe the Horde, $n.  Go to Camp Mojache in Feralas and speak with Talo.', `VerifiedBuild`=19034 WHERE `ID`=7492; -- Camp Mojache
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='$n!  Your aid is needed in Feralas!$B$BAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre''thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.$B$BLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.$B$BServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.', `VerifiedBuild`=19034 WHERE `ID`=7494; -- Feathermoon Stronghold
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `FlagsEx`=8, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (7495 /*Victory for the Alliance*/, 7781 /*The Lord of Blackrock*/);
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=18875469, `QuestDescription`='Seek out Major Mattingly in the Valley of Heroes, $n. He will be expecting you...', `VerifiedBuild`=19034 WHERE `ID`=7496; -- Celebrating Good Times
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID` IN (7604 /*A Binding Contract*/, 9250 /*Frame of Atiesh*/);
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.$B$BI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.$B$BFortune to you, $n.  And may the souls of your enemies swiftly find their way into your shard pouch.', `VerifiedBuild`=19034 WHERE `ID`=7631; -- Dreadsteed of Xoroth
UPDATE `quest_template` SET `RewardMoney`=-1499999, `AllowableRaces`=-1, `QuestDescription`='In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.$B$BYou must acquire High Priest Rohan''s exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.$B$BProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.$B$BGo now $n, time is of the essence.', `VerifiedBuild`=19034 WHERE `ID`=7637; -- Emphasis on Sacrifice
UPDATE `quest_template` SET `RewardMoney`=-1499999, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=7642; -- Collection of Goods
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='The time has come, $n, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.$B$BSpeak with Lord Grayson Shadowbreaker in Stormwind''s Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin''s most trusted mount, but the tasks before you to acquire one of your own.$B$BI wish you the best in this trial.  For the Light, noble $G brother : sister;!', `VerifiedBuild`=19034 WHERE `ID`=7670; -- Lord Grayson Shadowbreaker
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='When that traitor, Maltorius, left our clan, he left with something more valuable than a pristine arcane crystal: Our recipe for fiery flux! I''d bet anything that the recipe was part of the deal in his new promotion amongst the Dark Irons.$B$BI want you to get our secret plans back, $n. I''m sure they''re somewhere near Maltorius, deep inside the Slag Pit.', `VerifiedBuild`=19034 WHERE `ID`=7722; -- What the Flux?
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `FlagsEx`=8, `AllowableRaces`=-1, `LogDescription`='Return the Head of Nefarian to Vol''jin in Orgrimmar.', `VerifiedBuild`=19034 WHERE `ID`=7783; -- The Lord of Blackrock
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `AllowableRaces`=-1, `LogDescription`='Speak with Overlord Natoj in Orgrimmar. He stands waiting for you in the Valley of Strength.', `QuestDescription`='Seek out Overlord Natoj in the Valley of Strength.', `VerifiedBuild`=19034 WHERE `ID`=7784; -- The Lord of Blackrock
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='I have told you all that I know, $n. It is you who must find elementium. It is you who must destroy the Firelord''s corporeal form.$B$BDo this and gain the blessing of Thunderaan.', `VerifiedBuild`=19034 WHERE `ID`=7786; -- Thunderaan the Windseeker
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=-1, `QuestDescription`='The wilds of the Ashenvale forest will succumb to the might of the Horde, $r. Nothing the Silverwing say or do can stop our sovereign imperative. Kalimdor belongs to the Horde. How dare they attempt to prevent us from harvesting what is rightfully ours!$B$BLet the pride swell in your chest as you cut down their weak attempts at slowing our progress. Destroy the Silverwing Sentinels, and earn a Warsong mark of honor.  Return to me with such a mark, $n, and you will be rewarded.
', `VerifiedBuild`=19034 WHERE `ID` IN (7789 /*Quell the Silverwing Usurpers*/, 7875 /*Quell the Silverwing Usurpers*/);
UPDATE `quest_template` SET `MinLevel`=1, `QuestSortID`=-22, `Flags`=20480, `FlagsEx`=64, `LogTitle`='The Written Word', `QuestDescription`='Here''s something you didn''t expect....$b$b$b ', `QuestCompletionLog`='Speak with Jonathan LeCraft.', `VerifiedBuild`=19034 WHERE `ID`=7790; -- The Written Word
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `Flags`=2097216, `VerifiedBuild`=19034 WHERE `ID`=7848; -- Attunement to the Core
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=-1, `QuestDescription`='Beyond this tunnel you will find a field of strife and turmoil, young $c. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.$B$BEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!$B$BDo this, and earn a talisman of merit.  Bring me such a talisman, $n, and I shall reward you.', `VerifiedBuild`=19034 WHERE `ID`=7873; -- Vanquish the Invaders!
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=-1, `QuestDescription`='The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!$B$BIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer''s Guide to help you identify treasures in your travels!$B$BJust hand your voucher to Gelvas Grimegate located inside the Faire.$B$BRight now, the entrance to the Faire is outside Goldshire, in Elwynn Forest.', `VerifiedBuild`=19034 WHERE `ID`=7905; -- The Darkmoon Faire
UPDATE `quest_template` SET `RewardBonusMoney`=960, `QuestDescription`='The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!$B$BIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer''s Guide to help you identify treasures in your travels!$B$BJust hand your voucher to Gelvas Grimegate located inside the Faire.$B$BRight now, the entrance to the Faire is outside Thunder Bluff in Mulgore!', `VerifiedBuild`=19034 WHERE `ID`=7926; -- The Darkmoon Faire
UPDATE `quest_template` SET `FlagsEx`=64, `VerifiedBuild`=19034 WHERE `ID` IN (7961 /*Waskily Wabbits!*/, 11088 /*<DEPRECATED>Unravelling Your Training*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `FlagsEx`=64, `VerifiedBuild`=19034 WHERE `ID`=7962; -- [DEPRECATED] Wabbit Pelts
UPDATE `quest_template` SET `Flags`=16392, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID` IN (8021 /*Redeem iCoke Prize Voucher*/, 8022 /*Redeem iCoke Prize Voucher*/);
UPDATE `quest_template` SET `Flags`=16392, `VerifiedBuild`=19034 WHERE `ID` IN (8023 /*Redeem iCoke Prize Voucher*/, 8024 /*Redeem iCoke Prize Voucher*/, 8025 /*Redeem iCoke Prize Voucher*/, 8026 /*Redeem iCoke Prize Voucher*/, 9273 /*Redeem iCoke Prize Voucher*/, 9353 /*Redeem iCoke Gift Box Voucher*/);
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='The ultimate symbol of a haruspex''s power is what they wear, $n.  Of these, the tunic symbolizes the connection between themselves and the divine wisdom they seek.  It often weaves parts of the beasties they sacrifice into the tunic; this reminds them of the connection they have to their gifts.$B$BBring me an offerin'' of the Paragons of Power from inside Zul''Gurub and prove your worth to us.  Do this, and a tunic seeping with the true power of a haruspex is yours.', `VerifiedBuild`=19034 WHERE `ID`=8065; -- Paragons of Power: The Haruspex's Tunic
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='The tribe acknowledges station and power through what we wear.  Our vestments are made from the finest of materials, and interwoven with the mojo we use to make us powerful.  Illusionists are no exception; their robes are said to embody the essence of illusion in their look.  Legend states that their ancient robes never looked the same twice.$B$BI will give you an illusionist''s robe, $n... but earn your place of reverence among the tribe first!  Bring me the Paragons of Power from Zul''Gurub!', `VerifiedBuild`=19034 WHERE `ID`=8069; -- Paragons of Power: The Illusionist's Robes
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='The vindicator''s symbol of power is the breastplate.  It is forged with powerful mojo.  It is trusted only to those we revere.  It is the Zandalar symbol of vengeance.$B$BTo become a vindicator is to become vengeance.  Take the Paragons of Power we need from Zul''Gurub.  Bring them to us.  We will take the mojo stolen from us.  We will make the minions of Hakkar pay.  We will reward you with the vindicator''s breastplate.$B$BGo.  Be our vengeance, $n.', `VerifiedBuild`=19034 WHERE `ID`=8079; -- Paragons of Power: The Vindicator's Breastplate
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='$n, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy''s banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.', `VerifiedBuild`=19034 WHERE `ID`=8105; -- The Battle for Arathi Basin!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=85200, `AllowableRaces`=-1, `QuestDescription`='$n, you have taken the battle of Arathi Basin to our enemies and earned great honors in that field of battle.  You have shown us your worth as a $c, and you have shown our enemies that we will not submit to their villainy!$B$BBecause of your proven value to us, I have a difficult task for you.  I want you to take and hold at least four of the bases in Arathi Basin.  If you can do that, then we will not only secure critical resources, we will show the Horde our dominance!$B$BGo, $n, and good fortune. ', `VerifiedBuild`=19034 WHERE `ID`=8114; -- Control Four Bases
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=85200, `AllowableRaces`=-1, `QuestDescription`='$n, battling for the resources of Arathi Basin is a bloody undertaking.  Your services to the League of Arathor are as needed as they are appreciated.$B$BAnd we have one more task for you.$B$BThe League wishes to make one strong push against the Defilers'' occupation of Arathi Basin.  We want them driven out of every strategic point on the battlefield!$B$BIt will not be easy, but if anyone can get it done, it is you.', `VerifiedBuild`=19034 WHERE `ID`=8115; -- Control Five Bases
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=48900, `AllowableRaces`=-1, `QuestDescription`='As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!$B$BGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies'' banners, declaring those territories for the Horde.$B$BGo, $n.  Report back to me when this task is complete.', `VerifiedBuild`=19034 WHERE `ID`=8120; -- The Battle for Arathi Basin!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=85200, `AllowableRaces`=-1, `QuestDescription`='$n, as the battles over Arathi Basin rage, news of your actions have reached many ears.  You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you.$B$BIt is time to send a message to the League of Arathor.  We must show them that their holdings in Arathi Basin are tenuous and quickly lost.  We will show them this by holding, all at once, four strategic points in Arathi Basin.$B$BSucceed in this, $n, and earn great respect among the Defilers.', `VerifiedBuild`=19034 WHERE `ID`=8121; -- Take Four Bases
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=85200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (8122 /*Take Five Bases*/, 12428 /*The Conquest Pit: Mad Furbolg Fighting*/, 12429 /*The Conquest Pit: Blood and Metal*/);
UPDATE `quest_template` SET `RewardChoiceItemID1`=116445, `RewardChoiceItemID2`=116444, `RewardChoiceItemID3`=116443, `RewardChoiceItemID4`=116442, `RewardChoiceItemQuantity1`=3, `RewardChoiceItemQuantity2`=3, `RewardChoiceItemQuantity3`=3, `RewardChoiceItemQuantity4`=3, `VerifiedBuild`=19034 WHERE `ID`=8149; -- Honoring a Hero
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `RewardChoiceItemID1`=116445, `RewardChoiceItemID2`=116444, `RewardChoiceItemID3`=116443, `RewardChoiceItemID4`=116442, `RewardChoiceItemQuantity1`=3, `RewardChoiceItemQuantity2`=3, `RewardChoiceItemQuantity3`=3, `RewardChoiceItemQuantity4`=3, `VerifiedBuild`=19034 WHERE `ID`=8150; -- Honoring a Hero
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=-1, `QuestDescription`='War must be fought with soldiers, any soldier will tell you.  They''ll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!$B$BThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.$B$BThat is what I want from you, $n.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.', `VerifiedBuild`=19034 WHERE `ID`=8156; -- Arathi Basin Resources!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=33300, `AllowableRaces`=-1, `QuestDescription`='$n, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy''s banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.', `VerifiedBuild`=19034 WHERE `ID`=8166; -- The Battle for Arathi Basin!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=19800, `AllowableRaces`=-1, `QuestDescription`='$n, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy''s banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.', `VerifiedBuild`=19034 WHERE `ID`=8167; -- The Battle for Arathi Basin!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=12000, `AllowableRaces`=-1, `QuestDescription`='$n, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.$B$BAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy''s banner and rip it from its flag post!$B$BWhen you have done this to all four points, return to me.', `VerifiedBuild`=19034 WHERE `ID`=8168; -- The Battle for Arathi Basin!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!$B$BGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies'' banners, declaring those territories for the Horde.$B$BGo, $n.  Report back to me when this task is complete.', `VerifiedBuild`=19034 WHERE `ID` IN (8169 /*The Battle for Arathi Basin!*/, 8170 /*The Battle for Arathi Basin!*/, 8171 /*The Battle for Arathi Basin!*/);
