UPDATE `quest_template` SET `TimeAllowed`=300, `VerifiedBuild`=19034 WHERE `ID`=8274; -- Test Kill Quest
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=50700, `QuestDescription`='Blasted!  The antidote didn''t work.  Noggle must''ve been stung by one of the stronger creatures in the far south.$B$BI''m going to need you to go there and get me some more samples, $n.  The good news is that since their poison is stronger I won''t require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you''ll have to draw from more sources.', `VerifiedBuild`=19034 WHERE `ID`=8278; -- Noggle's Last Hope
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=50700, `QuestDescription`='Your performance has been truly exemplary so far, $n.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north.$B$BYou''ll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.  ', `VerifiedBuild`=19034 WHERE `ID`=8281; -- Stepping Up Security
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=63300, `VerifiedBuild`=19034 WHERE `ID` IN (8283 /*Wanted - Deathclasp, Terror of the Sands*/, 10261 /*Wanted: Annihilator Servo!*/, 10701 /*Breaking Down Netherock*/, 10821 /*You're Fired!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=50700, `VerifiedBuild`=19034 WHERE `ID` IN (8284 /*The Twilight Mystery*/, 8320 /*Twilight Geolords*/, 8323 /*True Believers*/);
UPDATE `quest_template` SET `QuestDescription`='It is time, $n.$B$BI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master.', `VerifiedBuild`=19034 WHERE `ID`=8303; -- Anachronos
UPDATE `quest_template` SET `QuestDescription`='My dear Natalia has gone missing.$B$BTruth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research.$B$BShe was last seen heading to Bronzebeard''s camp to the south.$B$BMy soldiers are spread too thin, $n. I need you to go to Bronzebeard''s camp and question those dwarves. ', `VerifiedBuild`=19034 WHERE `ID`=8304; -- Dearest Natalia
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=63300, `LogDescription`='Commander Mar''alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive''Regal in the south as being the area in which you may find Mistress Natalia Mar''alith.$B$BDo not forget to visit the dwarves at Bronzebeard''s camp before venturing into the hive. They might have some additional work and advice for you.$B$BAnd $n, remember the Commander''s words: "Do what you must..."', `QuestDescription`='I need you to venture into Hive''Regal and find what became of my dearest Natalia, $n. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you speak with those dwarves further. They might be able to give you some tips on dealing with the silithid that inhabit that hive.$B$BAnd $n, if she truly is as mad as they say... do what you must.', `VerifiedBuild`=19034 WHERE `ID`=8306; -- Into The Maw of Madness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='After our initial foray into the hives and Mistress Mar''alith''s subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.$B$BIf I can get rubbings of those crystals and the glyphs on them, we might be able to make sense of this madness.$B$BTake this transcription set  and hit Hive''Regal to the east, $n. That''s the last rubbing I need!', `VerifiedBuild`=19034 WHERE `ID`=8309; -- Glyph Chasing
UPDATE `quest_template` SET `RewardBonusMoney`=960, `VerifiedBuild`=19034 WHERE `ID` IN (8311 /*Hallow's End Treats for Jesper!*/, 8312 /*Hallow's End Treats for Spoops!*/, 8883 /*Valadar Starsong*/);
UPDATE `quest_template` SET `QuestDescription`='We''re on the verge of a breakthrough, $n! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.$B$BUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.$B$BTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.', `VerifiedBuild`=19034 WHERE `ID`=8314; -- Unraveling the Mystery
UPDATE `quest_template` SET `LogDescription`='Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.$B$BYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.$B$BAssemble an army for this task, $n!', `VerifiedBuild`=19034 WHERE `ID`=8315; -- The Calling
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=25200, `VerifiedBuild`=19034 WHERE `ID`=8317; -- Kitchen Assistance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=50700, `VerifiedBuild`=19034 WHERE `ID`=8318; -- Secret Communication
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=63300, `QuestDescription`='We have discovered another base of operations for the Twilight''s Hammer.  It is called Twilight''s Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring.$B$BFortune to you, $n.  The horrors of Twilight''s Run are formidable indeed.', `VerifiedBuild`=19034 WHERE `ID`=8321; -- Vyral the Vile
UPDATE `quest_template` SET `QuestPackageID`=609, `RewardXPDifficulty`=7, `RewardMoney`=50, `RewardMoneyDifficulty`=7, `FlagsEx`=512, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `QuestDescription`='The sooner you begin your education, $n, the better for us all.  There is little room for error, so listen closely.$B$BThe Burning Crystals - the green floating objects to the west of the Sunspire here - have long been used to power the isle''s experimentations.  The mana wyrms were their guardians, but the Scourge invasion of Quel''Thalas has driven them errant from our lack of magical control over them.$B$BThere is little choice but to thin their numbers for reclamation.  Do this, then return to me.', `VerifiedBuild`=19034 WHERE `ID`=8325; -- Reclaiming Sunstrider Isle
UPDATE `quest_template` SET `QuestPackageID`=563, `RewardNextQuest`=0, `RewardXPDifficulty`=8, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=300, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `QuestDescription`='Your effort has made something clear that, honestly, I wish were not true.  The unchecked power of the Burning Crystals has maligned a much larger swath of the isle''s natural balance than I thought.  We must now take on more unfortunate measures to reclaim control.$B$BThe nearby lynxes have succumbed to the influence of the crystals, and they must be put down.  Bring their collars, $n, as I may yet be able to fashion a magical restraint to turn some back from being uncontrolled.', `VerifiedBuild`=19034 WHERE `ID`=8326; -- Unfortunate Measures
UPDATE `quest_template` SET `QuestDescription`='You are to report to my assistant, Lanthan Perilon.  He will instruct you on what needs to be done next.  While we here at the Sunspire will continue to rein in the Burning Crystals, you will be focused on a more pressing matter concerning Falthrien Academy.  Lanthan will explain fully when you speak to him.$B$BSimply walk west of here along the path, and you should see him standing close by.$B$BGood luck, $n - your continued successes shall be rewarded.', `VerifiedBuild`=19034 WHERE `ID`=8327; -- Report to Lanthan Perilon
UPDATE `quest_template` SET `QuestPackageID`=564, `RewardMoneyDifficulty`=5, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `VerifiedBuild`=19034 WHERE `ID`=8334; -- Aggression
UPDATE `quest_template` SET `QuestPackageID`=610, `RewardMoneyDifficulty`=6, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `VerifiedBuild`=19034 WHERE `ID`=8335; -- Felendren the Banished
UPDATE `quest_template` SET `AllowableRaces`=512, `VerifiedBuild`=19034 WHERE `ID` IN (8344 /*Windows to the Source*/, 9425 /*Report to Tarren Mill*/, 14081 /*Learn to Ride in the Eversong Woods*/);
UPDATE `quest_template` SET `QuestPackageID`=565, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `QuestDescription`='If there is only one lesson you deign to remember from your time on Sunstrider Isle, let it be this - control your thirst for magic.  It is a thirst unending, $n - what you absorb must be controlled and released via Arcane Torrent.  Failure is to become one of the Wretched... hopelessly addicted and insane.$B$BSeek out a mana wyrm and unleash your Arcane Torrent upon it.  Learn to master your power. When you have sufficiently released an Arcane Torrent, return to me.', `VerifiedBuild`=19034 WHERE `ID`=8346; -- Thirst Unending
UPDATE `quest_template` SET `QuestDescription`='Magistrix Erona wanted you to head over to Silvermoon City in order to aid our reclamation efforts there... that is, once you had successfully addressed the situation at Falthrien Academy.  You did not disappoint us, $n.$B$BOn your way to Falconwing Square, south of here, you should speak with Outrunner Alarion.  She''s not far from the bridge.$B$BThe Outrunners take care of shuttling goods between here and the mainland, and since you''ve proven to be so resourceful, they could use your assistance.', `VerifiedBuild`=19034 WHERE `ID`=8347; -- Aiding the Outrunners
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='The death of another outrunner is a true tragedy, but it''s a risk we all accept when we take the job.  Magistrix Erona at the Sunspire needs to get this package to the inn at Falconwing Square, and she needs it there as soon as possible.$B$BWe''re short handed and I don''t have anyone else available that can cover for us.$B$BI''m not going to lie to you; the path to Falconwing Square can be extremely dangerous if you leave the safety of Dawning Lane.  Do you feel up to the task, $n?', `VerifiedBuild`=19034 WHERE `ID`=8350; -- Completing the Delivery
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='Argh! They want the impossible from me!$B$BThe Steamwheedle Cartel wants me to teach the Southsea pirates a lesson.  The problem is that I can''t be in two places at once; I need to stay here to keep the peace.$B$BOf late, the pirates have been disregarding the protection money that the cartel regularly forks over. So I''d like to temporarily deputize you to go down there and show them what for.$B$BYou''ll find them at Lost Rigger Cove, which is not too far to the south.  Thanks $n, I''ll owe you one!', `VerifiedBuild`=19034 WHERE `ID`=8366; -- Southsea Shakedown
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (8367 /*For Great Honor*/, 11131 /*Stop the Fires!*/, 11219 /*Stop the Fires!*/, 11505 /*Spirits of Auchindoun*/, 11506 /*Spirits of Auchindoun*/, 11580 /*Desecrate this Fire!*/, 11581 /*Desecrate this Fire!*/, 11732 /*Desecrate this Fire!*/, 11734 /*Desecrate this Fire!*/, 11735 /*Desecrate this Fire!*/, 11736 /*Desecrate this Fire!*/, 11737 /*Desecrate this Fire!*/, 11738 /*Desecrate this Fire!*/, 11739 /*Desecrate this Fire!*/, 11740 /*Desecrate this Fire!*/, 11741 /*Desecrate this Fire!*/, 11742 /*Desecrate this Fire!*/, 11743 /*Desecrate this Fire!*/, 11744 /*Desecrate this Fire!*/, 11745 /*Desecrate this Fire!*/, 11746 /*Desecrate this Fire!*/, 11747 /*Desecrate this Fire!*/, 11749 /*Desecrate this Fire!*/, 11750 /*Desecrate this Fire!*/, 11751 /*Desecrate this Fire!*/, 11752 /*Desecrate this Fire!*/, 11753 /*Desecrate this Fire!*/, 11754 /*Desecrate this Fire!*/, 11755 /*Desecrate this Fire!*/, 11756 /*Desecrate this Fire!*/, 11757 /*Desecrate this Fire!*/, 11758 /*Desecrate this Fire!*/, 11759 /*Desecrate this Fire!*/, 11760 /*Desecrate this Fire!*/, 11761 /*Desecrate this Fire!*/, 11762 /*Desecrate this Fire!*/, 11763 /*Desecrate this Fire!*/, 11764 /*Desecrate this Fire!*/, 11765 /*Desecrate this Fire!*/, 11766 /*Desecrate this Fire!*/, 11767 /*Desecrate this Fire!*/, 11768 /*Desecrate this Fire!*/, 11769 /*Desecrate this Fire!*/, 11770 /*Desecrate this Fire!*/, 11771 /*Desecrate this Fire!*/, 11772 /*Desecrate this Fire!*/, 11773 /*Desecrate this Fire!*/, 11774 /*Desecrate this Fire!*/, 11775 /*Desecrate this Fire!*/, 11776 /*Desecrate this Fire!*/, 11777 /*Desecrate this Fire!*/, 11778 /*Desecrate this Fire!*/, 11779 /*Desecrate this Fire!*/, 11780 /*Desecrate this Fire!*/, 11781 /*Desecrate this Fire!*/, 11782 /*Desecrate this Fire!*/, 11783 /*Desecrate this Fire!*/, 11784 /*Desecrate this Fire!*/, 11786 /*Desecrate this Fire!*/, 11787 /*Desecrate this Fire!*/, 11799 /*Desecrate this Fire!*/, 11800 /*Desecrate this Fire!*/, 11801 /*Desecrate this Fire!*/, 11802 /*Desecrate this Fire!*/, 11803 /*Desecrate this Fire!*/, 12491 /*Direbrew's Dire Brew*/, 12492 /*Direbrew's Dire Brew*/, 13440 /*Desecrate this Fire!*/, 13441 /*Desecrate this Fire!*/, 13442 /*Desecrate this Fire!*/, 13443 /*Desecrate this Fire!*/, 13444 /*Desecrate this Fire!*/, 13445 /*Desecrate this Fire!*/, 13446 /*Desecrate this Fire!*/, 13447 /*Desecrate this Fire!*/, 13449 /*Desecrate this Fire!*/, 13450 /*Desecrate this Fire!*/, 13451 /*Desecrate this Fire!*/, 13453 /*Desecrate this Fire!*/, 13454 /*Desecrate this Fire!*/, 13455 /*Desecrate this Fire!*/, 13457 /*Desecrate this Fire!*/, 13458 /*Desecrate this Fire!*/, 13476 /*For Great Honor*/, 13479 /*The Great Egg Hunt*/, 13480 /*The Great Egg Hunt*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn''t belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.$B$BDo not let this happen, $n!  Come back to me with proof of serving the Horde in a worthy manner!', `VerifiedBuild`=19034 WHERE `ID` IN (8368 /*Battle of Warsong Gulch*/, 8427 /*Battle of Warsong Gulch*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=70800, `AllowableRaces`=-1, `QuestDescription`='Listen up, $n.  No matter what you might have heard about the battle raging in Alterac Valley, one thing remains true: the Stormpike Expedition invaded Frostwolf Territory.  The day we allow the Alliance to invade Horde lands without a forceful response is the day I hang up my axe and live the rest of my life in shame.  Go forth and expel the invaders!', `VerifiedBuild`=19034 WHERE `ID`=8369; -- Invaders of Alterac Valley
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.$B$BThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $n!', `VerifiedBuild`=19034 WHERE `ID` IN (8370 /*Conquering Arathi Basin*/, 8436 /*Conquering Arathi Basin*/, 8437 /*Conquering Arathi Basin*/);
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='We''re not fighting isolated battles against the Horde anymore, $g lad:lass;.$B$BVictory in one front means denying the Horde resources they''d use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.$B$BThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  $n, come back to me after you''ve served against the Horde at all of our active battlegrounds.', `VerifiedBuild`=19034 WHERE `ID`=8371; -- Concerted Efforts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.$B$BThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.$B$BDo your part in fighting the Warsong Outriders, $n!  For the Alliance!', `VerifiedBuild`=19034 WHERE `ID` IN (8372 /*Fight for Warsong Gulch*/, 8399 /*Fight for Warsong Gulch*/, 8400 /*Fight for Warsong Gulch*/, 8402 /*Fight for Warsong Gulch*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.$B$BWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.$B$BIf the Alliance comes out victorious, it''ll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they''d just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $n.', `VerifiedBuild`=19034 WHERE `ID` IN (8374 /*Claiming Arathi Basin*/, 8393 /*Claiming Arathi Basin*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=70800, `AllowableRaces`=-1, `QuestDescription`='Make no mistake about it, $n.  The Horde is quite right when they say Alterac Valley is Frostwolf Territory.$B$BYou see, the Stormpike Expedition arrived as peaceful visitors to the area in search of ore and relics.  The Frostwolves reacted with the most brutal and uncivilized act of aggression the Alliance has experienced.$B$BLet us never forget the brave dwarves that perished in that cowardly unannounced attack.  Go now, $c, do your part in the battle for Alterac Valley.  For the Alliance!', `VerifiedBuild`=19034 WHERE `ID`=8375; -- Remember Alterac Valley!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `AllowableRaces`=-1, `QuestDescription`='Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.$B$BWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.$B$BIf the Alliance comes out victorious, it''ll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they''d just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, $n.', `VerifiedBuild`=19034 WHERE `ID`=8396; -- Claiming Arathi Basin
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `AllowableRaces`=-1, `QuestDescription`='The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn''t belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.$B$BDo not let this happen, $n!  Come back to me with proof of serving the Horde in a worthy manner!', `VerifiedBuild`=19034 WHERE `ID`=8430; -- Battle of Warsong Gulch
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `AllowableRaces`=-1, `QuestDescription`='Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.$B$BThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, $n!', `VerifiedBuild`=19034 WHERE `ID`=8439; -- Conquering Arathi Basin
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID` IN (8446 /*Shrouded in Nightmare*/, 8791 /*The Fall of Ossirian*/);
UPDATE `quest_template` SET `QuestDescription`='The waters of Lake Elune''ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, $n.', `VerifiedBuild`=19034 WHERE `ID`=8447; -- Waking Legends
UPDATE `quest_template` SET `Flags`=0, `FlagsEx`=64, `VerifiedBuild`=19034 WHERE `ID`=8450; -- <TXT> Mystery Reward
UPDATE `quest_template` SET `QuestDescription`='There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.$B$BThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.$B$BPlease, $n - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.', `VerifiedBuild`=19034 WHERE `ID`=8461; -- [DEPRECATED]Deadwood of the North
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='A group of Wretched recently raided a supply of unstable mana crystals from one of our arcane sanctums.  If not handled properly, the crystals could explode with enough force to blow a hole into the city walls.$B$BNow, $n, I don''t quite care if they blow themselves up while tapping unstable arcane sources, but the whole incident would make my men look bad.$B$BBring me back any remaining stolen crystals you find; they might still be inside their original crates.', `VerifiedBuild`=19034 WHERE `ID`=8463; -- Unstable Mana Crystals
UPDATE `quest_template` SET `QuestDescription`='The Timbermaw tend to stay to themselves, $n.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.$B$BThe Winterfall tribe as of late has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.$B$BI must ask you to thin their numbers as to lessen the threat against us.  Seek them out in Winterfall Village, far to the east of here.', `VerifiedBuild`=19034 WHERE `ID`=8464; -- [DEPRECATED]Winterfall Activity
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=50332671, `VerifiedBuild`=19034 WHERE `ID` IN (8468 /*Wanted: Thaelis the Hungerer*/, 9062 /*Soaked Pages*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=16384, `VerifiedBuild`=19034 WHERE `ID`=8471; -- Winterfall Ritual Totem
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `VerifiedBuild`=19034 WHERE `ID` IN (8472 /*Major Malfunction*/, 8489 /*An Intact Converter*/, 8490 /*Powering our Defenses*/, 8491 /*Pelt Collection*/, 9064 /*Taking the Fall*/, 9076 /*Wretched Ringleader*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='These are difficult times for us, $n.  It was a very hard decision to burn the woods bordering the Ghostlands to prevent the Scourge''s expansion.$B$BThe treants, who have been our friends for years, are now trying to foster the regrowth of the forest along the Scorched Grove.$B$BThis is a painful thing to ask of you, $c, but we''ve failed to convince our former allies to cease their endeavors.  I need you to stop them by the only means that remain to us: force.', `VerifiedBuild`=19034 WHERE `ID`=8473; -- A Somber Task
UPDATE `quest_template` SET `AllowableRaces`=50332671, `QuestDescription`='The black swath of soil that cuts through Eversong Woods is a permanent reminder of the day Arthas led the Scourge into our beloved city.$B$BThis blemish is more than an eyesore as even today it brings Scourge from the Ghostlands to Silvermoon.$B$BGo, $n, and give my men a hand in killing the mindless undead that walk down the Dead Scar.', `VerifiedBuild`=19034 WHERE `ID`=8475; -- The Dead Scar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='Ours are not the vast kingdoms of the humans and orcs.  All we have left of our lands in Azeroth lies mostly before your eyes, $n.$B$BUntil we can reach Outland, we must defend what little land we have at any cost.$B$BOur uncivilized neighbors to the southeast, the Amani trolls, certainly have a different opinion regarding the ownership of these lands.  Their daily raids are something we can''t tolerate anymore.  Go to their settlements, Zeb''Watha and Tor''Watha, and teach them a lesson.', `VerifiedBuild`=19034 WHERE `ID`=8476; -- Amani Encroachment
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='The Amani and the sin''dorei have a long history of mutual dislike and open hostility.  That doesn''t prevent me from appreciating a fellow craftsman''s work, $n.$B$BI''ve come across pieces of Amani weaponry and I must admit I''m impressed by the quality of their work.  It is rumored that Spearcrafter Otembe wields a magical hammer that is so light and well-balanced it allows him to work with great dexterity and efficiency.$B$BIf you bring me this tool I''ll use it to craft you a weapon.', `VerifiedBuild`=19034 WHERE `ID`=8477; -- The Spearcrafter's Hammer
UPDATE `quest_template` SET `AllowableRaces`=50332671, `VerifiedBuild`=19034 WHERE `ID` IN (8479 /*Zul'Marosh*/, 8486 /*Arcane Instability*/, 9035 /*Roadside Ambush*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='The Wretched grow bolder every day, $n.  They''ve achieved enough coordination to launch an attack on Sunsail Anchorage.$B$BAs if that weren''t embarrassing enough, most of our weapons were left behind when they attacked.  Bring me back our armaments so that we may show those ruffians who''s boss.', `VerifiedBuild`=19034 WHERE `ID`=8480; -- Lost Armaments
UPDATE `quest_template` SET `QuestDescription`='$n, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!$B$BTake this torch to the mouth of Grolnar''s personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.', `VerifiedBuild`=19034 WHERE `ID`=8481; -- The Root of All Evil
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Listen, $n.  This is a very delicate situation; even though we''ve identified the spy, we cannot kill him out in the open.  We cannot try to capture him either as the risk of him escaping is too great.$B$BI want you to go find Prospector Anvilward at the North Sanctum and kill him.  Do this in a quiet manner, we don''t want word to spread that we allowed a spy into our city.$B$BBring me his head as proof.  Ironforge will learn not to meddle with the sin''dorei.', `VerifiedBuild`=19034 WHERE `ID`=8483; -- The Dwarven Spy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='This was a fully functional arcane sanctum before Arthas and his army of Scourge decided to plow through it on their way to Silvermoon.$B$BNow it''s as useful to us as any part of the Dead Scar.  The soil is tainted, undead are drawn to it and the energy in the ley lines is completely disrupted.$B$BWhat I want to know, $n, is whether this taint is reversible or not.  I want you to collect soil samples from this area so I can study them.  Perhaps with time we can set things back to normal.', `VerifiedBuild`=19034 WHERE `ID`=8487; -- Corrupted Soil
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `QuestDescription`='Something''s wrong, $n.  I sense the presence of Scourge.  Be ready to fight them!', `VerifiedBuild`=19034 WHERE `ID`=8488; -- Unexpected Results
UPDATE `quest_template` SET `FlagsEx`=8, `AllowableRaces`=512, `VerifiedBuild`=19034 WHERE `ID`=8547; -- Welcome!
UPDATE `quest_template` SET `QuestDescription`='The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $n.$B$BYou''d be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.  ', `VerifiedBuild`=19034 WHERE `ID`=8548; -- Volunteer's Battlegear
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestCompletionLog`='Return to Windcaller Yessendra at Ahn''Qiraj in Silithus.', `VerifiedBuild`=19034 WHERE `ID` IN (8556 /*Signet of Unyielding Strength*/, 8698 /*Ring of the Gathering Storm*/, 8699 /*Band of Vaulted Secrets*/, 8700 /*Band of Unending Life*/, 8701 /*Band of Veiled Shadows*/, 8702 /*Ring of Unspoken Names*/, 8703 /*Ring of Eternal Justice*/, 8704 /*Signet of the Unseen Path*/);
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='I''m glad to hear you''re aiding us in our attack on Ahn''Qiraj, $n.  I can make you a protective item that''ll be of assistance in the fight against our enemy, $c.$B$BI shall need a Qiraji drape, which I''ll resize for you of course.  I''ll also need idols and scarabs which I''ll use to create a suitable clasp.$B$BI promise you won''t be disappointed.', `VerifiedBuild`=19034 WHERE `ID` IN (8557 /*Drape of Unyielding Strength*/, 8689 /*Shroud of Infinite Wisdom*/, 8690 /*Cloak of the Gathering Storm*/, 8691 /*Drape of Vaulted Secrets*/, 8692 /*Cloak of Unending Life*/, 8693 /*Cloak of Veiled Shadows*/, 8694 /*Shroud of Unspoken Names*/, 8695 /*Cape of Eternal Justice*/, 8696 /*Cloak of the Unseen Path*/);
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.$B$BJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $n, and I will make you a powerful weapon from the finest Qiraji materials.', `QuestCompletionLog`='Return to Warden Haro at Ahn''Qiraj in Silithus.', `VerifiedBuild`=19034 WHERE `ID` IN (8558 /*Sickle of Unyielding Strength*/, 8705 /*Gavel of Infinite Wisdom*/, 8706 /*Hammer of the Gathering Storm*/, 8708 /*Mace of Unending Life*/, 8709 /*Dagger of Veiled Shadows*/, 8710 /*Kris of Unspoken Names*/, 8711 /*Blade of Eternal Justice*/, 8712 /*Scythe of the Unseen Path*/);
UPDATE `quest_template` SET `QuestDescription`='The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.$B$BIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.$B$BBring me the components I require, $n.  I will give you a headpiece of unmatched power.', `VerifiedBuild`=19034 WHERE `ID` IN (8561 /*Conqueror's Crown*/, 8592 /*Tiara of the Oracle*/, 8623 /*Stormcaller's Diadem*/, 8628 /*Avenger's Crown*/, 8632 /*Enigma Circlet*/, 8639 /*Deathdealer's Helm*/, 8662 /*Doomcaller's Circlet*/, 8667 /*Genesis Helm*/);
UPDATE `quest_template` SET `LogDescription`='Bring the Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8562; -- Conqueror's Breastplate
UPDATE `quest_template` SET `QuestDescription`='The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, $n.$B$BYou''d be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.', `VerifiedBuild`=19034 WHERE `ID`=8572; -- Veteran's Battlegear
UPDATE `quest_template` SET `QuestDescription`='The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show, $n.$B$BYou''d be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.', `VerifiedBuild`=19034 WHERE `ID`=8574; -- Stalwart's Battlegear
UPDATE `quest_template` SET `LogDescription`='Bring the Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8603; -- Vestments of the Oracle
UPDATE `quest_template` SET `LogDescription`='Bring the Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8627; -- Avenger's Breastplate
UPDATE `quest_template` SET `LogDescription`='Bring the Carapace of the Old God, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8638; -- Deathdealer's Vest
UPDATE `quest_template` SET `LogDescription`='Bring the Carapace of the Old God, 2 Idols of Life, 5 Gold Scarabs and 5 Clay Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8656; -- Striker's Hauberk
UPDATE `quest_template` SET `QuestDescription`='The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.$B$BIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.$B$BBring me the components I require, $n.  I will make you a headpiece of unmatched power.', `VerifiedBuild`=19034 WHERE `ID`=8657; -- Striker's Diadem
UPDATE `quest_template` SET `LogDescription`='Bring the Husk of the Old God, 2 Idols of Night, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8661; -- Doomcaller's Robes
UPDATE `quest_template` SET `LogDescription`='Bring the Husk of the Old God, 2 Idols of Rebirth, 5 Bronze Scarabs and 5 Ivory Scarabs to Vethsera inside Ahn''Qiraj.  You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.', `VerifiedBuild`=19034 WHERE `ID`=8666; -- Genesis Vest
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.$B$BJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, $n, and I will make you a powerful weapon from the finest Qiraji materials.', `VerifiedBuild`=19034 WHERE `ID`=8707; -- Blade of Vaulted Secrets
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Greetings, $n.  Before I assign you to more involved tasks in the war, you''ll need to do your share of field duty.  $B$BYou will find Captain Skullsplit''s Orgrimmar Legion outside Hive''Regal.$B$BReport to him and come back to me with proof of your field service.  I shall have a more advanced assignment ready for you.$B$BOh, please do your best to stay away from the Ironforge Brigade.  Tensions are high among our Alliance and Horde volunteers.', `VerifiedBuild`=19034 WHERE `ID`=8731; -- Field Duty
UPDATE `quest_template` SET `QuestDescription`='We''ve sent our best scouts deep into the silithid hives to gather intelligence.  Scout Landion has been watching the silithid movements at Hive''Regal for several days now.  Find him and obtain a written report.  We need to be able to act on that information as soon as possible, $n.', `VerifiedBuild`=19034 WHERE `ID`=8738; -- Hive'Regal Scout Report
UPDATE `quest_template` SET `RewardMoney`=-49999, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (8763 /*The Hero of the Day*/, 8799 /*The Hero of the Day*/);
UPDATE `quest_template` SET `QuestDescription`='We have not sat idly by for a millennium, $n.$B$BWe have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery.$B$BWeaknesses exist and we know how to use those weaknesses to our advantage.$B$BFind and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.', `VerifiedBuild`=19034 WHERE `ID`=8789; -- Imperial Qiraji Armaments
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Hello, I''m glad that you''ve decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn''Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won''t be able to meet our goals without your assistance, $n!$B$BYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, $c? Will you help out with the vital preparations?', `VerifiedBuild`=19034 WHERE `ID` IN (8792 /*The Horde Needs Your Help!*/, 8793 /*The Horde Needs Your Help!*/, 8794 /*The Horde Needs Your Help!*/, 10500 /*The Horde Needs Your Help!*/);
UPDATE `quest_template` SET `QuestDescription`='Hello, I''m glad that you''ve decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn''Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won''t be able to meet our goals without your assistance, $n!$B$BYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, $c? Will you help out with the vital preparations?', `VerifiedBuild`=19034 WHERE `ID` IN (8795 /*The Alliance Needs Your Help!*/, 8796 /*The Alliance Needs Your Help!*/, 8797 /*The Alliance Needs Your Help!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='To the Caverns of Time you go, $G Lord:Lady; $n. Anachronos awaits your return. Give him the eye of C''Thun as he will undoubtedly wish to place it in his master''s collection.
', `VerifiedBuild`=19034 WHERE `ID`=8802; -- The Savior of Kalimdor
UPDATE `quest_template` SET `RewardMoney`=7, `RewardMoneyDifficulty`=1, `AllowableRaces`=18875469, `QuestDescription`='Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they''ll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it''ll be even better!$B$BWell anyway, Innkeeper Allison in Stormwind needs a supply of Smokywood Pastures fare to help feed all the party goers.  Can you do me a favor and deliver it?$B$BThanks, $n!  Innkeeper Allison is in The Gilded Rose, in the Trade District of Stormwind.', `VerifiedBuild`=19034 WHERE `ID`=8860; -- New Year Celebrations!
UPDATE `quest_template` SET `RewardMoney`=7, `RewardMoneyDifficulty`=1, `AllowableRaces`=33555378, `QuestDescription`='Thunder Bluff is holding a celebration for the new year!  All day you''ll find free booze there, and at night they''ll put on a firework show!$B$BIt should be pretty nice... but Booty Bay is also having a party today; I bet it''ll be even better!$B$BWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smokywood Pastures fare to help feed all the party goers.  Can you do me a favor and deliver it?$B$BThanks, $n!  Innkeeper Pala is in the inn near the bridge to Hunter''s Rise.', `VerifiedBuild`=19034 WHERE `ID`=8861; -- New Year Celebrations!
UPDATE `quest_template` SET `QuestDescription`='Every year the druids of Moonglade hold a celebration of our city''s great triumph over an ancient evil.$B$BWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!$B$BFor a small donation you can purchase colorful rockets from our vendor.  Try using some of the launchers around here, $n.', `VerifiedBuild`=19034 WHERE `ID`=8867; -- Lunar Fireworks
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `LogDescription`='Summon Omen, defeat him and gain Elune''s Blessing.  Return to Valadar Starsong in Nighthaven.', `QuestDescription`='The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake.$B$BFinally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune''ara.  But each new year, during the festival, he stirs...$B$BGather cohorts, $n, and summon and defeat the beast Omen.  Earn the blessing of Elune!', `VerifiedBuild`=19034 WHERE `ID`=8868; -- Elune's Blessing
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='It''s that time of the year, $n!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.', `VerifiedBuild`=19034 WHERE `ID` IN (8870 /*The Lunar Festival*/, 8871 /*The Lunar Festival*/, 8872 /*The Lunar Festival*/);
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='It''s that time of the year, $n!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.', `VerifiedBuild`=19034 WHERE `ID` IN (8873 /*The Lunar Festival*/, 8874 /*The Lunar Festival*/, 8875 /*The Lunar Festival*/);
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='$n, I have one last favor to ask of you. Would you please relay what''s transpired here to Magister Duskwither, back at the Farstrider Retreat? Let him know that I am well, but make certain that he is aware that some of the apprentices have become Wretched.$B$BThank you for your help!', `VerifiedBuild`=19034 WHERE `ID`=8890; -- Word from the Spire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='Sunsail Anchorage has been overrun by Wretched scum.  As soon as we manage to get reinforcements to the area we''ll show those thugs who''s boss, $n.$B$BIn the meantime you can help by showing them a bit of discipline.  Go in there and show them we are not to be trifled with.  You will find Sunsail Anchorage just to the west of Fairbreeze Village.', `VerifiedBuild`=19034 WHERE `ID`=8892; -- Situation at Sunsail Anchorage
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=50332671, `QuestDescription`='I''m pleased to discover that you''re at least somewhat competent, $n.  I''ll give you another task since you seem so eager to prove yourself.$B$BThis is a letter to Ley-Keeper Caidanis, the arcanist in charge of the upkeep of the North Sanctum.  Go southwest of Falconwing Square  and you will find him.  He is a very important person, so I hope you don''t bother him too much with trivial chatter.', `VerifiedBuild`=19034 WHERE `ID`=8895; -- Delivery to the North Sanctum
UPDATE `quest_template` SET `RewardMoney`=-399999, `QuestDescription`='Ah, you''re in need of my latest project... the extra-dimensional ghost revealer!  Unfortunately I''ve run out of funds and manpower.$B$BYou''re willing to help?  Excellent!  Our first task is to build a device to harvest the very fabric of death!  Building an ectoplasmic distiller won''t be an easy task, $n.$B$BI''ll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I''ll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter.', `VerifiedBuild`=19034 WHERE `ID`=8921; -- The Ectoplasmic Distiller
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `TimeAllowed`=6000, `VerifiedBuild`=19034 WHERE `ID`=9065; -- The Pattymac Special
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='I hope you learn a valuable lesson today, $n.  Never trust someone else to lie for you.$B$BNow I want you to go back to my two dimwitted students and discipline them using this wand.  My magic tells me that you''ll find them along the road to the west on the other side of the Dead Scar.$B$BCome back to me after you''ve done this.  I''ll give you a small reward for your troubles.', `VerifiedBuild`=19034 WHERE `ID`=9066; -- Swift Discipline
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9067 /*The Party Never Ends*/, 9156 /*Wanted: Knucklerot and Luzran*/, 25591 /*Thunderdrome: Grudge Match!*/, 25688 /*The Altar of Storms*/, 26043 /*BEWARE OF CRAGJAW!*/, 26334 /*Bloodlord Mandokir*/, 26386 /*Surkhan*/, 26419 /*Shadra the Venom Queen*/, 27090 /*Andorhal, Once and For All*/, 27297 /*Justice Dispensed*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Since you''re here, $n, I''ve a favor to ask you.  Ley-Keeper Velania''s apprentice dropped by earlier to ask for assistance.  Apparently there''s some malfunction happening at the West Sanctum.  I''ve been a bit busy entertaining our... most pleasant... dwarven guest.  See if you can give her a hand.  You''ll find the West Sanctum southwest of here.', `VerifiedBuild`=19034 WHERE `ID`=9119; -- Malfunction at the West Sanctum
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=33555378, `QuestDescription`='$n, the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our offensive by thinning out their numbers.$B$BThe magisters at the nearby Sanctum of the Sun have made a special request this time; they want the remains from these Scourge to study in hopes of finding creative ways of fighting them.$B$BGood hunting!', `VerifiedBuild`=19034 WHERE `ID`=9140; -- Windrunner Village
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='My nephew was sent into the Ghostlands a few days ago.  He never mentioned anything about his task, except that it was of an extremely secret nature.$B$BHe never returned and I fear for the worst, $c.  A missing messenger might not mean much to the callous magisters of Silvermoon, but he''s like a son to me.  Please, $n, will you look for him?', `VerifiedBuild`=19034 WHERE `ID`=9144; -- Missing in the Ghostlands
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=50332671, `QuestDescription`='To find a cure for the plague we need to understand how it affects different creatures, from the most complex life forms to the lowliest subspecies.$B$BI''ve come here to study the murlocs since, like us, they''ve retained free will in undeath.  What makes these lowly mongrels so special?  I need to find out, $n!$B$BTravel northwest and bring me their spines so that I may study the accumulation of plague in their marrow.  Who knows what secrets their little bones hold?', `VerifiedBuild`=19034 WHERE `ID`=9149; -- The Plagued Coast
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=33555378, `QuestDescription`='You''ve proven your loyalty to Tranquillien and have helped us defend it against the threat of the Scourge.  Some of our most powerful magisters have come from Silvermoon to help us take the fight to the enemy''s doorstep.$B$BThey''ve rebuilt the arcane sanctum to the south and have driven the Scourge away from the surrounding area.  They plan to launch an offensive into Deatholme, Dar''Khan''s stronghold.  You would do well to join them, $n.  I''m sure they can make use of a seasoned $c like yourself.', `VerifiedBuild`=19034 WHERE `ID`=9151; -- The Sanctum of the Sun
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='You show courage coming to the Ghostlands, $n.  There is much work to be done here and not enough brave souls to do it.$B$BI''ve a thankless task to offer you, should you have the inclination to aid our cause.  The very wildlife in this land has been tainted by the plague and we must stop it from spreading.  Hunt the ghostclaw lynxes to the east and south of here and return when you''ve slain enough of them.', `VerifiedBuild`=19034 WHERE `ID`=9158; -- Bearers of the Plague
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='You''ve proven your worth as an ally, $n.  I need you to continue your task and track down more plagued wildlife.  This time seek out some of the more dangerous beasts.  Hunt the spindleweb lurkers west of the Dead Scar and the vampiric mistbats just south of here.  Return to me when you''re done.', `VerifiedBuild`=19034 WHERE `ID`=9159; -- Curbing the Plague
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Dar''Khan Drathir is believed to have returned from the dead to rule over the armies of the Scourge in the Ghostlands.  Dar''Khan aligned himself with the Scourge long ago... yet he was once a living, breathing elf.  Much of his time was spent inside Dawnstar Spire, northeast of here.  He hid there for many nights, scheming against his own. $B$BSearch the tower for more information, $n.  Perhaps he had a journal or kept notes.  One never knows where useful information might present itself.', `VerifiedBuild`=19034 WHERE `ID`=9161; -- The Traitor's Shadow
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=33555378, `QuestDescription`='Everything we''ve done in the Ghostlands has been done with the goal of taking back what is rightfully ours.  The Scourge have maintained their chokehold on the region for far too long.$B$BThe time has come for payback, $n.  Thanks to your help and the help of our new allies, the Forsaken, vengeance will soon be ours.$B$BHe who sought to steal the power of the Sunwell must die.  Go to Deatholme, the Scourge stronghold south of the Dead Scar.  Bring me Dar''Khan''s head and your deeds will go down in history!', `VerifiedBuild`=19034 WHERE `ID`=9167; -- The Traitor's Destruction
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=11700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9170; -- Dar'Khan's Lieutenants
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='The magisters at the Sanctum of the Sun have made great progress in analyzing the Scourge''s weaknesses with the aid of the Forsaken.  Magister Kaendris will know what to do with this information.$B$BYou''ll find the Sanctum of the Sun southwest of here.  You must hurry, $n.  Dar''Khan is a cunning enemy and watches our every move!', `VerifiedBuild`=19034 WHERE `ID`=9172; -- Report to Magister Kaendris
UPDATE `quest_template` SET `AllowableRaces`=33554866, `VerifiedBuild`=19034 WHERE `ID` IN (9177 /*Journey to Undercity*/, 9329 /*The Forsaken*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=512, `VerifiedBuild`=19034 WHERE `ID`=9189; -- Delivery to the Sepulcher
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='I hear the Amani trolls eat their enemies'' hearts to steal their strength.  They might just be on to something, $n.  With the proper treatment, the hearts of the unliving can produce potent elixirs.$B$BHunt down the zombies that roam the Dead Scar and bring me their hearts.  I''ll show you the kind of enhancement we can perform to your physical prowess against the undead.', `VerifiedBuild`=19034 WHERE `ID`=9216; -- Rotting Hearts
UPDATE `quest_template` SET `QuestDescription`='$n,$B$BIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.$B$B$n, please report to the Keeper of the Rolls at Light''s Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.', `VerifiedBuild`=19034 WHERE `ID`=9247; -- The Keeper's Call
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `QuestDescription`='You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, $n. I only do as I must.$B$BKel''Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.$B$BAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn''Qiraj. He has left Ahn''Qiraj but the base of Atiesh remains.$B$BShould you succeed in recovering the pieces, return them to me.', `VerifiedBuild`=19034 WHERE `ID`=9251; -- Atiesh, the Befouled Greatstaff
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='We''ve experienced a marked increase in Scourge attacks, $n.  Our defenses are barely holding and there''s no sign of reinforcements from Silvermoon City.  Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.', `VerifiedBuild`=19034 WHERE `ID`=9252; -- Defending Fairbreeze Village
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=50332671, `VerifiedBuild`=19034 WHERE `ID` IN (9253 /*Runewarden Deryan*/, 9258 /*The Scorched Grove*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=50332671, `QuestDescription`='Thank you for your help, $n.  While I get things back in order here, I''d like to ask you for a favor.  One of my former apprentices embarked in a very dangerous line of research.  She journeyed to the East Sanctum, in the middle of the Dead Scar.$B$BI worry for her well-being.  See if you can find her and convince her to return to her senses.', `VerifiedBuild`=19034 WHERE `ID`=9254; -- The Wayward Apprentice
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9255 /*Research Notes*/, 24633 /*Mahka's Plea*/, 24977 /*Johaan's Experiment*/, 24983 /*Forsaken Duties*/, 25128 /*Hana'zua*/, 25171 /*Riding On*/, 25679 /*Into the Mountain*/, 25684 /*Attune the Bloodstone*/, 25686 /*Blood Ritual*/, 25689 /*Time is Short*/, 25700 /*Loramus Thalipedes Awaits*/, 26416 /*Well, Come to the Jungle*/, 26435 /*I'm A Huge Liar and a Fraud*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=33555378, `QuestDescription`='I have another task for you, $n.  Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard.  He has requested reinforcements which we cannot yet provide.  Seek him out and grant him whatever aid you can.$B$BFairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south.  Good luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=9256; -- Fairbreeze Village
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, $n.  The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake.$B$BThe details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse.$B$BIf you''re up to the task, I want you to go to the lake and put an end to their suffering, $n.  You will have my gratitude as well as theirs... I''m sure.', `VerifiedBuild`=19034 WHERE `ID`=9274; -- Spirits of the Drowned
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Time for something a little more challenging. Zeb''Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I''m dispatching you to go down there and assail them by whatever means you have at your disposal.$B$BWhat do you say, $n? Ready to deal with some more trolls?', `VerifiedBuild`=19034 WHERE `ID`=9277; -- Assault on Zeb'Nowa
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardBonusMoney`=60, `FlagsEx`=512, `QuestDescription`='Nevermind my injuries, $g brother : sister;. It''s a miracle that any of us are alive!$b$bIt didn''t look like you''d pull through; you''ve been in suspension for weeks.$B$BSomething happened and the Exodar crashed. Many have died.$B$BBut I''m relieved that you are alive, $n. With you leading our efforts, I''m sure we''ll get to safety soon! Proenitus asked me to send you to him when you awoke. He''s waiting for you at the bottom of the hill. Just follow the path southwest.', `VerifiedBuild`=19034 WHERE `ID`=9279; -- You Survived!
UPDATE `quest_template` SET `QuestPackageID`=566, `RewardNextQuest`=9409, `RewardXPDifficulty`=6, `RewardMoneyDifficulty`=5, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `VerifiedBuild`=19034 WHERE `ID`=9280; -- Replenishing the Healing Crystals
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Magisters and Farstriders may not see eye to eye all the time, $n.  When it comes to Dar''Khan, however, we''re all in agreement that a way must be found to defeat him and his legions.$B$BRanger Vynna, at the Farstrider Enclave northeast of here, has come across important information regarding our enemy.  Speak to her and see if you can be of assistance.  ', `VerifiedBuild`=19034 WHERE `ID`=9282; -- The Farstrider Enclave
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors.$b$bYou''ll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale.$b$bThe survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them.$B$BYou must save them, $n.', `VerifiedBuild`=19034 WHERE `ID`=9283; -- Rescue the Survivors!
UPDATE `quest_template` SET `RewardNextQuest`=9293, `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9293; -- What Must Be Done...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9303 /*Inoculation*/, 9606 /*Return to Caregiver Chellan*/, 9610 /*[DEPRECATED]Pool of Tears*/, 11134 /*The End of the Deserters*/, 13698 /*Explosives Shredding*/, 25736 /*The Floodsurge Core*/, 25805 /*Return the Statuette*/, 26095 /*Stromgarde Badges*/, 26112 /*Demanding Answers*/, 26504 /*Wanted: Redridge Gnolls*/, 27033 /*Skystrider's Heart*/, 27160 /*War Machines*/, 27171 /*Ambushed!*/, 27222 /*Take Down Tethyr!*/, 27239 /*Survey Alcaz Island*/, 27241 /*Return to Jaina*/, 27288 /*The Deserters*/, 28278 /*I Am the Law and I Am the Lash*/, 28328 /*Twilight Scheming*/);
UPDATE `quest_template` SET `QuestPackageID`=567, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=18875469, `QuestDescription`='We managed to recover a damaged holographic emitter from the crash. If we repair it, we''ll have a chance to find other survivors outside of Ammen Vale.$B$BThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. $B$B$n, you must go south to Nestlewood Thicket and Hills to find the spare parts.', `VerifiedBuild`=19034 WHERE `ID`=9305; -- Spare Parts
UPDATE `quest_template` SET `Flags`=1572992, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9309; -- The Missing Scout
UPDATE `quest_template` SET `QuestPackageID`=568, `RewardMoneyDifficulty`=7, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemQuantity6`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9311; -- Blood Elf Spy
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='$n, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter.  You might want to speak with her.', `VerifiedBuild`=19034 WHERE `ID`=9312; -- The Emitter
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='By all that is good, $n, you must go at once to this Azure Watch and speak with Dyvuun!$B$BThere is a path that leads west off of this tiny isle.  Follow it and cross the Crystalbrook River to arrive on the larger part of the isle.  Continue to follow the path and you should find Azure Watch.$B$BSee if you can convince them to send us some aid and supplies.  The rest of us will follow when we can.$B$BThank you, we wouldn''t have made it without you!', `VerifiedBuild`=19034 WHERE `ID`=9313; -- Travel to Azure Watch
UPDATE `quest_template` SET `RewardMoney`=55, `RewardMoneyDifficulty`=4, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9324 /*Stealing Orgrimmar's Flame*/, 9325 /*Stealing Thunder Bluff's Flame*/, 9326 /*Stealing the Undercity's Flame*/, 11935 /*Stealing Silvermoon's Flame*/);
UPDATE `quest_template` SET `QuestDescription`='This is the beginning of a new chapter in the history of our race, $n.  Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies.$B$BTake the traitor''s head to Regent Lord Lor''themar Theron in Silvermoon City.  He''ll be eager to hear the news.', `VerifiedBuild`=19034 WHERE `ID`=9328; -- Hero of the Sin'dorei
UPDATE `quest_template` SET `RewardMoney`=55, `RewardMoneyDifficulty`=4, `RewardBonusMoney`=6900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9330 /*Stealing Stormwind's Flame*/, 9331 /*Stealing Ironforge's Flame*/, 9332 /*Stealing Darnassus's Flame*/, 11933 /*Stealing the Exodar's Flame*/, 13112 /*Infused Mushroom Meatloaf*/, 13113 /*Convention at the Legerdemain*/, 13114 /*Sewer Stew*/, 13115 /*Cheese for Glowergold*/);
