UPDATE `quest_template` SET `RewardBonusMoney`=14700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9390 /*In Search of Sedai*/, 9423 /*Return to Obadei*/, 9793 /*The Fate of Tuurem*/, 9961 /*What's Wrong at Cenarion Thicket?*/, 10093 /*The Temple of Telhamat*/, 10104 /*Concerns About Tuurem*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=33555378, `QuestDescription`='Outland holds many secrets, $n.  It''s only a matter of time before we uncover them all.$B$BThe half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world.  Travel to the Den of Haal''esh, south of here.  Obtain any magical scrolls that the Haal''eshi might be carrying on them and bring them to me.', `VerifiedBuild`=19034 WHERE `ID`=9396; -- Magic of the Arakkoa
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9398 /*Deadly Predators*/, 9420 /*The Finest Down*/, 9777 /*Fulgor Spores*/, 9780 /*Umbrafen Eel Filets*/, 9781 /*Too Many Mouths to Feed*/, 9786 /*The Boha'mu Ruins*/, 9790 /*Diaphanous Wings*/, 9791 /*Menacing Marshfangs*/, 9801 /*Gathering the Reagents*/, 9827 /*Withered Basidium*/, 9896 /*Blacksting's Bane*/, 9901 /*Unfinished Business*/, 10869 /*Thin the Flock*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9402 /*Fetch!*/, 9403 /*The Purest Water*/, 9404 /*Recently Living*/, 27278 /*Grimshot's Call*/, 27283 /*A Journey to Moonglade*/);
UPDATE `quest_template` SET `RewardBonusMoney`=29100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9405; -- The Warchief's Mandate
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='For years the Dark Portal loomed silent... forgotten.  But it is silent no longer.$B$BAfter stopping the demonic assault here, our forces breached the portal and met the demons on their own ground!$B$BNow, we are locked in a savage war, and there are some who think we might not win.  So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, $n.$B$BIf you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...
', `VerifiedBuild`=19034 WHERE `ID`=9407; -- Through the Dark Portal
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `AllowableRaces`=33555378, `QuestDescription`='Even our best tracking wolves'' senses can fail them, $n.  The spirits have a way of seeing the world differently than ours.  The being you will call forth will find the person you seek, for they''ll be drawn not to their scent but their essence.$B$BGo now, $c, take this totem with you and use it at the location you found the stone axe.', `VerifiedBuild`=19034 WHERE `ID`=9410; -- A Spirit Guide
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=59100, `AllowableRaces`=18875469, `QuestDescription`='The arakkoa are smart creatures... smart as any gnome you ever met.  They have this way with magic and a violent temper, however. $B$BLately they''ve taken to attacking Honor Hold patrols, which is why we were sent here.  See, Mirren and I are world-famous marksmen, we are!  But fowl and game are what we specialize in... not these... lightning-invoking birdmen.$B$BSo what do you say you give us a hand in this one assignment?  You''ll find the Den of Haal''esh to the southeast.', `VerifiedBuild`=19034 WHERE `ID`=9417; -- The Arakkoa Threat
UPDATE `quest_template` SET `RewardBonusMoney`=59100, `VerifiedBuild`=19034 WHERE `ID` IN (9418 /*Avruu's Orb*/, 9732 /*Return to the Marsh*/, 9739 /*The Sporelings' Plight*/, 9802 /*Plants of Zangarmarsh*/, 9978 /*By Any Means Necessary*/, 10878 /*Before Darkness Falls*/);
UPDATE `quest_template` SET `RewardBonusMoney`=50700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9419; -- Scouring the Desert
UPDATE `quest_template` SET `RewardBonusMoney`=59100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9424; -- Makuru's Vengeance
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9426 /*The Pools of Aggonar*/, 9427 /*Cleansing the Waters*/, 9563 /*Gaining Mirren's Trust*/);
UPDATE `quest_template` SET `AllowableRaces`=512, `QuestDescription`='<The ambassador keeps her voice low as she leans in close.>$B$BYour reputation precedes you, $n.  I want you to travel to Splintertree Post in Ashenvale.  The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.$B$BWhen you arrive, speak with Advisor Sunsworn.  Travel carefully; Ashenvale can be a very dangerous place!', `VerifiedBuild`=19034 WHERE `ID`=9428; -- Report to Splintertree Post
UPDATE `quest_template` SET `RewardBonusMoney`=59100, `AllowableRaces`=18875469, `QuestDescription`='As I''ve told you before, I do not require eyes to see what others cannot.  I will not pass judgment on what you did on Makuru''s behalf, yet I think you need to see beyond what your eyes show you.$B$BTravel southwest to the Ruins of Sha''naar and salvage any relics you find.  If fate wills it you will find what we need.$B$BThe meaning of my request might not be immediately apparent.  Have faith though, $n.  Clarity comes to those with patience.', `VerifiedBuild`=19034 WHERE `ID`=9430; -- Sha'naar Relics
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `AllowableRaces`=33555378, `QuestDescription`='The warchief has been waiting for word of this ever since we set foot on Outland.  Now you get the honor of giving him the news of the Mag''har yourself.$B$BGo quickly, $n.  Take this letter with you; it bears my personal seal.  There is nothing that Thrall wants to hear more than the message you bear.', `VerifiedBuild`=19034 WHERE `ID`=9438; -- Messenger to Thrall
UPDATE `quest_template` SET `RewardBonusMoney`=59100, `AllowableRaces`=33555378, `QuestDescription`='I''d leave for Outland this very minute after hearing the news you brought.  Important matters require my attention in Durotar, however.$B$BI will arrange for a fitting tribute to be sent to the Mag''har immediately.  I will send my most trusted diplomats as well.  This will all take time... I need someone to represent us there right now.$B$BI must place my trust on you, $n.  Go to the Mag''har Post in Hellfire and render whatever services you can to my kin.  Do not fail me, $n.  Too much depends on this.', `VerifiedBuild`=19034 WHERE `ID`=9441; -- Envoy to the Mag'har
UPDATE `quest_template` SET `RewardBonusMoney`=59100, `AllowableRaces`=33555378, `QuestDescription`='It is good that you''ve offered to aid us, $n.  Our grunts have fallen sick from drinking contaminated water and I''m missing an ingredient to produce a healing salve.  I''m in need of a rare mushroom called drycap.$B$BOur foremost orders are to keep our location secret and not risk being spotted while looking for it, or I would go myself.  The only place in Hellfire Peninsula where drycap grows is a cave at the Great Fissure, south of here.$B$BBe extremely careful if you choose to seek it.', `VerifiedBuild`=19034 WHERE `ID`=9442; -- A Debilitating Sickness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=59100, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9447; -- Administering the Salve
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='You did a wonderful job, $n. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch?$B$BHe shouldn''t be hard to find as he is awaiting this catch.', `VerifiedBuild`=19034 WHERE `ID`=9453; -- Find Acteon!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `AllowableRaces`=-1, `QuestDescription`='You''re starting to make a name for yourself, $n. How about trying your hand at hunting?$B$BBack on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk.$B$BIf you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat.$B$BYou will find them grazing south of Azure Watch. Watch out for their horns!', `VerifiedBuild`=19034 WHERE `ID`=9454; -- The Great Moongraze Hunt
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9457 /*An Unusual Patron*/, 25195 /*That's the End of That Raptor*/, 25259 /*Gaur Icehorn*/, 25340 /*Dark Heart*/, 25628 /*Two-Tusk Takedown*/, 25681 /*Some People Just Need Killing*/, 25874 /*Horn of the Traitor*/, 26029 /*The Real Threat*/, 26180 /*Supervisor Fizsprocket*/, 26330 /*Who's a Big Troll?*/, 26553 /*High Priestess Jeklik*/, 26912 /*The Princess Unleashed*/, 26925 /*Araj the Summoner*/, 27319 /*Grimtotem Chiefs: Elder Stormhoof*/, 27324 /*Grimtotem Chiefs: Grundig Darkcloud*/, 27330 /*Invoking the Serpent*/, 28438 /*Trial by Magma*/);
UPDATE `quest_template` SET `AllowableRaces`=1024, `VerifiedBuild`=19034 WHERE `ID` IN (9464 /*Call of Fire*/, 9465 /*Call of Fire*/, 9468 /*Call of Fire*/, 14082 /*Learn to Ride at the Exodar*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=74100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9466; -- Wanted: Blacktalon the Savage
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=72900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9472; -- Arelion's Mistress
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='The girl is too far gone for mere ointments to be effective. There may be another way...$B$BThe forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all.$B$BYou can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste!$B$BAnd $n, be wary of the root threshers of the region as they consume snapdragon for sustenance.', `VerifiedBuild`=19034 WHERE `ID`=9473; -- An Alternative Alternative
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=74100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9490; -- The Rock Flayer Matriarch
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=129900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9492 /*Turning the Tide*/, 9493 /*Pride of the Fel Horde*/, 29654 /*Turning the Tide*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=129900, `AllowableRaces`=18875469, `QuestDescription`='The stuffy academics of Azeroth have cowered in their towers for too long and it''s fallen to me to show them what cutting edge research is! They''re afraid to play with fire and that''s exactly what I intend to do, once I get my hands on the fire, that is.$B$BWithin Hellfire Citadel''s Shattered Halls, Grand Warlock Nethekurse performs unrivaled magical feats augmented by the powers of a pair of strange braziers. Using the vessel he uses to contain these fel embers, capture one and bring it back to me, $n.', `VerifiedBuild`=19034 WHERE `ID`=9494; -- Fel Embers
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=129900, `AllowableRaces`=33555378, `QuestDescription`='The struggle to free the orcish people from our tainted blood has not been easy, $n. Warchief Thrall has seen too many orcish heroes laid low by fate''s hand. Now, it seems Kargath Bladefist numbers among them.$B$BIn the Shattered Halls of Hellfire Citadel, Kargath has claimed the title of ''Warchief'' of the Fel Horde. With an army of crazed, bloodthirsty fel orcs at his back, he won''t rest until Thrallmar is destroyed. Warchief Thrall has commanded us to defeat Kargath and his forces at all costs.', `VerifiedBuild`=19034 WHERE `ID`=9495; -- The Will of the Warchief
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=129900, `AllowableRaces`=33555378, `QuestDescription`='Overlord Maimfist''s insults aside, $n, this Fel Horde is nothing to be trifled with.$B$BFrom what we know, Fel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the Fel Horde regulars and serve as an officer corps.$B$BTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde''s leadership.
', `VerifiedBuild`=19034 WHERE `ID`=9496; -- Pride of the Fel Horde
UPDATE `quest_template` SET `RewardBonusMoney`=5850, `AllowableRaces`=33554866, `QuestDescription`='My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel.  You are welcome there as an ally, $n.$B$BIf you''re looking for work, go there and tell Ranger Captain Venn''ren that I sent you.  He will see to it that you''re given tasks worthy of someone of your caliber.', `VerifiedBuild`=19034 WHERE `ID`=9498; -- Falcon Watch
UPDATE `quest_template` SET `RewardBonusMoney`=5850, `QuestDescription`='What are you still doing here, $n?  Didn''t you hear we built a proper sin''dorei outpost here in Hellfire Peninsula?$B$BSurely you''d rather be among fellow blood elves and away from all this... smell.  You''ll find Falcon Watch in the southwest, beyond Hellfire Citadel.  Report to Ranger Captain Venn''ren; he will take care of you.$B$BThe road ahead is dangerous and heavily patrolled by Alliance scouts.  I would recommend travelling with companions.  Blood elves, preferably.', `VerifiedBuild`=19034 WHERE `ID`=9499; -- Falcon Watch
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=-1, `QuestDescription`='A naga invasion would be disastrous, $n. I''ve seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss''tiz will be hidden in a cave - probably along the coast to the west.$B$BFind Warlord Sriss''tiz and put an end to his reign.', `VerifiedBuild`=19034 WHERE `ID`=9515; -- Warlord Sriss'tiz
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!$B$BNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, $n, and we will show them that we''ll not suffer further destruction of our lands!$B$BGo, and do not rest until Overseer Gorthak and his minions are dead!', `VerifiedBuild`=19034 WHERE `ID`=9518; -- Agents of Destruction
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine''s keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.$B$BThese stories might be nothing but old wives'' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, $n.', `VerifiedBuild`=19034 WHERE `ID`=9519; -- The Lost Chalice
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `VerifiedBuild`=19034 WHERE `ID` IN (9524 /*Imprisoned in the Citadel*/, 10439 /*Dimensius the All-Devouring*/, 10781 /*Battle of the Crimson Watch*/, 10888 /*Trial of the Naaru: Magtheridon*/, 10901 /*The Cudgel of Kar'desh*/, 10946 /*Ruse of the Ashtongue*/, 10959 /*The Fall of the Betrayer*/, 10982 /*The Eye of Haramad*/, 11059 /*Guardian of the Monument*/, 11071 /*Dragonmaw Race: Captain Skyshatter*/, 11079 /*A Fel Whip For Gahk*/, 11087 /*HYJAL FLAG*/, 11116 /*Trial of the Naaru: (QUEST FLAG)*/, 11166 /*X Marks... Your Doom!*/, 13430 /*Trial of the Naaru: Magtheridon*/, 13431 /*The Cudgel of Kar'desh*/, 13432 /*The Vials of Eternity*/);
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us.$B$BI fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer.$B$BWhen I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole.$B$BI care not for vengeance, $n. I only ask that their remains be returned to me for proper burial.', `VerifiedBuild`=19034 WHERE `ID`=9527; -- All That Remains
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=-1, `QuestDescription`='According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, $n.$B$BRemember the tree and leaves? You''re going to wear them! It''s a perfect disguise.$B$BGo to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.', `VerifiedBuild`=19034 WHERE `ID`=9531; -- Tree's Company
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.$B$BThe task of building won''t be easy, $n, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested $g men:women; his way.$B$BSpeak to me again and I will arrange for fast transport for you to their location.', `VerifiedBuild`=19034 WHERE `ID`=9533; -- A Helping Hand
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardFactionID1`=76, `AllowableRaces`=33555378, `QuestDescription`='$n, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.$B$BYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth''s floating, broken spear.$B$BDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.$b$bReturn to me with their weapons as proof of your deeds.', `VerifiedBuild`=19034 WHERE `ID` IN (9536 /*Never Again!*/, 26449 /*Never Again!*/);
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Spark must be brought to justice!$B$BI need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!$B$BIf a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt?$B$BAnd $n, use force if you have to...
', `VerifiedBuild`=19034 WHERE `ID`=9537; -- Show Gnomercy
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='I think I''ve cracked it, $n!$B$B<Aurren points to the totem.>$B$BAll that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs.$B$BI''ve written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem.$B$BSpeak to Arugoo when you return an educated $r!', `VerifiedBuild`=19034 WHERE `ID`=9538; -- Learning the Language
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=18875469, `QuestDescription`='Our history with the orcs is one of constant conflict, $n.  We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence.$B$BYet, this retaliation... it''s not what Sedai would''ve wanted.  Speak with our elder, Amaan the Wise.  He will help shed light on these events.', `VerifiedBuild`=19034 WHERE `ID`=9543; -- Atonement
UPDATE `quest_template` SET `RewardBonusMoney`=74100, `AllowableRaces`=18875469, `QuestDescription`='The stubborn close their mind and convince themselves of one truth.  The wise keep an open mind to the different possibilities leading to and stemming from the present.$B$BTake this relic with you to where you found Sedai.  See not with your eyes, $n, but with your mind.', `VerifiedBuild`=19034 WHERE `ID`=9545; -- The Seer's Relic
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9548; -- Pilfered Equipment
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='My observations and writings about the Blacksilt murlocs are quite illuminating, $n, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts'' rudimentary crafting skills.$B$BThe problem is that the Blacksilt carry these items with them at all times, and I can''t have their blood on my conscience. If you''re willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won''t ask how you came by them.', `VerifiedBuild`=19034 WHERE `ID`=9549; -- Artifacts of the Blacksilt
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9550 /*A Map to Where?*/, 9557 /*Deciphering the Book*/, 12123 /*Informing the Queen*/, 12128 /*Check Up on Raegar*/, 29144 /*Clean Up in Stormwind*/);
UPDATE `quest_template` SET `RewardBonusMoney`=5850, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9558; -- The Longbeards
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='The translation is ready now, $n.$B$B<Anchorite Paetheus points out a block of text at the end of his translation.>$B$B''The enemy is nearly upon us. We''ve gathered up all the survivors and retreated to the temple to the east. It''s the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I''ve taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.''', `VerifiedBuild`=19034 WHERE `ID`=9561; -- Nolkai's Words
UPDATE `quest_template` SET `RewardBonusMoney`=1080, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9564 /*Gurf's Dignity*/, 9573 /*Chieftain Oomooroo*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=4650, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9567 /*Know Thine Enemy*/, 9574 /*Victims of Corruption*/, 9584 /*The Second Sample*/, 9594 /*Signs of the Legion*/, 9628 /*Salvaging the Data*/, 26347 /*Keeper of the Flame*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=8100, `AllowableRaces`=18875469, `QuestDescription`='Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion''s hounds in these lands.$B$BToo long have the draenei fled in the wake of the Legion and its minions, $n. Wherever they have found us, they have shown no mercy.$B$BWe must not permit the satyr to exploit the Exodar''s crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!', `VerifiedBuild`=19034 WHERE `ID`=9569; -- Containing the Threat
UPDATE `quest_template` SET `RewardBonusMoney`=2760, `AllowableRaces`=-1, `QuestDescription`='After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast.$B$BIn my visions, I have seen one defeat the Kurken. The one must be you, $n. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.
', `VerifiedBuild`=19034 WHERE `ID`=9570; -- The Kurken is Lurkin'
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=116700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9572; -- Weaken the Ramparts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=116700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9575; -- Weaken the Ramparts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=2160, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9576 /*Cruelfin's Necklace*/, 9624 /*A Favorite Treat*/);
UPDATE `quest_template` SET `RewardBonusMoney`=8100, `AllowableRaces`=18875469, `QuestDescription`='Do you think often of your family, $n? There were a number of families aboard the Exodar, but I''ve heard of very few being reunited.$B$BI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it''s swarming with blood elves!$B$BI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.', `VerifiedBuild`=19034 WHERE `ID`=9578; -- Searching for Galaen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=8100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9579 /*Galaen's Fate*/, 9585 /*The Final Sample*/, 13882 /*The Seeds of Life*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9580 /*The Bear Necessities*/, 9647 /*Culling the Flutterers*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=1080, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9581 /*Learning from the Crystals*/, 9634 /*Alien Predators*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardSpell`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9582; -- Strength of One
UPDATE `quest_template` SET `QuestLevel`=100, `RewardMoney`=154000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=246600, `Flags`=4224, `RewardItem1`=2772, `RewardAmount1`=1, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `LogTitle`='Omar''s Test Quest bk', `VerifiedBuild`=19034 WHERE `ID`=9583; -- Omar's Test Quest
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=116700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9587; -- Dark Tidings
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=118200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9589 /*The Blood is Life*/, 9607 /*Heart of Rage*/, 29540 /*The Breaker*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=118200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9590 /*The Blood is Life*/, 9608 /*Heart of Rage*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9595; -- Control
UPDATE `quest_template` SET `QuestDescription`='Your task then, $n, is to aid our new allies, the Stillpine furbolgs.$b$bSeveral of the younger Stillpine shaman stumbled across a Bristlelimb camp and were slaughtered to the last.  Take this Symbol of Life and resurrect one of the shaman.$b$bBristlelimb Enclave is located to the east of the road just after you cross the bridge spanning Azuremyst and Bloodmyst Isle.  Speak with me when you have done this.
', `VerifiedBuild`=19034 WHERE `ID`=9600; -- Redemption
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='You must get this information to your people, $n. While your brave acts have certainly slowed down the plans of Kael''thas and his dark master, the attacks will undoubtedly continue.$B$BTake the traitor''s communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.', `VerifiedBuild`=19034 WHERE `ID`=9602; -- Deliver Them From Evil...
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='Here''s the box, $n. That should be enough for Chellan to get the inn up and running. Let her know that she can keep sending in orders as the need arises. Azure Watch urgently needs a place to care for the wounded and put up any travelers they receive.$B$BWhen you''re ready to return to Azure Watch, seek out Stephanos near the Seat of the Naaru in the Exodar.', `VerifiedBuild`=19034 WHERE `ID`=9605; -- Hippogryph Master Stephanos
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=-1, `QuestDescription`='You saved my life, $n! Thank you so much! That beast would have torn me to shreds if it weren''t for you.$B$BIf you see the exarch at Azure Watch, tell him of what you did. I''m sure he''ll be pleased to hear such news!', `VerifiedBuild`=19034 WHERE `ID`=9612; -- A Hearty Thanks!
UPDATE `quest_template` SET `QuestDescription`='Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, $n.  She is a beacon of wisdom for those of our calling.$b$bFarstrider Retreat lies south of Silvermoon City.', `VerifiedBuild`=19034 WHERE `ID`=9617; -- Seek the Farstriders
UPDATE `quest_template` SET `RewardBonusMoney`=4650, `AllowableRaces`=18875469, `QuestDescription`='As we''ve gotten ourselves established here at Blood Watch, I''ve been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn''t reported back.$B$BI worry about what might have happened to them, but I can''t spare the men to send another mission after them. Find them, $n, and lend them any assistance they require to return with their survey data.', `VerifiedBuild`=19034 WHERE `ID`=9620; -- The Missing Survey Team
UPDATE `quest_template` SET `QuestDescription`='There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?$B$BThis changes everything.  No longer will our power be questioned.  We''ll be able to join the Horde as equals.$B$BTake this letter to Sylvanas, ruler of the Forsaken.  She''s already on our side but the news of Dar''Khan''s death will be music to her ears.  Prepare for a long trip, $n.  If all goes well she will send you to Orgrimmar.', `VerifiedBuild`=19034 WHERE `ID`=9621; -- Envoy to the Horde
UPDATE `quest_template` SET `RewardBonusMoney`=780, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9622; -- Warn Your People
UPDATE `quest_template` SET `RewardBonusMoney`=120, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9623; -- Coming of Age
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=270, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9625; -- Elekks Are Serious Business
UPDATE `quest_template` SET `QuestDescription`='Ya people suffered a great betrayal by da Alliance. Ya succeeded in fightin'' off da Darnassian attacks an'' da spies from Ironforge. Now ye defeated a powerful Scourge leader at da footsteps of ya home. Ya worthiness is no longer a question.

It be clear dat now we need each other. Return ta Lor''themar. Tell him I hear ye message and accept. 

<The warchief crushes the letter inside his palm.> 

Welcome to da Horde, elf.', `VerifiedBuild`=19034 WHERE `ID`=9627; -- Allegiance to the Horde
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=3300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9629; -- Catch and Release
UPDATE `quest_template` SET `QuestDescription`='Your name is getting around, $n.  You''ve made your way into and out of Karazhan - more than most mortals can claim.$B$BI need to ask a special favor of you.  As part of our research, the Violet Eye has been trying to track down Medivh''s own journal.$B$BUnfortunately, none of the agents we''ve sent inside have come out.  Wravien was the last to be sent; see if you can find him and see about any leads on the journal.', `VerifiedBuild`=19034 WHERE `ID`=9630; -- Medivh's Journal
