UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9646; -- WANTED: Deathclaw
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=4650, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9648; -- Mac'Aree Mushroom Menagerie
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=8100, `AllowableRaces`=-1, `QuestDescription`='Good to see you again, $n! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?$B$BTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera''s tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.
', `VerifiedBuild`=19034 WHERE `ID`=9649; -- Ysera's Tears
UPDATE `quest_template` SET `RewardBonusMoney`=2160, `FlagsEx`=8, `AllowableRaces`=-1, `QuestDescription`='You''re just in time, $n. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots.$B$BWarn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus'' Landing.$B$BTime is of the essence so I am lending you my elekk. Be sure to keep it out of water.', `VerifiedBuild`=19034 WHERE `ID`=9663; -- The Kessel Run
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9664; -- Establishing New Outposts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=3300, `AllowableRaces`=-1, `QuestDescription`='Have you seen the serpent men? The ones that call themselves naga?$B$B<Kessel spits.>$B$BThey dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts?$B$BI need you to deliver a message to their leadership, $n. To the northeast is Wrathscale Lair, home to Lord Xiz. Find him, slay him where he stands and drive this banner through his corpse.$B$BLet them know fear whenever they should see our standard!', `VerifiedBuild`=19034 WHERE `ID`=9666; -- Declaration of Power
UPDATE `quest_template` SET `RewardBonusMoney`=4200, `AllowableRaces`=-1, `QuestDescription`='Help me, $n! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!$B$BHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!$B$BMy father will richly reward you if you can save me!', `VerifiedBuild`=19034 WHERE `ID`=9667; -- Saving Princess Stillpine
UPDATE `quest_template` SET `RewardBonusMoney`=330, `AllowableRaces`=18875469, `QuestDescription`='A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, $c.$B$BReport to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier.$B$BAnd remember this, $n: Honorable people do not always perform honorably. Sometimes they cannot.$B$BYou will find Blood Watch just up this road, to the north.', `VerifiedBuild`=19034 WHERE `ID`=9668; -- Report to Exarch Admetius
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=8700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9669; -- The Missing Expedition
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='It was a bloody mess, $n. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.$B$BAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!$B$BI managed to cut my way out and escape but I will not leave the others behind. So far I''ve been unsuccessful in nearing the pass. Would you lend a hand?$B$BDestroy those cocoons! Hopefully some of our team is still alive!
', `VerifiedBuild`=19034 WHERE `ID`=9670; -- They're Alive! Maybe...
UPDATE `quest_template` SET `RewardBonusMoney`=2040, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9672; -- The Bloodcurse Legacy
UPDATE `quest_template` SET `RewardBonusMoney`=8700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9683 /*Ending the Bloodcurse*/, 9688 /*Into the Dream*/);
UPDATE `quest_template` SET `RewardBonusMoney`=9900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9689; -- Razormaw
UPDATE `quest_template` SET `RewardBonusMoney`=660, `AllowableRaces`=18875469, `QuestDescription`='What does Argus mean to you, $n? Many draenei probably do not know or remember our home planet. It is there that we split from the man''ari: the twisted demonic reflections of ourselves that were ''gifted'' by Sargeras. Or as they call themselves, eredar.$B$BEredar... this word once held meaning.$B$B<Admetius smacks his lips as if to taste the word.>$B$BDisgusting.$B$BLet us not waste anymore time. Find Vindicator Boros to begin your training.', `VerifiedBuild`=19034 WHERE `ID`=9693; -- What Argus Means to Me
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9694 /*Blood Watch*/, 9944 /*Missing Mag'hari Procession*/, 9982 /*He Called Himself Altruis...*/, 9983 /*He Called Himself Altruis...*/, 10081 /*To Meet Mother Kashur*/, 10759 /*Find the Deserter*/);
UPDATE `quest_template` SET `RewardBonusMoney`=720, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9696; -- Translations...
UPDATE `quest_template` SET `RewardBonusMoney`=29700, `VerifiedBuild`=19034 WHERE `ID` IN (9697 /*Watcher Leesa'oh*/, 9979 /*Wind Trader Lathrai*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=-1, `QuestDescription`='I need you to deliver the translated documents to Velen personally, $n. I don''t trust that deranged messenger.$B$BExplain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar.$B$BMake haste!
', `VerifiedBuild`=19034 WHERE `ID`=9698; -- Audience with the Prophet
UPDATE `quest_template` SET `RewardBonusMoney`=1740, `AllowableRaces`=-1, `QuestDescription`='I thank you for the timely delivery, $n. You are turning out to be one of the Hand''s better agents.$B$BIf only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be.$B$BWould you be interested in some reconnaissance work?$B$BIf so, take these orders back to Vindicator Boros. He will give you your next mission.', `VerifiedBuild`=19034 WHERE `ID`=9699; -- Truth or Fiction
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=-1, `QuestDescription`='Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies.$B$BBe warned, $n; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.
', `VerifiedBuild`=19034 WHERE `ID`=9700; -- I Shoot Magic Into the Darkness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60000, `VerifiedBuild`=19034 WHERE `ID` IN (9702 /*A Question of Gluttony*/, 9911 /*The Count of the Marshes*/, 9990 /*Investigate Tuurem*/, 10112 /*A Personal Favor*/, 10839 /*Veil Skith: Darkstone of Terokk*/, 10848 /*Veil Rhaze: Unliving Evil*/, 10861 /*Veil Lithic: Preemptive Strike*/);
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='We have others pursuing leads on the sun portals, $n. I need you to focus on the task at hand.$B$BBoros has received new reports of another crash site. What we''ve since discovered is that the crash site is actually the Exodar''s cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale.$B$BThis area also holds medical supplies. Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.
', `VerifiedBuild`=19034 WHERE `ID`=9703; -- The Cryo-Core
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9706; -- Galaen's Journal - The Fate of Vindicator Saruan
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75000, `VerifiedBuild`=19034 WHERE `ID` IN (9709 /*Stealing Back the Mushrooms*/, 9730 /*Leader of the Darkcrest*/, 10020 /*A Cure for Zahlia*/);
UPDATE `quest_template` SET `RewardBonusMoney`=8100, `AllowableRaces`=18875469, `QuestDescription`='Matis will be brought to justice, $n; and I want you to be the one to find him and bring him back to the Triumvirate.$B$BScour the island for this killer. Should you find him, use this flare gun. When my trackers see the flare, they''ll come and assist in capturing Matis. Return to me after he''s been captured.', `VerifiedBuild`=19034 WHERE `ID`=9711; -- Matis the Cruel
UPDATE `quest_template` SET `RewardBonusMoney`=121500, `VerifiedBuild`=19034 WHERE `ID` IN (9715 /*Bring Me A Shrubbery!*/, 9717 /*Oh, It's On!*/, 9738 /*Lost in Action*/, 29563 /*Lost in Action*/);
UPDATE `quest_template` SET `RewardBonusMoney`=44400, `VerifiedBuild`=19034 WHERE `ID`=9718; -- As the Crow Flies
UPDATE `quest_template` SET `RewardBonusMoney`=121500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9719; -- Stalk the Stalker
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75000, `QuestDescription`='I cannot begin to comprehend why the naga would drain the water out of their own habitat.  What I do understand is a need to put a stop to their operations.$B$BThese seeds carry with them the rage of the earth.  Take them to the steam pumps operated by the naga and use them on their controls.$B$BThe vines that grow from the seeds will be as thick as your arm and as strong as iron.  Go, $n.  Restore the balance that the naga have upset.', `VerifiedBuild`=19034 WHERE `ID`=9720; -- Balance Must Be Preserved
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=30000, `VerifiedBuild`=19034 WHERE `ID`=9724; -- Warning the Cenarion Circle
UPDATE `quest_template` SET `RewardBonusMoney`=60000, `VerifiedBuild`=19034 WHERE `ID` IN (9726 /*Now That We're Friends...*/, 9743 /*Natural Enemies*/, 10017 /*Strained Supplies*/, 10021 /*Restoring the Light*/, 10037 /*Rather Be Fishin'*/, 10852 /*Missing Friends*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75000, `VerifiedBuild`=19034 WHERE `ID`=9728; -- A Warm Welcome
UPDATE `quest_template` SET `RewardBonusMoney`=75900, `VerifiedBuild`=19034 WHERE `ID` IN (9729 /*Fhwoor Smash!*/, 10930 /*The Big Bone Worm*/);
UPDATE `quest_template` SET `RewardBonusMoney`=8100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9740 /*The Sun Gate*/, 9748 /*Don't Drink the Water*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9741 /*Critters of the Void*/, 9890 /*Success!*/, 10113 /*The Nesingwary Safari*/, 10114 /*The Nesingwary Safari*/);
UPDATE `quest_template` SET `RewardBonusMoney`=8100, `AllowableRaces`=18875469, `QuestDescription`='Victory is close at hand, $n. With the discovery of the sun gate, it won''t be long until their supply lines are completely closed off. Now is the time to strike at their numbers.$B$BTo the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.', `VerifiedBuild`=19034 WHERE `ID`=9746; -- Limits of Physical Exhaustion
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `VerifiedBuild`=19034 WHERE `ID` IN (9747 /*The Umbrafen Tribe*/, 9894 /*Safeguarding the Watchers*/, 10096 /*Saving the Sporeloks*/, 10355 /*Withered Flesh*/, 10847 /*The Eyes of Skettis*/);
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9753 /*What We Know...*/, 11356 /*Costumed Orphan Matron*/, 11970 /*The Master of Summer Lore*/, 28492 /*Hero's Call: Ashenvale!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='Our attempts at interrogation have failed miserably, $n. Torture is - of course - out of the question. What we need is a $r on the inside.$B$BI can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent.$B$BUnder this guise, I want you to get whatever information you can out of the prisoner.$B$BAnd $n, do not leave Blood Watch while disguised as the spell will fail.', `VerifiedBuild`=19034 WHERE `ID`=9756; -- What We Don't Know...
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Now my friend, if you would be so kind as to return to Arcanist Vandril, I know that he is very anxious to send you out on your first mission here in the Ghostlands.$B$BWe''re counting on you, $n.  Don''t let us down.', `VerifiedBuild`=19034 WHERE `ID`=9758; -- Return to Arcanist Vandril
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=14100, `AllowableRaces`=18875469, `QuestDescription`='Don''t accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well.$B$BI won''t think less of you if you just walk away, $n.$B$BBut maybe you''re the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?', `VerifiedBuild`=19034 WHERE `ID`=9759; -- Ending Their World
UPDATE `quest_template` SET `RewardBonusMoney`=2340, `AllowableRaces`=18875469, `QuestDescription`='I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, $n; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment.$B$BTake the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator''s Rest - it will be slightly west of the road itself. Corin will be waiting for you.', `VerifiedBuild`=19034 WHERE `ID`=9760; -- Vindicator's Rest
UPDATE `quest_template` SET `RewardBonusMoney`=11700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9761; -- Clearing the Way
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=129900, `Flags`=16520, `VerifiedBuild`=19034 WHERE `ID`=9763; -- The Warlord's Hideout
UPDATE `quest_template` SET `RewardBonusMoney`=129900, `QuestDescription`='The Cenarion Expedition began as a peaceful venture, yet we now face the prospect of all out war with the naga.$B$BWe have many among us who are willing to fight but are ill equipped.  Bring me the naga''s own weapons so that we may reforge them into glaives and arrowheads.$B$BOnly the best armaments will have materials useful to us, $n.  You will have to seek out the naga of Coilfang Reservoir.', `VerifiedBuild`=19034 WHERE `ID`=9765; -- Preparing for War
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=33555378, `QuestDescription`='Sometimes I wish Denjai had sent a shaman with us, or at least given us a totem to keep the marshfang rippers at bay.$B$BThe whole place is crawling with the pests! It''s just not right. Shouldn''t something be eating these despicable things?$B$BWe''ve all been taking turns playing exterminator. You showed up at just the right time, $n. Congratulations! Now get out there and mop up some marshfangs!', `VerifiedBuild`=19034 WHERE `ID`=9770; -- Menacing Marshfangs
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `AllowableRaces`=33555378, `QuestDescription`='Now that you''re familiar with the terrain, I''d like to ask your help with something else. The Dead Mire, we''ve taken to calling the area to the northwest, is an eerie place. No one has ever reported seeing anything alive there, but they didn''t stay for very long, either.$B$BScout Jyoba volunteered to investigate the area and report on his findings. He left the post three days ago and hasn''t returned. It''s not like him to be gone that long without sending some kind of report. Will you search for him, $n?', `VerifiedBuild`=19034 WHERE `ID`=9771; -- Searching for Scout Jyoba
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9773 /*No More Mushrooms!*/, 10086 /*I Work... For the Horde!*/, 10087 /*Burn It Up... For the Horde!*/, 10220 /*Make Them Listen*/, 10278 /*The Warp Rifts*/, 10294 /*Void Ridge*/);
UPDATE `quest_template` SET `RewardBonusMoney`=14700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9775 /*Report to Shadow Hunter Denjai*/, 9796 /*News from Zangarmarsh*/, 9960 /*What's Wrong at Cenarion Thicket?*/);
UPDATE `quest_template` SET `RewardBonusMoney`=15000, `AllowableRaces`=18875469, `QuestDescription`='As you know, many of Telredor''s inhabitants are refugees from the war that decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our allies in this struggle. There are some who desire to join us, but feel they are not yet ready.$B$BWe owe them whatever help we can provide, $n. A group of Broken under the leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of Serpent Lake. Seek them out and extend your hand in friendship to them.', `VerifiedBuild`=19034 WHERE `ID`=9776; -- The Orebor Harborage
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `VerifiedBuild`=19034 WHERE `ID` IN (9778 /*Warden Hamoot*/, 9876 /*Failed Incursion*/, 10554 /*Ishanah*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='It is good to see you again, $n. I have a quandary that you might be able to solve.$B$BOur agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document.$B$BUnfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.', `VerifiedBuild`=19034 WHERE `ID`=9779; -- Intercepting the Message
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=18875469, `QuestDescription`='I have lived among the anchorites of Telredor for some time, $n, and in that time I''ve come to know the marsh quite well. Recently, I''ve started to notice a disturbing change in the land to the northeast.$B$BVirtually all life there has begun to wither and die, seemingly without explanation. I have a few ideas as to what might be happening, but they are little more than speculation. If you were to bring me a sample of the soil in that area, I may be able to get to the bottom of this mystery.', `VerifiedBuild`=19034 WHERE `ID`=9782; -- The Dead Mire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=18875469, `QuestDescription`='The soil sample you brought me is nearly devoid of moisture, $n. If the soil itself is losing moisture, then the creatures that live in the Dead Mire must be suffering terribly.$B$BI''ve seen what happens when the region''s fungal giants begin to wither and die. The pain drives them mad, causing them to attack anything in their path.$B$BThese creatures have no idea what''s happening to them. They''re beyond our ability to save, so the best we can do is to end their suffering.', `VerifiedBuild`=19034 WHERE `ID`=9783; -- An Unnatural Drought
UPDATE `quest_template` SET `RewardBonusMoney`=30000, `QuestDescription`='You''ve earned the trust of the Cenarion Expedition, $n.  It is time you spoke to the ancients allied with our cause, Ashyen and Keleth, and asked for their blessing.$B$BCarrying the mark of an ancient will fill you with great power.  These boons will become more powerful as your renown among us increases.$B$BGo, $n, and ask the ancients for their blessing. ', `VerifiedBuild`=19034 WHERE `ID`=9785; -- Blessings of the Ancients
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=18875469, `QuestDescription`='From what you''ve told me about your observations at the Boha''mu Ruins, it seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we can approach them, we must know more of their beliefs.$B$BReturn to Feralfen Village and discreetly gather some of their idols so that I may study them. Try to avoid angering them, $n, as it may hurt our chances of making contact with them.', `VerifiedBuild`=19034 WHERE `ID`=9787; -- Idols of the Feralfen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `QuestDescription`='Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their village.  Little did I know that the cave was being fought over by marsh beasts and spore men!$B$BI had to leave in a hurry and left behind a box containing my only worldly possessions.$B$BAfter managing to sneak out of Umbrafen with my belongings it was terrible irony that I would lose them so soon after.  If you''re willing to bring them back to me I''ll give you one of my very own personal items.  What do you say, $n?', `VerifiedBuild`=19034 WHERE `ID`=9788; -- A Damp, Dark Place
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=61500, `VerifiedBuild`=19034 WHERE `ID` IN (9789 /*Clefthoof Mastery*/, 9858 /*Talbuk Mastery*/, 9882 /*Stealing from Thieves*/, 9914 /*A Head Full of Ivory*/, 9925 /*Matters of Security*/, 9927 /*Ruthless Cunning*/, 9928 /*Armaments for Deception*/, 10109 /*I Must Have Them!*/, 10877 /*The Dread Relic*/);
UPDATE `quest_template` SET `RewardBonusMoney`=15000, `AllowableRaces`=18875469, `QuestDescription`='You''ve been honorable in our dealings, $n, at a time when trust is hard to win among my people.$B$BA large group of my brethren have made their home in the old draenei city of Telaar in Nagrand, to the south. To reach Telaar, take the road south into Nagrand, then continue southeast until you find yourself in the cliffs east of Oshu''gun.$B$BAnyone who has aided us, as you have, would be welcome among the people of Telaar.$B$BSeek out Warden Moi''bff Jill and tell him you have earned my trust.', `VerifiedBuild`=19034 WHERE `ID`=9792; -- A Message to Telaar
UPDATE `quest_template` SET `RewardBonusMoney`=15300, `AllowableRaces`=18875469, `QuestDescription`='$n, I have a favor to ask of you. Normally, I would do this myself, but my hands are already beyond full.$B$BI have an associate named Kialon at Sylvanaar in the Blade''s Edge Mountains to the north. He''s expecting to hear from me in the near future, although I suspect he won''t like what I have to say.$B$BIf you would deliver my response to him, you would have my gratitude. I must insist, and this is very important, that you not attempt to read the letter. It is for Kialon''s eyes alone.', `VerifiedBuild`=19034 WHERE `ID`=9794; -- No Time for Curiosity
UPDATE `quest_template` SET `RewardBonusMoney`=15300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9795; -- The Ogre Threat
UPDATE `quest_template` SET `RewardBonusMoney`=15000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9797; -- Reinforcements for Garadar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9798; -- Blood Elf Plans
UPDATE `quest_template` SET `RewardBonusMoney`=60900, `VerifiedBuild`=19034 WHERE `ID` IN (9800 /*A Rare Bean*/, 9804 /*Agitated Spirits of Skysong*/, 9805 /*Blessing of Incineratus*/, 9819 /*The Tortured Earth*/, 10024 /*Voren'thal's Visions*/, 10842 /*Vengeful Souls*/, 10913 /*An Improper Burial*/, 10914 /*A Hero Is Needed*/, 10915 /*The Fallen Exarch*/, 10920 /*For the Fallen*/, 10921 /*Terokkarantula*/, 10923 /*Evil Draws Near*/, 10929 /*Fumping*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=72900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9803; -- Messenger to the Feralfen
UPDATE `quest_template` SET `RewardBonusMoney`=60000, `LogDescription`='Gshaff wants you to gather 6 Fertile Spores from the various Zangarmarsh Spore Bats and Marsh Walkers.  Return to Gshaff at Sporeggar when you''ve completed this task.', `VerifiedBuild`=19034 WHERE `ID`=9806; -- Fertile Spores
UPDATE `quest_template` SET `RewardBonusMoney`=60000, `QuestDescription`='I''ve seen your kind use shiny round pieces of metal to trade for things that you need.  We''re not so different from you.  We use shiny round mushrooms as our currency.$B$BGlowcap mushrooms grow everywhere in the marsh, you just have to know how to pick them from the ground without wrecking them.  I''ll teach you how to do it, if you promise to bring us some for our reserves.  What do you say, $n?', `VerifiedBuild`=19034 WHERE `ID`=9808; -- Glowcap Mushrooms
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=61500, `VerifiedBuild`=19034 WHERE `ID` IN (9810 /*The Spirit Polluted*/, 9931 /*Returning the Favor*/, 9932 /*Body of Evidence*/);
UPDATE `quest_template` SET `AllowableRaces`=33554866, `QuestDescription`='This is the beginning of a new chapter in blood elf history, $n.  You''ve helped cement the bond between my race and yours, $r.$B$BTake the traitor''s head to Regent Lord Lor''themar Theron in Silvermoon City.  He''ll be eager to hear the news.', `VerifiedBuild`=19034 WHERE `ID`=9811; -- Friend of the Sin'dorei
UPDATE `quest_template` SET `AllowableRaces`=33554610, `QuestDescription`='There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?$B$BThis changes everything.  No longer will our power be questioned.  We''ll be able to join the Horde as equals.$B$BTake this letter to Sylvanas, ruler of the Forsaken.  She''s already on our side but the news of Dar''Khan''s death will be music to her ears.  Prepare for a long trip, $n.  If all goes well she will send you to Orgrimmar.', `VerifiedBuild`=19034 WHERE `ID`=9812; -- Envoy to the Horde
UPDATE `quest_template` SET `AllowableRaces`=33554610, `VerifiedBuild`=19034 WHERE `ID`=9813; -- Meeting the Warchief
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9814 /*Burstcap Mushrooms, Mon!*/, 9816 /*Have You Ever Seen One of These?*/, 9842 /*The Sharpest Blades*/, 9845 /*Angling to Beat the Competition*/, 9847 /*A Spirit Ally?*/, 9903 /*The Biggest of Them All*/, 9904 /*Pursuing Terrorclaw*/, 9987 /*Stymying the Arakkoa*/, 9997 /*Attack on Firewing Point*/, 10003 /*The Firewing Liaison*/, 10008 /*What Happens in Terokkar Stays in Terokkar*/, 10013 /*An Unseen Hand*/, 10018 /*Vestments of the Wolf Spirit*/, 10027 /*Magical Disturbances*/, 10118 /*Message to the Daggerfen*/);
UPDATE `quest_template` SET `RewardBonusMoney`=61500, `VerifiedBuild`=19034 WHERE `ID` IN (9815 /*Muck Diving*/, 9821 /*Eating Damnation*/, 10567 /*Creating the Pendant*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=74100, `VerifiedBuild`=19034 WHERE `ID`=9817; -- Leader of the Bloodscale
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (9820 /*WANTED: Boss Grog'ak*/, 10023 /*Patriarch Ironjaw*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60000, `AllowableRaces`=33555378, `QuestDescription`='The position of the ogres'' mushroom-cutting operation can''t be an accident. I can''t escape the suspicion that they''re preparing for an attack on Zabra''jin.$B$BI must know for certain, $n. The ogres have another outpost to the northwest, the Ango''rosh Grounds. If they''re staging for an attack, there will be evidence of their plans there. Go there, $n and search the camp for signs of their intentions. Return to me with anything that might be suspicious.', `VerifiedBuild`=19034 WHERE `ID`=9822; -- Impending Attack
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75000, `AllowableRaces`=33555378, `QuestDescription`='In order to end the Ango''rosh threat, we must kill their leader, Overlord Gorefist. We''ll do better than that, though. We''ll make an example of the overlord and his followers.$B$BGo to the Ango''rosh Stronghold and deal with our foes. The stronghold is located in a cave on a small island to the northwest of Zabra''jin. You''ll see a bridge made from a fallen mushroom beyond the Ango''rosh Camp.$B$BShow no mercy, $n. They certainly wouldn''t spare any of us.', `VerifiedBuild`=19034 WHERE `ID`=9823; -- Us or Them
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `VerifiedBuild`=19034 WHERE `ID` IN (9824 /*Arcane Disturbances*/, 10270 /*A Not-So-Modest Proposal*/, 10271 /*Getting Down to Business*/, 10272 /*A Promising Start*/, 10273 /*Troublesome Distractions*/, 10275 /*Triangulation Point Two*/, 10276 /*Full Triangle*/, 10290 /*In Search of Farahlite*/, 10315 /*Neutralizing the Nethermancers*/, 10318 /*Dealing with the Overmaster*/, 10323 /*Shutting Down Manaforge Ara*/, 10335 /*Surveying the Ruins*/, 10336 /*The Minions of Culuthas*/, 10353 /*Arconus the Insatiable*/, 10365 /*Shutting Down Manaforge Ara*/, 10970 /*A Mission of Mercy*/, 10971 /*Ethereum Secrets*/, 11004 /*World of Shadows*/, 11008 /*Fires Over Skettis*/, 11010 /*Bombing Run*/, 11015 /*Netherwing Crystals*/, 11016 /*Nethermine Flayer Hide*/, 11017 /*Netherdust Pollen*/, 11018 /*Nethercite Ore*/, 11020 /*A Slow Death*/, 11025 /*The Crystals*/, 11026 /*Banish the Demons*/, 11030 /*Our Boy Wants To Be A Skyguard Ranger*/, 11035 /*The Not-So-Friendly Skies...*/, 11051 /*Banish More Demons*/, 11058 /*An Apexis Relic*/, 11064 /*Dragonmaw Race: The Ballad of Oldie McOld*/, 11065 /*Wrangle Some Aether Rays!*/, 11066 /*Wrangle More Aether Rays!*/, 11077 /*Dragons are the Least of Our Problems*/, 11082 /*Seeker of Truth*/, 11086 /*Disrupting the Twilight Portal*/, 11090 /*Subdue the Subduer*/, 11093 /*Hungry Nether Rays*/, 11102 /*Bombing Run*/, 11515 /*Blood for Blood*/, 11535 /*Making Ready*/, 11536 /*Don't Stop Now....*/, 11539 /*Taking the Harbor*/, 11540 /*Crush the Dawnblade*/, 11541 /*Disrupt the Greengill Coast*/, 11546 /*Open for Business*/, 11547 /*Know Your Ley Lines*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='As you may have noticed, the outside of Karazhan is crawling with ghostly beings. The reason for their existence is unknown and unknowns bother me!$B$BBring me their ghostly essence so that I may study their nature.  Karazhan has many secrets, $n.  I''m determined to uncover all of them.', `VerifiedBuild`=19034 WHERE `ID`=9825; -- Restless Activity
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='These signs do not bode well for us, $n.  I''ve never been one for secrecy so I will tell you a bit about my organization, the Violet Eye.$B$BWe are agents of the Kirin Tor, the Magus Senate of Dalaran.  We were assigned to keep an eye on Karazhan and Medivh, in case things got out of hand.$B$BWhich they did... very quickly, after Medivh disappeared.$B$BThis report details my findings.  Take it to Archmage Cedric, also from the Violet Eye; you will find him in the outskirts of Dalaran Crater.', `VerifiedBuild`=19034 WHERE `ID`=9826; -- Contact from Dalaran
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9830 /*Stinger Venom*/, 9833 /*Lines of Communication*/, 9835 /*Ango'rosh Encroachment*/, 9848 /*Secrets of the Daggerfen*/, 9902 /*The Terror of Marshlight Lake*/, 9905 /*Maktu's Revenge*/, 9986 /*Stymying the Arakkoa*/, 9996 /*Attack on Firewing Point*/, 10002 /*The Firewing Liaison*/, 10007 /*Thinning the Ranks*/, 10012 /*Fel Orc Plans*/, 10016 /*Timber Worg Tails*/, 10026 /*Magical Disturbances*/, 10115 /*Daggerfen Deviance*/);
UPDATE `quest_template` SET `RewardBonusMoney`=129900, `QuestDescription`='I am deeply troubled by the news in this report, $n.  Gaining entry into Karazhan will be difficult, however.$B$BYou see, when it became apparent that I was stranded here I split the key into three fragments.$B$BI placed the keys inside enchanted containers, and in turn placed those in places that were safe at the time.$B$BWith the dark changes Outland has endured this no longer is the case.  The first fragment is in a section of Auchindoun taken over by the Shadow Council.  Return this fragment to me.', `VerifiedBuild`=19034 WHERE `ID`=9831; -- Entry Into Karazhan
UPDATE `quest_template` SET `RewardBonusMoney`=129900, `QuestDescription`='I hid the second fragment at the bottom of Serpent Lake, long before it was called that.  The giant drain installed there after the naga took over has likely pulled the container into the depths of Coilfang Reservoir.$B$BThe third fragment will prove the most trying, as I left it inside Tempest Keep back when it was controlled by the naaru.  Kael''thas now rules it and the chamber where I left it has become a prison.$B$BBring me these remaining fragments, $n.  Much depends on your success.', `VerifiedBuild`=19034 WHERE `ID`=9832; -- The Second and Third Fragments
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60000, `AllowableRaces`=18875469, `QuestDescription`='Maktu can always see a draenei approaching in his shiny armor from a mile away, even in this murky swamp!$B$BMaktu wants to laugh at them, but then he remembers that they have been kind to the Kurenai and he wants to teach them about how Kurenai make armor.$B$BThe dark, scaly hides of the fenclaw thrashers make some of the best armor Maktu has ever worn. If $n can bring Maktu some of these hides from the fenclaw thrashers deep in Serpent Lake, he''ll be happy to share some of his armor.', `VerifiedBuild`=19034 WHERE `ID`=9834; -- Natural Armor
UPDATE `quest_template` SET `RewardBonusMoney`=129900, `VerifiedBuild`=19034 WHERE `ID` IN (9836 /*The Master's Touch*/, 10178 /*Find Spy To'gun*/, 10649 /*The Book of Fel Names*/, 10705 /*Seer Udalo*/, 10902 /*Master of Elixirs*/, 11488 /*Magisters' Terrace*/);
UPDATE `quest_template` SET `RewardBonusMoney`=97500, `QuestDescription`='I seem to have memories about future events surrounding you and this key.$B$B<Medivh looks at you like he''s just seen a ghost.>$B$BYou have trying times ahead of you, $n.  Let us hope your strength does not fail you.$B$BRegarding the key, I am to hand it to Khadgar when he''s sent to me.  I couldn''t hope for a better apprentice.$B$BI suppose you will need a key of your own.$B$B<Medivh reaches into his robe and hands you his own key.>$B$BGo on then.  And best of luck, $c.', `VerifiedBuild`=19034 WHERE `ID`=9837; -- Return to Khadgar
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='A great responsibility has been bestowed upon you, $n.  If the signs that the Violet Eye has observed are to be trusted, then you must help them.$B$BFor all my disagreements with Cedric, the work that men like Alturus do is still important.  Beware that they do not use you, however.  Remember it is you who the key is bound to, not them.  But if the danger in Karazhan is real, then it is they who are best prepared to guide you in dealing with it.  Go back to Alturus and help him in any way that you can.', `VerifiedBuild`=19034 WHERE `ID`=9838; -- The Violet Eye
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (9839 /*Overlord Gorefist*/, 10022 /*The Elusive Ironjaw*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60000, `AllowableRaces`=33555378, `QuestDescription`='It''s impossible to work with all this infernal buzzing! Do you hear it?$B$BI can''t get it out of my head! I know exactly what''s making the noise, too. It''s those damnable marshlight bleeders! The noise always comes from the south and west of the village.$B$BThey''re too big to swat, crush underfoot, or wave away. The only way to stop that unholy droning is to kill them. I don''t care how you do it, $n, just quiet them!', `VerifiedBuild`=19034 WHERE `ID`=9841; -- Stinging the Stingers
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='Keanna''s last few entries confirm our suspicions of a demonic presence inside Karazhan.$B$BShe detected the arrival of a Burning Legion agent whose location she describes as coming from the top of the tower.$B$BHer entries stop there.$B$BKarazhan is a very important place, $c.  It is a portal into the nether, a beacon shining into other worlds.  The possible repercussions of it falling into the wrong hands are unthinkable.  This demonic intrusion must be stopped.  And you, $n, are the only one with a key.', `VerifiedBuild`=19034 WHERE `ID`=9844; -- A Demonic Presence
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=33555378, `QuestDescription`='The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to possess powerful medicine. There may be no truth to such rumors, but anything that might help me channel the spirits of this world cannot be ignored.$B$BFind the Feralfen mystics, hunters and druids, $n, and capture their totems. Everything I need to know should be apparent from the carvings.', `VerifiedBuild`=19034 WHERE `ID`=9846; -- Spirits of the Feralfen
UPDATE `quest_template` SET `RewardBonusMoney`=93600, `VerifiedBuild`=19034 WHERE `ID` IN (9849 /*Shattering the Veil*/, 9853 /*Gurok the Usurper*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `VerifiedBuild`=19034 WHERE `ID` IN (9850 /*Clefthoof Mastery*/, 9855 /*Windroc Mastery*/, 9900 /*Gava'xi*/, 9956 /*The Ravaged Caravan*/, 10074 /*Oshu'gun Crystal Powder*/, 10076 /*Oshu'gun Crystal Powder*/, 10682 /*A Time for Negotiation...*/, 10713 /*...and a Time for Action*/, 10717 /*Poaching from Poachers*/, 10770 /*Little Embers*/, 10771 /*From the Ashes*/, 10893 /*Longtail is the Lynchpin*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=78000, `VerifiedBuild`=19034 WHERE `ID` IN (9851 /*Clefthoof Mastery*/, 9856 /*Windroc Mastery*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=94800, `RewardChoiceItemID2`=25639, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemQuantity6`=0, `VerifiedBuild`=19034 WHERE `ID`=9852; -- The Ultimate Bloodsport
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60900, `VerifiedBuild`=19034 WHERE `ID` IN (9854 /*Windroc Mastery*/, 9857 /*Talbuk Mastery*/, 9897 /*I'm Saved!*/, 10030 /*Recover the Bones*/, 10840 /*The Tomb of Lights*/, 10873 /*Taken in the Night*/, 10874 /*Veil Shalas: Signal Fires*/, 10917 /*The Outcast's Plight*/, 10922 /*Digging Through Bones*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=77100, `VerifiedBuild`=19034 WHERE `ID` IN (9859 /*Talbuk Mastery*/, 10111 /*Bring Me The Egg!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `QuestDescription`='Return to Cedric at once, $n.  The aid you''ve given the Violet Eye will not go unrewarded.$B$BThink what you want of us and our organization, $c, but gaining the favor of the archmages of Dalaran will not be something you regret.', `VerifiedBuild`=19034 WHERE `ID`=9860; -- The New Directive
UPDATE `quest_template` SET `RewardBonusMoney`=62400, `VerifiedBuild`=19034 WHERE `ID` IN (9861 /*The Howling Wind*/, 9862 /*Murkblood Corrupters*/, 9867 /*Murkblood Leaders...*/, 9878 /*Solving the Problem*/, 10231 /*What Book? I Don't See Any Book.*/, 10252 /*Vision of the Dead*/);
UPDATE `quest_template` SET `RewardBonusMoney`=61500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9863 /*Vile Idolatry*/, 9916 /*Bleeding Hollow Supply Crates*/, 9924 /*Corki's Gone Missing Again!*/, 10555 /*Malaise*/);
UPDATE `quest_template` SET `RewardBonusMoney`=15600, `AllowableRaces`=-1, `QuestDescription`='After the last Murkblood raid, a group of younglings decided to act. We tried to stop them but the rage had taken hold. It has now been one week since we last saw our beloved younglings.$B$BPlease, $r, you must find them! They have just barely reached adolescence. How can they expect to defeat such savages?$B$BThey took the road leading west out of town. Follow that road around and look for signs of our younglings.$B$BAnd $n, avoid Halaa if you value your life. It is a war-zone.', `VerifiedBuild`=19034 WHERE `ID`=9864; -- The Missing War Party
UPDATE `quest_template` SET `RewardBonusMoney`=62400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9865 /*Once Were Warriors*/, 9871 /*Murkblood Invaders*/, 9872 /*Murkblood Invaders*/, 9873 /*Ortor My Old Friend...*/, 10476 /*Fierce Enemies*/, 10479 /*Proving Your Strength*/);
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Will you do me one last honor, $n? I do not wish to return to Garadar. I believe that my destiny lies elsewhere - that I will serve a greater purpose someday.$B$BPlease, return to Farseer Corhuk and tell him that I will not be returning. That I cannot return. I must walk the earth... He will understand.', `VerifiedBuild`=19034 WHERE `ID`=9866; -- He Will Walk The Earth...
UPDATE `quest_template` SET `RewardBonusMoney`=78000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9868 /*The Totem of Kar'dash*/, 9879 /*The Totem of Kar'dash*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=15300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9869; -- The Throne of the Elements
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=15300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9870; -- The Throne of the Elements
UPDATE `quest_template` SET `RewardBonusMoney`=62400, `AllowableRaces`=-1, `QuestDescription`='I have just gotten word of a catastrophe of epic proportions, $n. The foul Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered its residents. To make matters worse, they have begun dumping the bodies into Sunspring Lake. Should those bodies rot, our primary source of water in the region will be compromised.$B$BIt''s a gruesome task that I give you next but it must be done. Take this enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...', `VerifiedBuild`=19034 WHERE `ID`=9874; -- Stopping the Spread
UPDATE `quest_template` SET `RewardBonusMoney`=15300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9888 /*The Impotent Leader*/, 9891 /*Because Kilrath is a Coward*/);
UPDATE `quest_template` SET `RewardBonusMoney`=60900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9889 /*Don't Kill the Fat One*/, 9910 /*Standards and Practices*/, 9917 /*Do My Eyes Deceive Me*/, 9918 /*Not On My Watch!*/, 9921 /*The Ruins of Burning Blade*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `QuestDescription`='All this waiting around for Oshu''gun to be ready for digging is eating into our profits, $n.$B$BFortunately, I''ve devised an alternate source of income.  The ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price in many other worlds.$B$BZerid already has had to take care a few of the brutes as a matter of security.  Think of the warbeads as an added bonus.  Or better yet, don''t think about it too much and just bring them to me.', `VerifiedBuild`=19034 WHERE `ID`=9893; -- Obsidian Warbeads
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=72900, `QuestDescription`='Have you observed your surroundings closely, $n? This is an ailing landscape, struggling to keep itself in balance and losing the fight.$B$BIf you know where to look, you can see the symptoms. Members of some species rapidly outgrow their peers and become more aggressive.$B$BA good example of this uncontrolled growth is the marshtrekker Boglash. If you wish to see it for yourself, look no further than the waterways south of the refuge.$B$BBe prepared to defend yourself. The creature knows no mercy.', `VerifiedBuild`=19034 WHERE `ID`=9895; -- The Dying Balance
UPDATE `quest_template` SET `RewardBonusMoney`=60900, `AllowableRaces`=-1, `QuestDescription`='Ogres are moved by one thing: Might. If we expose ourselves to them as being weak, they will take advantage of that weakness and wipe us out.$B$BGarrosh might be ready to lie down and let the ogre dogs take our lands but I am not! I need you to deliver a message to the Boulderfist, $n. The only type of message that they are capable of understanding: Brutality.$B$BTravel to the Burning Blade Ruins, southeast of here and show them the might of the Mag''har.$B$BAnd $n, check in with the others before leaving.', `VerifiedBuild`=19034 WHERE `ID`=9906; -- Message in a Battle
UPDATE `quest_template` SET `RewardBonusMoney`=77100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9907; -- An Audacious Advance
UPDATE `quest_template` SET `RewardBonusMoney`=5850, `VerifiedBuild`=19034 WHERE `ID`=9912; -- The Cenarion Expedition
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `VerifiedBuild`=19034 WHERE `ID` IN (9913 /*The Consortium Needs You!*/, 10194 /*Stealth Flight*/, 10200 /*Return to Thalodien*/, 10227 /*I See Dead Draenei*/, 10263 /*Assisting the Consortium*/, 10282 /*Old Hillsbrad*/, 10423 /*To the Stormspire*/, 10430 /*Testing the Prototype*/, 10434 /*The Dynamic Duo*/, 10652 /*Behind Enemy Lines*/, 10719 /*Did You Get The Note?*/, 10825 /*The Truth Unorbed*/, 10829 /*Treebole Must Know*/, 10894 /*Wyrmskull Watcher*/, 11038 /*Assist Exarch Orelis*/);
UPDATE `quest_template` SET `RewardBonusMoney`=60000, `QuestDescription`='You''re a kind $r, $n.  Not like some of the others I''ve met.$B$BYou should meet the rest of my people; they''ll be very grateful for your help.  Take these spore sacs to my leader, Msshi''fn.  You will find him in Sporeggar, north of here.', `VerifiedBuild`=19034 WHERE `ID`=9919; -- Sporeggar
UPDATE `quest_template` SET `RewardBonusMoney`=77100, `AllowableRaces`=-1, `QuestDescription`='You made a strong showing, $n. Are you ready for more?$B$BI have received reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand, northwest of here in the Halaani Basin.$B$BVenture forth to the clefts and deal with the remaining Boulderfist ogres.', `VerifiedBuild`=19034 WHERE `ID`=9922; -- The Twin Clefts of Nagrand
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=60900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9923; -- HELP!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=77100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=9933; -- Message to Telaar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=77100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=9934; -- Message to Garadar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=61500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9935 /*Wanted: Giselda the Crone*/, 9936 /*Wanted: Giselda the Crone*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=93600, `AllowableRaces`=-1, `QuestDescription`='You have destroyed two of the biggest threats in Nagrand, $n. Are you ready to take on the scourge of the Spirit Fields?$B$BDurn the Hungerer lords over the area surrounding Oshu''gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, far southwest of here, near Oshu''gun, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.
', `VerifiedBuild`=19034 WHERE `ID`=9937; -- Wanted: Durn the Hungerer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=93600, `AllowableRaces`=-1, `QuestDescription`='You have destroyed two of the biggest threats in Nagrand, $n. Are you ready to take on the scourge of the Spirit Fields?$B$BDurn the Hungerer lords over the area surrounding Oshu''gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, west of here, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.', `VerifiedBuild`=19034 WHERE `ID`=9938; -- Wanted: Durn the Hungerer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=61500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (9939 /*Wanted: Zorbo the Advisor*/, 9940 /*Wanted: Zorbo the Advisor*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=-1, `QuestDescription`='We were en route to the Ancestral Grounds when we were ambushed by Warmaul. They came from all sides, killing several of the procession guards and many of the others. They even desecrated the remains of the elder in the wagon.$B$BAnd for what? So they could humiliate us and display their power. Not even Boulderfist would have sunk so low.$B$BI am a spiritual orc, $n, but even I have limitations. Find the attackers at Warmaul Hill to the northwest and destroy them!', `VerifiedBuild`=19034 WHERE `ID`=9945; -- War on the Warmaul
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=78000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9946; -- Cho'war the Pillager
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=9948; -- Finding the Survivors
UPDATE `quest_template` SET `RewardBonusMoney`=75000, `VerifiedBuild`=19034 WHERE `ID` IN (9951 /*It's Watching You!*/, 10881 /*The Shadow Tomb*/);
UPDATE `quest_template` SET `RewardBonusMoney`=62400, `AllowableRaces`=-1, `QuestDescription`='<Arechron shows you a grime covered letter.>$B$BI just received this letter. It''s from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand. It says that they have Corki and if we don''t cooperate, they''re going to eat him. Admittedly, Corki is a moron, but he''s still my blood. Will you rescue him, $n?$B$BI presume that he''s locked up in a cage somewhere on Warmaul Hill. That should be your first stop.', `VerifiedBuild`=19034 WHERE `ID`=9954; -- Corki's Ransom
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=78000, `AllowableRaces`=-1, `QuestDescription`='They call him Cho''war the Pillager, $n. He''s the ogre that forced out the gronn that used to rule over these ogres. You better believe he''s powerful!$B$BThe chef said that Cho''war lives in the big cave - wherever that may be... Get that key and get me out of here! If we live through this, my father will no doubt give you the big reward! As soon as I''m free, seek him out.', `VerifiedBuild`=19034 WHERE `ID`=9955; -- Cho'war the Pillager
UPDATE `quest_template` SET `RewardBonusMoney`=14700, `QuestDescription`='We haven''t heard from the druids at the Cenarion Thicket of Terokkar Forest in quite some time.$B$B$n, I''d like for you to go down there and check in with them to see what''s happening.  There are several ways to get there, but the fastest is to head south along the path, and then take the road that branches east from Shattrath City once you''re in the forest.', `VerifiedBuild`=19034 WHERE `ID`=9957; -- What's Wrong at Cenarion Thicket?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=93600, `VerifiedBuild`=19034 WHERE `ID` IN (9962 /*The Ring of Blood: Brokentoe*/, 9972 /*The Ring of Blood: Skra'gath*/, 9973 /*The Ring of Blood: The Warmaul Champion*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=93600, `QuestDescription`='This next battle involves a duo - twin brothers to be precise. They call themselves the "Blue Brothers."$B$BIt''s not too late to chicken out, $n. I''d certainly understand.$B$BBut if you''re ready for some action, step in the Ring of Blood and wait for the Murkblood twins to arrive.$B$BLast one standing is the winner!', `VerifiedBuild`=19034 WHERE `ID`=9967; -- The Ring of Blood: The Blue Brothers
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=93600, `QuestDescription`='This fight is gonna be painful, $n. Do you have any friends that are brave enough to help you out? The ogres managed to get a giant from Blade''s Edge named Rokdar! Trust me, you''re gonna need friends, he seems unbeatable! He''s hard as a rock - literally!$B$BIf you still want to fight him, step into the Ring of Blood and he will come.', `VerifiedBuild`=19034 WHERE `ID`=9970; -- The Ring of Blood: Rokdar the Sundered Lord
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=94800, `VerifiedBuild`=19034 WHERE `ID`=9977; -- The Ring of Blood: The Final Challenge
UPDATE `quest_template` SET `RewardBonusMoney`=15900, `QuestDescription`='To be my eyes will require some diligence on your part. Nethrandamus will take you through the Legion camps, but you must catalog everything that you see. Even the smallest detail that you may think to be inconsequential could be useful for our purposes.$B$BPrimarily, I want you to note what structures are in the camps and what comprises the camps'' defenses.$B$BNethrandamus is ready when you are, $n. Do not be afraid, he will keep you safe from harm.
', `VerifiedBuild`=19034 WHERE `ID`=9991; -- Survey the Land
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=30000, `AllowableRaces`=18875469, `QuestDescription`='I don''t know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!$B$B$n, I think you should take this box of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast.  She may have some idea of what these are.', `VerifiedBuild`=19034 WHERE `ID`=9994; -- What Are These Things?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=30000, `AllowableRaces`=33555378, `QuestDescription`='I don''t know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!$B$B$n, I think you should take this box of parts to Tooki at Stonebreaker Hold to the southeast.  He may have some idea of what these are.', `VerifiedBuild`=19034 WHERE `ID`=9995; -- What Are These Things?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=59100, `AllowableRaces`=18875469, `QuestDescription`='The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings.$B$BThe construction goes on day and night, $n. I''ve dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She''ll give you further instructions.', `VerifiedBuild`=19034 WHERE `ID`=9998; -- Unruly Neighbors
UPDATE `quest_template` SET `RewardBonusMoney`=63300, `VerifiedBuild`=19034 WHERE `ID` IN (9999 /*Buying Time*/, 10001 /*The Master Planner*/, 10004 /*Patience and Understanding*/, 10182 /*Battle-Mage Dathric*/, 10243 /*Naaru Technology*/, 10246 /*Attack on Manaforge Coruu*/, 10313 /*Measuring Warp Energies*/, 10607 /*Whispers of the Raven God*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=88800, `AllowableRaces`=18875469, `QuestDescription`='$n, after you''re done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.$B$BI''m certain that he''ll want to know what really happened out there.', `VerifiedBuild`=19034 WHERE `ID`=10005; -- Letting Earthbinder Tavgren Know
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=88800, `AllowableRaces`=33555378, `QuestDescription`='$n, I think that after you''re done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.$B$BI''m certain that he''ll want to know what really happened out there.', `VerifiedBuild`=19034 WHERE `ID`=10006; -- Letting Earthbinder Tavgren Know
