UPDATE `quest_template` SET `RewardBonusMoney`=31500, `VerifiedBuild`=19034 WHERE `ID`=10010; -- It's Just That Easy?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=94800, `QuestDescription`='Gather your courage, $n. You will need it if you are to face an overseer.$B$BOnce you are ready, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.', `VerifiedBuild`=19034 WHERE `ID`=10011; -- Forge Camp: Annihilated
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60900, `QuestDescription`='Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.$B$B$n, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun''s walls.$B$BWhat?  You think leaving them to wander in blind agony would be better?$B$BAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.', `VerifiedBuild`=19034 WHERE `ID`=10031; -- Helping the Lost Find Their Way
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10033 /*Wanted: Bonelashers Dead!*/, 10040 /*Who Are They?*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10034 /*Wanted: Bonelashers Dead!*/, 10041 /*Who Are They?*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10035; -- Torgos!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10036; -- Torgos!
UPDATE `quest_template` SET `RewardBonusMoney`=15000, `AllowableRaces`=18875469, `QuestDescription`='A report''s just come in from one of our scouts near Grangol''var Village.  He says that a shadowy band has moved into the ruins there.$B$B$n, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.', `VerifiedBuild`=19034 WHERE `ID`=10038; -- Speak with Private Weeks
UPDATE `quest_template` SET `RewardBonusMoney`=15000, `AllowableRaces`=33555378, `QuestDescription`='I am informed that one of our scouts near Grangol''var Village is currently observing a shadowy band that has recently moved in there.$B$B$n, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.$B$BJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.', `VerifiedBuild`=19034 WHERE `ID`=10039; -- Speak with Scout Neftis
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AllowableRaces`=18875469, `QuestDescription`='What!  Those guys are Shadow Council?!$B$B$n, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.$B$BAfter you''re done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.$B$BGood luck, $c!', `VerifiedBuild`=19034 WHERE `ID`=10042; -- Kill the Shadow Council!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AllowableRaces`=33555378, `QuestDescription`='What!  Those guys are Shadow Council?!$B$B$n, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.$B$BAfter you''re done with that, report back to Advisor Faila at Stonebreaker Hold.$B$BGood luck, $c!', `VerifiedBuild`=19034 WHERE `ID`=10043; -- Kill the Shadow Council!
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=-1, `QuestDescription`='The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.$B$BMy will has been sapped but make no mistake, $n, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.$B$B<Garrosh points at the large building to the north.>$B$BListen to what she has to say and do as she tells you.', `VerifiedBuild`=19034 WHERE `ID`=10044; -- A Visit With the Greatmother
UPDATE `quest_template` SET `RewardBonusMoney`=79200, `AllowableRaces`=-1, `QuestDescription`='Mother Kashur wishes to speak with you, $n. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.$B$BYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade''s Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.', `VerifiedBuild`=19034 WHERE `ID`=10045; -- Material Components
UPDATE `quest_template` SET `RewardBonusMoney`=57600, `AllowableRaces`=18875469, `QuestDescription`='The ''Path of Glory,'' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.$B$BIt wasn''t enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.$B$BThose tortured souls still wander these lands, crying out for release. I ask you, $n, help me in this undertaking.', `VerifiedBuild`=19034 WHERE `ID`=10047; -- The Path of Glory
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=18875469, `QuestDescription`='Near the end of our invasion, the Armory to the south fell under attack by the Horde''s insidious Death Knights. Those vile shades cursed the Armory''s defenders - and trapped their souls between the realms of the living and the dead.$B$BThose noble souls must be set free! I beg you, $n, end my comrades'' torment, for I have not the heart to slay them myself.', `VerifiedBuild`=19034 WHERE `ID`=10050; -- Unyielding Souls
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10051; -- Escape from Firewing Point!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10052; -- Escape from Firewing Point!
UPDATE `quest_template` SET `RewardBonusMoney`=1920, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10063; -- Explorers' League, Is That Something for Gnomes?
UPDATE `quest_template` SET `RewardBonusMoney`=840, `AllowableRaces`=18875469, `QuestDescription`='The Hand of Argus has established a forward base at Vindicator''s Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we''d have no way to keep an eye on events near the Vector Coil.$B$BReport to Scout Jorli at Vindicator''s Rest to the northwest and offer her your assistance, $n.', `VerifiedBuild`=19034 WHERE `ID`=10064; -- Talk to the Hand
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10065 /*Cutting a Path*/, 25983 /*Promontory Point*/, 26056 /*The Wavespeaker*/, 26977 /*Twilight Investigation*/, 27443 /*The War Has Many Fronts*/, 27727 /*Hero's Call: Deepholm!*/, 28295 /*Meetup with the Caravan*/, 28558 /*Hero's Call: Uldum!*/, 28716 /*Hero's Call: Twilight Highlands!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=10200, `AllowableRaces`=18875469, `QuestDescription`='We don''t dare abandon our post, or wander too far from Vindicator''s Rest, $r. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.$B$BThe mutated tanglers appear to have gained a certain degree of sentience. They''ve learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.$B$BWe''ll never be able to move against the Sunhawks if we''re constantly forced to look underfoot. Attack the problem at its source, $n.', `VerifiedBuild`=19034 WHERE `ID`=10066; -- Oh, the Tangled Webs They Weave
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=8700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10067 /*Fouled Water Spirits*/, 27016 /*The Joy of Boar Hunting*/, 27025 /*Thistle While You Work*/, 27028 /*Hornet Hunting*/);
UPDATE `quest_template` SET `MinLevel`=2, `LogTitle`='Frost Nova', `LogDescription`='Reach level 3 to learn Frost Nova. Locate a Training Dummy outside the Sunspire and practice using it 2 times.', `QuestDescription`='As you begin to grow in power, your connection to the arcane will develop, granting you access to new spells.$B$BGo, develop your power, and then demonstrate what you learn for me.', `VerifiedBuild`=19034 WHERE `ID`=10068; -- Frost Nova
UPDATE `quest_template` SET `MinLevel`=2, `LogDescription`='Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself, then locate a Training Dummy outside the Sunspire and hit it.', `QuestDescription`='It is time for your first lesson in the ways of the Light, $n. As you fight more battles, it will bring you closer to the light, and you''ll start to uncover new abilities.

Go, get more experience, and learn a new ability. Return and demonstrate it for me, and we''ll continue your training.', `VerifiedBuild`=19034 WHERE `ID`=10069; -- Ways of the Light
UPDATE `quest_template` SET `MinLevel`=2, `LogDescription`='Reach level 3 to learn Steady Shot. Locate a Training Dummy outside the Sunspire and practice using Steady Shot 5 times.', `QuestDescription`='And now, it is time for your first lesson.$B$BAs you become more skilled, you will begin to discover new techniques.$B$BGo out, get some more experience, and learn your first new ability. Once you do, go find a training dummy and practice your new skill.', `VerifiedBuild`=19034 WHERE `ID`=10070; -- Steady Shot
UPDATE `quest_template` SET `MinLevel`=2, `LogDescription`='Reach level 3 to learn Eviscerate, then locate a Training Dummy outside the Sunspire and practice using Eviscerate 3 times.', `QuestDescription`='As you grow in power, you''ll start to figure out the tricks of the trade.$B$BOne of the first things you''ll probably figure out is how to Eviscerate your enemy after landing some initial attacks.

Get some experience, learn how to do it, and then find one of the training dummies outside and give it a try. ', `VerifiedBuild`=19034 WHERE `ID`=10071; -- Evisceration
UPDATE `quest_template` SET `MinLevel`=2, `LogTitle`='Learning the Word', `LogDescription`='Reach level 3 to learn Shadow Word: Pain. Practice casting it 5 times on nearby training dummies.', `QuestDescription`='As you grow in skill, so will the array of powers that you can call upon.$B$BI''d like you to go, continue to become more experienced, and discover a new spell. Once you do, come back and demonstrate it for me.', `QuestCompletionLog`='Return to Matron Arena in the Sunspire on Sunstrider Isle.', `VerifiedBuild`=19034 WHERE `ID`=10072; -- Learning the Word
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `LogTitle`='Corruption', `LogDescription`='Reach level 3 to learn Corruption. Locate a Training Dummy outside the Sunspire and practice casting Corruption 5 times.', `QuestDescription`='By now, you''ve heard the rumors about our kind, the warlocks. Pay them no mind; they are uttered by those jealous of our fearsome powers.$B$BAs you become more experienced, you will uncover mysteries of controlling fel energies. 

Go, continue your journey until you uncover a new technique. I want you to practice using this new spell on the training dummies outside the Sunspire.', `VerifiedBuild`=19034 WHERE `ID`=10073; -- Corruption
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=46800, `VerifiedBuild`=19034 WHERE `ID` IN (10075 /*Oshu'gun Crystal Powder*/, 10077 /*Oshu'gun Crystal Powder*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=18875469, `QuestDescription`='Now that we''ve gotten our salvage operation off the ground, it''s time to begin the second phase of the plan.$B$BAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don''t let their age fool you, $n, they''re still very dangerous. Much as we''re working to reclaim what we can, we can''t assume the Horde is going to dismantle their weaponry.$B$BTake this torch and burn the remaining siege equipment. I''ll take no chances with Honor Hold''s safety.', `VerifiedBuild`=19034 WHERE `ID`=10078; -- Laying Waste to the Unwanted
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=18875469, `QuestDescription`='The mine''s been overrun by a plague of gan''arg misfits!$B$BNot only did they run all my workers out of the tunnels, but they''re pounding away in there night and day! To make things worse, now I''ve got Danath on me back! He says he''s going to take away me ale ration if I don''t get this taken care of soon!$B$BNone of the miners''ll go in there, and the guards are busy drinking themselves silly.$B$BI''m begging you, $n, help me here. Danath can take me dignity, but he''ll never take me ale!', `VerifiedBuild`=19034 WHERE `ID`=10079; -- When This Mine's a-Rockin'
UPDATE `quest_template` SET `RewardBonusMoney`=63300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10082 /*The Agitated Ancestors*/, 10101 /*When Spirits Speak*/, 10102 /*A Secret Revealed*/);
UPDATE `quest_template` SET `RewardBonusMoney`=63300, `AllowableRaces`=-1, `QuestDescription`='I need for you to journey to the villages of the ancestors, $n. Seek each one out and see if the ancestors remain.$B$BVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.$B$BReturn to me once you have observed the ancestors in their homes.', `VerifiedBuild`=19034 WHERE `ID`=10085; -- A Visit With The Ancestors
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=129900, `VerifiedBuild`=19034 WHERE `ID`=10091; -- The Soul Devices
UPDATE `quest_template` SET `RewardBonusMoney`=129900, `QuestDescription`='It has been two years since the Shadow Council summoning that resulted in the explosion of this once-great mausoleum, and the formation of the Bone Wastes.$B$BNow they are at war with an unbelievably powerful force on the inside.$B$B$n, you must make your way into the Shadow Labyrinth to determine what they are up against, and to see if it poses a threat to us.  Our spies speak of their use of a forbidden book of unholy summoning, known only as the Codex of Blood.$B$BSeek your answers within its pages.', `VerifiedBuild`=19034 WHERE `ID`=10094; -- The Codex of Blood
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=129900, `QuestDescription`='The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago!  It is what caused the explosion of Auchindoun, and the creation of the Bone Wastes beyond.$B$BKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!$B$BWith the grandmaster, and the rest of their leadership dead, you are Outland''s last hope against this monstrosity!$B$B$n, you know at the core of your being that you and your companions dare not fail!', `VerifiedBuild`=19034 WHERE `ID`=10095; -- Into the Heart of the Labyrinth
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=128100, `VerifiedBuild`=19034 WHERE `ID` IN (10097 /*Brother Against Brother*/, 10098 /*Terokk's Legacy*/);
UPDATE `quest_template` SET `RewardBonusMoney`=14700, `AllowableRaces`=33555378, `QuestDescription`='Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.$B$BShe''s sharp and capable, $n, but be careful around her. She''s got a lot of goods she''s eager to move along the roads, but don''t assume she''s got our best interests at heart. Rakoria goes where she believes there''s profit to be found.', `VerifiedBuild`=19034 WHERE `ID`=10105; -- News for Rakoria
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=42600, `AllowableRaces`=-1, `QuestDescription`='The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can''t yet launch a real offensive against them.  To do that, we need forward staging areas.$B$BOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.$B$BMay fortune shine upon you in the conflicts ahead, $n, for you will no doubt clash with Horde forces eager to gain these same fortifications.', `VerifiedBuild`=19034 WHERE `ID` IN (10106 /*Hellfire Fortifications*/, 13408 /*Hellfire Fortifications*/, 13410 /*Hellfire Fortifications*/);
UPDATE `quest_template` SET `RewardBonusMoney`=46200, `AllowableRaces`=-1, `QuestDescription`='Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, $n!$B$BBe warned, he is a blademaster...', `VerifiedBuild`=19034 WHERE `ID`=10107; -- Diplomatic Measures
UPDATE `quest_template` SET `RewardBonusMoney`=46200, `AllowableRaces`=-1, `QuestDescription`='The huntress''s agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, $n!$B$BBe warned, he is a blademaster...', `VerifiedBuild`=19034 WHERE `ID`=10108; -- Diplomatic Measures
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=42600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10110 /*Hellfire Fortifications*/, 13409 /*Hellfire Fortifications*/, 13411 /*Hellfire Fortifications*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=60000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10116; -- Wanted: Chieftain Mummaki
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=60000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10117; -- Wanted: Chieftain Mummaki
UPDATE `quest_template` SET `RewardBonusMoney`=14400, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10119 /*Through the Dark Portal*/, 10140 /*Journey to Honor Hold*/);
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we''ll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather. She''ll speed you on your way.', `VerifiedBuild`=19034 WHERE `ID`=10120; -- Arrival in Outland
UPDATE `quest_template` SET `RewardBonusMoney`=5700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10121 /*Eradicate the Burning Legion*/, 10124 /*Forward Base: Reaver's Fall*/, 10141 /*The Legion Reborn*/, 10143 /*Expedition Point*/, 10254 /*Force Commander Danath*/, 10340 /*Shatter Point*/, 10344 /*Wing Commander Gryphongar*/, 10388 /*Return to Thrallmar*/);
UPDATE `quest_template` SET `RewardBonusMoney`=57600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10123 /*Felspark Ravine*/, 10142 /*The Path of Anguish*/);
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `QuestDescription`='Directly east of here is the Legion Front. The front acts as a mobile command station for the Burning Legion. Jutting out of the ground you''ll see Legion antennas. The Legion uses these to communicate with their forge camps throughout Outland. They also serve as wards to scramble Legion transmissions, making magical surveillance impossible.$B$BI want you to take these explosives and use them to obliterate the antennas. Get all of them, $n. They run south to north on the border of the Legion Front.', `VerifiedBuild`=19034 WHERE `ID`=10125; -- Mission: Disrupt Communications
UPDATE `quest_template` SET `RewardBonusMoney`=72900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10129 /*Mission: Gateways Murketh and Shaadraz*/, 10146 /*Mission: The Murketh and Shaadraz Gateways*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=74100, `RewardChoiceItemID1`=28062, `RewardChoiceItemID2`=28063, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `VerifiedBuild`=19034 WHERE `ID`=10132; -- Colossal Menace
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=29700, `VerifiedBuild`=19034 WHERE `ID`=10134; -- Crimson Crystal Clue
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=88800, `AllowableRaces`=33555378, `QuestDescription`='Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak''s lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, $n. Terminate with extreme prejudice. $B$BHead west to the Pools of Aggonar and put an end to this so-called ''Legion lord''. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned. ', `VerifiedBuild`=19034 WHERE `ID`=10136; -- Cruel's Intentions
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10144 /*Disrupt Their Reinforcements*/, 10162 /*Mission: The Abyssal Shelf*/, 10163 /*Mission: The Abyssal Shelf*/);
UPDATE `quest_template` SET `RewardBonusMoney`=14400, `AllowableRaces`=18875469, `QuestDescription`='Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we''re familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.$B$BI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.$B$BAnd $n - be careful out there. You''re heading into a dangerous new world.', `VerifiedBuild`=19034 WHERE `ID`=10160; -- Know your Enemy
UPDATE `quest_template` SET `RewardBonusMoney`=124800, `QuestDescription`='You''ve had quite an adventure, $n. And before you''ve even set foot inside of the Auchenai Crypts.$B$BI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar''s vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.$B$BWhat I ask is simple. Enter the Auchenai Crypts and destroy Exarch Maladaar so that the spirits trapped inside can finally rest in peace.', `VerifiedBuild`=19034 WHERE `ID`=10164; -- Everything Will Be Alright
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=123300, `VerifiedBuild`=19034 WHERE `ID` IN (10165 /*Undercutting the Competition*/, 10218 /*Someone Else's Hard Work Pays Off*/);
UPDATE `quest_template` SET `RewardBonusMoney`=126600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10167; -- Auchindoun...
UPDATE `quest_template` SET `RewardBonusMoney`=79200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10168; -- What the Soul Sees
UPDATE `quest_template` SET `RewardBonusMoney`=30300, `QuestDescription`='The Aldor have gained the favor of the Sha''tar today.  As if that should come as any sort of surprise!$B$BWatch them showing off their fancy footwork a few feet away from A''dal.  Could they possibly put any more effort into sucking up to the naaru?$B$BHarbinger Haronem''s marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, $n.$B$BI want you to pour this vial into their meal.  The results should be... comical.', `VerifiedBuild`=19034 WHERE `ID`=10169; -- Losing Gracefully
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=-1, `QuestDescription`='Return to Greatmother Geyah at Garadar with news of your victory, $n. This will surely lift the spirits of the Mag''har. Perhaps even the young Hellscream will be lifted from his malaise.', `VerifiedBuild`=19034 WHERE `ID`=10170; -- Return to the Greatmother
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=-1, `QuestDescription`='You have done so much for the Mag''har, $n. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.', `VerifiedBuild`=19034 WHERE `ID`=10171; -- The Inconsolable Chieftain
UPDATE `quest_template` SET `RewardBonusMoney`=94800, `AllowableRaces`=-1, `QuestDescription`='You are an honorable $r, $n. You have done much for the Mag''har. No one could ever deny your service to my people. Alas, the time of the Mag''har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.$B$BPlease, $n, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.', `VerifiedBuild`=19034 WHERE `ID`=10172; -- There Is No Hope
UPDATE `quest_template` SET `RewardBonusMoney`=15900, `VerifiedBuild`=19034 WHERE `ID` IN (10174 /*Curse of the Violet Tower*/, 10266 /*Request for Assistance*/, 10343 /*The Unending Invasion*/);
UPDATE `quest_template` SET `RewardBonusMoney`=48600, `VerifiedBuild`=19034 WHERE `ID` IN (10177 /*Trouble at Auchindoun*/, 10381 /*Aldor No More*/, 10509 /*Bound for Glory*/, 10528 /*Demonic Crystal Prisons*/, 10570 /*To Catch A Thistlehead*/, 10706 /*A Mysterious Portent*/, 10793 /*The Journal of Val'zareq: Portends of War*/, 10815 /*The Journal of Val'zareq: Portends of War*/, 10833 /*Becoming a Shadoweave Tailor*/);
UPDATE `quest_template` SET `RewardBonusMoney`=15900, `QuestDescription`='I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he''s decided to venture out to Auchindoun again on his own.$B$BHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won''t be a second time.$B$BI admire his desire to free his sister, but he''s not going to be able to do it without help.$B$BFind Isfar and have a word with him, $n. If you can''t persuade him to come back, perhaps you could help him rescue Lakka?', `VerifiedBuild`=19034 WHERE `ID`=10180; -- Can't Stay Away
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=15900, `VerifiedBuild`=19034 WHERE `ID` IN (10183 /*Off To Area 52*/, 10810 /*Damaged Mask*/, 10812 /*Mystery Mask*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=63300, `QuestDescription`='Let me be the first to welcome you aboard, Junior Technician 3rd Grade $n!$B$BWe''re building my masterpiece out here - the X-52 Nether-Rocket!$B$BBut first we need to get all of the parts and fuel for it.  That''s where you come in.$B$BTo start, I need crystals - LOTS of crystals - for the rocket''s Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!$B$BSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.', `VerifiedBuild`=19034 WHERE `ID`=10186; -- You're Hired!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `VerifiedBuild`=19034 WHERE `ID` IN (10188 /*The Sigil of Krasus*/, 10192 /*Krasus's Compendium*/, 10205 /*Warp-Raider Nesaad*/, 10209 /*Summoner Kanthin's Prize*/, 10234 /*One Demon's Trash...*/, 10235 /*Declawing Doomclaw*/, 10239 /*Potential Energy Source*/, 10240 /*Building a Perimeter*/, 10248 /*You, Robot*/, 10256 /*Finding the Keymaster*/, 10265 /*Consortium Crystal Collection*/, 10293 /*Hitting the Motherlode*/, 10300 /*Rebuilding the Staff*/, 10301 /*Unlocking the Compendium*/, 10312 /*The Annals of Kirin'Var*/, 10314 /*A Lingering Suspicion*/, 10319 /*Capturing the Phylactery*/, 10330 /*Shutting Down Manaforge Coruu*/, 10331 /*Indispensable Tools*/, 10337 /*When the Cows Come Home*/, 10348 /*New Opportunities*/, 10426 /*Flora of the Eco-Domes*/, 10433 /*Keeping Up Appearances*/, 10435 /*Retrieving the Goods*/, 10436 /*All Clear!*/, 10777 /*Asghar's Totem*/, 10780 /*Sketh'lon Feathers*/, 10782 /*Imbuing the Headpiece*/, 10855 /*Fel Reavers, No Thanks!*/, 10924 /*Bloody Imp-ossible!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `RewardChoiceItemID2`=30252, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `VerifiedBuild`=19034 WHERE `ID`=10191; -- Mark V is Alive!
UPDATE `quest_template` SET `RewardBonusMoney`=47400, `VerifiedBuild`=19034 WHERE `ID` IN (10198 /*Information Gathering*/, 10820 /*Deceive thy Enemy*/);
UPDATE `quest_template` SET `RewardBonusMoney`=45600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10201; -- And Now, the Moment of Truth
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='See the fissure running through Area 52?  We did that!  <grin>$B$BIt''s yielding up all sorts of goodies for the X-52 Nether-Rocket, but we''re running short on equipment.$B$BWe had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in.  I need you to take this Ultra Deconsolodation Zapper to the ruins.  Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.$B$BJunior Technician 3rd Grade $n, this is your chance for that promotion.  Don''t blow it!', `VerifiedBuild`=19034 WHERE `ID`=10203; -- Invaluable Asset Zapping
UPDATE `quest_template` SET `RewardBonusMoney`=5700, `VerifiedBuild`=19034 WHERE `ID`=10207; -- Forward Base: Reaver's Fall REUSE
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=58200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10208; -- Disrupt Their Reinforcements
UPDATE `quest_template` SET `RewardBonusMoney`=30300, `VerifiedBuild`=19034 WHERE `ID` IN (10210 /*A'dal*/, 10211 /*City of Light*/);
UPDATE `quest_template` SET `RewardBonusMoney`=123300, `VerifiedBuild`=19034 WHERE `ID`=10216; -- Safety Is Job One
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=63300, `QuestDescription`='$n, my former protege, Sparky Uberthruster, wouldn''t wear his helmet while down here and one day transformed into the infamous Dr. Boom!$B$BAnd he stole off to the northeast with most of our sapping equipment!  He and his Boom Bots have been a menace to Area 52 ever since.$B$BI need you to go to his Camp of Boom just outside of town and put an end to him!  Use these Boom''s Doom bombs to take him out.$B$BAnd make sure not to get too close to him or his Boom Bots!', `VerifiedBuild`=19034 WHERE `ID`=10221; -- Dr. Boom!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='After Prince Kael''thas''s forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their ''amazing victory'' while we are helpless to avenge the fallen.$B$BWe must not allow these crimes to go unanswered! Be the instrument of our vengeance, $n. Go to Sunfury Hold and claim the lives of those responsible for this crime.', `VerifiedBuild`=19034 WHERE `ID`=10222; -- The Sunfury Garrison
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='I''ll never forget the blood elf who led the attack. He wore a tabard with a device I''ve never seen before, over top of crimson armor.$B$BHe was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn''t linger long at Sunfury Hold. Kael''thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, $n, and silence his bow for good.', `VerifiedBuild`=19034 WHERE `ID`=10223; -- Down With Daellis
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `QuestDescription`='$n!  I need you to take all of these etherlithium crystals over to Chief Engineer Trep, my, uh, chief of engineering.$B$BHe should know what to do with them.  And if he doesn''t, you see to it that he finds out!', `VerifiedBuild`=19034 WHERE `ID`=10225; -- Report to Engineering
UPDATE `quest_template` SET `RewardBonusMoney`=15600, `VerifiedBuild`=19034 WHERE `ID`=10228; -- Ezekiel
UPDATE `quest_template` SET `RewardBonusMoney`=5700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10229; -- Decipher the Tome
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east.$B$BThis could be a huge problem for us!  With the Legion at the Arklon Ruins, and now there, it''s starting to look bad for us - and the rocket project - here at Area 52.$B$B$n, I need you to go out there and deal with those demons!  I''d do it, but I''m a lover, not a fighter.$B$BYep, this is going to be trouble, I can feel it!', `VerifiedBuild`=19034 WHERE `ID`=10232; -- In A Scrap With The Legion
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael''thas''s followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return.$B$BNo, it must all be destroyed. See to it that their tents and artillery burn to ashes!$B$B<The ghost''s fists clench.>$B$BSteal torches from the Sunfury flamekeepers to accomplish your task, $n.', `VerifiedBuild`=19034 WHERE `ID`=10233; -- Torching Sunfury Hold
UPDATE `quest_template` SET `RewardBonusMoney`=15900, `QuestDescription`='$n, you have to get word back to Area 52 immediately!  Hurry!$B$BTell the rocket-chief that the Burning Legion is after us now!', `VerifiedBuild`=19034 WHERE `ID`=10237; -- Warn Area 52!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=14100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10242 /*Spinebreaker Post*/, 10449 /*Apothecary Zelana*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `QuestDescription`='On the outskirts of town to the east are the Proving Grounds.  Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there.$B$BThis is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, $n!$B$BGo to him; I know that he''ll have a solution for saving Area 52.$B$BAnd since he''s likely to use you as a test subject, if I were you, I''d bring some friends along just in case.', `VerifiedBuild`=19034 WHERE `ID`=10247; -- Doctor Vomisa, Ph.T.
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=96000, `VerifiedBuild`=19034 WHERE `ID`=10249; -- Back to the Chief!
UPDATE `quest_template` SET `RewardBonusMoney`=31200, `VerifiedBuild`=19034 WHERE `ID`=10251; -- The Master's Grand Design?
UPDATE `quest_template` SET `RewardBonusMoney`=93600, `QuestDescription`='Go now, $n. You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls...$B$BDestroy him and take the book of the dead. Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.', `VerifiedBuild`=19034 WHERE `ID`=10253; -- Levixus the Soul Caller
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=129900, `VerifiedBuild`=19034 WHERE `ID` IN (10257 /*Capturing the Keystone*/, 11000 /*Into the Soulgrinder*/);
UPDATE `quest_template` SET `RewardBonusMoney`=57600, `AllowableRaces`=33555378, `QuestDescription`='Hogarth, the commander of the Armory, is in the eastern tower.  You must report your victory over Urtrak to him.  Perhaps he will be friendly?  Of course he may try to consume your soul.  One can never tell with spirits such as these. $B$BThe Unyielding are still against us and will no doubt kill you if they can.  Be careful $n.  ', `VerifiedBuild`=19034 WHERE `ID`=10258; -- Honor the Fallen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `QuestDescription`='Battle rages non-stop at the portal!  The Argent Dawn is fighting a desperate fight -- and if we lose, then there will be no end to the demon''s fire.$B$BHelp us, $n.  Enter the breach and lend aid to our brothers and sisters.  Help stem this tide of darkness!  The Argent Dawn -- and the world -- needs you!', `VerifiedBuild`=19034 WHERE `ID`=10259; -- Into the Breach
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='Our business relations with the blood elves appear to be at an end.  A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro.  They have refused to pay for it.$B$B$n, I would ask that you pay the blood elves of Manaforge Duro to the east a visit.  They appear to be having some trouble with an infestation of mana creatures there, so take advantage of their preoccupation.$B$BI care not what happens to them, but I would very much like to see the return of our property.', `VerifiedBuild`=19034 WHERE `ID`=10267; -- Rightful Repossession
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=32100, `VerifiedBuild`=19034 WHERE `ID`=10268; -- An Audience with the Prince
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='There is another reason for the retrieval of the surveying equipment.  There is a crystal from draenei legend of great importance to me.$B$BIt is said that the crystal bestows god-like powers to its bearer!  But it is in danger of being unearthed by others - namely the Burning Legion.$B$B$n, take the equipment and use it to find the first triangulation point.  We know it to be somewhere to the east near Manaforge Ultris.$B$BAfterward, check-in with my agent, Dealer Hazzin, on the Manaforge Ultris island.', `VerifiedBuild`=19034 WHERE `ID`=10269; -- Triangulation Point One
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=81300, `VerifiedBuild`=19034 WHERE `ID` IN (10274 /*Securing the Celestial Ridge*/, 10310 /*Sabotage the Warp-Gate!*/, 10413 /*The Horrors of Pollution*/, 11049 /*The Great Netherwing Egg Hunt*/, 11068 /*Dragonmaw Race: Corlok the Vet*/, 11069 /*Dragonmaw Race: Wing Commander Ichman*/, 11070 /*Dragonmaw Race: Wing Commander Mulverick*/, 11097 /*The Deadliest Trap Ever Laid*/, 11101 /*The Deadliest Trap Ever Laid*/, 11132 /*Promises, Promises...*/, 11164 /*Tuskin' Raiders*/, 11165 /*A Troll Among Trolls*/, 11544 /*Ata'mal Armaments*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `QuestDescription`='Greetings, $n. Please follow the custodian. She will make things a bit more... clear.', `VerifiedBuild`=19034 WHERE `ID`=10277; -- The Caverns of Time
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=-1, `QuestDescription`='Ah, $n. We have been expecting you. Please, allow one of my brothers to fly you down to the master. He awaits you below...', `VerifiedBuild`=19034 WHERE `ID`=10279; -- To The Master's Lair
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `QuestDescription`='I am an ethereal of my word, $n.  You have truly inspired me.$B$BI am now going to give you the ata''mal crystal to hand over to the naaru.  As it was your heroics that made this possible, I wish for you to deliver it.$B$BYou may use my personal teleporter to go directly to Shattrath City.  Simply step through it and you will be transported there.$B$BGive the crystal to the naaru known as A''dal on the Terrace of Light.  May the trade winds be at your back.', `VerifiedBuild`=19034 WHERE `ID`=10280; -- Special Delivery to Shattrath City
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `QuestDescription`='Greetings, $n. Do not be alarmed. This is merely a projection of my current form. It''s the only way my companion and I could keep watch without revealing ourselves.$B$BThe ethereal who approached you, Marid, is little better than a swindler in the guise of a legitimate merchant. I''d like you to consider working with me instead. My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet me at the north end of the ridge and we will discuss this further.', `VerifiedBuild`=19034 WHERE `ID`=10281; -- Formal Introductions
UPDATE `quest_template` SET `RewardBonusMoney`=126600, `VerifiedBuild`=19034 WHERE `ID`=10283; -- Taretha's Diversion
UPDATE `quest_template` SET `RewardBonusMoney`=43800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10286; -- Arelion's Secret
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=29100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10287; -- The Mistress Revealed
UPDATE `quest_template` SET `RewardBonusMoney`=14400, `AllowableRaces`=18875469, `QuestDescription`='I want you to speak with Amish Wildhammer and catch the first flight to Honor Hold. When you arrive at Honor Hold, you''ll be greeted by Marshal Isildor. I have prepared a report detailing our situation here.  Give him the report, and tell him you''re ready for duty.$B$BYou have your orders, soldier, now move out!  And though your blood must be burning to help us against the fiends below, waste no time here.  Honor Hold needs you even more.', `VerifiedBuild`=19034 WHERE `ID`=10288; -- Arrival in Outland
UPDATE `quest_template` SET `RewardBonusMoney`=28800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10291 /*Report to Nazgrel*/, 10903 /*Return to Honor Hold*/, 10916 /*Digging for Prayer Beads*/);
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=44000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `VerifiedBuild`=19034 WHERE `ID`=10297; -- The Opening of the Dark Portal
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=524416, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10302; -- Volatile Mutations
UPDATE `quest_template` SET `QuestPackageID`=570, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10303; -- The Blood Elves
UPDATE `quest_template` SET `RewardBonusMoney`=64200, `VerifiedBuild`=19034 WHERE `ID` IN (10305 /*Abjurist Belmara*/, 10306 /*Conjurer Luminrath*/, 10307 /*Cohlien Frostweaver*/, 10316 /*Searching for Evidence*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=80100, `QuestDescription`='Archmage Vargoth saw the danger in Naberius''s pursuit of necromancy, but I don''t think he ever anticipated that his own apprentice would wreak this much destruction upon the Kirin Tor.$B$BYou must defeat him, $n, or else he will continue enslaving the spirits of our fallen brothers, robbing them of their rightful rest and destroying what little remains of Kirin''Var.$B$BWith his phylactery in hand, he can be confronted by two or three combatants, but who knows what his magic might do to more foes?', `VerifiedBuild`=19034 WHERE `ID`=10320; -- Destroy Naberius!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='Your success at B''naar has given us a great deal of hope, $n.$B$BWe''ve shared our discoveries with the Scryers and in return they''ve given us more information on the remaining manaforges.$B$BThree other manaforges still stand, in full control of the Sunfury army.$B$BYou will find Manaforge Coruu to the east.  Overseer Seylanna holds the access crystal there.  Obtain it and use it on the manaforge''s control console to begin the emergency shutdown.$B$BWe''re all counting on you, $n.', `VerifiedBuild`=19034 WHERE `ID`=10321; -- Shutting Down Manaforge Coruu
UPDATE `quest_template` SET `RewardBonusMoney`=60900, `QuestDescription`='As you probably know, $n, the Aldor are keepers of the Light and servants of the naaru.$B$BDiametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent.$B$BIf you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers.  We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade''s Edge Mountains.', `VerifiedBuild`=19034 WHERE `ID`=10325; -- Marks of Kil'jaeden
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='Something about these manaforges has been bothering me, $n.  Naaru technology is incredibly advanced; it should''ve taken Kael''thas years to even begin to understand it.$B$BInformation-gathering on the subject has been difficult as Kael''s army is well disciplined and destroys all evidence of written communication.$B$BWe''ve been informed Manaforge Duro is under attack by mana creatures.  It is possible that those defending it have not yet destroyed their briefings.  Obtain them and bring them to me.', `VerifiedBuild`=19034 WHERE `ID`=10328; -- Sunfury Briefings
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='At last, my journeyman project is complete! I can''t wait to formally present it to Master Rhonsus.$B$B<The apprentice looks at you as you describe your experiences retrieving the hammer.>$B$BThey attacked you? All of them? By the Light, they''ve gone mad!$B$BWhat are we to do, $n? It grieves me to say so, but it may be necessary to kill Master Rhonsus. It would leave me as the only smith in Kirin''Var, but I believe my training is sufficient to serve the town''s needs.', `VerifiedBuild`=19034 WHERE `ID`=10332; -- Master Smith Rhonsus
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `QuestDescription`='Say, $n, I was wondering if you could do me another favor.$B$BMy partner out in the field could probably use a hand.  I was wondering if you could go check in on her.$B$BI''m sure that Mama Wheeler will appreciate the help.  Just don''t mind her sharp tongue.$B$BShe''s trying to look out for our interests to the east.  You''ll find her just inside Eco-Dome Midrealm at the Midrealm Post.', `VerifiedBuild`=19034 WHERE `ID`=10333; -- Help Mama Wheeler
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48000, `VerifiedBuild`=19034 WHERE `ID` IN (10334 /*Needs More Cowbell*/, 10664 /*Additional Materials*/);
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='The news you''ve discovered is fortunate, $n.  Not only do you get to waltz into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to Kael''s army.$B$BUse the mana creature assault to your advantage and pick off any Sunfury stragglers you run into.$B$BI do not take particular glee in the senseless slaughter of my own kin the way that Thalodien does, but the tactical advantage here is too high to pass up.', `VerifiedBuild`=19034 WHERE `ID`=10341; -- Kick Them While They're Down
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6000, `VerifiedBuild`=19034 WHERE `ID` IN (10349 /*The Earthbinder*/, 10908 /*Speak with Rilak the Redeemed*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10350 /*Behomat*/, 27225 /*A Summons from Ander Germaine*/, 27265 /*Lord Grayson Shadowbreaker*/, 27267 /*Make Contact with SI:7*/, 28259 /*Meet with Demisette Cloyce*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=74100, `QuestDescription`='It must be that the evil emanations from that giant crystal are summoning the mountain giants and driving them insane.$B$BIt''s too big to move, and beyond our ability to destroy, but I know a way to quell its power.$B$BI''ve summoned a circle at the northwest corner of the crystal on the ridge.  Take this seed to the circle and channel its powers to heal the land through the natural forces of rain, growth and insect repopulation.$B$BBeware, $n, I sense an external force at play here... this is not natural!', `VerifiedBuild`=19034 WHERE `ID`=10351; -- Natural Remedies
UPDATE `quest_template` SET `RewardBonusMoney`=58200, `VerifiedBuild`=19034 WHERE `ID` IN (10367 /*A Traitor Among Us*/, 10368 /*The Dreghood Elders*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=72900, `VerifiedBuild`=19034 WHERE `ID`=10369; -- Arzeth's Demise
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='We''ve been so blind, $n, that the alliance of two of our most dangerous enemies went completely unnoticed.$B$BI wouldn''t be surprised if the Scryers had something to do with hiding this information from us, but we must now face the reality.  The Burning Legion and Kael''thas'' Sunfury army serve under the same banner.$B$BThese demons are the only reason Kael''thas was ever able to utilize the technology in Tempest Keep.  Under Orelis''s orders I must command you to destroy them.', `VerifiedBuild`=19034 WHERE `ID`=10380; -- A Dark Pact
UPDATE `quest_template` SET `RewardBonusMoney`=5700, `AllowableRaces`=18875469, `QuestDescription`='Well, $n, I hope you''re prepared for the next phase of our operation. The Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - it''s a small post near the Legion Front. $B$BSpeak with Field Marshal Brock. He''ll have instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said ''hello''.  
', `VerifiedBuild`=19034 WHERE `ID`=10382; -- Go to the Front
UPDATE `quest_template` SET `Flags`=16512, `FlagsEx`=64, `VerifiedBuild`=19034 WHERE `ID`=10383; -- This is a Breadcrumb!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=33555378, `QuestDescription`='Greetings, $n. I''ve deciphered the Legion missive and uncovered the demons'' strategic plans for this Peninsula. Apparently, there is a large group of hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow such a force to go unchallenged. You must go there and decimate their cursed numbers. ', `VerifiedBuild`=19034 WHERE `ID`=10389; -- The Agony and the Darkness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=33555378, `QuestDescription`='$n, we have reason to believe that the easternmost forge camp is not yet complete. The Legion''s gan''arg servants are working ''round the clock to get the facility up and running. We can''t allow that to happen. $B$BHead east to Forge Camp: Mageddon and slay 10 gan''arg. Bring me the head of their master - Razorsaw - and the Legion''s fel reaver production will grind to a halt!   

', `VerifiedBuild`=19034 WHERE `ID`=10390; -- Forge Camp: Mageddon
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=33555378, `QuestDescription`='There is a second production facility, Forge Camp: Rage, that lies to the immediate northeast of Thrallmar. The demons have positioned a number of their fel cannons along the ridge - and they''re aimed straight at us! You must enter the camp and destroy these fel cannons. $B$B$n, you must be sure to detonate them all - or nothing will stop the Legion from raining fiery hell down upon our heads!  
', `VerifiedBuild`=19034 WHERE `ID`=10391; -- Cannons of Rage
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=33555378, `QuestDescription`='You are an honor to us, $n. But now we must strike before the Legion recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a warp-portal through which the Legion draws its reinforcements. $B$BYou must overload that portal - and blast it back to the abyss it came from. The portal''s activation key will be held by the Point''s commander - Warbringer Arix''Amal. Slay him. Take the key. Use it on the portal and do what must be done. May the warchief''s blessings be with you.   ', `VerifiedBuild`=19034 WHERE `ID`=10392; -- Doorway to the Abyss
UPDATE `quest_template` SET `RewardBonusMoney`=28800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10393; -- Vile Plans
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=18875469, `QuestDescription`='Pay close attention, $n. We''ve been surveying the Legion camps that lie along the ridge ahead. We have reason to believe that these so-called ''Forge Camps'' are where the demons are constructing those blasted Fel Reavers. $B$BYou can see the closest target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it''s still under construction. If you can slay the Gan''arg Servants and their master - Razorsaw - we can bring the Legion''s Fel Reaver production to a grinding halt!   

', `VerifiedBuild`=19034 WHERE `ID`=10394; -- Disruption - Forge Camp: Mageddon
UPDATE `quest_template` SET `RewardBonusMoney`=28800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10395; -- The Dark Missive
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=18875469, `QuestDescription`='It is just as I feared. Arix''Amal - the demon you killed earlier, was working for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a force of hellish terrorfiends near the Pools of Aggonar. $B$BYou must journey there and slay the terrorfiends before they strike against us. But be wary, friend - the Pools of Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the northwest of here, beyond Hellfire Citadel. $B$BLight be with you, $n.  
', `VerifiedBuild`=19034 WHERE `ID`=10399; -- The Heart of Darkness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=88800, `AllowableRaces`=18875469, `QuestDescription`='The honorable Warp-Scryer has told me of your perils, $n - and of the new foe you''ve discovered. If Kryv is to be believed, this ''Arazzius the Cruel'' is as powerful and evil as any foe the Sons of Lothar have ever faced. $B$BWill you stand for us now, $n? Will you face this Legionlord and deliver the Light''s justice upon him? If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly find you. 
', `VerifiedBuild`=19034 WHERE `ID`=10400; -- Overlord
UPDATE `quest_template` SET `RewardBonusMoney`=14700, `VerifiedBuild`=19034 WHERE `ID` IN (10403 /*Naladu*/, 14191 /*Furien's Footsteps*/, 14193 /*Nothing a Couple of Melons Won't Fix*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=81300, `VerifiedBuild`=19034 WHERE `ID` IN (10407 /*Socrethar's Shadow*/, 10508 /*A Gift for Voren'thal*/, 10679 /*Quenching the Blade*/, 11521 /*Rediscovering Your Roots*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `QuestDescription`='I have in my possession another disruptor, one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar''s protective force fields will be down. For this act, he will strike at you with a ferocity you have never before witnessed, $n.$B$BIf you are willing to rid the world of Salhadaar, I will give you the disruptor.', `VerifiedBuild`=19034 WHERE `ID`=10408; -- Nexus-King Salhadaar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `QuestDescription`='When facing eredar of great power, large armies are useless for the most part.  Their corruptive powers over mortal souls are such that only the strongest-willed can even stand face to face with them.$B$BTake this stone to the Invasion Point: Overlord, between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with you.  Orelis and Karja will meet you at Socrethar''s Seat; I will send Adyen along with them.$B$BMay the Light prevail today, $n.  May Socrethar meet his end.', `VerifiedBuild`=19034 WHERE `ID`=10409; -- Deathblow to the Legion
UPDATE `quest_template` SET `RewardBonusMoney`=48600, `QuestDescription`='The time has come to face Socrethar, $n.  Confronting an eredar leader isn''t something that''s taken lightly among us.  A single mistake is likely to cost us our lives if we''re ill-prepared.$B$BTake Socrethar''s teleportation stone to High Priestess Ishanah at the Shrine of Unending Light in Shattrath City.  She will determine how we need to handle the situation.', `VerifiedBuild`=19034 WHERE `ID`=10410; -- Ishanah's Help
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=64800, `VerifiedBuild`=19034 WHERE `ID` IN (10411 /*Electro-Shock Goodness!*/, 10422 /*Captain Tyralius*/, 10973 /*A Thousand Worlds*/, 11041 /*A Job Unfinished...*/);
UPDATE `quest_template` SET `RewardBonusMoney`=60900, `QuestDescription`='It is no secret that Kael''thas Sunstrider perceives us as a great threat.  Let''s face it - not many sin''dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps.$B$BIt''s also no secret that this is not just a war of words.  Scryers and the armies that serve Kael''thas attack each other on sight.  The only way to prove you''re with us, $n, is to do your share of fighting.$B$BKael''s lower ranking followers wear Firewing signets to indicate their rank.  Bring them to me.', `VerifiedBuild`=19034 WHERE `ID`=10412; -- Firewing Signets
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `VerifiedBuild`=19034 WHERE `ID` IN (10416 /*Synthesis of Power*/, 10420 /*A Cleansing Light*/, 10464 /*Sage's Vow*/, 10465 /*Restorer's Vow*/, 10466 /*Champion's Vow*/, 10467 /*Defender's Vow*/, 10522 /*The Cipher of Damnation - Grom'tor's Charge*/, 10540 /*The Cipher of Damnation - Ar'tor's Charge*/, 10733 /*Down the Violet Path*/, 10734 /*Down the Violet Path*/, 10735 /*Down the Violet Path*/, 10736 /*Down the Violet Path*/, 10958 /*Seek Out the Ashtongue*/, 11072 /*Adversarial Blood*/, 11885 /*Adversarial Blood*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=31500, `VerifiedBuild`=19034 WHERE `ID`=10417; -- Run a Diagnostic!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=48000, `VerifiedBuild`=19034 WHERE `ID`=10424; -- Diagnosis: Critical
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=80100, `VerifiedBuild`=19034 WHERE `ID`=10427; -- Creatures of the Eco-Domes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='The dome technology possesses such power! Certainly, there are bounds beyond which we dare not go, $n.$B$BCreatures allowed to grow too large or too fast could be just as bad as a barren landscape.$B$BI have heard rumors of just such a creature in the pool to the east. I''ve heard the ethereal merchants conspiring to catch the overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me the creature''s heart so I may study it.', `VerifiedBuild`=19034 WHERE `ID`=10429; -- When Nature Goes Too Far
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `VerifiedBuild`=19034 WHERE `ID` IN (10431 /*Outside Assistance*/, 10523 /*The Cipher of Damnation - The First Fragment Recovered*/, 10546 /*Borak, Son of Oronok*/, 10550 /*The Bundle of Bloodthistle*/, 10814 /*Neltharaku's Tale*/, 11009 /*Ogre Heaven*/, 11550 /*Enter, the Deceiver...*/, 26593 /*Scaring Shaky*/);
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='Here it is, $n. Take this phase disruptor and mount up! The Protectorate nether drake will fly you close enough to Ultris so that you can drop the disruptor on top of the void conduit.$B$BDrop as many disruptor charges as possible to ensure complete annihilation!$B$BWhen you are ready, speak with the nether drake and he''ll take you up.$B$BIf you miss the mark you will have to get more bombs from me before you can go up again.', `VerifiedBuild`=19034 WHERE `ID`=10438; -- On Nethery Wings
UPDATE `quest_template` SET `RewardBonusMoney`=15900, `QuestDescription`='The test was a resounding success! We can certainly use this device to start repairing the domes.$B$BCarry word of the test results to the Stormspire and let Ghabar know that I''ve also found a pattern in the damage to the shield generators. Key pieces of generator units have gone missing from a number of sites. This is no accident, $n, no technological failure. We''re being stolen from. ', `VerifiedBuild`=19034 WHERE `ID`=10440; -- Success!
UPDATE `quest_template` SET `RewardBonusMoney`=5700, `AllowableRaces`=33555378, `QuestDescription`='$C, there''s some tauren by the name of Thiah Redmane that keeps pestering us for assistance.  She''s with the Cenarion Expedition, and they''ve setup a little post just to the west on the south side of the road leading to Zangarmarsh.$B$BIf you hit Thornfang Hill, you''ve gone too far.$B$BDo you think you might head over there and see what she needs?  I don''t want to have to bother Ranger Captain Venn''ren with such trivialities.', `VerifiedBuild`=19034 WHERE `ID`=10442; -- Helping the Cenarion Post
UPDATE `quest_template` SET `RewardBonusMoney`=5700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10443 /*Helping the Cenarion Post*/, 10936 /*Trollbane is Looking for You*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=18875469, `QuestDescription`='This calls for immediate action!$B$BWe have someone out in the field closer to Firewing Point that I want you to speak with.  He''ll have a better idea of what our next step should be.$B$BReport to Lieutenant Meridian out at the Allerian Post and apprise him of the situation.  You''ll find the post to the northeast on the southern bank of the river just south of Firewing Point.$B$BGodspeed, $n.', `VerifiedBuild`=19034 WHERE `ID`=10444; -- Report to the Allerian Post
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID`=10445; -- The Vials of Eternity
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AllowableRaces`=18875469, `QuestDescription`='They''re building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.$B$B$n, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.$B$BTake the final code to the mana bomb that they''re working on in the central courtyard and set it off.$B$BOnly then will we be certain that the Allerian Stronghold is safe.', `VerifiedBuild`=19034 WHERE `ID`=10446; -- The Final Code
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `AllowableRaces`=33555378, `QuestDescription`='They''re building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.$B$B$n, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.$B$BTake the final code to the mana bomb that they''re working on in the central courtyard and set it off.$B$BOnly then will we be certain that Stonebreaker Hold is safe.', `VerifiedBuild`=19034 WHERE `ID`=10447; -- The Final Code
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=33555378, `QuestDescription`='This calls for immediate action!$B$BWe have someone out in the field closer to Firewing Point that I want you to speak with.  She''ll have a better idea of what our next step should be.$B$BReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation.$B$BTake the road north out of the hold.  From the middle of Tuurem, follow the road to the east.  You''ll find the camp on the bank of the river that lies just southwest of Firewing Point.$B$BGood luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=10448; -- Report to Stonebreaker Camp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `AllowableRaces`=-1, `QuestDescription`='Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!$B$BI have a mission for you, $n.  Kill Bonechewer orcs and collect their vile blood.  There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.$B$BBonechewers scavenge near the ruined battlements along the Path of Glory, to the south.  Return to me when your mission is complete.', `VerifiedBuild`=19034 WHERE `ID`=10450; -- Bonechewer Blood
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=81300, `VerifiedBuild`=19034 WHERE `ID`=10451; -- Escape from Coilskar Cistern
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=61500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10455 /*The Encroaching Wilderness*/, 10456 /*Marauding Wolves*/, 10457 /*Protecting Our Own*/, 10502 /*The Bloodmaul Ogres*/, 10504 /*The Bladespire Ogres*/, 10506 /*A Dire Situation*/, 10510 /*Into the Draenethyst Mine*/, 10511 /*Strange Brew*/, 10516 /*The Trappings of a Vindicator*/, 10690 /*The Den Mother*/);
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `QuestDescription`='You''ve carried out the promise you made to us, $n.  And for that you''ve gained the recognition you deserve.$B$BAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won''t be long until it has reached its full potential.', `VerifiedBuild`=19034 WHERE `ID` IN (10468 /*Sage's Oath*/, 10469 /*Restorer's Oath*/, 10470 /*Champion's Oath*/, 10471 /*Defender's Oath*/);
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `QuestDescription`='Your accomplishments have gone beyond my greatest expectations, $n.$B$BYou step in and out of time as comfortably as any bronze dragon I''ve known.  You are destined for great power and I am more than pleased to help you on your way there.$B$BContinue to serve the Scale of the Sands and I will unleash your gift''s full potential.', `VerifiedBuild`=19034 WHERE `ID` IN (10472 /*Sage's Covenant*/, 10473 /*Restorer's Covenant*/, 10474 /*Champion's Covenant*/, 10475 /*Defender's Covenant*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=54000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10482 /*Fel Orc Scavengers*/, 10484 /*Cursed Talismans*/);
UPDATE `quest_template` SET `RewardBonusMoney`=13500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10483; -- Ill Omens
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=56700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10485 /*Warlord of the Bleeding Hollow*/, 10538 /*Boiling Blood*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=61500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10486 /*The Encroaching Wilderness*/, 10487 /*Dust from the Drakes*/, 10489 /*Felling an Ancient Tree*/, 10505 /*The Bloodmaul Ogres*/, 10542 /*They Stole Me Hookah and Me Brews!*/, 10545 /*Bladespire Kegger*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=61500, `AllowableRaces`=33555378, `QuestDescription`='With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses.$B$BOur dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge.$B$B$n, I want you to take this ointment and apply it to our dire wolf friends.  The Alliance will get a rude surprise the next time that they send one of their hunting parties.$B$BBe aware though that some of the wolves may not like this, and will turn on you.', `VerifiedBuild`=19034 WHERE `ID`=10488; -- Protecting Our Own
UPDATE `quest_template` SET `AllowableRaces`=-1, `QuestDescription`='Hello, I''m glad that you''ve decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn''Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won''t be able to meet our goals without your assistance, $n!$B$BYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, $c? Will you help out with the vital preparations?', `VerifiedBuild`=19034 WHERE `ID`=10501; -- The Alliance Needs Your Help!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=77100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10503 /*The Bladespire Threat*/, 10544 /*A Curse Upon Both of Your Clans!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `QuestDescription`='This is the chance we''ve been waiting for, $n.  Not only have we uncovered the evidence we need to show our people who Kael''thas is really working for, but we can prove our strength by defeating his new masters.$B$BMy frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.  ', `VerifiedBuild`=19034 WHERE `ID`=10507; -- Turning Point
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=61500, `AllowableRaces`=18875469, `QuestDescription`='I''ll not take another sip of that ill-smelling muck!  But it does give me an idea.$B$B<Borgrim gets a twinkle in his eye.>$B$BSo here''s the plan.  We know that the Bloodmaul practically live off of this swill.  But I wonder what their enemies, the Bladespire ogres, think of it?$B$B$n, I want you to take the rest of this rubbish and see if you can get the Bladespire ogres tanked.  You can find them by heading north from Bloodmaul Outpost through the ravine.', `VerifiedBuild`=19034 WHERE `ID`=10512; -- Getting the Bladespire Tanked
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `QuestDescription`='I do not know how we can acquire the spell that the spirits mentioned, $n. Truth be told, I don''t even know where we would start such a search.$B$B<Torlok stares off in the distance, lost in thought.>$B$BHrm... It is a long shot but it might be our only chance. There is an orc that I have seen visit this area before. I spoke to him briefly once. He is a hermit that claims to live above Coilskar Cistern to the northeast. Seek out this orc, Oronok Torn-heart.$B$BAs I said, it is a long shot.', `VerifiedBuild`=19034 WHERE `ID`=10513; -- Oronok Torn-heart
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10517 /*Gorr'Dim, Your Time Has Come...*/, 10584 /*Picking Up Some Power Converters*/, 10594 /*Gauging the Resonant Frequency*/, 10608 /*Crystal Clear*/, 10609 /*What Came First, the Drake or the Egg?*/, 10620 /*Ridgespine Menace*/, 10632 /*Cutting Your Teeth*/, 10657 /*Ride the Lightning*/, 10674 /*Trapping the Light Fantastic*/, 10795 /*A Date with Dorgok*/, 10796 /*Crush the Bloodmaul Camp!*/, 10799 /*Into the Churning Gulch*/, 10800 /*Goodnight, Gronn*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=78000, `AllowableRaces`=18875469, `QuestDescription`='I want you to steal the Bladespire banner from one of their champions and take it south to Bloodmaul Outpost.  Plant it atop their Northmaul Tower.$B$BThis will infuriate the Bloodmaul and they will attack you relentlessly.  But it will also keep their hatred focused on Bladespire Hold, and away from Sylvanaar.$B$BYou will know you have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm.  Return it to Sylvanaar.$B$B$n, this isn''t going to be easy.  Take a  friend or two with you.', `VerifiedBuild`=19034 WHERE `ID`=10518; -- Planting the Banner
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `QuestDescription`='<Oronok adjusts his posture and stands to his full height.>$B$BI had to be sure, $n. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are $g female:male;. Which is to say, not at all.$B$BIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.', `VerifiedBuild`=19034 WHERE `ID`=10519; -- The Cipher of Damnation - Truth and History
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=61500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10524 /*Thunderlord Clan Artifacts*/, 10566 /*Trial and Error*/, 10617 /*Silkwing Cocoons*/);
UPDATE `quest_template` SET `RewardBonusMoney`=46200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10525; -- Vision Guide
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=78000, `AllowableRaces`=33555378, `QuestDescription`='If the vision that I granted you is true, then you must travel down into the ravine and to the south end of Bloodmaul Ravine.  There you will find the Draenethyst Mine.$B$BJourney to the back of the mine, and retrieve the Thunderspike.  Ignore everything else!  I have no interest in the crystals of the mine, nor the ogres therein.$B$BAs soon as you have the spear return it to me here!$B$BAnd, $n, be very careful with it... I would hate to think what would happen to you should you break it.', `VerifiedBuild`=19034 WHERE `ID`=10526; -- The Thunderspike
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='My youngest son, Ar''tor, left to search Illidari Point - far to the southwest, nestled between Legion Hold and Wildhammer Stronghold.$B$BWhile Ar''tor is a hunter of remarkable skill and an expert tracker, I fear that he may be in over his head this time. Illidari Point is the proving grounds for Illidan''s demons. These are demons that left the Burning Legion to join the Betrayer!$B$BTravel to Illidari Point and find Ar''tor, $n.', `VerifiedBuild`=19034 WHERE `ID`=10527; -- Ar'tor, Son of Oronok
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='It is a sign, $n. Even in death, I cannot be stopped. Recovering a part of the Cipher of Damnation is my destiny. With your help, that destiny will be fulfilled.$B$BBefore we embark on that journey, I must have my longbow, Lohn''goron. It is a family heirloom that has been handed down from Torn-heart to Torn-heart for generations.$B$BMy instinct tells me that a demon stole it from my corpse. Kill the demons here until you find my bow. ', `VerifiedBuild`=19034 WHERE `ID`=10537; -- Lohn'goron, Bow of the Torn-heart
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10543 /*Grimnok and Korgaah, I Am For You!*/, 10714 /*On Spirit's Wings*/, 10715 /*Into the Churning Gulch*/, 10720 /*The Smallest Creatures*/, 10724 /*Prisoner of the Bladespire*/, 10846 /*Understanding the Mok'Nathal*/, 10851 /*The Totems of My Enemy*/, 10853 /*Spirit Calling*/, 10859 /*Gather the Orbs*/, 10860 /*Mok'Nathal Treats*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `QuestDescription`='Now that you''ve chosen a side, $n, you should meet the Scryers'' leader.$B$BYou will find Voren''thal the Seer inside the Seer''s Library at the Scryer''s Tier.$B$BSee if you can be of assistance to him.  He will be glad to hear you''ve decided to lend them a hand.', `VerifiedBuild`=19034 WHERE `ID`=10553; -- Voren'thal the Seer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=46200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10556; -- Scratches
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=15000, `AllowableRaces`=-1, `QuestDescription`='I built an amazing device, the Zephyrium Capacitorium, and I''m sure it''ll work perfectly, but... do you want to help me test it?$B$BThere''s plenty of hazard pay!$B$BSpeak with my twin over there, Rally. Good luck, $n. Come back after your experiment.  Or... if that''s not possible due to sustained injuries, your next of kin can report to collect your pay.', `VerifiedBuild`=19034 WHERE `ID`=10557; -- Test Flight: The Zephyrium Capacitorium
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=18875469, `QuestDescription`='Don''t let your guard down, $r. We''re under constant assault from the Burning Legion.$B$BFrom their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks.$B$BMy men are ragged and exhausted. I don''t know how much longer they''ll hold out. Please, $n, lend your help to our defenses. Take your place on the line and halt the advance of the infernals!', `VerifiedBuild`=19034 WHERE `ID`=10562; -- Besieged!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=18875469, `QuestDescription`='The fortress of Legion Hold is nigh impregnable, and to be completely honest, I can''t spare the forces for an assault. Our hopes are riding on you, $n.$B$BWhat little information we''ve been able to gather indicates that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I''ll give you, you must sneak into Legion Hold and learn about their plans. Your best hope is to intercept or overhear communication between their commanders. Good luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=10563; -- To Legion Hold
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10564 /*Blast the Infernals!*/, 10569 /*The Sketh'lon Wreckage*/, 10582 /*Minions of the Shadow Council*/, 10585 /*The Summoning Chamber*/, 10586 /*Bring Down the Warbringer!*/, 10589 /*Gaining Access*/, 10606 /*The Art of Fel Reaver Maintenance*/);
UPDATE `quest_template` SET `RewardBonusMoney`=30900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10565; -- The Stones of Vekh'nir
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=18875469, `QuestDescription`='We cannot permit the Legion to carry out its plan to destroy Wildhammer Stronghold on their march to the Black Temple.$B$BThere''s only one way to stop them, $n. You must create an explosive large enough to destroy the Legion''s entire stockpile of infernals at the hold.$B$BThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the base of your device. Search the other wreckage near the fel reaver for armor plating we might be able to make a casing from.', `VerifiedBuild`=19034 WHERE `ID`=10572; -- Setting Up the Bomb
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='<Borak looks you up and down.>$B$BThis is going to be tricky, but I think I can make it work.$B$BI can disguise you as one of these Illidari blood elves, $n. What I need first, though, are several pieces of their armor. It is imperative that the armor be clean. No blood stains! We want to avoid suspicion.$B$BBring me the gear and I''ll take care of the rest of the disguise.$B$BOnce the disguise is assembled, you''re going to deliver the message to the Grand Commander - in person.', `VerifiedBuild`=19034 WHERE `ID`=10576; -- The Shadowmoon Shuffle
UPDATE `quest_template` SET `RewardBonusMoney`=48600, `QuestDescription`='Take this disguise and enter Eclipse Point. Once inside, use the disguise to cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, thereby granting you safe passage to Grand Commander Ruusk.$B$BOnce you find Ruusk, tell him where next to move the cipher. You''re going to have to act your heart out, $n. Play it off as if you are his superior, delivering a message from his lord. That should do it!$B$BOh - watch out for the dragonhawks as they see through the disguise.', `VerifiedBuild`=19034 WHERE `ID`=10577; -- What Illidan Wants, Illidan Gets...
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='That Cipher fragment will never reach Zuluhed. You''re going to ambush Ruul the Darkener and his transport before it has a chance to make the delivery.$B$BThe Dragonmaw Fortress is directly east of here, across the Netherwing Fields. Somewhere between Dragonmaw Fortress and the Sanctum of the Stars is where you''ll find Ruul. Strike hard and strike fast! And $n, from the sound of it, this Ruul is going to be tough. Keep your guard up.$B$BReturn the Cipher to me should you succeed.
', `VerifiedBuild`=19034 WHERE `ID`=10578; -- The Cipher of Damnation - Borak's Charge
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='Take this box to my father. He still resides at Oronok''s Farm, far to the north, above Coilskar Cistern. When all three fragments are pieced together, the ancient words will be known once more.$B$BGood luck, $n. Tell my father that I will be home soon.', `VerifiedBuild`=19034 WHERE `ID`=10579; -- The Cipher of Damnation - The Third Fragment Recovered
UPDATE `quest_template` SET `RewardBonusMoney`=15600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (10580 /*Where Did Those Darn Gnomes Go?*/, 10581 /*Follow the Breadcrumbs*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=18875469, `QuestDescription`='Wing Commander Nuainn originally sent three of us out here to keep watch over the Deathforge and to gather information. Flanis Swiftwing volunteered to try to infiltrate the Deathforge, but we haven''t heard anything from him in days.$B$BI fear the worst, $n. Flanis is a skilled scout, but if he''s gotten in over his head, we have no way of knowing. Search the Deathforge for him and recover any information or items he might have collected.', `VerifiedBuild`=19034 WHERE `ID`=10583; -- The Fate of Flanis
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `QuestDescription`='How many times has this spell been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled.$B$BWhat you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul''dan stands.$B$BWhat you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh.$B$BYou must be victorious, $n. This land cannot withstand another shattering.', `VerifiedBuild`=19034 WHERE `ID`=10588; -- The Cipher of Damnation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10595 /*Besieged!*/, 10596 /*To Legion Hold*/, 10598 /*Blast the Infernals!*/, 10600 /*Minions of the Shadow Council*/, 10601 /*The Fate of Kagrosh*/, 10602 /*The Summoning Chamber*/, 10603 /*Bring Down the Warbringer!*/, 10604 /*Gaining Access*/, 10611 /*The Art of Fel Reaver Maintenance*/, 10760 /*The Sketh'lon Wreckage*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=33555378, `QuestDescription`='We can''t allow the Legion to trample us on their march to Black Temple.$B$BFind a way to destroy the infernals they intend to use against us. That''s not a request, $n; it''s an order.$B$BThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the basis for a kind of fel bomb. Search the other wreckage near the fel reaver for a section of armor plating. You should be able to make a bomb powerful enough to take out those infernals and give the hold a nice shake!', `VerifiedBuild`=19034 WHERE `ID`=10597; -- Setting Up the Bomb
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10599 /*The Deathforge*/, 10614 /*Whispers on the Wind*/, 10663 /*The Hermit Smith*/, 10749 /*Baron Sablemane's Poison*/, 10761 /*Find the Deserter*/, 10767 /*Invasion Point: Cataclysm*/, 10785 /*It's a Trap!*/, 10865 /*Inform Leoroxx!*/, 11036 /*Out of This World Produce!*/, 11046 /*Chief Apothecary Hildagard*/, 11047 /*The Apprentice's Request*/, 11048 /*Kroghan's Report*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=80100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10612; -- The Fel and the Furious
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=80100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10613; -- The Fel and the Furious
UPDATE `quest_template` SET `RewardBonusMoney`=15000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10615; -- Ruuan Weald
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10618 /*The Softest Wings*/, 10927 /*Killing the Crawlers*/, 10928 /*Killing the Crawlers*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10621; -- Illidari-Bane Shard
UPDATE `quest_template` SET `QuestDescription`='Akama has been tracking your progress quite closely, $n.$B$BThe Ashtongue you''ve slain at the Ruins of Baa''ri are amongst the most evil Broken known among us... carefully hand-picked by Akama himself to maintain the facade we need to present to Illidan.  The Deathsworn, however, know of Akama''s true intentions.$B$BFirst things first.  We need to know that you are not with Illidan.  A Satyr known as Zandras watches over us from above the prison walls on his behalf.  Slay him as proof of your allegiance.', `VerifiedBuild`=19034 WHERE `ID`=10622; -- Proof of Allegiance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10623; -- Illidari-Bane Shard
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10624 /*A Haunted History*/, 10625 /*Spectrecles*/, 10626 /*Capture the Weapons*/, 10627 /*Capture the Weapons*/, 10642 /*A Ghost in the Machine*/, 10643 /*Harbingers of Shadowmoon*/, 10660 /*What Strange Creatures...*/, 10661 /*Spleendid!*/, 10672 /*Frankly, It Makes No Sense...*/, 10677 /*The Second Course...*/);
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `QuestDescription`='You''ve proven what side you''re on.  I will reveal to you our leader''s hideout.$B$BFollow the halls beyond; there will be an underground passage hidden by stagnant water on your right.$B$BI must warn you, $n.  You are not to speak to anyone of what you see there.', `VerifiedBuild`=19034 WHERE `ID`=10628; -- Akama
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=57600, `VerifiedBuild`=19034 WHERE `ID`=10629; -- Shizz Work
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10633 /*Teron Gorefiend - Lore and Legend*/, 10644 /*Teron Gorefiend - Lore and Legend*/);
UPDATE `quest_template` SET `RewardBonusMoney`=97500, `VerifiedBuild`=19034 WHERE `ID` IN (10634 /*Divination: Gorefiend's Armor*/, 10651 /*Varedis Must Be Stopped*/, 10692 /*Varedis Must Be Stopped*/, 10884 /*Trial of the Naaru: Mercy*/, 10885 /*Trial of the Naaru: Strength*/, 10886 /*Trial of the Naaru: Tenacity*/, 10947 /*An Artifact From the Past*/, 10957 /*Redemption of the Ashtongue*/, 10974 /*Stasis Chambers of Bash'ir*/);
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.$B$BDo not be fooled by their name, $n, their power will be used against us as often as against any demon.$B$BTheir warlocks summon and subdue demons to be used as part of the initiates'' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.', `VerifiedBuild`=19034 WHERE `ID` IN (10637 /*A Necessary Distraction*/, 10688 /*A Necessary Distraction*/);
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='You''ve proven your allegiance, $n.  You must forgive my caution, but in this world things are not what they appear.$B$BI will tell you about Varedis when you''re ready.', `VerifiedBuild`=19034 WHERE `ID`=10646; -- Illidan's Pupil
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=81300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10647 /*Wanted: Uvuros, Scourge of Shadowmoon*/, 10648 /*Wanted: Uvuros, Scourge of Shadowmoon*/);
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, $n.$B$BYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.', `VerifiedBuild`=19034 WHERE `ID` IN (10650 /*Return to the Aldor*/, 10691 /*Return to the Scryers*/);
UPDATE `quest_template` SET `RewardBonusMoney`=128100, `VerifiedBuild`=19034 WHERE `ID`=10665; -- Fresh from the Mechanar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=128100, `VerifiedBuild`=19034 WHERE `ID`=10666; -- The Lexicon Demonica
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=129900, `VerifiedBuild`=19034 WHERE `ID` IN (10667 /*Underworld Loam*/, 11492 /*Hard to Kill*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=129900, `QuestDescription`='The sword''s enchantments must be contained within a powerful focus, such as a gem. I know of a gem that we can use for this purpose, for there are few that can play host to such powerful magics without shattering.$B$BThe gem we need is called the tear of the earthmother. It''s a powerful artifact in the hands of the ogres who created it, and Warbringer O''mrogg, who currently holds the gem, has many powerful allies in Hellfire Citadel''s Shattered Halls. Take care in retrieving the tear, $n.', `VerifiedBuild`=19034 WHERE `ID`=10670; -- Tear of the Earthmother
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=18875469, `QuestDescription`='$n, I''ve got something else for you to do.  One of the eggheads wants to study the fiendling flesh beasts that can be found at Razaan''s Landing, north of the Razor Ridge.$B$BMore to the point, they want to study the flesh of the flesh beasts that are there.$B$B<Dizzy makes a disgusted face.>$B$BBut, of course, they aren''t willing to get their hands dirty, and they only want the ether-energized flesh, which it''s not likely that all of them have.$B$BI say, beggars can''t be choosers, but what can you do?', `VerifiedBuild`=19034 WHERE `ID`=10671; -- More than a Pound of Flesh
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=64800, `AllowableRaces`=-1, `QuestDescription`='Gnomus knows about the massive diemetradon and plans to eat it! He must have been able to see what I could see through the eyes of his arcano-scorp. Look, there''s no time to explain. He''s crazy and that craziness is going to cost us the closest thing we''ve got to a fireproof jumpsuit.$B$BGet back to the lava flow near Baa''ri and track down Felspine the Greater. Once you find it, kill it and bring me back its hide.$B$BDon''t try and reason with me, $n. I''m well past that point.', `VerifiedBuild`=19034 WHERE `ID`=10673; -- Felspine the Greater
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `AllowableRaces`=18875469, `QuestDescription`='<The blood drains out of Toshley''s face.>$B$BThese orbs are made up of both nether energy and souls, some of them gnome souls!$B$BHow dare they!  Were they the ones killing our people that traveled north?!$B$B$n, you must put a stop to this, and the only way to do that is to finish off their leader, Nexus-Prince Razaan.$B$BYou''ll have to coax him out of hiding though.  I''m guessing that you can do that by killing a lot of his Razaani ethereal.$B$BBring me the collection of souls that he no doubt has.', `VerifiedBuild`=19034 WHERE `ID`=10675; -- Show Them Gnome Mercy!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=64800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10678; -- The Main Course!
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10680; -- The Hand of Gul'dan
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10681; -- The Hand of Gul'dan
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='You don''t see many demon hunters nowadays.  They''re viewed with suspicion by their own people and it''s very rare to find one that doesn''t have some sort of allegiance to Illidan.$B$BThere are rumors of one such demon hunter out in Nagrand.  His name is Altruis.  He hates all demons with a passion and will help us if you can convince him that you share his goals.$B$BGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.', `VerifiedBuild`=19034 WHERE `ID`=10689; -- Altruis
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=64200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10702 /*A Grunt's Work...*/, 10703 /*Put On Yer Kneepads...*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=129900, `RewardItem1`=0, `RewardAmount1`=0, `VerifiedBuild`=19034 WHERE `ID`=10704; -- How to Break Into the Arcatraz
UPDATE `quest_template` SET `RewardBonusMoney`=97500, `QuestDescription`='It has been known to us that the fel orcs, under Illidan''s command, have guarded an Ata''mal crystal known as the Heart of Fury at the Ata''mal Terrace.  They cloud its presence with dark magic, to keep it from the Sha''tar.$B$BFight your way to the Ata''mal Terrace outside the Black Temple and turn your eyes to the sky.  Shadowlord Deathwail will circle the terrace, beyond your reach.  You will have to slay him and his warlocks before you can obtain the crystal.$B$BIt won''t be easy, $n.  I wish you luck.', `VerifiedBuild`=19034 WHERE `ID`=10707; -- The Ata'mal Terrace
UPDATE `quest_template` SET `RewardBonusMoney`=15600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10709 /*Reunion*/, 10783 /*Baron Sablemane*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=30000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10710; -- Test Flight: The Singing Ridge
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=30000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10711; -- Test Flight: Razaan's Landing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=30000, `AllowableRaces`=-1, `QuestDescription`='Hey, $n.  I''m glad I caught you!  I have a very important mission!$B$BHere is a nether-weather vane.  I need you to take some in flight readings for me and deliver them to my cousin in Ruuan Weald.$B$BSpeak with Rally and take a Zephyrium Capacitorium flight to Ruuan Weald.  While you''re flying, spin the vane!$B$BAfter you land, bring the spinning vane to O''Mally Zabnabber.$B$BGood luck, $n.  And don''t delay!', `VerifiedBuild`=19034 WHERE `ID`=10712; -- Test Flight: Ruuan Weald
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=33555378, `QuestDescription`='$n, now that you can see me, there is something you must tell Rexxar. I know that he seeks his people, and I know where they are.$B$BThe Mok''Nathal, as they are known, have a village to the east beyond the Razor Ridge.$B$BGo, give Rexxar this news. His people are in danger, and I know that he will want to come to their aid.', `VerifiedBuild`=19034 WHERE `ID`=10718; -- The Spirits Have Voices
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=33555378, `QuestDescription`='$n, I have a pet boar named Huffer. He wants to help you to have some fun with one of the nearby sons of Gruul.$B$BGrulloc inhabits a place known as the Cursed Hollow. When you get there, let Huffer loose. The gronn will have a fine time chasing him around, and you will retrieve the bag that he guards and deliver it to Baron Sablemane.$B$BTo get to the Cursed Hollow, head down the northern ramp and east through Dragons'' End. The hollow is on the eastern edge.', `VerifiedBuild`=19034 WHERE `ID`=10721; -- A Boaring Time for Grulloc
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=63300, `QuestDescription`='I know what must be done!  $n, you must pose as Overseer Nuaar and attend that meeting!$B$BThe wyrmcultists at the coven all have a standard outfit that they wear, so go collect scraps from them, and when you have enough, put together a disguise.$B$BPose as Overseer Nuuar and speak with Kolphis Darkscale to see what he has to say, and then return to Tree Warden Chawn.$B$BYou''ll find the coven by heading through the Wyrmskull Tunnel and following the path past the Raven''s Wood and Grishnath to its end.', `VerifiedBuild`=19034 WHERE `ID`=10722; -- Meeting at the Blackwing Coven
UPDATE `quest_template` SET `RewardBonusMoney`=63300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10723; -- Gorgrom the Dragon-Eater
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `QuestDescription`='Your services have gone above and beyond what is expected of you, $n.  You are but a step away from achieving the highest honor available to non-citizens of Dalaran.$B$BContinue to prove your loyalty to us and I will empower your signet to its full capacity.', `VerifiedBuild`=19034 WHERE `ID` IN (10725 /*Eminence Among the Violet Eye*/, 10726 /*Eminence Among the Violet Eye*/, 10727 /*Eminence Among the Violet Eye*/, 10728 /*Eminence Among the Violet Eye*/);
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `QuestDescription`='You have not disappointed us, $n.  We continue to have very high hopes for you, however.$B$BContinue to serve the Violet Eye and you will be appropriately rewarded.', `VerifiedBuild`=19034 WHERE `ID` IN (10738 /*Distinguished Service*/, 10739 /*Distinguished Service*/, 10740 /*Distinguished Service*/, 10741 /*Distinguished Service*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10742; -- Showdown
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=81300, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10744; -- News of Victory
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=81300, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10745; -- News of Victory
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=63300, `QuestDescription`='I need to examine the whelps that they are raising at the Blackwing Coven.$B$BThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.$B$BPlease, $n, take the net and capture a handful of them alive for me.$B$BFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven''s Wood.', `VerifiedBuild`=19034 WHERE `ID`=10747; -- Whelps of the Wyrmcult
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `QuestDescription`='They''ve left us no choice, $n.  It''s time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.$B$BI don''t know if you caught a glimpse of him while you were in there, but he''s one of the dragonkin, half-man, half-dragon.  And he''s tough, so don''t underestimate him!$B$BFinish it quickly and with any luck you''ll secure the safety of Evergrove and the Ruuan Weald.', `VerifiedBuild`=19034 WHERE `ID`=10748; -- Maxnar Must Die!
UPDATE `quest_template` SET `RewardBonusMoney`=48600, `AllowableRaces`=-1, `QuestDescription`='Word has come from my wind riders, $n. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.$B$BI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.', `VerifiedBuild`=19034 WHERE `ID`=10750; -- The Path of Conquest
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10751 /*Breaching the Path*/, 10764 /*Hotter than Hell*/, 10765 /*When Worlds Collide...*/, 10768 /*Tabards of the Illidari*/, 10773 /*Breaching the Path*/, 10774 /*Blood Elf + Giant = ???*/, 10775 /*Tabards of the Illidari*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=46800, `QuestDescription`='The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. $n, help me stop these crimes of nature destroy all which they corrupt. $B$BOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.', `VerifiedBuild`=19034 WHERE `ID`=10753; -- Culling the Wild
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10754 /*Entry Into the Citadel*/, 10755 /*Entry Into the Citadel*/, 10757 /*Rohok's Request*/, 10763 /*Dumphry's Request*/, 11477 /*Out of My Element?*/);
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10756 /*Grand Master Rohok*/, 10762 /*Grand Master Dumphry*/, 11273 /*The Human League*/, 11274 /*Zedd's Probably Dead*/, 11291 /*To Westguard Keep!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=81300, `AllowableRaces`=-1, `QuestDescription`='It''s no good, $n!  No matter how many coals I put to the fire, it''s just not enough heat.$B$BThere''s only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion''s fel reavers.$B$BI''ve only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.', `VerifiedBuild`=19034 WHERE `ID`=10758; -- Hotter than Hell
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10769 /*Dissension Amongst the Ranks...*/, 10776 /*Dissension Amongst the Ranks...*/);
UPDATE `quest_template` SET `RewardBonusMoney`=48600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10772 /*The Path of Conquest*/, 11276 /*And Then There Were Two...*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64200, `QuestDescription`='The totem alone is not strong enough to counteract the sinister magics of the dark conclave.$B$BWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.$B$BOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, $n.', `VerifiedBuild`=19034 WHERE `ID`=10778; -- The Rod of Lianthe
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=62400, `AllowableRaces`=33555378, `QuestDescription`='<Tor''chunk leans in close to whisper.>$B$B$n, you''ve done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.$B$BThat way we''ll be doubly certain of the outcome.$B$BTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons'' End and north through the Churning Gulch and Daggermaw Canyon.', `VerifiedBuild`=19034 WHERE `ID`=10784; -- Crush the Bloodmaul Camp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `AllowableRaces`=33555378, `QuestDescription`='I know that Rexxar has plans for you to head to Boulder''mok.  I have something that I want you to do while you are there.$B$BWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!$B$BBoulder''mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven''s Wood.$B$B$n, I want you to kill the Bladespire ogres of Boulder''mok.  Wipe them out!', `VerifiedBuild`=19034 WHERE `ID`=10786; -- Slaughter at Boulder'mok
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=10791; -- Welcoming the Wolf Spirit
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=57600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10792 /*Zeth'Gor Must Burn!*/, 10864 /*A Burden of Souls*/, 10909 /*Fel Spirits*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10802; -- Gorgrom the Dragon-Eater
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=63300, `AllowableRaces`=18875469, `QuestDescription`='I know that we have plans for you to head to Boulder''mok. I have something that I want you to do while you are there.$B$BWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!$B$BBoulder''mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven''s Wood you will find them.$B$B$n, I want you to wipe out the Bladespire ogres of Boulder''mok.', `VerifiedBuild`=19034 WHERE `ID`=10803; -- Slaughter at Boulder'mok
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=78000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10805; -- Massacre at Gruul's Lair
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10806; -- Showdown
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=80100, `QuestDescription`='The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh''lon Base Camp.$B$BGul''dan''s magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, $n. The death and destruction it would bring are unimaginable!$B$BCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!', `VerifiedBuild`=19034 WHERE `ID`=10808; -- Thwart the Dark Conclave
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `QuestDescription`='Their patron soars high above, $n. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.$B$B<Mordenai points to the sky.>$B$BFly high, friend...', `VerifiedBuild`=19034 WHERE `ID`=10811; -- Seek Out Neltharaku
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=29100, `AllowableRaces`=-1, `QuestDescription`='$n, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth''Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!$B$BTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.$B$BGo, $n.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!', `VerifiedBuild`=19034 WHERE `ID`=10813; -- The Eyes of Grillok
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='You did well against the Broken in Baa''ri, $n.  Let''s see how well you do against Illidan''s most feared army.$B$BThe fel orcs of the Shadowmoon Clan occupy the Ata''mal Terrace, once a very holy site where ata''mal crystals were used in spiritual ceremonies.$B$BWe had reason to believe they were hiding an actual ata''mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.', `VerifiedBuild`=19034 WHERE `ID`=10816; -- Reclaiming Holy Grounds
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='You did well against the Ashtongue Broken, $n.  I have another challenge for you, should you be up to it.$B$BNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan''s fel orcs.$B$BWe''ve determined it was perpetrated by the Shadowmoon orcs who occupy the Ata''mal Terrace.$B$BShow them that the Scryers are not to be trifled with.', `VerifiedBuild`=19034 WHERE `ID`=10817; -- The Great Retribution
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=18875469, `QuestDescription`='$n, while you were out being one hell of a $c, Baron Sablemane sent his pet dragon up here with a message.$B$BHe''s asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.$B$BI guess you''re the most qualified person in all of Outland to help him, but if I were you, I''d get in contact with a couple of friends first and ask them to join you at the Circle of Blood.', `VerifiedBuild`=19034 WHERE `ID`=10818; -- Baron Sablemane Has Requested Your Presence
UPDATE `quest_template` SET `RewardBonusMoney`=63300, `QuestDescription`='I have a very special mission for you, $n. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.$B$BIf all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted.$B$BGood luck to you $C.', `VerifiedBuild`=19034 WHERE `ID`=10819; -- Felsworn Gas Mask
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `VerifiedBuild`=19034 WHERE `ID`=10830; -- Exorcising the Trees
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=72900, `AllowableRaces`=-1, `QuestDescription`='Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon''s trinket... and the patch that covers his betrayal holds its own dark secrets.$B$BBring me Grillok''s eyepatch, $n, and I will reward you greatly for your service...', `VerifiedBuild`=19034 WHERE `ID`=10834; -- Grillok ""Darkeye""
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters'' grasps.$B$BTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.$B$BAnd $n, Beware the Dragonmaw that now inhabit the island.', `VerifiedBuild`=19034 WHERE `ID`=10837; -- To Netherwing Ledge!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=72000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10838 /*The Demoniac Scryer*/, 10935 /*The Exorcism of Colonel Jules*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=63300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (10843 /*Since Time Forgotten...*/, 10845 /*Slay the Brood Mother*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=14700, `VerifiedBuild`=19034 WHERE `ID`=10849; -- Seek Out Kirrik
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.$B$BRelease all that you can find and return to me, $n.', `VerifiedBuild`=19034 WHERE `ID`=10854; -- The Force of Neltharaku
UPDATE `quest_template` SET `RewardBonusMoney`=64200, `QuestDescription`='Brave acts of industrial sabotage will only get us so far, $n.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion''s teleportation devices are located.$B$BI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can''t allow that.', `VerifiedBuild`=19034 WHERE `ID`=10856; -- The Best Defense
UPDATE `quest_template` SET `RewardBonusMoney`=80100, `VerifiedBuild`=19034 WHERE `ID`=10857; -- Teleport This!
UPDATE `quest_template` SET `RewardBonusMoney`=16200, `QuestDescription`='It shames me to ask for your assistance once more, $n, but you are my flight''s only hope. Without my mate, the netherwing brood may die out completely.$B$BMake your way to the top of Dragonmaw Fortress and find Karynaku.$B$BWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.
', `VerifiedBuild`=19034 WHERE `ID`=10858; -- Karynaku
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=59100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (10862 /*Surrender to the Horde*/, 10863 /*Secrets of the Arakkoa*/);
UPDATE `quest_template` SET `RewardBonusMoney`=97500, `AllowableRaces`=52461566, `VerifiedBuild`=19034 WHERE `ID`=10866; -- Zuluhed the Whacked
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=79200, `AllowableRaces`=33555378, `QuestDescription`='There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!$B$B$n, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan''s Landing.$B$BGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!', `VerifiedBuild`=19034 WHERE `ID`=10867; -- There Can Be Only One Response
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=52461566, `VerifiedBuild`=19034 WHERE `ID`=10870; -- Ally of the Netherwing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=1, `VerifiedBuild`=19034 WHERE `ID`=10871; -- Ally of the Netherwing
UPDATE `quest_template` SET `RewardBonusMoney`=97500, `AllowableRaces`=1, `VerifiedBuild`=19034 WHERE `ID`=10872; -- Zuluhed the Whacked
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=74100, `AllowableRaces`=-1, `QuestDescription`='Force-Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor''s edge.  You must kill him, $n, for his loss would be a mighty blow to the fel orcs.$B$BHowever, that is not all you must do.$B$BTake this banner.  Place it atop Gorax''s corpse.  Gorax''s commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!$B$BHis head, the head of the hand of Kargath, is what I seek.', `VerifiedBuild`=19034 WHERE `ID`=10876; -- The Foot of the Citadel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=91200, `VerifiedBuild`=19034 WHERE `ID`=10879; -- The Skettis Offensive
UPDATE `quest_template` SET `RewardBonusMoney`=30000, `VerifiedBuild`=19034 WHERE `ID`=10880; -- Cabal Orders
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=129900, `QuestDescription`='<A discordant note can be detected in A''dal''s ''voice''.>$B$BPrince Kael''thas has chosen his warden poorly, and now the entities that we kept locked up within the Arcatraz are breaking free.$B$BOne in particular, a servant of the Old Gods known as Harbinger Skyriss, seeks to usher in his masters'' vision of conquering all of the worlds in the universe.$B$B$n, you must not allow him to escape.  Return to Tempest Keep, enter the Arcatraz, and slay Harbinger Skyriss before it is too late!', `VerifiedBuild`=19034 WHERE `ID`=10882; -- Harbinger of Doom
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `QuestDescription`='You have proven yourself capable of great feats, $n. Your discovery of the Cipher of Damnation and Kael''Thas'' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.$B$BA''dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.$B$B<Khadgar nods.>$B$BA''dal awaits...
', `VerifiedBuild`=19034 WHERE `ID`=10883; -- The Tempest Key
UPDATE `quest_template` SET `RewardBonusMoney`=60000, `QuestDescription`='I appreciate your help, $n.  I was certain I was going to be killed.$B$BLet''s get out of here with a hurry.  It won''t be long before more cultists come after us.', `VerifiedBuild`=19034 WHERE `ID`=10887; -- Escaping the Tomb
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=45600, `VerifiedBuild`=19034 WHERE `ID`=10889; -- Return to Shattrath
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=70800, `ItemDrop1`=31739, `ItemDropQuantity1`=1, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=10895; -- Zeth'Gor Must Burn!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=60900, `QuestDescription`='The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  $B$BRotting forest-ragers and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.', `VerifiedBuild`=19034 WHERE `ID`=10896; -- The Infested Protectors
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=75900, `VerifiedBuild`=19034 WHERE `ID`=10898; -- Skywing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=94800, `QuestDescription`='Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.$B$BThe Death''s Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.$B$BYou''re going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.$B$BAfter you have defeated Baelmon, return to Wildlord Antelarion.$B$BAnd, $n, thank you for all that you''ve gone through for us here.', `VerifiedBuild`=19034 WHERE `ID`=10912; -- The Hound-Master
UPDATE `quest_template` SET `RewardBonusMoney`=45600, `VerifiedBuild`=19034 WHERE `ID`=10926; -- Return to Sha'tari Base Camp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=72900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=10937; -- Drill the Drillmaster
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='One special little girl is going to be very happy to have you as a friend, even if it is for a short while.$B$BTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children''s Week itself, in fact.$B$BPlease, $n, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!', `VerifiedBuild`=19034 WHERE `ID`=10942; -- Children's Week
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='One special little girl is going to be very happy to have you as a friend, even if it is for a short while.$B$BTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children''s Week itself, in fact.$B$BPlease, $n, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!', `VerifiedBuild`=19034 WHERE `ID`=10943; -- Children's Week
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=81300, `QuestDescription`='Thanks again, $n.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.$B$BThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.$B$BIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul''s deepest secrets.$B$BAkama must be warned.  Our plans are in jeopardy!', `VerifiedBuild`=19034 WHERE `ID`=10944; -- The Secret Compromised
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?$B$BMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.$B$BThe time has come, $n.  I''ll lead Maiev and my Deathsworn to Illidan''s doorstep.$B$BSpeak to A''dal and and tell him of our plan.  If we strike together we''ll break through Illidan''s defenses.', `VerifiedBuild`=19034 WHERE `ID`=10948; -- The Hostage Soul
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48600, `VerifiedBuild`=19034 WHERE `ID` IN (10949 /*Entry Into the Black Temple*/, 11513 /*Intercepting the Mana Cells*/, 11514 /*Maintaining the Sunwell Portal*/, 11516 /*Blast the Gateway*/, 11537 /*The Battle Must Go On*/, 11538 /*The Battle for the Sun's Reach Armory*/);
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='One of the priests that comes to visit told a story about a place nearby.  It''s called Auchindoun, and it''s supposed to be very important to the draenei.$B$BHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.$B$BI''d like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.$B$BPlease, $G Mr. : Miss; $n, can we go?', `VerifiedBuild`=19034 WHERE `ID`=10950; -- Auchindoun and the Ring of Observance
UPDATE `quest_template` SET `RewardChoiceItemID5`=116202, `RewardChoiceItemQuantity5`=1, `AllowableRaces`=18875469, `QuestDescription`='Darn it all!  I guess it''s time to go back to the orphanage at Shattrath City.$B$BI''ve had such a great time.  You''re the best person in all of the worlds, $n!  You''re my big $g brother : sister; now!$B$B<Dornaa''s eyes begin to well up with tears.>$B$BI''m going to miss you so much!  When I grow up, I''m going to be just like you!!!', `VerifiedBuild`=19034 WHERE `ID`=10966; -- Back to the Orphanage
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `RewardChoiceItemID5`=116202, `RewardChoiceItemQuantity5`=1, `AllowableRaces`=33555378, `QuestDescription`='Darn it all!  I guess it''s time to go back to the orphanage at Shattrath City.$B$BI''ve had such a great time.  You''re the best person in all of the worlds, $n!  You''re my big $g brother : sister; now!$B$B<Salandria''s eyes begin to well up with tears.>$B$BI''m going to miss you so much!!!', `VerifiedBuild`=19034 WHERE `ID`=10967; -- Back to the Orphanage
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6600, `VerifiedBuild`=19034 WHERE `ID` IN (10969 /*Seek Out Ameer*/, 11119 /*Assault on Bash'ir Landing!*/, 11481 /*Crisis at the Sunwell*/, 11482 /*Duty Calls*/, 11663 /*Sharing Intelligence*/, 11680 /*Taking Wing*/, 11696 /*Ahune is Here!*/, 12011 /*Signs of Big Watery Trouble*/);
UPDATE `quest_template` SET `QuestDescription`='I am in need of more I.D tags, $n. What I''ve discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!$B$BOnce this code is broken we''ll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.', `VerifiedBuild`=19034 WHERE `ID`=10972; -- Ethereum Prisoner I.D. Catalogue
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=97500, `VerifiedBuild`=19034 WHERE `ID`=10976; -- The Mark of the Nexus-King
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `VerifiedBuild`=19034 WHERE `ID` IN (10977 /*Stasis Chambers of the Mana-Tombs*/, 11354 /*Wanted: Nazan's Riding Crop*/, 11362 /*Wanted: Keli'dan's Feathered Stave*/, 11363 /*Wanted: Bladefist's Seal*/, 11368 /*Wanted: The Heart of Quagmirran*/, 11369 /*Wanted: A Black Stalker Egg*/, 11370 /*Wanted: The Warlord's Treatise*/, 11372 /*Wanted: The Headfeathers of Ikiss*/, 11373 /*Wanted: Shaffar's Wondrous Pendant*/, 11374 /*Wanted: The Exarch's Soul Gem*/, 11375 /*Wanted: Murmur's Whisper*/, 11378 /*Wanted: The Epoch Hunter's Head*/, 11382 /*Wanted: Aeonus's Hourglass*/, 11384 /*Wanted: A Warp Splinter Clipping*/, 11386 /*Wanted: Pathaleon's Projector*/, 11388 /*Wanted: The Scroll of Skyriss*/, 11499 /*Wanted: The Signet Ring of Prince Kael'thas*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=16200, `VerifiedBuild`=19034 WHERE `ID`=10983; -- Mog'dorg the Wizened
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `QuestDescription`='<V''eru''s voice fills your mind with crystalline tone and clarity.>$B$BThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.$B$BDo you think you might aid him?$B$BHis name is Grok, and he is sitting near the merchants to the southeast.$B$BThank you, $n.', `VerifiedBuild`=19034 WHERE `ID`=10984; -- Speak with the Ogre
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=97500, `VerifiedBuild`=19034 WHERE `ID` IN (10995 /*Grulloc Has Two Skulls*/, 10996 /*Maggoc's Treasure Chest*/, 10998 /*Grim(oire) Business*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=97500, `QuestDescription`='Are you familiar with Shattrath City, $c?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.$B$BOne of Gruul''s sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.$B$B$n, you must travel there, and bring back his standard as proof that he has been dealt with.', `VerifiedBuild`=19034 WHERE `ID`=10997; -- Even Gronn Have Standards
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `FlagsEx`=8, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11002 /*The Fall of Magtheridon*/, 11003 /*The Fall of Magtheridon*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='We''re still having problems with those flak cannons, $n.$B$BDon''t get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn''t change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we''re having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri''la.$B$BWhat do you say?  Want to take another shot at it?', `VerifiedBuild`=19034 WHERE `ID`=11023; -- Bomb Them Again!
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.$B$BI always believed this to be the mere legend, $n.  The return of the talonpriests and your recovery of this tome indicate otherwise.$B$BWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.', `VerifiedBuild`=19034 WHERE `ID`=11028; -- Countdown to Doom
UPDATE `quest_template` SET `RewardBonusMoney`=48600, `QuestDescription`='Open the package, $n.  It is a disguise.  It doesn''t look very convincing, does it?$B$BI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk''s Rest; his name is Sahaak.  He is old and nearly blind.$B$BUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, $n.  The disguise won''t fool the other arakkoa.', `VerifiedBuild`=19034 WHERE `ID`=11029; -- A Shabby Disguise
UPDATE `quest_template` SET `RewardMoney`=-749999, `VerifiedBuild`=19034 WHERE `ID` IN (11031 /*Archmage No More*/, 11032 /*Protector No More*/, 11033 /*Assassin No More*/, 11034 /*Restorer No More*/, 11103 /*Sage No More*/, 11104 /*Restorer No More*/, 11105 /*Champion No More*/, 11106 /*Defender No More*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=33555378, `QuestDescription`='I''ve had a most unusual vision, $n, and I don''t know quite what to make of it. I''ve seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.$B$BIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, $n. Lend them your help, for without it, their efforts may yet fail.', `VerifiedBuild`=19034 WHERE `ID`=11037; -- A Strange Vision
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `QuestDescription`='Some time ago, Voren''thal dispatched a small team to Netherstorm to investigate the activities of Kael''thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.$B$BThalodien''s report was brief, but clear that he''s encountered something of great importance. Report to him at Area 52 and assist him in any way possible, $n.', `VerifiedBuild`=19034 WHERE `ID`=11039; -- Report to Spymaster Thalodien
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=18875469, `QuestDescription`='A strange vision haunts me, $n. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.$B$BI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.$B$BTravel to Netherstorm, $c. Locate those responsible for this creation and offer them your aid.', `VerifiedBuild`=19034 WHERE `ID`=11042; -- A Mystifying Vision
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=18875469, `QuestDescription`='A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.$B$BTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, $n. Help them in their fight.', `VerifiedBuild`=19034 WHERE `ID`=11044; -- Visions of Destruction
UPDATE `quest_template` SET `RewardBonusMoney`=97500, `QuestDescription`='<Akama inserts the crystal into the medallion in his hand.>$B$BI am not as strong as I once was, $n.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.$B$BTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A''dal in Shattrath City.', `VerifiedBuild`=19034 WHERE `ID`=11052; -- Akama's Promise
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11053 /*Rise, Overseer!*/, 11054 /*Overseeing and You: Making the Right Choices*/, 11055 /*The Booterang: A Cure For The Common Worthless Peon*/, 11084 /*Stand Tall, Captain!*/, 11243 /*If Valgarde Falls...*/, 11244 /*Rescuing the Rescuers*/, 11290 /*Dragonflayer Battle Plans*/, 11502 /*In Defense of Halaa*/, 11503 /*Enemies, Old and New*/);
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `QuestDescription`='Do not draw attention to our conversation.  Adaris would not approve.$B$BI belong to the lowest caste of arakkoa, $n.  During Terokk''s rule I would''ve been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk''s return, then you must prevent them from succeeding - regardless of what your leader says!$B$BI''ve something to offer you that you''ll find useful.  There is a package at my old dwelling in Upper Veil Shil''ak.  Bring it to me!', `VerifiedBuild`=19034 WHERE `ID`=11056; -- Hazzik's Bargain
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='As to that other magical flask, it can only be obtained from one spot: Bash''ir Landing.  It''s an ethereal base, and they aren''t too friendly with outsiders, so it might be a little dangerous to obtain.$B$BWhere''s Bash''ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you''ll eventually spot it.  The Bash''ir crystalforge itself is at the northeast corner of the landing.$B$BThank you for doing this, $n.  It''ll mean the world to our sons!', `VerifiedBuild`=19034 WHERE `ID`=11061; -- A Father's Duty
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6600, `QuestDescription`='$n, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?$B$BSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he''s asked us to send along anyone that we feel would excel at helping out.$B$BThat would be you!$B$BHead up there as soon as you can, and please, give him our regards.', `VerifiedBuild`=19034 WHERE `ID`=11062; -- The Skyguard Outpost
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='Dragonmaw treat you right, $n. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.$B$BI''m going to shake you off my tail like a bad case of fleas...$B$BWe''ll lift off when you are ready.', `VerifiedBuild`=19034 WHERE `ID`=11067; -- Dragonmaw Race: Trope the Filth-Belcher
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `RewardChoiceItemID2`=32830, `RewardChoiceItemID3`=32829, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `QuestDescription`='I... I''ve turned a blind eye to your dealings with the arakkoa prisoner, $n.  It looks like your instincts to cooperate with him were right.$B$BYou must understand... I would''ve faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.$B$BTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you''ll only get one chance at this.', `VerifiedBuild`=19034 WHERE `ID`=11073; -- Terokk's Downfall
UPDATE `quest_template` SET `RewardBonusMoney`=32400, `AllowableRaces`=-1, `QuestDescription`='Your help is required at the Netherwing Mines, overseer $n.$B$BTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.$B$BReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.', `VerifiedBuild`=19034 WHERE `ID`=11075; -- The Netherwing Mines
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=81300, `AllowableRaces`=-1, `QuestDescription`='Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can''t get to any of it with the current infestation.$B$BThat''s where you come in, $n. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.$B$BGather the nethermine cargo and return it to me or my sister.', `VerifiedBuild`=19034 WHERE `ID`=11076; -- Picking Up The Pieces...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `QuestDescription`='As ye''ve flown around, ye must have noticed the dragons above.  I trust ye haven''t fallen victim ta their rage.  Help us put an end ta it, $n!$B$BRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, $g lad : lass;, break open an egg with 35 apexis shards and attract the dragon down.$B$BBring me some teeth as proof.', `VerifiedBuild`=19034 WHERE `ID`=11078; -- To Rule The Skies
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=48600, `VerifiedBuild`=19034 WHERE `ID` IN (11080 /*The Relic's Emanation*/, 11496 /*The Sanctum Wards*/, 11520 /*Discovering Your Roots*/, 11523 /*Arm the Wards!*/, 11524 /*Erratic Behavior*/, 11525 /*Further Conversions*/, 11526 /*The Missing Magistrix*/, 11532 /*Distraction at the Dead Scar*/, 11533 /*The Air Strikes Must Continue*/);
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='Don''t worry about this dragon, $n. We''ve got plans for it...$B$BDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they''ve lost all sense of decency.$B$BThey''ve resorted to cannibalism and the promotion of mayhem. We don''t need that kind of madness in this place. Find ''em and kill ''em. All of ''em.', `VerifiedBuild`=19034 WHERE `ID`=11083; -- Crazed and Confused
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=48600, `QuestDescription`='Hail, $n.  I thank you for coming to my aid.$B$BThe arakkoa''s monstrous birds knocked me from my nether ray while on a scouting mission.$B$BLet''s get out of here, while we can.', `VerifiedBuild`=19034 WHERE `ID`=11085; -- Escape from Skettis
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6600, `QuestDescription`='You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.$B$BJho''nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri''la.$B$BYou are one such friend, $n.$B$BWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.', `VerifiedBuild`=19034 WHERE `ID`=11091; -- A Special Thank You
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `AllowableRaces`=-1, `QuestDescription`='Captain $n!$B$B<Taskmaster Varkule salutes you.>$B$BOverlord Mor''ghor has asked to see you in his chambers at once!', `VerifiedBuild`=19034 WHERE `ID`=11092; -- Hail, Commander!
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='Commander $n, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers'' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.$B$BGo now! Use this flare gun to signal the Skybreakers for the attack!', `VerifiedBuild`=19034 WHERE `ID`=11094; -- Kill Them All!
UPDATE `quest_template` SET `QuestDescription`='The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.$B$BI want you to let them come, $n.$B$B<Thelis nods.>$B$BYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.', `VerifiedBuild`=19034 WHERE `ID`=11095; -- Commander Hobb
UPDATE `quest_template` SET `RewardBonusMoney`=64800, `QuestDescription`='Commander $n, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha''tar destroyed, our lines of communication to our posts at Coilskar will once more be open.$B$BGo now! Use this flare gun to signal the Skybreakers for the attack!', `VerifiedBuild`=19034 WHERE `ID`=11099; -- Kill Them All!
UPDATE `quest_template` SET `QuestDescription`='The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.$B$BI want you to let them come, $n.$B$B<Ceyla nods.>$B$BYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.
', `VerifiedBuild`=19034 WHERE `ID`=11100; -- Commander Arcus
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=97500, `Flags`=131, `QuestDescription`='Come, highlord $n. Illidan himself awaits us!', `VerifiedBuild`=19034 WHERE `ID`=11108; -- Lord Illidan Stormrage
UPDATE `quest_template` SET `RewardMoney`=7, `RewardMoneyDifficulty`=1, `AllowableRaces`=-1, `LogDescription`='Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be wearing Synthebrew Goggles to see them.', `QuestDescription`='Here now. Ye hear that? There be sounds in them hills. Those''re the wolpertingers! Wily beasts, they are, attracted by the smells o'' Brewfest. I''ve a mind to catch me some, but I knocked me shin and can''t outrun the buggers. Ye can help me, though!$b$bTake this net and cast it over the little blighters. Bring me a good five of ''em and I''ll make it worth yer while!$b$bOne more thing - ye gotta use Synthebrew Goggles to spot ''em! Let me know if ya need a pair.', `VerifiedBuild`=19034 WHERE `ID`=11117; -- Catch the Wild Wolpertinger!
UPDATE `quest_template` SET `RewardMoney`=7, `RewardMoneyDifficulty`=1, `AllowableRaces`=-1, `LogDescription`='Visit the beer gardens outside Stormwind, Darnassus, and the Exodar, zap three elekks at each location, and return to Goldark Snipehunter. You must be wearing Synthebrew Goggles to see the pink elekks.', `QuestDescription`='Getting drunk is a time-honored tradition at Brewfest -- it''s damn near required! Thing is, I''m getting reports across Azeroth saying the celebration''s plagued by hallucinations!  We can''t have that!$b$bThese elekks can''t be harmed by normal weapons -- they pass right through ''em -- so take this fabulous piece of gnomish machinery, visit the other beer gardens, and zap ''em to oblivion.$b$bRemember, you have to be wearing Synthebrew Goggles to see ''em! Talk to me if you need a pair.', `VerifiedBuild`=19034 WHERE `ID`=11118; -- Pink Elekks On Parade
UPDATE `quest_template` SET `RewardMoney`=7, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=960, `AllowableRaces`=-1, `LogDescription`='Visit the beer gardens outside of Silvermoon, Thunder Bluff, and the Undercity, zap three elekks at each location, and return to Glodrak Huntsniper. You must be wearing Synthebrew Goggles to see the pink elekks.', `QuestDescription`='Look. We''re running a business here. People being drunk? It''s good business. But I''ll tell ya one thing that puts a cramp in the profits - hallucinations. Wouldn''t ya know it, the boys are reporting that the sot- er, the loyal customers are seeing pink elekks everywhere.$b$bI don''t need my customers unsettled. Look, take this ray and travel to the other beer gardens to take care of ''em for me, would ya? And be sure to wear Synthebrew Goggles! Talk to me if ya need a pair.', `VerifiedBuild`=19034 WHERE `ID`=11120; -- Pink Elekks On Parade
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `StartItem`=0, `AllowableRaces`=18875469, `LogDescription`='Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill.    If you lose your ram, ask Neill Ramstein for another.', `VerifiedBuild`=19034 WHERE `ID`=11122; -- There and Back Again
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Help, $n! My prized puppy, Kyle, has run away! I just know he''s running around Bloodhoof Village, lost and hungry.$B$BWill you find him and feed him? Once he eats he will settle down and come home.$B$BTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.', `VerifiedBuild`=19034 WHERE `ID`=11129; -- Kyle's Gone Missing!
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `QuestDescription`='Come closer, $G man:sweetheart;! Let ol'' Griftah look at yer shiny things....$b$bHmm. Yeh, yeh, not bad, but ya can do better. Much, much better.$b$b<Griftah leans in and whispers.>$b$bThere be priceless shinies everywhere, $n, ya just gotta know where to look! It be yer lucky day; I know a fella who can help ya find more shinies than ya can ever carry.$b$bVisit my ol'' friend, Budd, near Zul''Aman and show him this here. Ya be tellin'' him ol'' Griftah sent ya and he''ll let ya in on his new project.', `VerifiedBuild`=19034 WHERE `ID`=11130; -- Oooh, Shinies!
UPDATE `quest_template` SET `RewardBonusMoney`=73200, `VerifiedBuild`=19034 WHERE `ID` IN (11135 /*The Headless Horseman*/, 11220 /*The Headless Horseman*/, 12900 /*Making a Harness*/, 12983 /*The Last of Her Kind*/, 14482 /*Call of Duty*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11153 /*Break the Blockade*/, 11154 /*Scare the Guano Out of Them!*/, 11155 /*Shoveltusk Soup Again?*/, 11188 /*Two Wrongs...*/, 11190 /*One Size Does Not Fit All*/, 11202 /*Mission: Eternal Flame*/, 11224 /*Send Them Packing*/, 11231 /*Of Keys and Cages*/, 11240 /*Leader of the Deranged*/, 11245 /*Towers of Certain Doom*/, 11246 /*Gruesome, But Necessary*/, 11247 /*Burn Skorn, Burn!*/, 11284 /*The Yeti Next Door*/, 11322 /*The Cleansing*/, 11348 /*The Rune of Command*/, 11349 /*Mastering the Runes*/, 11390 /*I've Got a Flying Machine!*/, 11391 /*Steel Gate Patrol*/, 11394 /*And You Thought Murlocs Smelled Bad!*/, 11410 /*The One That Got Away*/, 11432 /*Sleeping Giants*/, 11645 /*Dirty, Stinkin' Snobolds!*/, 11650 /*Just a Few More Things...*/, 11653 /*Hah... You're Not So Big Now!*/, 11658 /*Plan B*/, 11693 /*Oh Great... Plagued Magnataur!*/, 11694 /*There's Something Going On In Those Caves*/, 11698 /*Might As Well Wipe Out the Scourge*/, 11710 /*What's the Matter with the Transmatter?*/, 11715 /*Fueling the Project*/, 11718 /*A Bot in Mammoth's Clothing*/, 11726 /*A Little Bit of Spice*/, 11728 /*Lupus Pupus*/, 11795 /*Emergency Protocol: Section 8.2, Paragraph C*/, 11796 /*Emergency Protocol: Section 8.2, Paragraph D*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='$n, I don''t trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed!$B$BSince we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don''t do something quickly, we''ll be surrounded on all sides by the fire within a few weeks'' time!$B$BGet down there and eliminate the threat by destroying those eggs and the proto-whelps.', `VerifiedBuild`=19034 WHERE `ID`=11157; -- The Clutches of Evil
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='When the dragons came and took over Brogg''s old home, Stonemaul ogres fled and left everything behind, including clan''s banner.$B$BBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it''s called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.$B$BBrogg''s clan''s old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, $n.', `VerifiedBuild`=19034 WHERE `ID`=11160; -- [DEPRECATED]Banner of the Stonemaul
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11167 /*The New Plague*/, 11170 /*Test at Sea*/, 11227 /*Let Them Eat Crow*/, 11230 /*Ambushed!*/, 11282 /*A Lesson in Fear*/, 11307 /*Field Test*/, 11420 /*The Path to Payback*/, 11424 /*Shield Hill*/, 11443 /*Daggercap Divin'*/, 11797 /*The Siege*/, 11889 /*Death From Above*/, 11913 /*Take No Chances*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=33000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11168 /*Spiking the Mix*/, 11574 /*Too Close For Comfort*/, 11575 /*Nick of Time*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `VerifiedBuild`=19034 WHERE `ID`=11171; -- Hex Lord? Hah!
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11175 /*My Daughter*/, 11176 /*See to the Operations*/, 11302 /*The Enigmatic Frost Nymphs*/, 11328 /*Mission: Forsaken Intel*/, 11331 /*You Tell Him ...Hic!*/, 11395 /*It's a Scourge Device*/, 11497 /*Learning to Fly*/, 11692 /*Check in With Bixie*/, 11704 /*King Mrgl-Mrgl*/, 11708 /*The Mechagnomes*/, 11729 /*The Ultrasonic Screwdriver*/, 11995 /*Your Presence is Required at Stars' Rest*/, 12168 /*The Favor of Zangus*/, 12766 /*Speak with your Ambassador*/, 25481 /*To New Thalanaar*/);
UPDATE `quest_template` SET `RewardBonusMoney`=82200, `VerifiedBuild`=19034 WHERE `ID` IN (11182 /*Root Causes*/, 11467 /*Dead Man's Debt*/, 11479 /*""Crowleg"" Dan*/, 11613 /*Karuk's Oath*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='THIS IS OUTRAGEOUS! Those proto-drakes are attacking the keep!$B$BBeasts such as that should have been scared off when you took care of their clutches and whelps.$B$BYou did take care of them, right?$B$B$n, this calls for more direct action. Speak with my advisor, Mage-Lieutenant Malister. He''ll provide you with the means to get at those infernal creatures.', `VerifiedBuild`=19034 WHERE `ID`=11187; -- Mage-Lieutenant Malister
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=94000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `QuestDescription`='Da Amani been rebuildin'' their forces and dey raised up a new warlord to lead dem, $n. He be called Daakara da Invincible, but we be seein'' whether he lives up to the name or not.$B$BYa must first defeat all his lieutenants to clear da way before ya can face this Daakara. Defeat him and put an end to da ambitions of da Zandalari and da Amani!


', `VerifiedBuild`=19034 WHERE `ID`=11196; -- Warlord of the Amani
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='$n, now that those damnable proto-creatures have been dealt with, I''ve another task for you.$B$BOne of my scouts has reported back some suspicious activity by the Forsaken to the south. It looks like they''re up to no good at the vrykul village known as Halgrind.$B$BI want you to personally take over the investigation down there. Speak with Scout Knowles to find out what he''s uncovered and proceed from there.$B$BHis last reported position is at the Ember Spear Tower, just to the west of Halgrind.', `VerifiedBuild`=19034 WHERE `ID`=11199; -- Report to Scout Knowles
UPDATE `quest_template` SET `RewardBonusMoney`=2220, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=11212; -- Tabetha's Farm
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='$n, the captain''s tasked me with a mission. I''d like you to help.$B$BA bunch of my fellow Explorers'' League people went nuts digging up stuff in the Whisper Gulch just to the north. They''re attacking anyone trying to get in!$B$BThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.$B$BGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn''t cheap you know!$B$BI gotta warn you though, that ore is strange!', `VerifiedBuild`=19034 WHERE `ID`=11218; -- Danger! Explosives!
UPDATE `quest_template` SET `RewardBonusMoney`=49200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11221 /*Reports from the Field*/, 11253 /*Sniff Out the Enemy*/, 11285 /*Baleheim Must Burn!*/, 11600 /*The Late William Allerton*/, 11603 /*In Wine, Truth*/, 11711 /*Coward Delivery... Under 30 Minutes or it's Free*/, 11789 /*A Soldier in Need*/, 11901 /*Military?  What Military?*/);
UPDATE `quest_template` SET `RewardBonusMoney`=16500, `AllowableRaces`=-1, `QuestDescription`='We have the Windrunner, the Queen''s Reprisal and the Oblivion stationed just east of the Derelict Strand.  Send orders to the fleet''s commander, Captain Harker, that they''re to destroy the Alliance''s cannons.$B$BSpeak to our bat handler, Camille, and ask for passage to the fleet''s location.  Be quick, $n, every minute we spend fighting the Alliance is a minute we could''ve spent fighting Arthas.', `VerifiedBuild`=19034 WHERE `ID`=11229; -- The Windrunner Fleet
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11232 /*Guide Our Sights*/, 11270 /*War is Hell*/, 11277 /*The Depths of Depravity*/, 11300 /*Stunning Defeat at the Ring*/, 11333 /*Into the World of Spirits*/, 11344 /*Anguish of Nifflevar*/, 11423 /*The Enemy's Legacy*/, 11429 /*Drop It then Rock It!*/, 11460 /*Trust is Earned*/, 11465 /*The Ransacked Caravan*/, 11484 /*We Have the Technology*/, 11598 /*Taking Back Mightstone Quarry*/, 11602 /*Cutting Off the Source*/, 11606 /*Patience is a Virtue that We Don't Need*/, 11611 /*Taken by the Scourge*/, 11632 /*What the Cold Wind Brings...*/, 11643 /*Mobu's Pneumatic Tank Transjigamarig*/, 11644 /*Super Strong Metal Plates!*/, 11662 /*Seek Out Karuk!*/, 11676 /*Merciful Freedom*/, 11686 /*The Warsong Farms*/, 11688 /*Damned Filthy Swine*/, 11716 /*The Wondrous Bloodspore*/, 11721 /*Gammothra the Tormentor*/, 11724 /*Massive Moth Omelet?*/, 11792 /*Enemies of the Light*/, 11794 /*The Hunt is On*/, 12482 /*Against Nifflevar*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=-1, `QuestDescription`='You''ve proven yourself in the field of battle, $n.  You might very well have changed the tides in our favor.$B$BI''ve an important assignment for you now.  I''m not sure how much longer the weakness we''ve exposed is going to last, so we must use the element of surprise to our advantage.$B$BI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, $c.', `VerifiedBuild`=19034 WHERE `ID`=11233; -- Landing the Killing Blow
UPDATE `quest_template` SET `RewardBonusMoney`=33000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11234 /*Report to Anselm*/, 11254 /*The Dragonskin Map*/, 11599 /*Thassarian, My Brother*/, 11601 /*Lost and Found*/, 11790 /*Cultists Among Us*/, 11902 /*Pernicious Evidence*/, 11920 /*Cultists Among Us*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.$B$BThey call the place Gjalerbron, though you''d pronounce the ''Gj'' as if it were an ''Sh''. Odd creatures.$B$BBut that''s not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they''re up to.$B$BI know that I can count on you, $n.', `VerifiedBuild`=19034 WHERE `ID`=11235; -- Dealing With Gjalerbron
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=18875469, `QuestDescription`='The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas'' fold.$B$BI want the leader of these necrolords eliminated!$B$BDo whatever it takes, $n, but see to it that Necro Overlord Mezhen, and whatever he''s attempting to accomplish, is neutralized.$B$BI will not see the vrykul successfully allied with the Scourge!$B$BLook for Mezhen on the platform in the rear right section of Gjalerbron.', `VerifiedBuild`=19034 WHERE `ID`=11236; -- Necro Overlord Mezhen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11237 /*Gjalerbron Attack Plans*/, 11355 /*March of the Giants*/, 12000 /*Rifle the Bodies*/, 12060 /*Projections and Plans*/, 12065 /*The Focus on the Beach*/, 12067 /*A Letter for Home*/, 12092 /*Strengthen the Ancients*/, 12098 /*Search Indu'le Village*/, 12166 /*The Liquid Fire of Elune*/, 12167 /*Kill the Cultists*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=18875469, `QuestDescription`='You were right to bring this to me, $n. You must venture to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!$B$BEven now, as we speak here, the frost wyrm may be on its way.$B$BHowever, if I''m reading these plans correctly, blowing the wyrmcaller''s horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!$B$BAnd $n, please bring me the horn. We wouldn''t want it falling back into the wrong hands.', `VerifiedBuild`=19034 WHERE `ID`=11238; -- The Frost Wyrm and its Master
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='Your service has been exemplary, $n, but there is something that is troubling me: the Scourge.$B$BThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.$B$BPurification is the key to salvation, my child. Make us proud!', `VerifiedBuild`=19034 WHERE `ID`=11239; -- In Service to the Light
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=33555378, `QuestDescription`='Thanks for bailing me out of this mess, $n.  I was not looking forward to what these Alliance scumbags had in store for me.$B$BLet''s get out of here and see if we can get back at them somehow.  Is that a campfire over there?', `VerifiedBuild`=19034 WHERE `ID`=11241; -- Trail of Fire
UPDATE `quest_template` SET `RewardMoney`=150, `RewardMoneyDifficulty`=6, `AllowableRaces`=18875469, `QuestDescription`='Rage was my prison, $n, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.$B$BThank you for leading me back to the Light.  May I never again lose my way.$B$BTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.', `VerifiedBuild`=19034 WHERE `ID`=11242; -- Free at Last!
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='$n, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.$B$BThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those ''giants'' are poised to strike us, and with my forces scattered all over the fjord, I don''t have the men to take the place by force.$B$BInstead, you''re going to use your cunning. I''ve sent a sergeant ahead with the details. Show this command insignia at Skorn and he''ll reveal himself and follow your orders.', `VerifiedBuild`=19034 WHERE `ID`=11248; -- Operation: Skornful Wrath
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11249 /*Stop the Ascension!*/, 11250 /*All Hail the Conqueror of Skorn!*/, 11359 /*Demolishing Megalith*/, 11452 /*The Slumbering King*/, 11670 /*It Was The Orcs, Honest!*/, 12107 /*The End of the Line*/);
UPDATE `quest_template` SET `QuestInfoID`=81, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11251; -- Fresh Legs
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=131400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11252; -- Into Utgarde!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `AllowableRaces`=-1, `QuestDescription`='This battle is far from over, $n. If our people are still alive inside that village, someone has to go and get ''em.$B$B<Vice Admiral Keller nods at you.>$B$BHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you''ll need to find a way to break them out.$B$BMaybe they''ll have some more information about what it is that we''re actually fighting.', `VerifiedBuild`=19034 WHERE `ID`=11255; -- Prisoners of Wyrmskull
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=33555378, `QuestDescription`='$n, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.$B$BMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.$B$BI ask that you use your cunning to buy us time. I''ve sent a brave ahead with the details. Show this emblem at Skorn and he''ll reveal himself and do all he can to aid you.', `VerifiedBuild`=19034 WHERE `ID`=11256; -- Skorn Must Fall!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (11257 /*Gruesome, But Necessary*/, 11259 /*Towers of Certain Doom*/, 11263 /*Dealing With Gjalerbron*/, 11271 /*Hasty Preparations*/, 11279 /*Green Eggs and Whelps*/, 11281 /*Mimicking Nature's Call*/, 11286 /*The Artifacts of Steel Gate*/, 11298 /*What's in That Brew?*/, 11301 /*Brains! Brains! Brains!*/, 11311 /*Suppressing the Elements*/, 11317 /*The Cleansing*/, 11350 /*The Book of Runes*/, 11351 /*Mastering the Runes*/, 11352 /*The Rune of Command*/, 11397 /*And You Thought Murlocs Smelled Bad!*/, 11433 /*Sleeping Giants*/, 11593 /*The Honored Dead*/, 11594 /*Put Them to Rest*/, 11635 /*Farseer Grimwalker's Spirit*/, 11639 /*Revenge Upon Magmoth*/, 11649 /*Motes of the Enraged*/, 11675 /*A Proper Death*/, 11677 /*Stop the Plague*/, 11683 /*Fallen Necropolis*/, 11684 /*Scouting the Sinkholes*/, 11685 /*The Heart of the Elements*/, 11695 /*The Horn of Elemental Fury*/, 11881 /*Load'er Up!*/, 11887 /*Emergency Supplies*/, 11890 /*What Are They Up To?*/, 11893 /*The Power of the Elements*/, 11895 /*Master the Storm*/, 11896 /*Weakness to Lightning*/, 11899 /*Souls of the Decursed*/, 11906 /*Cleaning Up the Pools*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `QuestDescription`='Chieftain Ashtotem ordered me to destroy many buildings here.$B$BHowever, you are in charge, so it falls to your hands, $n.$B$BI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.', `VerifiedBuild`=19034 WHERE `ID`=11258; -- Burn Skorn, Burn!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (11260 /*Stop the Ascension!*/, 11261 /*The Conqueror of Skorn!*/, 11367 /*Demolishing Megalith*/, 11453 /*The Slumbering King*/, 11592 /*We Strike!*/, 12110 /*The End of the Line*/);
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=47000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=11262; -- Ingvar Must Die!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=33555378, `QuestDescription`='The dead ones are at Gjalerbron and they have necromancers with them?$B$BWe must eliminate the leader of these necrolords.$B$BDo whatever it takes, $n, but see to it that Necro Overlord Mezhen, and whatever he''s attempting to accomplish, is neutralized.$B$BWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!$B$BLook for Mezhen on the platform in the rear right section of Gjalerbron.', `VerifiedBuild`=19034 WHERE `ID`=11264; -- Necro Overlord Mezhen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `QuestDescription`='From the little we know, the vrykul are conducting unnatural rites in an ''awakening'' ritual to the west in Gjalerbron.$B$BThey''re using living sacrifices to fuel their rituals.$B$B$n, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.$B$BThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....', `VerifiedBuild`=19034 WHERE `ID`=11265; -- Of Keys and Cages
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (11266 /*Gjalerbron Attack Plans*/, 11296 /*Rivenwood Captives*/, 11365 /*March of the Giants*/, 11366 /*The Lodestone*/, 11627 /*Boiling Point*/, 11628 /*Shrouds of the Scourge*/, 11630 /*The Bad Earth*/, 11633 /*Blending In*/, 11637 /*Kaganishu*/, 11659 /*Shatter the Orbs!*/, 11687 /*The Doctor and the Lich-Lord*/, 11999 /*Rifle the Bodies*/, 12066 /*The Focus on the Beach*/, 12084 /*Atop the Woodlands*/, 12085 /*A Letter for Home*/, 12096 /*Strengthen the Ancients*/, 12106 /*Search Indu'le Village*/, 12205 /*Wanted: The Scarlet Onslaught*/, 12209 /*Materiel Plunder*/, 12214 /*Fresh Remounts*/, 12230 /*Stealing from the Siegesmiths*/, 12232 /*Bombard the Ballistae*/, 12234 /*Need to Know*/, 12239 /*The Spy in New Hearthglen*/, 12240 /*A Means to an End*/, 12243 /*Fire Upon the Waters*/, 12245 /*No Mercy for the Captured*/, 12252 /*Torture the Torturer*/, 12254 /*Without a Prayer*/, 12260 /*The Perfect Dissemblance*/, 12283 /*The Truth Will Out*/, 12303 /*Funding the War Effort*/, 12304 /*Beachfront Property*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=33555378, `QuestDescription`='Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must venture west to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!$B$BEven now it may be on its way!$B$BIf I''m reading these plans correctly, blowing the wyrmcaller''s horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!$B$BAnd $n, bring me the horn. We wouldn''t want it falling back into the wrong hands!', `VerifiedBuild`=19034 WHERE `ID`=11267; -- The Frost Wyrm and its Master
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `QuestDescription`='Your assistance to us has been tremendous, $n, but there is something that is troubling me: these so-called Scourge.$B$BThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!$B$BPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!', `VerifiedBuild`=19034 WHERE `ID`=11268; -- The Walking Dead
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I''ve still got more cloaks to make.$B$BI''ve been using spotted hippogryph down for the cloaks'' linings, but my stock won''t last!$B$BYou''ve got to help me, $n. Captain Adams will have my hide if those cloaks aren''t ready in time! Bring me all the down you can find out there. It''s dropped to the ground by molting hippogryphs flying over the wilderness around the fort.', `VerifiedBuild`=19034 WHERE `ID`=11269; -- Down to the Wire
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=47000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11272 /*A Score to Settle*/, 13094 /*Have They No Shame?*/, 13095 /*Have They No Shame?*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `QuestDescription`='My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.$B$BTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.$B$BBring me the best dire ram horns you can find, $n, and I''ll select one from among them.', `VerifiedBuild`=19034 WHERE `ID`=11275; -- Making the Horn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=16500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11278; -- Return to Valgarde
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `QuestDescription`='Wait, that gives me an idea! What if it didn''t kill the whelps because it was sprayed on the outside of their eggs?$B$B$n, we have to get the plague inside of them!$B$BI know! I''ve got some plagued meat here. Take it to the Ember Clutch and get them to eat it!$B$BBut no, we''re thinking too small. Let''s get one of the proto-drakes flying overhead to come down and eat it.$B$BYes!$B$BStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.', `VerifiedBuild`=19034 WHERE `ID`=11280; -- Draconis Gastritis
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11283 /*Baleheim Bodycount*/, 11303 /*The Ambush*/, 11310 /*Warning: Some Assembly Required*/, 11421 /*It Goes to 11...*/, 12481 /*Adding Injury to Insult*/);
