UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=33000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11289; -- Guided by Honor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11292 /*Preying Upon the Weak*/, 11329 /*I'll Try Anything!*/);
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `StartItem`=0, `AllowableRaces`=18875469, `QuestDescription`='We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I''ll make things easy though, I''ll lend you a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.', `VerifiedBuild`=19034 WHERE `ID`=11293; -- Bark for the Barleybrews!
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `StartItem`=0, `AllowableRaces`=18875469, `QuestDescription`='It''s time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.$b$bWe''ll make it easy though.  We''ll lend you a ram for 4 minutes.$b$bBe careful with going too fast though since you won''t find any apple crates in Ironforge...  We can''t take the chance of helping out the Barleybrew messengers.', `VerifiedBuild`=19034 WHERE `ID`=11294; -- Bark for the Thunderbrews!
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=33555378, `QuestDescription`='Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed.$B$BA small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, $n. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.', `VerifiedBuild`=19034 WHERE `ID`=11297; -- Keeping Watch on the Interlopers
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `LogTitle`='The Ring of Judgment', `VerifiedBuild`=19034 WHERE `ID`=11299; -- The Ring of Judgment
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='I''m afraid our equipment isn''t exactly the best here at Vengeance Landing.  After all it''s a military controlled outpost.$B$BI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.$B$BYou must hurry, $n.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!', `VerifiedBuild`=19034 WHERE `ID`=11304; -- New Agamand
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='We''ve been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won''t drop dead.$B$BLet''s face it, $n, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul''s biology.$B$BHalgrind''s chieftain fled the town after we took it over; you''ll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.', `VerifiedBuild`=19034 WHERE `ID`=11305; -- A Tailor-Made Formula
UPDATE `quest_template` SET `RewardBonusMoney`=49200, `AllowableRaces`=-1, `QuestDescription`='You''ve done well so far, $n.  I''d like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.$B$BTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.', `VerifiedBuild`=19034 WHERE `ID`=11306; -- Apply Heat and Stir
