UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `RewardBonusMoney`=4650, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11583 /*Honor the Flame*/, 11804 /*Honor the Flame*/, 11805 /*Honor the Flame*/, 11806 /*Honor the Flame*/, 11807 /*Honor the Flame*/, 11808 /*Honor the Flame*/, 11809 /*Honor the Flame*/, 11810 /*Honor the Flame*/, 11811 /*Honor the Flame*/, 11812 /*Honor the Flame*/, 11813 /*Honor the Flame*/, 11814 /*Honor the Flame*/, 11815 /*Honor the Flame*/, 11816 /*Honor the Flame*/, 11817 /*Honor the Flame*/, 11818 /*Honor the Flame*/, 11820 /*Honor the Flame*/, 11821 /*Honor the Flame*/, 11822 /*Honor the Flame*/, 11823 /*Honor the Flame*/, 11824 /*Honor the Flame*/, 11825 /*Honor the Flame*/, 11826 /*Honor the Flame*/, 11827 /*Honor the Flame*/, 11828 /*Honor the Flame*/, 11829 /*Honor the Flame*/, 11830 /*Honor the Flame*/, 11831 /*Honor the Flame*/, 11832 /*Honor the Flame*/, 11833 /*Honor the Flame*/, 11834 /*Honor the Flame*/, 13485 /*Honor the Flame*/, 13486 /*Honor the Flame*/, 13489 /*Honor the Flame*/, 13490 /*Honor the Flame*/, 13491 /*Honor the Flame*/, 13492 /*Honor the Flame*/, 28922 /*Honor the Flame*/, 28925 /*Honor the Flame*/, 28926 /*Honor the Flame*/, 28928 /*Honor the Flame*/, 28929 /*Honor the Flame*/, 28932 /*Honor the Flame*/, 28950 /*Honor the Flame*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, $n.$B$B<Saurfang nods.>$B$BDid you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike!$B$BThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.', `VerifiedBuild`=19034 WHERE `ID`=11595; -- The Defense of Warsong Hold
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `VerifiedBuild`=19034 WHERE `ID` IN (11605 /*The Honored Ancestors*/, 11607 /*The Lost Spirits*/, 11612 /*Reclaiming the Quarry*/, 11617 /*Hampering Their Escape*/, 11866 /*Ears of Our Enemies*/, 11945 /*Preparing for the Worst*/, 11949 /*Not Without a Fight!*/, 11958 /*Let Nothing Go To Waste*/, 11960 /*Planning for the Future*/, 12006 /*Avenge this Atrocity!*/, 12009 /*Tua'kea's Crab Traps*/, 12016 /*The Bait*/, 12028 /*Spiritual Insight*/, 12038 /*Seared Scourge*/);
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub''ar sinkholes.$B$B<Holgoth hands you a bundle.>$B$BBe very careful with that package, $n. Mishandle it and you''ll be dog meat.$B$BInside the bundle are seaforium depth charges. Get to each of those Nerub''ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.$B$BGet a move on!', `VerifiedBuild`=19034 WHERE `ID`=11608; -- Bury Those Cockroaches!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `QuestDescription`='With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.$B$BThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, $n, for some are centuries old. You may need to wrest them from the hands of the invaders.', `VerifiedBuild`=19034 WHERE `ID`=11609; -- Picking Up the Pieces
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `VerifiedBuild`=19034 WHERE `ID` IN (11610 /*Leading the Ancestors Home*/, 12032 /*Conversing With the Depths*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `QuestDescription`='My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.$B$BYou''ve dealt with his men already.  Finish what you''ve started, $n.  Avenge my father and I will share with you what little I still have.', `VerifiedBuild`=19034 WHERE `ID`=11619; -- Gamel the Cruel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `QuestDescription`='The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I''ve never seen anything like this curator before.$B$BHe''s landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. $n, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.', `VerifiedBuild`=19034 WHERE `ID`=11623; -- A Visit to the Curator
UPDATE `quest_template` SET `RewardBonusMoney`=98700, `VerifiedBuild`=19034 WHERE `ID`=11626; -- The Emissary
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=33555378, `QuestDescription`='Here, $n, I''ve attuned the primal to you.$B$BOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.$B$BThe spirit of the wind touches all; with any luck you will be granted a vision.', `VerifiedBuild`=19034 WHERE `ID`=11631; -- Vision of Air
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='You''re a tough mother, $n. I think your talents are better suited elsewhere - like the root of the whole damn problem!$B$B<Razgor points to the west.>$B$BA thousand Scourge, at least four full sized floating death machines and who knows what else.$B$BBut you''re gonna find out and then you''re gonna handle it... That''s right, you''re gonna beat the hell out of the Scourge army that''s currently beating down our door.$B$BGet to the top of Warsong Hold and report to Wind Master To''bor. He''ll be expecting you.', `VerifiedBuild`=19034 WHERE `ID`=11634; -- Wind Master To'bor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `RewardChoiceItemID3`=37047, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemQuantity6`=0, `AllowableRaces`=33555378, `QuestDescription`='$n, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.$B$BI sense that the spirit talker is still at Bor''gorok Outpost to the west where last I saw her.', `VerifiedBuild`=19034 WHERE `ID`=11638; -- Return My Remains
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `QuestDescription`='Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.$B$BAn endless stream of Scourge minions will overrun us if we can''t find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, $n, to slay the high priests and take the scrolls they hold.', `VerifiedBuild`=19034 WHERE `ID`=11640; -- Words of Power
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `QuestDescription`='From the beginning, I''ve counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he''d rather tip-toe around according to Sage Aeire''s plans.$B$BI''ll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you''d be willing to show him that a direct attack can succeed. Storm the Temple City of En''kilah and slay all in your path, $n.', `VerifiedBuild`=19034 WHERE `ID`=11641; -- A Courageous Strike
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `QuestDescription`='The presence of plague cauldrons within the Temple City of En''kilah worries me greatly, $n. It''s clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?$B$BI''ve prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.', `VerifiedBuild`=19034 WHERE `ID`=11647; -- Neutralizing the Cauldrons
UPDATE `quest_template` SET `RewardBonusMoney`=98700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11652 /*The Plains of Nasam*/, 11705 /*Foolish Endeavors*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=49800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=11654; -- The Spire of Blood
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `VerifiedBuild`=19034 WHERE `ID` IN (11657 /*Torch Catching*/, 11924 /*More Torch Catching*/, 12958 /*Shipment: Blood Jade Amulet */, 12959 /*Shipment: Glowing Ivory Figurine*/, 12960 /*Shipment: Wicked Sun Brooch*/, 12961 /*Shipment: Intricate Bone Figurine*/, 12962 /*Shipment: Bright Armor Relic*/, 12963 /*Shipment: Shifting Sun Curio */, 26451 /*Gurubashi Challenge: Free-For-All Arena Combat*/, 26452 /*Gurubashi Challenge*/, 28910 /*Desecrate this Fire!*/, 28911 /*Desecrate this Fire!*/, 28913 /*Desecrate this Fire!*/, 28914 /*Desecrate this Fire!*/, 28916 /*Desecrate this Fire!*/, 28917 /*Desecrate this Fire!*/, 28918 /*Desecrate this Fire!*/, 28920 /*Desecrate this Fire!*/, 28943 /*Desecrate this Fire!*/, 28944 /*Desecrate this Fire!*/, 28947 /*Desecrate this Fire!*/, 28948 /*Desecrate this Fire!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=65700, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11661; -- Orabus the Helmsman
UPDATE `quest_template` SET `RewardBonusMoney`=82200, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11664; -- Escaping the Mist
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='You''ve come to enlist, right?  Normally you''d have to stand in line like the other recruits.  Normally you''d be out of luck because the recruitment ledger''s gone missing and I can''t process anyone until the new books get here.$B$BFortunately for you, $n, I''ve heard about you and what you did in Outland.  To be honest, you''re a cut above these poor saps.  Lines aren''t for you.$B$BGo to the barracks and speak to General Arlos.  He''ll be more than happy to meet with someone of your caliber.', `VerifiedBuild`=19034 WHERE `ID`=11672; -- Enlistment Day
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `RewardChoiceItemID3`=37047, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `RewardChoiceItemQuantity6`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=11673; -- Get Me Outa Here!
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=33555378, `QuestDescription`='Bristlehorn should have returned by now.$B$BThe other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He''s impetuous and has likely gotten himself into trouble.$B$B$n, go to that place and find him, please.', `VerifiedBuild`=19034 WHERE `ID`=11678; -- Find Bristlehorn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=33000, `VerifiedBuild`=19034 WHERE `ID` IN (11682 /*Dragonspeak*/, 11967 /*Mustering the Reds*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=33555378, `QuestDescription`='The greatmother will need to know, $n.$B$BWill you please return to Taunka''le? Tell her that I will be following shortly.', `VerifiedBuild`=19034 WHERE `ID`=11689; -- Return with the Bad News
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `TimeAllowed`=600, `AllowableRaces`=-1, `QuestDescription`='Take this riding snaffle, $n. You''ll notice that I''ve placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you''ve cured the sick out of ''em, you''ll need to ride ''em home. They''ll be weak so you''ll need to gently direct ''em here.$B$BBring my babies back, $n!$B$BOne last thing, you''ve got ten minutes! That''s how long the antidote will remain effective inside that snaffle.', `VerifiedBuild`=19034 WHERE `ID`=11690; -- Bring 'Em Back Alive
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=64800, `QuestDescription`='I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  $n, you will be the fist of the Earthmother.$B$BTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.$B$BIf fortune is with us, then, perhaps, we can defeat him.$B$BPrepare yourself, $n.  If Ahune comes to face us, then his fury will be great.', `VerifiedBuild`=19034 WHERE `ID`=11691; -- Summon Ahune
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west.$B$BI''m 100% certain that those cultists came from inside that thing, which means I''m now 100% certain that Tinky''s in trouble!$B$BShe''s the airstrip''s number one engineer. Without her we''re doomed!$B$BI''d find her myself, but one of those things got in a swipe on my leg before I could vanish again. $n, if anyone can get her out, it''s you!', `VerifiedBuild`=19034 WHERE `ID`=11697; -- Rats, Tinky Went into the Necropolis!
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=11699; -- I'm Stuck in this Damned Cage... But Not For Long!
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='My evil twin''s out there somewhere now.$B$BI''m pretty sure that she''s not back at the airstrip. In fact, wherever she ended up, it''s colder there than here. But I could only ''feel'' her for a moment.$B$BOh well, I''ll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I''ll meet her back there?$B$BThanks, $n!', `VerifiedBuild`=19034 WHERE `ID`=11700; -- Let Bixie Know
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=18875469, `QuestDescription`='Okay, I think I''m going to start making my way back to the airstrip, too. Of course, I''m moving a little slower with this leg injury.$B$BSay, do you think you could get there ahead of me and pass on the good news to Ol'' Fizzcrank? I bet anything that there''ll be a reward in it for you.$B$BThanks, $n!', `VerifiedBuild`=19034 WHERE `ID`=11701; -- Back to the Airstrip
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='Oh good, you''re $n, right?$B$BWe need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station!$B$BIt''s madness I tell you, madness!$B$BYou''ve got to head up there and talk to old man Fullthrottle a.s.a.p.!', `VerifiedBuild`=19034 WHERE `ID`=11707; -- Distress Call
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange.$B$BYou are dismissed, $n. ', `VerifiedBuild`=19034 WHERE `ID`=11709; -- Nork Bloodfrenzy's Charge
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `QuestDescription`='If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the "Curse of the Flesh", and now they''re robots!$B$BWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.$B$BWe''re hoping that this stuff will cure them and allow us to lock onto them to port ''em out of there.$B$BWhaddya say, $n?', `VerifiedBuild`=19034 WHERE `ID`=11712; -- Re-Cursive
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=65700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=11713; -- Scouting the Sinkholes
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='Perhaps you''d be interested in helping me clean up these fields? They''re littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call ''em, they''re all over the damned place. The stink alone is making my life hell!$B$BTake care of the vermin for me and I''ll make it worth your while, $n.
', `VerifiedBuild`=19034 WHERE `ID`=11714; -- Vermin Extermination
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='It''s obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth''s internal system that acts as a catalyst for this pollen to work. It''s all starting to make sense now, $n. That''s why the kobolds don''t kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!$B$BWell we''ll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?', `VerifiedBuild`=19034 WHERE `ID`=11717; -- Pollen from the Source
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='<Laurith looks you over as if to size you up.>$B$BSo we''ve got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What''s the worst that could happen anyway?$B$BDon''t you worry, $n! Just take this sample and rub it all over your face. ', `VerifiedBuild`=19034 WHERE `ID`=11719; -- A Suitable Test Subject
UPDATE `quest_template` SET `RewardBonusMoney`=49200, `AllowableRaces`=-1, `QuestDescription`='We cannot take all of the credit for this Horde victory, $n. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.$B$BHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.', `VerifiedBuild`=19034 WHERE `ID`=11722; -- Trophies of Gammoth
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='I should''ve flown the mission myself. It''s not that I don''t trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.$B$BNo, it''s just that it''s my responsibility to lead a mission of such import.$B$BI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.$B$BThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.$B$BFind Tailspin, $n.', `VerifiedBuild`=19034 WHERE `ID`=11725; -- Finding Pilot Tailspin
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='It''s good to have you among us, $n.  We''ve all heard of your past deeds.$B$BAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.$B$BI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.$B$BReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.', `VerifiedBuild`=19034 WHERE `ID`=11727; -- A Time for Heroes
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `TimeAllowed`=40, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11731; -- Torch Tossing
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11748 /*Desecrate this Fire!*/, 11785 /*Desecrate this Fire!*/, 12135 /*""Let the Fires Come!""*/, 12139 /*""Let the Fires Come!""*/, 13405 /*Call to Arms: Strand of the Ancients*/, 26414 /*Hitting a Walleye*/, 26420 /*Diggin' For Worms*/, 26442 /*Rock Lobster*/, 26488 /*Big Gulp*/, 26557 /*A Staggering Effort*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=18875469, `QuestDescription`='Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called ''Curse of the Flesh'', but what he''s really making are robotic slaves!$B$B$n, we''re pretty certain that he''s still at the pumping station out in the middle of the pools to the east.$B$BThe last we saw of him, he was in the command hut up top. Go up there and research his stuff.$B$BYou must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!', `VerifiedBuild`=19034 WHERE `ID`=11798; -- The Gearmaster
UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (11819 /*Honor the Flame*/, 13487 /*Honor the Flame*/, 13488 /*Honor the Flame*/, 28761 /*Honor the Flame*/, 28945 /*Honor the Flame*/);
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `VerifiedBuild`=19034 WHERE `ID` IN (11865 /*Unfit for Death*/, 11869 /*Happy as a Clam*/, 11871 /*Not On Our Watch*/, 11872 /*The Nefarious Clam Master...*/);
UPDATE `quest_template` SET `QuestDescription`='Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.
', `VerifiedBuild`=19034 WHERE `ID`=11867; -- Can't Get Ear-nough...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `QuestDescription`='Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!$B$BFind this murderer, Karen, and end her worthless existence.$B$BPrepare yourself properly, $n. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her!', `VerifiedBuild`=19034 WHERE `ID`=11868; -- The Culler Cometh
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `QuestDescription`='They''re majestic beasts, aren''t they?$B$B<Lathorius points towards the mammoths of the northern tundra.>$B$BWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.$B$B<Lathorius'' face contorts with anger.>$B$BIt''s the whimpers that drive me to madness, $n. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters'' vile traps, call out to us.$B$BTake this hammer and smash those traps. Free the calves!', `VerifiedBuild`=19034 WHERE `ID`=11876; -- Help Those That Cannot Help Themselves
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48600, `QuestDescription`='As we press the offensive on Quel''Danas, we''ve discovered that Kael''thas'' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.$B$BWe must not allow this to happen, $n. Each and every blade is needed on the front lines.$B$BGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=11877; -- Sunfury Attack Plans
UPDATE `quest_template` SET `RewardBonusMoney`=49800, `VerifiedBuild`=19034 WHERE `ID`=11878; -- Khu'nok Will Know
UPDATE `quest_template` SET `RewardBonusMoney`=83100, `VerifiedBuild`=19034 WHERE `ID` IN (11879 /*Kaw the Mammoth Destroyer*/, 11884 /*Nedar, Lord of Rhinos...*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=48600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11880; -- The Multiphase Survey
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `VerifiedBuild`=19034 WHERE `ID` IN (11886 /*Unusual Activity*/, 11891 /*An Innocent Disguise*/, 13833 /*Blood Is Thicker*/, 13836 /*Disarmed!*/, 13929 /*The Biggest Tree Ever!*/, 13930 /*Home Of The Bear-Men*/, 13933 /*The Bronze Dragonshrine*/, 13934 /*The Bronze Dragonshrine*/, 13937 /*A Trip To The Wonderworks*/, 13950 /*Playmates!*/, 13951 /*Playmates!*/, 13954 /*The Dragon Queen*/, 14151 /*Cardinal Ruby*/, 29506 /*A Fizzy Fusion*/, 29508 /*Baby Needs Two Pair of Shoes*/, 29509 /*Putting the Crunch in the Frog*/, 29511 /*Talkin' Tonks*/, 29513 /*Spoilin' for Salty Sea Dogs*/, 29515 /*Writing the Future*/, 29516 /*Keeping the Faire Sparkling*/, 29517 /*Eyes on the Prizes*/, 29518 /*Rearm, Reuse, Recycle*/, 29519 /*Tan My Hide*/, 29520 /*Banners, Banners Everywhere!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=99900, `QuestDescription`='You have done much for the animals of the Borean Tundra, $n. Nesingwary''s lackeys have been beaten back and taught a lesson that they will not soon forget.$B$BHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum''uya, west of here.$B$B<Lathorius hands you an intricately carved oak horn.>$B$BFind Lane and kill him. Use this horn should you require our aid.
', `VerifiedBuild`=19034 WHERE `ID`=11892; -- The Assassination of Harold Lane
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='The Scourge are showing no sign of letting up, $n.  It''s those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.$B$BIf there''s something years of mining has taught me it''s that without support beams, tunnels will cave in easily after an explosion.$B$BTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you''ve collapsed them.', `VerifiedBuild`=19034 WHERE `ID`=11897; -- Plug the Sinkholes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=33555378, `QuestDescription`='On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.$B$BBe cautious, $n. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.$B$BYou must find your way through the necropolis to the prince''s seat. If you fail to defeat him, $n, I fear my people will never know the safety Icemist offers.', `VerifiedBuild`=19034 WHERE `ID`=11898; -- Breaking Through
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='Well, $n.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.$B$BWe have deployed militia in what remains of Farshire.  Without your help, they''ve but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can''t let the Scourge break through!', `VerifiedBuild`=19034 WHERE `ID`=11903; -- It's Time for Action
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='The Scourge just keeps coming... but we can''t give up!  Listen, $n.  Inside that mine there''s a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.$B$BThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.$B$BThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.', `VerifiedBuild`=19034 WHERE `ID`=11904; -- Fruits of Our Labor
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=47000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=65700, `VerifiedBuild`=19034 WHERE `ID` IN (11905 /*Postponing the Inevitable*/, 11911 /*Quickening*/, 11973 /*Prisoner of War*/, 29803 /*Ears of the Lich King*/, 30112 /*A Score to Settle*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=82200, `AllowableRaces`=33555378, `QuestDescription`='It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.$B$BWe must put an end to them!$B$BOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.$B$BThe stations are centered on the spinning lights in the pools surrounding the pumping station.$B$BHurry, $n!', `VerifiedBuild`=19034 WHERE `ID`=11907; -- The Sub-Chieftains
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=49200, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=11908; -- Reference Material
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=33555378, `QuestDescription`='Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!$B$BThe winds that guide me whisper that he''s atop the pumping station out in the middle of the pools to the west.$B$BMost likely, he''ll be found in the command hut on top of the structure. Go inside and research his works.$B$B$n, you must confront Mechazod if we are to survive!', `VerifiedBuild`=19034 WHERE `ID`=11909; -- Defeat the Gearmaster
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (11915 /*Playing with Fire*/, 11971 /*The Spinner of Summer Tales*/, 14036 /*Pilgrim's Bounty*/, 29431 /*A Friend in Need*/);
UPDATE `quest_template` SET `RewardBonusMoney`=98700, `AllowableRaces`=-1, `QuestDescription`='You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, $n, that the Horde is now firmly entrenched in Northrend.$B$BBut our work has only just begun. We must march to Icecrown and we must tear down its walls!$B$BYour next assignment begins to the east, at Taunka''le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka''le.', `VerifiedBuild`=19034 WHERE `ID`=11916; -- Hellscream's Champion
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `TimeAllowed`=90, `VerifiedBuild`=19034 WHERE `ID`=11921; -- More Torch Tossing
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `TimeAllowed`=40, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=11922; -- Torch Tossing
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `TimeAllowed`=90, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=11926; -- More Torch Tossing
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='Hey, $n.  There''s a girl in the inn that''s asking about you.  Her name''s Leryssa.$B$BI don''t think she knows you, but she said she needed your help.  She sounded really desperate.', `VerifiedBuild`=19034 WHERE `ID`=11927; -- Word on the Street
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='My lads should be able to take it from here, $n.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however.$B$BWe sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians.$B$BGerald Green''s in charge of the villagers there. There''s a passage out of the northern wall out of Valiance Keep; it''ll take you straight to him.  See what you can do to help them.', `VerifiedBuild`=19034 WHERE `ID`=11928; -- Farshire
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='We are lost, $n. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be.$B$BI have called for the evacuation of Taunka''le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight.$B$B<Wintergale points east.>$B$BYou must help get my people to safety, $n. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!', `VerifiedBuild`=19034 WHERE `ID`=11929; -- The Fall of Taunka'le Village
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (11930 /*Across Transborea*/, 11938 /*Buying Some Time*/, 11944 /*Surrounded!*/, 11978 /*Into the Fold*/, 11980 /*Pride of the Horde*/, 12039 /*Black Blood of Yogg-Saron*/, 12048 /*Scourge Armaments*/, 12053 /*The Might of the Horde*/, 12057 /*The Flesh-Bound Tome*/, 12064 /*Chains of the Anub'ar*/, 12072 /*Blightbeasts be Damned!*/, 12100 /*Containing the Rot*/, 12188 /*The Forsaken Blight and You: How Not to Die*/, 12200 /*Emerald Dragon Tears*/, 12218 /*Spread the Good Word*/, 12237 /*Flight of the Wintergarde Defender*/, 12269 /*Not In Our Mine*/, 12272 /*The Bleeding Ore*/, 12276 /*The Search for Slinkin*/, 12290 /*The Murkweed Elixir*/);
UPDATE `quest_template` SET `RewardBonusMoney`=33000, `AllowableRaces`=-1, `QuestDescription`='Listen, $n.  No offense, but the operation they put Thassarian in charge of was pure suicide.$B$BA handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain''t my idea of fun.$B$BIf you''re still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool''s errand.', `VerifiedBuild`=19034 WHERE `ID`=11932; -- Cowards and Fools
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='The lich has spoken, $n.  The high priests of En''kilah hold the secret to entering Naxxanar.$B$BGo to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests.$B$BReturn once you''ve obtained the three scrolls.', `VerifiedBuild`=19034 WHERE `ID`=11942; -- Words of Power
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6600, `LogDescription`='Keristrasza wants you to speak to her when you are ready to prepare for a confrontation with Malygos.$b$bIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.', `VerifiedBuild`=19034 WHERE `ID`=11946; -- Keristrasza
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `QuestDescription`='Listen, $n.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight.$B$BMy people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters.$B$BYou are an outsider, maybe he''ll listen to you.  Show him reason... ask him to flee to the safety of Unu''pe before it''s too late.', `VerifiedBuild`=19034 WHERE `ID`=11950; -- Muahit's Wisdom
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=56700, `VerifiedBuild`=19034 WHERE `ID`=11953; -- Striking Back
UPDATE `quest_template` SET `QuestType`=2, `RewardMoney`=20, `RewardMoneyDifficulty`=2, `RewardBonusMoney`=9300, `VerifiedBuild`=19034 WHERE `ID`=11954; -- Striking Back
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='No time for small talk, $n.  I was sent on what was to be a suicide mission to take this ziggurat.  I''ve accomplished my duty as a soldier, now is the time to get some answers.$B$BThis lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge.$B$BThe lich stored his soul in a phylactery, and while it remains hidden, I won''t be able to pry the information from him.$B$BReturn to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.', `VerifiedBuild`=19034 WHERE `ID`=11956; -- Finding the Phylactery
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=84300, `VerifiedBuild`=19034 WHERE `ID`=11959; -- Slay Loguhn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=49800, `QuestDescription`='Powerful spirits watch over my tribe -- Kaskala will not be lost.$B$BIssliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way.$B$BIssliruk''s guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk''s totem, but the Kvaldir''s spears struck him down and his body fell into the waters to the north.  Bring me the totem, $n.  Don''t let my nephew''s death be in vain.', `VerifiedBuild`=19034 WHERE `ID`=11961; -- Spirits Watch Over Us
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.$b$bWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.$B$BWould you like to honor a scorchling, $n?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.', `VerifiedBuild`=19034 WHERE `ID`=11964; -- Incense for the Summer Scorchlings
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='Farshire has a fighting chance now, $n.  That''s all we could''ve asked for and you''ve made it possible.$B$BAll we need now is a rallying point.  I''ll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there.$B$BIt''s time to show the Scourge what we''re made of.', `VerifiedBuild`=19034 WHERE `ID`=11965; -- Call to Arms!
UPDATE `quest_template` SET `RewardBonusMoney`=960, `AllowableRaces`=33555378, `QuestDescription`='Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.$b$bWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.$B$BWould you like to honor a scorchling, $n?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.', `VerifiedBuild`=19034 WHERE `ID`=11966; -- Incense for the Festival Scorchlings
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `QuestDescription`='The spirits have heard our cry for help, $n.  It''s a sign that Kaskala might yet be saved.$B$BTake advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.', `VerifiedBuild`=19034 WHERE `ID`=11968; -- The Tides Turn
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID`=11972; -- Shards of Ahune
