UPDATE `quest_template` SET `RewardBonusMoney`=49800, `AllowableRaces`=-1, `QuestDescription`='They are ready, $n. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world.$B$B<Brighthoof hands you a scroll bearing the insignia of the Horde.>$B$BWithin this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein.$B$BTake the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.', `VerifiedBuild`=19034 WHERE `ID`=11983; -- Blood Oath of the Horde
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `VerifiedBuild`=19034 WHERE `ID` IN (11984 /*Filling the Cages*/, 11991 /*Subject to Interpretation*/, 12007 /*Sacrifices Must be Made*/, 12029 /*Seared Scourge*/, 12043 /*Nozzlerust Defense*/, 12044 /*Stocking Up*/, 12045 /*Shaved Ice*/, 12046 /*Soft Packaging*/, 12047 /*Something That Doesn't Melt*/, 12049 /*Hard to Swallow*/, 12050 /*Lumber Hack*/, 12075 /*Slim Pickings*/, 12076 /*Messy Business*/, 12077 /*Apply This Twice A Day*/, 12078 /*Worm Wrangler*/, 12079 /*Stomping Grounds*/, 12190 /*Say Hello to My Little Friend*/, 12261 /*No Place to Run*/, 12262 /*No One to Save You*/, 12264 /*Culling the Damned*/, 12265 /*Defiling the Defilers*/, 12454 /*Cycle of Life*/, 12458 /*Seeds of the Lashers*/, 12545 /*The Cleansing Of Jintha'kalar*/);
