UPDATE `quest_template` SET `RewardBonusMoney`=49800, `AllowableRaces`=-1, `QuestDescription`='Directly east of this refugee camp stands Agmar''s Hammer - testament to the Hordes'' power in the Dragonblight.$B$BWhile I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person.$B$BGo now, $n! Race the winds! East to Agmar''s Hammer!
', `VerifiedBuild`=19034 WHERE `ID`=12008; -- Agmar's Hammer
UPDATE `quest_template` SET `RewardBonusMoney`=51900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=12010; -- The Fate of Orlond
UPDATE `quest_template` SET `RewardBonusMoney`=4650, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12012 /*Inform the Elder*/, 14037 /*Spice Bread Stuffing*/, 14040 /*Pumpkin Pie*/, 14041 /*Cranberry Chutney*/, 14065 /*Sharing a Bountiful Feast*/, 29376 /*A Time to Build Up*/, 29377 /*A Time to Break Down*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=84300, `QuestDescription`='There is one last thing that I would have you do, $n the $r. I would have you destroy Arcanimus!$B$BThe sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity!$B$BI would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead.$B$BYou will put an end to it now!', `VerifiedBuild`=19034 WHERE `ID`=12013; -- End Arcanimus
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=86400, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=12014; -- Steady as a Rock?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=84300, `QuestDescription`='The time has come my friend: Tu''u''gwar must be dealt with!$B$BI''ve prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it.$B$BWhatever you do, don''t let Tu''u''gwar swallow you whole, $n!', `VerifiedBuild`=19034 WHERE `ID`=12017; -- Meat on the Hook
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=99900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12019; -- Last Rites
UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `RewardBonusMoney`=4650, `AllowableRaces`=18875469, `LogDescription`='Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.', `QuestDescription`='Hey there!  You look like you can handle your brew.  But can you handle your brew mug? $b$bThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let''s see if you can toss one at old S.T.O.U.T. here.$b$bIt''s easy, pick up an alcohol-free sampler and take a drink.  Just make sure you''re facing S.T.O.U.T.  Talk to me after you''ve hit him 5 times.', `VerifiedBuild`=19034 WHERE `ID`=12022; -- Chug and Chuck!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12026 /*The Damaged Journal*/, 12054 /*Deciphering the Journal*/, 12058 /*The Runic Prophecies*/, 12073 /*Pounding the Iron*/, 12165 /*An Intriguing Plan*/, 12195 /*The Unexpected 'Guest'*/, 12197 /*We Have the Power*/, 12198 /*... Or Maybe We Don't*/, 12201 /*The Overseer's Shadow*/, 12202 /*Cultivating an Image*/, 12203 /*Loken's Orders*/, 12415 /*The Horse Hollerer*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (12027 /*Mr. Floppy's Perilous Adventure*/, 12217 /*Eagle Eyes*/, 12222 /*Secrets of the Flamebinders*/, 12223 /*Thinning the Ranks*/, 12416 /*Heated Battle*/, 12417 /*Return to the Earth*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `QuestDescription`='My people....$B$B<The mystic is on the verge of breaking down.>$B$BWhile your spirit was flying through the village, I sensed that Elder Mana''loa took notice of you. $n, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom.$B$BThe elder must want to help. Seek him in the northwest corner of the village.', `VerifiedBuild`=19034 WHERE `ID`=12030; -- Elder Mana'loa
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `QuestDescription`='The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows.$B$BThe souls of the Kalu''ak are in danger as the blue dragons forces attempt to control the magic.$B$BThe power came up through the lake, instantly slaying most in the village. Those that survived were driven insane.$B$B$n, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.', `VerifiedBuild`=19034 WHERE `ID`=12031; -- Freedom for the Lingering
UPDATE `quest_template` SET `RewardBonusMoney`=49800, `AllowableRaces`=-1, `QuestDescription`='<Torvus shakes your hand, giving you a letter in the process.>$B$B<Torvus speaks under his breath.>$B$BJust play along, $n.$B$BIt is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar!$B$B<Torvus speaks under his breath.>$B$BRead it and then destroy it in the fire pot next to me.', `VerifiedBuild`=19034 WHERE `ID`=12033; -- Message from the West
UPDATE `quest_template` SET `RewardBonusMoney`=65700, `AllowableRaces`=-1, `QuestDescription`='Ok, I''ve got it!  The rewiring is a little complicated, but nothing a clever $c like you can''t handle.$B$BTake my tools and put some of the harvest collectors out of commission.  Once they''re down use the tools to plug all the red wires into the blue sockets.  That''ll make them go into self-defense mode.  Hurry, $n.  Before long there won''t be anything left to save.', `VerifiedBuild`=19034 WHERE `ID`=12035; -- Repurposed Technology
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory.$B$BI need eyes on the ground, $n. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location.
', `VerifiedBuild`=19034 WHERE `ID`=12036; -- From the Depths of Azjol-Nerub
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=136200, `VerifiedBuild`=19034 WHERE `ID` IN (12037 /*Search and Rescue*/, 13167 /*Death to the Traitor King*/, 13182 /*Don't Forget the Eggs!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=12040; -- An Enemy in Arthas
UPDATE `quest_template` SET `RewardBonusMoney`=49800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12041 /*The Lost Empire*/, 12063 /*Strength of Icemist*/);
UPDATE `quest_template` SET `RewardBonusMoney`=33300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=12055; -- A Strange Device
UPDATE `quest_template` SET `RewardBonusMoney`=33300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=12059; -- A Strange Device
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `QuestDescription`='This is a teleportation device. If I had to guess, I''d say that it leads to the surge needle platform floating above the Moonrest Gardens to the southwest.$B$B$n, I need you to use it to investigate what''s up there. It appears that the device works both ways so you shouldn''t have to jump off.$B$BI expect that once you teleport up to the top of the surge needle, there will be some sort of apparatus on it to observe.$B$BYou should be able to use the teleporter from anywhere within the gardens.', `VerifiedBuild`=19034 WHERE `ID`=12061; -- Projections and Plans
UPDATE `quest_template` SET `RewardBonusMoney`=101100, `AllowableRaces`=-1, `QuestDescription`='<Banthok hands you the prison key.>$B$BYou must hurry, $n. Take the key and use it to unchain my father from the Anub''ar prison. Once he is freed, assist him in destroying the Anub''ar leader, Under-king Anub''et''kan. When the Under-king is defeated, take from his chitinous carapace a fragment as a trophy to present to the Horde at Agmar''s Hammer. Let Agmar see the might of the High Chief!', `VerifiedBuild`=19034 WHERE `ID`=12069; -- Return of the High Chief
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=102300, `VerifiedBuild`=19034 WHERE `ID` IN (12080 /*Really Big Worm*/, 12151 /*Wanton Warlord*/, 12459 /*That Which Creates Can Also Destroy*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=18875469, `QuestDescription`='I''m convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don''t know precisely what they''re doing with all of that power, though.$B$BMy guess is that you''ll find another one atop the Lothalor Woodlands to the southeast. Once again you''ll need to find the person in charge and take whatever controlling device they have in their possession as I''m sure that each focus has its own.$B$BBe careful, $n, those woods are very dangerous.', `VerifiedBuild`=19034 WHERE `ID`=12083; -- Atop the Woodlands
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='The man you seek went far to the east, to a place near the coast called Death''s Stand, beyond Unu''pe.$B$BBe careful if you go in search of him, $n.  He bore the mark of Karkut... he who watches over the dead.', `VerifiedBuild`=19034 WHERE `ID`=12086; -- The Son of Karkut
UPDATE `quest_template` SET `RewardBonusMoney`=16500, `AllowableRaces`=-1, `QuestDescription`='Well, $n, you helped us out... so I figure it''s only fair that we help you out as well.$B$BYou''re looking for Thassarian?  He disappeared this morning.  We think he went off north to the Wailing Ziggurat.  If we hadn''t fought side by side by him we''d even think he was a traitor.$B$BSee, he''s a Death Knight... and I know they''re on our side and all... but it wasn''t too long ago they were servants of Arthas.$B$BBut not Thassarian, he''s a good guy.  Go to the Wailing Ziggurat, see if he''s doing okay.', `VerifiedBuild`=19034 WHERE `ID`=12088; -- Thassarian, the Death Knight
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=85200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12089 /*Wanted: Magister Keldonus*/, 12090 /*Wanted: Gigantaur*/, 12091 /*Wanted: Dreadtalon*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=103500, `AllowableRaces`=-1, `QuestDescription`='Me hunters be dead or frozen, $n. You still want to do dis? Just say da word and me call for da dragon once more.$B$BIf ya kill it, take da beast''s frozen heart back to Agmar''s Hammer and present it to Gort. He sure to reward you good, mon.', `VerifiedBuild`=19034 WHERE `ID`=12097; -- Sarathstra, Scourge of the North
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=86400, `VerifiedBuild`=19034 WHERE `ID` IN (12099 /*Free at Last*/, 12116 /*It Takes Guts....*/, 12267 /*Neltharion's Flame*/, 12470 /*Mystery of the Infinite*/, 12857 /*Wanted: Ragemane's Flipper*/);
