UPDATE `quest_template` SET `RewardBonusMoney`=84300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12126 /*In Service of the Unholy*/, 12326 /*Steamtank Surprise*/, 12457 /*The Chain Gun And You*/, 12467 /*Chasing Icestorm: Thel'zan's Phylactery*/, 12478 /*Frostmourne Cavern*/);
UPDATE `quest_template` SET `RewardBonusMoney`=67500, `AllowableRaces`=-1, `QuestDescription`='The biting cold protects the death knight while repelling his enemies. He that commands the power of frost can incite chaos and destruction!$B$BTake this frost gem and travel far across the open tundra of the Dragonblight until you come upon the Mirror of Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice revenants that dwell upon the lakes surface and take from them the essence of frost. Utilize the power of the gem when they are weak, $n!', `VerifiedBuild`=19034 WHERE `ID`=12127; -- In Service of Frost
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=101100, `AllowableRaces`=-1, `QuestDescription`='Here it is, $n. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent.$B$BTheir network of spies and operatives is impressive, to say the least.$B$BFarewell, friend. May the book serve you and your people well.', `VerifiedBuild`=19034 WHERE `ID`=12136; -- The Translated Tome
UPDATE `quest_template` SET `RewardBonusMoney`=86400, `VerifiedBuild`=19034 WHERE `ID`=12137; -- Chill Out, Mon
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='I see that you are very eager to help, $n.  You didn''t come all the way to Northrend to stay holed up in a city!  I''ve just the task for you... something that''ll take you far away from here.$B$BWe''ve long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn''t offer at the time.$B$BNow that you''re around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.  ', `VerifiedBuild`=19034 WHERE `ID`=12141; -- A Diplomatic Mission
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=67500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (12142 /*Pest Control*/, 12143 /*Canyon Chase*/, 12146 /*Disturbing Implications*/, 12172 /*Attunement to Dalaran*/);
