UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=67500, `VerifiedBuild`=19034 WHERE `ID` IN (12148 /*One of a Kind*/, 12149 /*Mighty Magnataur*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=86400, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (12153 /*The Iron Thane and His Anvil*/, 12418 /*Through Fields of Flame*/);
UPDATE `quest_template` SET `RewardBonusMoney`=16500, `AllowableRaces`=-1, `QuestDescription`='We''re lucky we made it this far, $n.  We were ambushed by Scourge as soon as we landed.$B$BOne of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top.$B$BI''ve sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name.
', `VerifiedBuild`=19034 WHERE `ID`=12157; -- The Lost Courier
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12159; -- Souls at Unrest
UPDATE `quest_template` SET `RewardBonusMoney`=17400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12160 /*A Name from the Past*/, 12161 /*Ruuna the Blind*/, 12425 /*Ruuna the Blind*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=103500, `QuestDescription`='It is time, then, $n.  Arugal must be defeated.$B$BGet a couple of people you can trust and head for Bloodmoon Isle.  It''s just off the coast, east of here.$B$BWe''ll hit them fast.  Take out Arugal''s lieutenants -- I''ll catch up with you when it''s time to take out the monster himself.', `VerifiedBuild`=19034 WHERE `ID`=12164; -- Hour of the Worg
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=83100, `AllowableRaces`=18875469, `QuestDescription`='I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north.$B$BYou know your target, $n. If there''s to be an end to the suffering of the land, the high cultist must die!', `VerifiedBuild`=19034 WHERE `ID`=12169; -- The High Cultist
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12170 /*Blackriver Brawl*/, 12324 /*Smoke 'Em Out*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight.$B$BIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.$B$BHurry, $n. Show the document to Palena Silvercloud here at Stars'' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!', `VerifiedBuild`=19034 WHERE `ID`=12171; -- Of Traitors and Treason
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='<Palena hands the missive back to you.>$B$BSnowstorm will take you to Wintergarde, $n. I guarantee you that it will be the fastest flight you''ve ever taken. Go now!
', `VerifiedBuild`=19034 WHERE `ID`=12174; -- High Commander Halford Wyrmbane
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12175 /*Gray Worg Hides*/, 12212 /*Replenishing the Storehouse*/, 12216 /*Take Their Rear!*/, 12244 /*Shredder Repair*/, 12255 /*The Thane of Voldrune*/, 12259 /*The Thane of Voldrune*/, 12268 /*Pieces Parts*/, 12270 /*Shred the Alliance*/, 12280 /*Making Repairs*/, 12284 /*Keep 'Em on Their Heels*/, 12288 /*Overwhelmed!*/, 12289 /*Kick 'Em While They're Down*/, 12296 /*Life or Death*/, 12310 /*A Swift Response*/);
UPDATE `quest_template` SET `RewardBonusMoney`=68100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12176 /*A Minor Substitution*/, 12213 /*The Darkness Beneath*/, 12219 /*The Failed World Tree*/, 12220 /*A Dark Influence*/, 12242 /*Vordrassil's Seeds*/, 12292 /*Local Support*/, 12308 /*Escape from Silverbrook*/, 12413 /*Attack on Silverbrook*/, 12436 /*Supplemental Income*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69000, `AllowableRaces`=18875469, `QuestDescription`='Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar''s team never expected Dun Argol to be this heavily populated.$B$BThey''re being held captive while the iron dwarves prepare for war. We haven''t the men to charge in after them, and Raegar''s too busy fantasizing about defeating the irons to be of much help.$B$BIt falls to you, $n. Any of the irons or their servants could be carrying the keys to the cages holding our men.', `VerifiedBuild`=19034 WHERE `ID`=12180; -- The Captive Prospectors
UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `AllowableRaces`=33555378, `LogDescription`='Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Bizzle Quicklift.', `QuestDescription`='Those pesky Dark Irons are back! We need to make sure that you can defend yourself if needed. More importantly, we need to know that you can defend our property!$b$bS.T.O.U.T. here is ready for action, are you? Drink from the Alcohol-Free Brewfest Samplers then throw the mug at S.T.O.U.T.! Hit the target 5 times then talk to me.', `VerifiedBuild`=19034 WHERE `ID`=12191; -- Chug and Chuck!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69000, `AllowableRaces`=33555378, `QuestDescription`='We don''t have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts.$B$BI think you should go back there and pick up enough of them for me to make a golem from this blueprint.$B$BThey''re probably scattered around any of the buildings where the iron rune-smiths are working.$B$BPlease hurry, $n. That Tormak looks like he''s just waiting for an excuse to carry out his threat!', `VerifiedBuild`=19034 WHERE `ID`=12196; -- From the Ground Up
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=86400, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12199 /*Bringing Down the Iron Thane*/, 12450 /*Through Fields of Flame*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=51900, `AllowableRaces`=33555378, `LogDescription`='Speak with Hugh Glass and Gavrock about Loken, then report your findings to Scout Vor''takh at Camp Oneqwah.', `VerifiedBuild`=19034 WHERE `ID`=12204; -- In the Name of Loken
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12206 /*Blighted Last Rites*/, 29688 /*Advancing the Campaign*/);
UPDATE `quest_template` SET `RewardBonusMoney`=68100, `AllowableRaces`=-1, `QuestDescription`='Long ago, powerful druids planted a tree to the northeast of here.$B$BIt was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed.$B$BEver since we arrived here, the earth has spoken to me, $n.  Its cries of pain come from the places where Vordrassil''s remains fell on the ground.$B$BCorrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.', `VerifiedBuild`=19034 WHERE `ID`=12207; -- Vordrassil's Fall
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=17100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12208; -- Good Troll Hunting
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=50400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12210; -- Troll Season!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66600, `AllowableRaces`=33555378, `QuestDescription`='I don''t understand it. The blight should have worked!$B$BNo sense worrying about it now.$B$B<The apothecary seems relieved for some reason.>$B$BThough it doesn''t work on the Onslaught for some strange reason, we still need to keep their priests from raising them.$B$BI have another idea, one that their corpses shouldn''t have any protection from.$B$B$n, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!', `VerifiedBuild`=19034 WHERE `ID`=12211; -- Let Them Not Rise!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=51000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12215 /*Them or Us!*/, 12453 /*Eyes Above*/);
UPDATE `quest_template` SET `RewardBonusMoney`=49800, `RewardChoiceItemID4`=38176, `RewardChoiceItemID5`=38134, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12221; -- The Forsaken Blight
UPDATE `quest_template` SET `RewardBonusMoney`=16800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12224 /*The Kor'kron Vanguard!*/, 12511 /*The Hills Have Us*/);
UPDATE `quest_template` SET `RewardBonusMoney`=16800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=12225; -- Mmm... Amberseeds!
UPDATE `quest_template` SET `RewardBonusMoney`=50400, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12227; -- Doing Your Duty
UPDATE `quest_template` SET `RewardBonusMoney`=51900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12231 /*The Bear God's Offspring*/, 12247 /*Children of Ursoc*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=103500, `AllowableRaces`=-1, `QuestDescription`='The time has come, $n.  Now we will learn whether our efforts will accomplish what we need or nothing at all.$B$BTake these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc''s Den.  You will find the den to the north of Grizzlemaw.$B$BConvince Tur to aid you, for you will need all the help you can get.$B$BOnce you''ve defeated the bear god, use these ashes over his body.$B$BEven if his worldly form is destroyed, his spirit must be saved.', `VerifiedBuild`=19034 WHERE `ID`=12236; -- Ursoc, the Bear God
UPDATE `quest_template` SET `MinLevel`=72, `RewardMoneyDifficulty`=7, `RewardBonusMoney`=103500, `VerifiedBuild`=19034 WHERE `ID`=12238; -- Cleansing Drak'Tharon
UPDATE `quest_template` SET `RewardBonusMoney`=69000, `AllowableRaces`=-1, `QuestDescription`='The furbolgs'' work must be undone, $n.  The best of intentions do not count for much when the result is tainted by such strong a corruption.$B$BThe sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes.$B$BOnce cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.', `VerifiedBuild`=19034 WHERE `ID`=12241; -- Destroy the Sapling
UPDATE `quest_template` SET `RewardBonusMoney`=69000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12248 /*Vordrassil's Sapling*/, 12250 /*Vordrassil's Seeds*/, 12412 /*My Enemy's Friend*/, 12652 /*Feedin' Da Goolz*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=103500, `AllowableRaces`=-1, `QuestDescription`='It is time, $n.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.$B$BYou will need his help.  You won''t be able to defeat Ursoc alone.$B$BOnce you''ve defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.', `VerifiedBuild`=19034 WHERE `ID`=12249; -- Ursoc, the Bear God
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='Return to High Commander Halford Wyrmbane at once, $n. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.', `VerifiedBuild`=19034 WHERE `ID`=12251; -- Return to the High Commander
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='Just down this path here is Wintergarde''s town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living.$B$BIn the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, $n, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.', `VerifiedBuild`=19034 WHERE `ID`=12253; -- Rescue from Town Square
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12256 /*The Flamebinders' Secrets*/, 12257 /*A Show of Strength*/, 12448 /*Heated Battle*/, 12449 /*Return to the Earth*/);
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, $n. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction.$B$BVenture forth to the town square and deliver the vengeful geists to their maker. Give them peace.', `VerifiedBuild`=19034 WHERE `ID`=12258; -- The Fate of the Dead
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `QuestDescription`='The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct.$B$BI will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes. $B$BBe cautious $n, any damage done to you is likely to break the fragile illusion.', `VerifiedBuild`=19034 WHERE `ID`=12263; -- The Best of Intentions
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6900, `VerifiedBuild`=19034 WHERE `ID` IN (12266 /*Tales of Destruction*/, 12447 /*The Obsidian Dragonshrine*/, 12469 /*Return to Sender*/, 12505 /*New Orders for Sergeant Stackhammer*/, 12789 /*Into the Breach!*/, 12792 /*First Things First*/, 12793 /*Smoke on the Horizon*/, 12795 /*Taking a Stand*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=33300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=12271; -- The Rod of Compulsion
UPDATE `quest_template` SET `RewardBonusMoney`=83100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12277; -- Leave Nothing to Chance
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='The memories of the past haunt this land, $n. I hear the cries of the fallen echo across Northrend - calling to me.$B$BArthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign.$B$BFirst, you must recover my scrying orb from the town hall, $n. Exit this tower and turn left down the path to reach the town square.', `VerifiedBuild`=19034 WHERE `ID`=12282; -- Imprints on the Past
UPDATE `quest_template` SET `RewardBonusMoney`=16500, `AllowableRaces`=-1, `QuestDescription`='I have gazed upon the orb and seen the path that you must walk, $n.$B$BMany years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore.$B$BTake the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn''s Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.', `VerifiedBuild`=19034 WHERE `ID`=12287; -- Orik Trueheart and the Forgotten Shore
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead.$B$BOnce a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me.$B$BRemember, $n, these spirits were once Alliance soldiers. Treat them with respect, honor and dignity.$B$BNow, with elixir in hand, venture south to the Forgotten Shore.', `VerifiedBuild`=19034 WHERE `ID`=12291; -- The Forgotten Tale
UPDATE `quest_template` SET `RewardBonusMoney`=17100, `AllowableRaces`=-1, `QuestDescription`='Very well, $n.  Your people kept their end of the bargain.$B$BTell Dumont that we''ll honor the deal.', `VerifiedBuild`=19034 WHERE `ID`=12294; -- A Tentative Pact
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight.$B$BIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.$B$BHurry, $n. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He''ll put you on his fastest gryphon to Wintergarde!', `VerifiedBuild`=19034 WHERE `ID`=12297; -- Of Traitors and Treason
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='<Greer hands the missive back to you.>$B$BSkysong will take you to Wintergarde, $n. I guarantee you that it will be the fastest flight you''ve ever taken. Go now!
', `VerifiedBuild`=19034 WHERE `ID`=12298; -- High Commander Halford Wyrmbane
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=68100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12299; -- Northern Hospitality
UPDATE `quest_template` SET `RewardBonusMoney`=51000, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12300; -- Test of Mettle
UPDATE `quest_template` SET `RewardBonusMoney`=99900, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12301; -- The Truth Shall Set Us Free
UPDATE `quest_template` SET `RewardBonusMoney`=51000, `AllowableRaces`=-1, `QuestDescription`='Thanks for helping me, $n.  My name''s Sasha.  Listen, I have to get the hell out of here.$B$BThe people that sent you here... my people... they''ve changed.  They''re not good people anymore... and they want to turn you into one of... one of them.$B$BThis... ''test'' they sent you on is just the beginning.$B$BHead to the northwestern end of Silverbrook.  You''ll find something of interest to you.$B$BGood luck... and trust no one.', `VerifiedBuild`=19034 WHERE `ID`=12302; -- Words of Warning
UPDATE `quest_template` SET `RewardBonusMoney`=16500, `AllowableRaces`=-1, `QuestDescription`='You have honored me and honored the memory of hundreds of Alliance veterans, $n. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore.$B$BI do not have the gift of foresight like Zelig, but I am certain that great things await you, friend.$B$BFarewell. 
', `VerifiedBuild`=19034 WHERE `ID`=12305; -- Parting Thoughts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=68100, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12307; -- Wolfsbane Root
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.$B$BThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.$B$BIn his message, Durkon requested assistance. You will find him and help him, $n. The crypt is on the western border of the town square.', `VerifiedBuild`=19034 WHERE `ID`=12309; -- Find Durkon!
UPDATE `quest_template` SET `RewardBonusMoney`=66600, `AllowableRaces`=-1, `QuestDescription`='Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.$B$BYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!$B$BAnd $n, be on the lookout for any information that might be laying about inside the room where Amarion resides. 
', `VerifiedBuild`=19034 WHERE `ID`=12311; -- The Noble's Crypt
UPDATE `quest_template` SET `RewardBonusMoney`=16800, `RewardSpell`=140428, `Flags`=3145856, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12312; -- Secrets of the Scourge
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=18875469, `QuestDescription`='The Horde''s forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde''s forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.$B$BIf you can defeat her, the Horde''s offensive will falter and we can seize the chance to capture the port. Beware, $n, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.', `VerifiedBuild`=19034 WHERE `ID`=12314; -- Down With Captain Zorna!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=-1, `QuestDescription`='With every advance, our men are met by fresh Alliance reinforcements. It''s almost as though their commander anticipates my every move!$B$BThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.$B$BThis will be no easy fight, $n. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!', `VerifiedBuild`=19034 WHERE `ID`=12315; -- Crush Captain Brightwater!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=-1, `QuestDescription`='We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.$B$BCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we''ll have no reinforcements.$B$BGo into the field, $n, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!', `VerifiedBuild`=19034 WHERE `ID`=12316; -- Keep Them at Bay!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=33555378, `QuestDescription`='This wretched Westfall Brigade is proving a tougher opponent than we''d thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.$B$BConqueror Krenna''s orders were to capture the port quickly. You must break the stalemate, $n. Find the enemy''s marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.$B$BGo quickly. We don''t want to keep Conqueror Krenna waiting.', `VerifiedBuild`=19034 WHERE `ID`=12317; -- Keep Them at Bay
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='What can it be, $n? That was certainly no ordinary curse that the blasted lich put on you!$B$B<Durkon flips through the grisly pages of the tome.>$B$BI don''t even know if I''m looking at it the right way. We must find out what information is held within this tome!$B$B<Durkon hands the book back to you.>$B$BThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.', `VerifiedBuild`=19034 WHERE `ID`=12319; -- Mystery of the Tome
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=12323; -- Smoke 'Em Out
UPDATE `quest_template` SET `RewardBonusMoney`=16800, `AllowableRaces`=-1, `QuestDescription`='You have done much to advance our efforts against the Scourge, $n. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.$B$BAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson''s Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!', `VerifiedBuild`=19034 WHERE `ID`=12325; -- Into Hostile Territory
UPDATE `quest_template` SET `RewardBonusMoney`=34500, `VerifiedBuild`=19034 WHERE `ID`=12327; -- Out of Body Experience
UPDATE `quest_template` SET `RewardBonusMoney`=69000, `VerifiedBuild`=19034 WHERE `ID`=12328; -- Ruuna's Request
UPDATE `quest_template` SET `RewardBonusMoney`=17400, `QuestDescription`='There are two types of people in this world, $n.  Those who believe in coincidence and those who don''t.$B$BOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.$B$BEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.$B$BYou''ll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.', `VerifiedBuild`=19034 WHERE `ID`=12329; -- Fate and Coincidence
UPDATE `quest_template` SET `RewardBonusMoney`=51900, `VerifiedBuild`=19034 WHERE `ID`=12330; -- Anatoly Will Talk
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `QuestDescription`='Emboldened by the overabundance of magic now flowing through the Azure Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself!$B$BI ask that you ride one of our defenders into battle to slay their dragons and drakes, and to attack the eruption of ley line energies at the dragonshrine itself in order to destabilize it.$B$BOutside on the east and west terraces are wyrmrest defenders. Speak with one to ride it into battle.$B$BWithout your help, $n, we will surely lose.', `VerifiedBuild`=19034 WHERE `ID`=12372; -- Defending Wyrmrest Temple
UPDATE `quest_template` SET `RewardBonusMoney`=34500, `QuestDescription`='Please, $n.  I know it is Arugal you''re after.  I swear on my father''s memory I will help you take him down.$B$BBut I must beg you... Anya is completely innocent, we cannot leave her with these savages.$B$BHelp me rescue my sister and you''ll have me at your side when you face Arugal.$B$BI know the den Anatoly spoke of.  We''ll find it on the other side of this hill.  Let''s go, my sister''s in danger.', `VerifiedBuild`=19034 WHERE `ID`=12411; -- A Sister's Pledge
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=17400, `VerifiedBuild`=19034 WHERE `ID` IN (12419 /*The Fate of the Ruby Dragonshrine*/, 12502 /*Troll Patrol: High Standards*/, 12507 /*Strange Mojo*/, 12509 /*Troll Patrol: Intestinal Fortitude*/, 12519 /*Troll Patrol: Whatdya Want, a Medal?*/, 12541 /*Troll Patrol: The Alchemist's Apprentice*/, 12568 /*Troll Patrol: Done to Death*/, 12585 /*Troll Patrol: Creature Comforts*/, 12588 /*Troll Patrol: Can You Dig It?*/, 12591 /*Troll Patrol: Throwing Down*/, 12594 /*Troll Patrol: Couldn't Care Less*/, 12598 /*Throwing Down*/);
UPDATE `quest_template` SET `RewardBonusMoney`=17100, `AllowableRaces`=-1, `QuestDescription`='Listen, $n.  I need you to act with discretion and speed.$B$BOne of Krenna''s top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over.$B$BWe can''t let that happen.  You see, the prisoner matches the description of Mikhail''s older daughter in his diary.$B$BIf we set her loose and follow her closely, she''ll lead us to whoever''s controlling the trappers.  Take this letter to her.', `VerifiedBuild`=19034 WHERE `ID`=12422; -- Tactical Clemency
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=103500, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12430 /*The Conquest Pit: Death Is Likely*/, 12431 /*The Conquest Pit: Final Showdown*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=68100, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (12432 /*Riding the Red Rocket*/, 12433 /*Seeking Solvent*/, 12437 /*Riding the Red Rocket*/, 12443 /*Seeking Solvent*/, 12444 /*Blackriver Skirmish*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `QuestDescription`='I abhor the loss of life... any life. But I will not stand idly by and allow Malygos to kill us and defile the temple!$B$BI have appointed Lord Afrasastrasz as the commander of Wyrmrest''s defenses.$B$BSpeak with Torastrasza to ride a drake down to him.$B$BPlease lend him your aid, $n. Your involvement with the defense of Wyrmrest will be critical to us prevailing against the blue dragonflight.', `VerifiedBuild`=19034 WHERE `ID`=12435; -- Report to Lord Afrasastrasz
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=85200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (12438 /*Wanted: Kreug Oathbreaker*/, 12441 /*Wanted: High Shaman Bloodpaw*/, 12442 /*Wanted: Onslaught Commander Iustus*/);
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='Another force threatens to destroy all that we have worked for, $n. You must head westward to Stars'' Rest. Archmage Modera has sensed a great disturbance in the magical ley lines of our world that must be dealt with immediately!$B$BGo now, $n! Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the nature of your mission. He will place you on his fastest gryphon to deliver you to Stars'' Rest. Speak with Archmage Modera when you arrive.', `VerifiedBuild`=19034 WHERE `ID`=12439; -- A Disturbance In The West
UPDATE `quest_template` SET `RewardBonusMoney`=17100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=12451; -- Onward to Camp Oneqwah
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (12460 /*Report to the Ruby Dragonshrine*/, 25287 /*Words for Delivery*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=12461; -- Report to the Ruby Dragonshrine
UPDATE `quest_template` SET `RewardBonusMoney`=33600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=12463; -- Plunderbeard Must Be Found!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=84300, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=12464; -- My Old Enemy
UPDATE `quest_template` SET `RewardBonusMoney`=16800, `AllowableRaces`=-1, `QuestDescription`='You need to get to the 7th Legion Front in northern Dragonblight. Return to Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. Take a left on that road and follow it until you reach the snowline. Once at the snowline keep heading west until you hit the Path of the Titans. Follow that north and it''ll lead you right into the 7th Legion Front.$B$BOnce there, speak with Legion Commander Tyralion. He''ll be expecting you.$B$BAnd $n - it has been a pleasure. Farewell.', `VerifiedBuild`=19034 WHERE `ID`=12466; -- Chasing Icestorm: The 7th Legion Front
UPDATE `quest_template` SET `RewardBonusMoney`=49200, `QuestDescription`='I thank you for saving me, $n.  The kvaldir are animals!$B$BThey made us fight the other prisoners.  It would''ve been more merciful to just kill us all.$B$BThe youngling Karuk is still alive -- I noticed him arrive here.  Tell him his father fought until the end.', `VerifiedBuild`=19034 WHERE `ID`=12471; -- Cruelty of the Kvaldir
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=-1, `QuestDescription`='Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel''zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that''s missing now is you.$B$BTake the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum.$B$BThere is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, $n! Lead us to victory!', `VerifiedBuild`=19034 WHERE `ID`=12472; -- Finality
UPDATE `quest_template` SET `RewardBonusMoney`=67500, `AllowableRaces`=-1, `QuestDescription`='Every good story has a beginning and an ending, $n. While your story is far from over, I''ll be damned if it''s not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you''ve done at Wintergarde will be a tale told for years to come.$B$BNow, ally, when you are ready I will use the phylactery to coax Thel''zan out of hiding.$B$BShould we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.', `VerifiedBuild`=19034 WHERE `ID`=12473; -- An End And A Beginning
UPDATE `quest_template` SET `RewardBonusMoney`=101100, `AllowableRaces`=-1, `QuestDescription`='With the Naxxramas war machine stopped dead in its tracks the time has come for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord Fordragon awaits your arrival! Go now, $n!$B$BTake the north gate out of town and travel north by northwest until you arrive at your destination.$B$BLight protect you!', `VerifiedBuild`=19034 WHERE `ID`=12474; -- To Fordragon Hold!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=67500, `AllowableRaces`=-1, `QuestDescription`='To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, $n.$B$BGo to Onslaught Base Camp and thin them out. 
', `VerifiedBuild`=19034 WHERE `ID`=12476; -- The Return of the Crusade?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=17100, `VerifiedBuild`=19034 WHERE `ID`=12484; -- Scourgekabob
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=34800, `VerifiedBuild`=19034 WHERE `ID`=12489; -- Welcome to Sholazar Basin
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=-1, `QuestDescription`='Our assault against Angrathar has staggered the Scourge, but they remain unrelenting. From overhead they send their frost wyrms to strafe the field of battle, making an advance upon the gate itself impossible. The frost wyrm attacks must be stopped, but before we defile the bones of ancient dragons, we must gain permission from their queen.$B$BTravel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell her what we must do and ask her for guidance.$B$BGo now, $n!', `VerifiedBuild`=19034 WHERE `ID`=12495; -- Audience With The Dragon Queen
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=-1, `QuestDescription`='Though I know you hunger to destroy the Scourge that stand before us at the Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing assaults of the frost wyrms are halted, we cannot move forward.$B$BBut before we assault the dying grounds of dragons, we must first be granted permission. Venture now to the hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen Alexstrasza.$B$BRide now, $n! Southeast, to Wyrmrest!', `VerifiedBuild`=19034 WHERE `ID`=12496; -- Audience With The Dragon Queen
UPDATE `quest_template` SET `RewardBonusMoney`=85200, `QuestDescription`='Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly north to Galakrond''s Rest. Once there, command the dragon to destroy the Scourge scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the Wicked Coil, overlooking Galakrond''s Rest, to destroy Grand Necrolord Antiok and recover the scythe that he uses to control the wyrms.$B$BDo this and return to Queen Alexstrasza for a hero''s reward!$B$B$n, beware the rotting storm giants that wander the area!', `VerifiedBuild`=19034 WHERE `ID`=12498; -- On Ruby Wings
UPDATE `quest_template` SET `RewardBonusMoney`=102300, `AllowableRaces`=18875469, `QuestDescription`='With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.$B$BThe time to make your final stand is now, $n. Return to Fordragon Hold and notify Highlord Fordragon.
', `VerifiedBuild`=19034 WHERE `ID`=12499; -- Return To Angrathar
UPDATE `quest_template` SET `RewardBonusMoney`=102300, `AllowableRaces`=33555378, `QuestDescription`='With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.$B$BThe time to make your final stand is now, $n. Return to the Kor''kron Vanguard and notify Saurfang the Younger.', `VerifiedBuild`=19034 WHERE `ID`=12500; -- Return To Angrathar
