UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69900, `QuestDescription`='We must send Foreman Swindlegrin packing if we''re going to shut down his mine permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and  isn''t likely to let you see the foreman without a fight.$B$BThe two probably occupy a platform that would let them look out over the entire Venture Company operation at Swindlegrin''s Dig.$B$BRemember, the dig is on the far side of the Suntouched Pillar to the northeast. Good luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=12525; -- Wipe That Grin Off His Face
