UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=52500, `QuestDescription`='Bones of Nozronn, Oracle Soo-rahm sends $n to you!$B$BWe have prepared incense for you. Light it and place it near Nozronn''s head and you will hear his voice.$B$B<Confused, you tell Soo-rahm that you haven''t even told him your question.>$B$BTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart''s question.$B$BGo. Nozronn not wait long.', `VerifiedBuild`=19034 WHERE `ID`=12544; -- The Bones of Nozronn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=107100, `QuestDescription`='It is time, $n.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands.$B$BThere is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.', `VerifiedBuild`=19034 WHERE `ID`=12546; -- Reclamation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=71400, `VerifiedBuild`=19034 WHERE `ID` IN (12547 /*The Activation Rune*/, 12691 /*A Timeworn Coffer*/, 12818 /*Clean Up*/, 12819 /*Just Around the Corner*/, 12820 /*A Delicate Touch*/, 12821 /*Opening the Backdoor*/, 12822 /*Know No Fear*/, 12823 /*A Flawless Plan*/, 12827 /*Reclaimed Rations*/, 12828 /*Ample Inspiration*/, 12829 /*Moving In*/, 12830 /*Ore Repossession*/, 12831 /*Only Partly Forgotten*/, 12832 /*Bitter Departure*/, 12833 /*Overstock*/, 12836 /*Expression of Gratitude*/, 13039 /*Defending The Vanguard*/, 13040 /*Curing The Incurable*/, 13122 /*The Scourgestone*/, 25445 /*Zalazane's Fall*/);
UPDATE `quest_template` SET `RewardBonusMoney`=71400, `QuestDescription`='It is time, $n.  The Waygate has been activated for the first time in seven centuries.  Use it to travel to where our final hope lies.$B$BLet us put an end to those who would seek to bring the taint of undeath to this pristine land.  Let us unleash the Etymidian.', `VerifiedBuild`=19034 WHERE `ID`=12548; -- The Etymidian
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=87300, `QuestDescription`='$n, head back down there!$B$BYou''ll find the leader of Kolramas, Malas the Corrupter, gloating from atop the crashed necropolis.$B$BKill him and bring me his head!', `VerifiedBuild`=19034 WHERE `ID`=12554; -- Malas the Corrupter
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=87300, `QuestDescription`='Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, $n? For all the spirit''s blustering, I''m certain it was telling the truth about the beast''s strength.$B$BWhen you''re ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.', `VerifiedBuild`=19034 WHERE `ID`=12556; -- Rhino Mastery: The Kill
UPDATE `quest_template` SET `RewardXPDifficulty`=0, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=0, `VerifiedBuild`=19034 WHERE `ID`=12557; -- Lab Work
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69900, `QuestDescription`='Shango awaits, $n. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage.$B$BHe is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.', `VerifiedBuild`=19034 WHERE `ID`=12558; -- Dreadsaber Mastery: Ready to Pounce
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=53100, `QuestDescription`='It is time then.  Let us activate the waygate.$B$BYou will find the first switch inside the Makers'' Perch in the western edge of the basin.$B$BBeware, $n.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.', `VerifiedBuild`=19034 WHERE `ID`=12559; -- Powering the Waygate - The Makers' Perch
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=88200, `VerifiedBuild`=19034 WHERE `ID`=12561; -- An Issue of Trust
