UPDATE `quest_template` SET `RewardBonusMoney`=70500, `VerifiedBuild`=19034 WHERE `ID` IN (12613 /*Powering the Waygate - The Makers' Overlook*/, 12615 /*The Blessing of Zim'Torga*/, 12627 /*Breaking Through Jin'Alai*/, 12632 /*But First My Offspring*/, 12635 /*Relics of the Snow Leopard Goddess*/, 12646 /*My Prophet, My Enemy*/, 12650 /*Plundering Their Own*/, 12655 /*The Blessing of Zim'Rhuk*/, 12665 /*I Sense a Disturbance*/, 12666 /*Preparations for the Underworld*/, 12672 /*Setting the Stage*/, 12684 /*Blood of a Dead God*/, 12708 /*Enchanted Tiki Warriors*/, 13556 /*Eggs for Dubra'Jin*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=88200, `RewardChoiceItemID3`=39488, `RewardChoiceItemID4`=39478, `RewardChoiceItemID5`=40353, `RewardChoiceItemID6`=0, `RewardChoiceItemQuantity6`=0, `VerifiedBuild`=19034 WHERE `ID`=12614; -- Post-partum Aggression
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=70500, `QuestDescription`='I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.$B$BI never anticipated the Lich King would send willing living servants to do his work.$B$BI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, $n.  Deliver my wrath to these insolent trespassers.', `VerifiedBuild`=19034 WHERE `ID`=12617; -- Exterminate the Intruders
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=98100, `VerifiedBuild`=19034 WHERE `ID`=12619; -- The Emblazoned Runeblade
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=53100, `QuestDescription`='We were not quick enough, $n.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.$B$BWe don''t have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.$B$BWe shall show this scum to not trifle with the titans'' creations.', `VerifiedBuild`=19034 WHERE `ID`=12620; -- The Lifewarden's Wrath
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='The cultists have been taken care of, but the Scourge''s invasion has not slowed down.  The situation is becoming desperate, $n.$B$BThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.', `VerifiedBuild`=19034 WHERE `ID`=12621; -- Freya's Pact
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='We Zandalari could use your help, $n. We must put an end to what the Drakkari are doing to their gods!$B$BTo the northeast, up the great steps that lead to the next tier of Zul''Drak, lies Zim''Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend.$B$BI would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.', `VerifiedBuild`=19034 WHERE `ID`=12623; -- To the Witch Doctor
UPDATE `quest_template` SET `RewardBonusMoney`=35400, `QuestDescription`='The gods have spoken, $n. We now know what you must do.$B$BYou must now go to the Altar of Har''koa to the southeast and speak with the leopard goddess.', `VerifiedBuild`=19034 WHERE `ID`=12628; -- To Speak With Har'koa
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=51900, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID` IN (12631 /*An Invitation, of Sorts...*/, 12633 /*Darkness Calling*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=4950, `QuestDescription`='Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! The Lich King has called for you, $n.$B$BGo now! Suffer well, $g brother:sister;...
', `VerifiedBuild`=19034 WHERE `ID`=12636; -- The Eye Of Acherus
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=34500, `VerifiedBuild`=19034 WHERE `ID` IN (12637 /*Near Miss*/, 12638 /*Close Call*/, 12686 /*Zero Tolerance*/, 12710 /*Disclosure*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=73500, `QuestDescription`='Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.$B$BUse the eye''s siphon to analyze the forge, town hall, hold, and chapel. The eye''s control mechanisms are located on either side of this platform. Waste no more time, $n.$B$BThe Scourge will have this place. The Lich King commands it!', `VerifiedBuild`=19034 WHERE `ID`=12641; -- Death Comes From On High
UPDATE `quest_template` SET `RewardBonusMoney`=88200, `QuestDescription`='My body is too far gone now, $n. It is only a matter of time before a new prophet is elevated and finishes what the other began.$B$BI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.$B$BUse the incense and do me the kindness of putting an end to my suffering.$B$BI apologize if I fight back. Even for me, the will to survive is strong.', `VerifiedBuild`=19034 WHERE `ID`=12647; -- An End to the Suffering
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=51900, `VerifiedBuild`=19034 WHERE `ID` IN (12648 /*Dressing Down*/, 12649 /*Suit Up!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7200, `VerifiedBuild`=19034 WHERE `ID` IN (12651 /*Lakeside Landing*/, 12824 /*Demolitionist Extraordinaire*/, 12826 /*Slightly Unstable*/, 12853 /*Luxurious Getaway!*/, 12970 /*The Hyldsmeet*/, 12999 /*The Bone Witch*/, 13061 /*Prepare for Glory*/, 13068 /*A Tale of Valor*/, 13080 /*Hope Yet Remains*/, 13106 /*Blackwatch*/, 13158 /*Discretion is Key*/, 13168 /*Parting Gifts*/, 13794 /*Eadric the Pure*/, 13795 /*The Scourgebane*/, 29829 /*Discretion is Key*/, 29836 /*Just Checkin'*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=73500, `VerifiedBuild`=19034 WHERE `ID` IN (12657 /*The Might Of The Scourge*/, 12842 /*Runeforging: Preparation For Battle*/, 12848 /*The Endless Hunger*/);
UPDATE `quest_template` SET `RewardBonusMoney`=70500, `QuestDescription`='I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.$B$BYou do still want to live, yes?$B$BAs you have seen, my devotees are enjoying their stay here, but now it''s time for them to make final restitution.$B$BDo me the smallest of favors if you would, $n. Lure them near my soul fonts and then put an end to their existences.$B$BThey taste so delicious, and their sacrifice will not go in vain, I can assure you.', `VerifiedBuild`=19034 WHERE `ID`=12668; -- Foundation for Revenge
UPDATE `quest_template` SET `RewardBonusMoney`=88200, `VerifiedBuild`=19034 WHERE `ID` IN (12674 /*Hell Hath a Fury*/, 12729 /*The Gods Have Spoken*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73500, `RewardTalents`=0, `VerifiedBuild`=19034 WHERE `ID` IN (12678 /*If Chaos Drives, Let Suffering Hold The Reins*/, 12679 /*Tonight We Dine In Havenshire*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73500, `RewardTalents`=0, `QuestDescription`='How fortuitous it is that the Crusade has a stable full of horses a mere stone''s throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully $g his:hers;!$B$BOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.$B$BRemember, $n, it''s only stealing if you''re caught. Watch out for that deranged stable master, Kitrik!', `VerifiedBuild`=19034 WHERE `ID`=12680; -- Grand Theft Palomino
UPDATE `quest_template` SET `RewardBonusMoney`=88200, `QuestDescription`='This is what it has come down to... revenge.$B$B<Har''koa sighs.>$B$BTake this ritual kit and enact it near Quetz''lun''s corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.$B$BThe rest will be up to you, $n. You must slay the prophet in his drained state.', `VerifiedBuild`=19034 WHERE `ID`=12685; -- You Reap What You Sow
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardItem1`=0, `RewardAmount1`=0, `RewardTalents`=0, `VerifiedBuild`=19034 WHERE `ID`=12687; -- Into the Realm of Shadows
UPDATE `quest_template` SET `RewardBonusMoney`=17700, `VerifiedBuild`=19034 WHERE `ID` IN (12696 /*Aerial Surveillance*/, 13052 /*Aerial Surveillance*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='CHAOS, $n! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light''s Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast.$B$BLet''s stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he''d like to bestow upon the Scarlet Crusade. Seek him out.', `VerifiedBuild`=19034 WHERE `ID`=12697; -- Gothik the Harvester
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardTalents`=0, `VerifiedBuild`=19034 WHERE `ID` IN (12698 /*The Gift That Keeps On Giving*/, 12716 /*The Plaguebringer's Request*/, 12720 /*How To Win Friends And Influence Enemies*/, 12722 /*Lambs To The Slaughter*/, 12724 /*The Path Of The Righteous Crusader*/, 12754 /*Ambush At The Overlook*/, 12756 /*The Scarlet Onslaught Emerges*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=70500, `LogTitle`='An Embarrassing Incident', `VerifiedBuild`=19034 WHERE `ID`=12699; -- An Embarrassing Incident
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=7, `RewardTalents`=0, `VerifiedBuild`=19034 WHERE `ID`=12701; -- Massacre At Light's Point
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=89400, `VerifiedBuild`=19034 WHERE `ID` IN (12703 /*Kartak's Rampage*/, 12705 /*Will of the Titans*/, 12759 /*Tools of War*/, 12761 /*Mastery of the Crystals*/, 12762 /*Power of the Great Ones*/);
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardTalents`=0, `QuestDescription`='<Prince Valanar hands you a sealed scroll.>$B$BThis is the full report of our victory at Death''s Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, $n.$B$BGo now!', `VerifiedBuild`=19034 WHERE `ID`=12706; -- Victory At Death's Breach!
UPDATE `quest_template` SET `RewardBonusMoney`=70500, `QuestDescription`='Pardon me, $n. I''m given to understand that you might be heading northeast up to the Zol''Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.$B$BAs I have come to know, the Drakkari warlord is extremely paranoid. He''s had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?$B$BIf you could find the time to acquire some of those goods, I would be most appreciative.', `VerifiedBuild`=19034 WHERE `ID`=12709; -- Hexed Caches
UPDATE `quest_template` SET `RewardBonusMoney`=88200, `QuestDescription`='$n, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.$B$BThe Drakkari warlord, Zol''Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.$B$BThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home''s gate.', `VerifiedBuild`=19034 WHERE `ID`=12712; -- The Key of Warlord Zol'Maz
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='It is the will of the Lich King that drives us onward, $n. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts...$B$BCan you hear him now? Perhaps it is too early for you.$B$B<Mograine closes his eyes and nods to an unseen host.>$B$BYes, my lord. It will be done.$B$B$n, you are to return to Death''s Breach and report to Prince Valanar. The Lich King commands it!', `VerifiedBuild`=19034 WHERE `ID`=12714; -- The Will Of The Lich King
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade''s front lines down while we labor to fortify our new forward base, the Crypt of Remembrance.$B$BVenture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth.$B$BHe will be expecting you.$B$BPrepare yourself, $n, for you are about to witness the next stage of Scourge warfare: DOMINATION!$B$BRide now, death knight!', `VerifiedBuild`=19034 WHERE `ID`=12715; -- The Crypt of Remembrance
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardTalents`=0, `QuestDescription`='Nothing less than total annihilation will suffice, $n. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge''s grasp!$B$BMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.', `VerifiedBuild`=19034 WHERE `ID`=12719; -- Nowhere To Run And Nowhere To Hide
UPDATE `quest_template` SET `RewardBonusMoney`=88200, `QuestDescription`='$n, there is no time left. You must take the key and use it to unlock Akali.$B$BHe is being held in the courtyard in front of Gundrak, the capital of Zul''Drak. Akali''s chains are secured by four anchor points. You must unlock each of them to set the rhino god free.$B$BGundrak is teeming with ice trolls. However, I believe that if you''re careful, you should be able to slip in without too much danger.$B$BOnce you''re done, please inform the witch doctor.', `VerifiedBuild`=19034 WHERE `ID`=12721; -- Rampage
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=2147483647, `VerifiedBuild`=19034 WHERE `ID`=12723; -- Behind Scarlet Lines
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardTalents`=0, `VerifiedBuild`=19034 WHERE `ID` IN (12725 /*Brothers In Death*/, 12755 /*A Meeting With Fate*/);
