UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardTalents`=0, `QuestDescription`='Return to Thassarian at the Scarlet Tavern and let him know that Koltira''s cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours.$B$BYou''re one cold-blooded monster, $n. I salute you, $g brother:sister;.', `VerifiedBuild`=19034 WHERE `ID`=12751; -- A Sort Of Homecoming
