UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=7, `RewardTalents`=0, `QuestDescription`='We must prepare for the encroaching armies, $n. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.$B$BGive Highlord Mograine Abbendis'' journal as well. Perhaps he''ll find it useful.
', `VerifiedBuild`=19034 WHERE `ID`=12757; -- Scarlet Armies Approach...
