UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=7, `RewardTalents`=0, `QuestDescription`='You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, $n.$B$B<The Lich King pauses.>$B$BThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.$B$BUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.', `VerifiedBuild`=19034 WHERE `ID`=12779; -- An End To All Things...
