UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=33555378, `QuestDescription`='Hello, $n. You may or may not be aware that we Kirin Tor moved our city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.$B$BWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.', `VerifiedBuild`=19034 WHERE `ID`=12791; -- The Magical Kingdom of Dalaran
