UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend.$B$BWe now turn all of our efforts to Light''s Hope Chapel. No longer will this affront to your master be allowed to exist!$B$BI have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill.$B$BDo not fail me, $n.', `VerifiedBuild`=19034 WHERE `ID`=12800; -- The Lich King's Command
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=8, `RewardTalents`=0, `VerifiedBuild`=19034 WHERE `ID`=12801; -- The Light of Dawn
