UPDATE `quest_template` SET `RewardBonusMoney`=72300, `VerifiedBuild`=19034 WHERE `ID` IN (12841 /*The Crone's Bargain*/, 13130 /*The Stone That Started A Revolution*/, 13139 /*Into The Frozen Heart Of Northrend*/);
UPDATE `quest_template` SET `RewardBonusMoney`=72300, `QuestDescription`='You have to help us!  We were in the middle of an expedition into the mountains to set up a transmission tower when we were attacked.$B$BThey looked like vrykul, except their skin was blue and layered with frost.... and they were all female!  They took all the men in the expedition and let us women go.  Please, $n!  We think they''re being held in Sifreldar, the village overlooking K3.', `VerifiedBuild`=19034 WHERE `ID`=12843; -- They Took Our Men!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=72300, `QuestDescription`='Please, $n.  When the Hyldnir took our men, they also took all our equipment.  Of course, it''s more important that we get our boys back, but if you run into any of our equipment, I''d really appreciate it if you brought it back to us.$B$BYou''ll find their village just above us, to the north.', `VerifiedBuild`=19034 WHERE `ID`=12844; -- Equipment Recovery
UPDATE `quest_template` SET `RewardBonusMoney`=35700, `QuestDescription`='All of our boys are back... thanks to you, $n!  Well... all but one.$B$BMy brother Zeev is still up there according to the others.  Apparently they have some sort of mine where they make their prisoners work.  Go in there and see if you can find out anything.', `VerifiedBuild`=19034 WHERE `ID`=12846; -- Leave No Goblin Behind
