UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `LogDescription`='Free 3 Captured Proto-Drakes and rescue 9 Brunnhildar Prisoners.', `QuestDescription`='To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....$b$bYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate our captive proto-drakes. With them, you will be able to free our sisters from their frozen bonds and carry them safely home.$b$bBeware the giants'' clubs, sister, lest you find yourself numbered among the captives.', `VerifiedBuild`=19034 WHERE `ID`=12856; -- Cold Hearted
