UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=54900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (12920 /*Catching up with Brann*/, 24451 /*An Audience With The Arcanist*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7200, `AllowableRaces`=33555378, `QuestDescription`='The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.$B$BThey have taken refuge in an old titan building, which they now call Bouldercrag''s Refuge, on the face of a mountain west of the Inventor''s Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, $n.', `VerifiedBuild`=19034 WHERE `ID`=12929; -- The Earthen of Ulduar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='The refuge''s defenders fight bravely, but they cannot keep up with the iron onslaught.$B$BWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we''ll last out there.$B$BTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, $n. Every casualty is one too many.', `VerifiedBuild`=19034 WHERE `ID`=12937; -- Relief for the Fallen
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='We need you focused, $n. We''re barely holding The Shadow Vault as it is. As you can see, we''ve greatly angered the Lich King.$B$B<The baron chuckles.>$B$BI need you to speak with Duke Lankral. He''s in charge here now. You''ll find him inside the vault building proper.$B$BWere I you, I would not keep him waiting.', `VerifiedBuild`=19034 WHERE `ID`=12938; -- The Duke
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=107100, `VerifiedBuild`=19034 WHERE `ID`=12948; -- The Champion of Anguish
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18300, `VerifiedBuild`=19034 WHERE `ID` IN (12951 /*Let the Baron Know*/, 12987 /*Mounting Hodir's Helm*/, 13412 /*Corastrasza*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=105900, `QuestDescription`='I was wondering when you''d show up, $n! Having a past champion of the Ring of Blood here will be a huge draw! We''re gonna be rich, buddy! RICH!$B$BAnyway, this dump is Zul''Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We''re here to make some gold!$B$BYou know the drill, $n. When you''re ready let me know and we''ll get this show on the road!
', `VerifiedBuild`=19034 WHERE `ID`=12954; -- The Amphitheater of Anguish: Yggdras!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.$B$BI don''t know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.$B$BGo to the Frozen Mine, $n, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.', `VerifiedBuild`=19034 WHERE `ID`=12957; -- Slaves of the Stormforged
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.$B$BIt could explain the strength and ferocity my men see in the stormforged warriors.$B$BValduran''s base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, $n, and neutralize his power. Destroy these gifts of Loken''s and help us to sap the strength of his followers.', `VerifiedBuild`=19034 WHERE `ID`=12965; -- The Gifts of Loken
UPDATE `quest_template` SET `RewardBonusMoney`=36600, `VerifiedBuild`=19034 WHERE `ID` IN (12969 /*Is That Your Goblin?*/, 12972 /*You'll Need a Bear*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (12973 /*The Brothers Bronzebeard*/, 13403 /*Tirion's Gambit*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `Flags`=4224, `LogDescription`='Blow Hodir''s Horn over 5 Niffelem Forefathers and 5 Restless Frostborn corpses at Thunderfall.', `QuestCompletionLog`='Return to Hodir''s Horn at Dun Niffelem in The Storm Peaks.', `VerifiedBuild`=19034 WHERE `ID`=12977; -- Blowing Hodir's Horn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='Now that I''m back, I''m certain that the baron will want me to recover my men. I can see that we''re barely hanging on here. The Lich King''s forces are about to break through and we won''t be able to hold without my captured death knights.$B$BCan you assist me once more, $n?$B$BGo back to Jotunheim and let them out of those cages. Break the damn locks, I don''t care what you have to do. The vrykul likely have the keys.$B$BJust get my men free!', `VerifiedBuild`=19034 WHERE `ID`=12982; -- Ebon Blade Prisoners
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=91500, `QuestDescription`='We have no choice, $n. What you learned in Mimir''s Workshop means that we must act before Valduran can complete and unleash his new weapon.$B$BEven now, the refuge''s defenders fight to buy us time to deal with Valduran the Stormborn.$B$BYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.', `VerifiedBuild`=19034 WHERE `ID`=12984; -- Valduran the Stormborn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='In my folly, I''d thought Valduran''s project at Narvir''s Cradle, a large construction area to the south, no more than a grotesque monument to "Keeper" Loken''s cruelty.$B$BNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, $n, for it will mean the end of the refuge.$B$BGo to Narvir''s Cradle, find the lightning forges the stormforged artisans use, and sabotage them.', `VerifiedBuild`=19034 WHERE `ID`=12988; -- Destroy the Forges!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='Dem vrykuls at the Jotunheim needs to be crushed!$B$B$n crush dems good!', `VerifiedBuild`=19034 WHERE `ID`=12992; -- Crush Dem Vrykuls!
UPDATE `quest_template` SET `RewardBonusMoney`=54900, `VerifiedBuild`=19034 WHERE `ID`=12996; -- The Warm-Up 
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=72300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID`=13000; -- Emergency Measures
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `QuestDescription`='We have failed to prevent the completion of the iron colossus, $n, which means we have no choice but to face it in battle.$B$BBruor has devised a plan to exploit the colossus'' only weakness.$B$BNo matter how tough the colossus'' armor is, it is still vulnerable to a jormungar''s acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the Iron Colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.', `VerifiedBuild`=19034 WHERE `ID`=13007; -- The Iron Colossus
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=71400, `LogDescription`='Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 5 Webbed Crusaders.', `VerifiedBuild`=19034 WHERE `ID`=13008; -- Scourge Tactics
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=89400, `QuestDescription`='We will do all that we can to assist you, $n. The proto-brood have volunteered to fly you across the Breach and into Scourgeholme. Rescue any captured Argent Crusaders that you find. Return them immediately to the Vanguard Infirmary, located at the center of this base.$B$BChoose one of the Argent Skytalons in the pen behind me and go!$B$BScourgeholme is located northwest, across the Valley of Echoes, through the great Breach.', `VerifiedBuild`=19034 WHERE `ID`=13045; -- Into The Wild Green Yonder
UPDATE `quest_template` SET `RewardNextQuest`=29861, `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `VerifiedBuild`=19034 WHERE `ID`=13047; -- The Reckoning
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=70500, `QuestDescription`='Gretchen Fizzlespark wants to use my flying machine to look for survivors from her expedition.  Apparently she thinks they''re being held prisoner in the village to the north.$B$BThe only problem is I don''t have a co-pilot.  If you''re willing to take it on, I''d be more than happy to teach you a move or two.$B$BWhat do you say, $n?  Deal?', `VerifiedBuild`=19034 WHERE `ID`=13053; -- Looking for Survivors
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36600, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (13054 /*The Missing Tracker*/, 13828 /*Mastery Of Melee*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=-1, `QuestDescription`='I should manage for now, $n.  There is one favor I''d like to ask, though.$B$BI would never had fallen to one of these worms, but my wind serpent, Heesha, was killed by the meanest worg I''ve seen in some time.$B$BDon''t worry about me now, I''ll feel better when that worg is breathing no more.  You should find him deeper in the cave.', `VerifiedBuild`=19034 WHERE `ID`=13056; -- There's Always Time for Revenge
UPDATE `quest_template` SET `RewardBonusMoney`=36600, `QuestDescription`='It is time, $n.  I am prepared to face Loken now.$B$BLet us make our way to the Terrace of the Makers and face my brother''s forces.  The fool will regret ever crossing me.', `VerifiedBuild`=19034 WHERE `ID`=13057; -- The Terrace of the Makers
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=91500, `RewardChoiceItemID2`=43185, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=13058; -- Changing the Wind's Course
UPDATE `quest_template` SET `RewardBonusMoney`=18300, `QuestDescription`='You''ve been a great ally, $n.  Now comes your true test.  You will need skill, courage and a little luck.$B$B<Lok''lira attaches a thin strand of hair to yours.>$B$BYou cannot fail now sister.  Speak to Gretta the Arbiter.  She''ll see you on your way.', `VerifiedBuild`=19034 WHERE `ID`=13062; -- Lok'lira's Parting Gift
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=73200, `QuestDescription`='Vile like fire! Vile like proto-drakes!$B$B<The abomination claps its hands excitedly.>$B$BLittle $n go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!', `VerifiedBuild`=19034 WHERE `ID`=13071; -- Vile Like Fire!
