UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='Let us see if we can further weaken the resolve of the vrykul, $n.$B$BEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.$B$BAt least... it can''t hurt.', `VerifiedBuild`=19034 WHERE `ID`=13084; -- Vandalizing Jotunheim
