UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='Quickly, $n, head southwest to the Halls of the Ancestors!$B$BWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.$B$BNow go. There is no time to waste!', `VerifiedBuild`=19034 WHERE `ID`=13133; -- Find the Ancient Hero
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=72300, `VerifiedBuild`=19034 WHERE `ID`=13135; -- It Could Kill Us All
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=72300, `QuestDescription`='<Highlord Fordring holds a banner of the Argent Crusade.>$B$BThis banner is like no other, $n. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.$B$BYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders'' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders'' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.$B$BGo now, $n. Hold no fear in your heart.', `VerifiedBuild`=19034 WHERE `ID`=13141; -- The Battle For Crusaders' Pinnacle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `QuestDescription`='The time has come, $n. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.$B$BAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.$B$BBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.$B$B<The banshee-possessed vrykul lets out a bellowing cackle.>', `VerifiedBuild`=19034 WHERE `ID`=13142; -- Banshee's Revenge
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `FlagsEx`=8, `ItemDropQuantity2`=1, `VerifiedBuild`=19034 WHERE `ID`=13148; -- Necklace Repair
UPDATE `quest_template` SET `MinLevel`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (13153 /*Warding the Warriors*/, 13154 /*Bones and Arrows*/, 13156 /*A Rare Herb*/, 13195 /*A Rare Herb*/, 13196 /*Bones and Arrows*/, 13197 /*Fueling the Demolishers*/, 13198 /*Warding the Warriors*/);
UPDATE `quest_template` SET `RewardBonusMoney`=108600, `QuestDescription`='Stand proud in knowing that it was you who helped establish the Argent Crusade inside the walls of Icecrown, $n. The Crusaders'' Pinnacle now stands in direct defiance of the Lich King and his twisted minions.$B$BHighlord Fordring and the crusaders who survived await your arrival at Crusaders'' Pinnacle. Travel once more through the Breach and seek out the highlord!', `VerifiedBuild`=19034 WHERE `ID`=13157; -- The Crusaders' Pinnacle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=141300, `VerifiedBuild`=19034 WHERE `ID`=13159; -- Containment
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father''s cursed soul: my last memory as a free man.$B$BWe must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, $n. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!', `VerifiedBuild`=19034 WHERE `ID`=13165; -- Taking Back Acherus
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=7, `QuestDescription`='The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.$B$BUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!$B$BGo, $n. You have my strength to carry you!', `VerifiedBuild`=19034 WHERE `ID`=13166; -- The Battle For The Ebon Hold
UPDATE `quest_template` SET `QuestLevel`=90, `MinLevel`=85, `RewardMoney`=114000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=83100, `RewardCurrencyQty1`=75, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (13177 /*No Mercy for the Merciless*/, 13181 /*Victory in Wintergrasp*/, 13186 /*Stop the Siege*/, 13222 /*Defend the Siege*/, 13538 /*Southern Sabotage*/);
UPDATE `quest_template` SET `QuestLevel`=90, `MinLevel`=85, `RewardMoney`=114000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=83100, `RewardCurrencyQty1`=75, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (13178 /*Slay them all!*/, 13183 /*Victory in Wintergrasp*/, 13185 /*Stop the Siege*/, 13223 /*Defend the Siege*/, 13539 /*Toppling the Towers*/);
UPDATE `quest_template` SET `QuestLevel`=90, `MinLevel`=85, `RewardMoney`=114000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=83100, `RewardCurrencyQty1`=75, `AllowableRaces`=18875469, `QuestDescription`='Welcome to Wintergrasp, $n. Your mission is simple. Defeat ten of the Horde''s finest. Now, go! Bring victory to the Alliance!', `VerifiedBuild`=19034 WHERE `ID`=13179; -- No Mercy for the Merciless
UPDATE `quest_template` SET `QuestLevel`=90, `MinLevel`=85, `RewardMoney`=114000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=83100, `RewardCurrencyQty1`=75, `AllowableRaces`=33555378, `QuestDescription`='Welcome to Wintergrasp, $n. Warlord Garrosh demands one thing: Slay them all!$B$BReturn to me when ten of the strongest members of the Alliance are dead.', `VerifiedBuild`=19034 WHERE `ID`=13180; -- Slay them all!
UPDATE `quest_template` SET `MinLevel`=71, `RewardXPDifficulty`=5, `RewardMoney`=62000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=69900, `VerifiedBuild`=19034 WHERE `ID`=13187; -- The Faceless Ones
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `QuestDescription`='You are now, and forever will be, a Knight of the Ebon Blade, $n, but know this: you were once a hero of the Alliance.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.$B$BOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Varian Wrynn. Use the portal.', `VerifiedBuild`=19034 WHERE `ID`=13188; -- Where Kings Walk
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `QuestDescription`='You are now, and forever will be, a Knight of the Ebon Blade, $n, but know this: you were once a hero of the Horde.$B$B<Darion stares at you.>$B$BThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.$B$BOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to the Warchief. Use the portal.', `VerifiedBuild`=19034 WHERE `ID`=13189; -- Warchief's Blessing
