UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `QuestDescription`='You''ve just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, $n!$B$BThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I''m afraid he almost has it completed. We''re in a race to see who''s gonna be king of the mountain!$B$BOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!', `VerifiedBuild`=19034 WHERE `ID`=13280; -- King of the Mountain
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (13281 /*Neutralizing the Plague*/, 13297 /*Neutralizing the Plague*/, 13298 /*Coprous the Defiled*/, 13346 /*No Rest For The Wicked*/, 13350 /*No Rest For The Wicked*/, 13367 /*No Rest For The Wicked*/, 13368 /*No Rest For The Wicked*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (13282 /*Return to the Surface*/, 13348 /*Futility*/, 13829 /*Mastery Of Melee*/, 13838 /*Mastery Of The Shield-Breaker*/, 13839 /*Mastery Of The Charge*/, 24558 /*Return To Myralion Sunblaze*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='Yo, $n, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!$B$BThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot''s better than mine. Hah! We''re in a race to see who''s gonna be king of the mountain!$B$BOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!', `VerifiedBuild`=19034 WHERE `ID`=13283; -- King of the Mountain
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `AllowableRaces`=33555378, `QuestDescription`='You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.$B$BOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It''s his jumpbot versus theirs in a king of the mountain contest!$B$BDon''t let us down, $n. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.$B$BThat and we''ve got money riding on it that you can kick those cowards in the pants!', `VerifiedBuild`=19034 WHERE `ID`=13293; -- Get to Ymirheim!
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `AllowableRaces`=18875469, `QuestDescription`='I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.$B$BFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It''s her jumpbot versus theirs in a king of the mountain contest!$B$BDon''t let us down, $n. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.$B$BThat and we''ve got money riding on it that you can kick those idiots in the pants!', `VerifiedBuild`=19034 WHERE `ID`=13296; -- Get to Ymirheim!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `QuestDescription`='Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.$B$BI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that''s exactly what we will do.$B$BUnfortunately, I''ve been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, $n?', `VerifiedBuild`=19034 WHERE `ID`=13300; -- Slaves to Saronite
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.$B$BI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that''s exactly what we will do.$B$BUnfortunately, I''ve been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, $n?', `VerifiedBuild`=19034 WHERE `ID`=13302; -- Slaves to Saronite
