UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='The Scourge is still reeling from our attack, $n.  Now is the time to capitalize on our momentum.$B$BThe strategically important valley below us is wide open.  We''ve located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.$B$BIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy''s ground units.', `VerifiedBuild`=19034 WHERE `ID`=13304; -- Field Repairs
