UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18300, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (13340 /*Joining the Assault*/, 13341 /*Joining the Assault*/, 24506 /*Inside the Frozen Citadel*/, 24510 /*Inside the Frozen Citadel*/, 24682 /*The Pit of Saron*/, 24683 /*The Pit of Saron*/, 24711 /*Frostmourne*/, 24713 /*Frostmourne*/);
UPDATE `quest_template` SET `RewardBonusMoney`=102300, `AllowableRaces`=18875469, `QuestDescription`='Our fate is emblazoned upon our souls at birth. Bolvar''s fall, while tragic, was unavoidable.$B$BAll that you can do now is honor your hero, $n. Collect Bolvar''s shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: "All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world."$B$BHe mustn''t lose faith. Go now, $n. Your people need a hero. They need you.', `VerifiedBuild`=19034 WHERE `ID`=13347; -- Reborn From The Ashes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='We need to keep our momentum going.  Let''s not give the Scourge forces any respite.$B$BSindragosa''s Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King''s undead vrykul lackeys.$B$BIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.$B$BAn attack there would have great impact on the enemy''s access to frost wyrms.  Are you up to it, $n?', `VerifiedBuild`=19034 WHERE `ID`=13349; -- Cradle of the Frostbrood
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18300, `AllowableRaces`=33555378, `QuestDescription`='You have a lot of questions, $n.  You''re the only one who can see me because you touched something that once belonged to him... don''t you remember?$B$BYou don''t know what it is?  Well I can''t just tell you... that would make him really mad.  He''s not just a prince anymore... he''s the king!$B$BMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.', `VerifiedBuild`=19034 WHERE `ID`=13360; -- Time for Answers
UPDATE `quest_template` SET `RewardBonusMoney`=36600, `AllowableRaces`=33555378, `QuestDescription`='Now you know what you''re up against, $n.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.$B$BThe heart was his weakness and now he knows you''ve found it.$B$BIf you''re going to go back for it, you''d best bring help.  He will not leave it unguarded again.', `VerifiedBuild`=19034 WHERE `ID`=13362; -- Knowledge is a Terrible Burden
UPDATE `quest_template` SET `RewardBonusMoney`=54900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=13363; -- Argent Aid
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=13364; -- Tirion's Gambit
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7200, `AllowableRaces`=-1, `QuestDescription`='Tezzla is the one you want to meet, yes she is... she mastered a new wavelength, infra-green, and used it to hide herself near the Scourge!  Near enough to bomb them!$B$BI''ll give you infra-green vision so you can find her hiding above Aldur''thar, the Desolation Gate.  Go, go... I know she has work for brave heroes eager to blow up!  I mean... eager to blow up the Scourge!$B$BAnd $n, the Alliance has stolen our technology and has their own hidden airport nearby.  Avoid the dome with the Alliance banners!', `VerifiedBuild`=19034 WHERE `ID`=13379; -- Green Technology
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=109800, `QuestDescription`='Now that you have access to the focusing iris it''s time to put that key to use.$B$BAs much as I would like to see Malygos brought back into the fold, that''s just not going to happen at this point. With everything that''s at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.$B$B<Krasus says this last with a great deal of trepidation.>$B$B$n, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.', `VerifiedBuild`=19034 WHERE `ID`=13384; -- Judgment at the Eye of Eternity
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=146400, `QuestDescription`='Now that you have access to the focusing iris it''s time to put that key to use.$B$BAs much as I would like to see Malygos brought back into the fold, that''s just not going to happen at this point. With everything that''s at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.$B$B<Krasus says this last with a great deal of trepidation.>$B$B$n, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.', `VerifiedBuild`=19034 WHERE `ID`=13385; -- Heroic Judgment at the Eye of Eternity
UPDATE `quest_template` SET `RewardBonusMoney`=36600, `AllowableRaces`=18875469, `QuestDescription`='I''ve got an interesting assignment for you, $n.  If you''re up for a challenge, that is.$B$BWe''ve been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it''s a structural weakness.$B$BWe''ve sent some men there along with some "borrowed" saronite bombs.  They''re under Captain Kendall''s command.$B$BWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, $n?', `VerifiedBuild`=19034 WHERE `ID`=13386; -- Exploiting an Opening
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `QuestDescription`='The saronite bombs are in place, $n.  We''re only going to get one shot at this, however.  Let''s make it count.$B$BWe need temporary control of the area for a safe detonation.  Let''s try to put a dent in the Scourge''s numbers.', `VerifiedBuild`=19034 WHERE `ID`=13387; -- Securing the Perimeter
