UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=54300, `VerifiedBuild`=19034 WHERE `ID`=13422; -- Maintaining Discipline
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7200, `AllowableRaces`=-1, `QuestDescription`='It seems we''re not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka''lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.$B$BMeet up with him, $n. See if what he knows can help us in any way. From his description, Camp Tunka''lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.', `VerifiedBuild`=19034 WHERE `ID`=13426; -- Xarantaur, the Witness
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='The reality of fighting on multiple fronts, $g lad : lass;, is that we cannot spread our forces too thin or we risk losing it all!$B$BCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that''s in most need of brave combatants.$B$BGo now, $n, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they''ve inflicted on our brethren!', `VerifiedBuild`=19034 WHERE `ID` IN (13427 /*Call to Arms: Alterac Valley*/, 24427 /*Call to Arms: Alterac Valley*/);
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='We''ve recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we''re redirecting all our reinforcements to aid the Frostwolf Clan.$B$BA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.$B$BGo, $n.  Earn great honor by heeding the call of the brave Frostwolf warriors.', `VerifiedBuild`=19034 WHERE `ID` IN (13428 /*Call to Arms: Alterac Valley*/, 24426 /*Call to Arms: Alterac Valley*/);
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=-1, `QuestDescription`='We''re not fighting isolated battles against the Horde anymore, $g lad:lass;.$B$BVictory in one front means denying the Horde resources they''d use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.$B$BThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  $n, come back to me after you''ve served against the Horde at all of our active battlegrounds.', `VerifiedBuild`=19034 WHERE `ID`=13478; -- Concerted Efforts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (13511 /*One Bitter Wish*/, 13512 /*Strategic Strikes*/, 13529 /*The Corruption's Source*/, 13563 /*A Love Eternal*/, 13565 /*Twice Removed*/, 13844 /*The Looting of Althalaxx*/, 13995 /*King of Centaur Mountain*/, 14383 /*The Terrible Tinkers of the Ruined Reaches*/, 14464 /*Lightning Strike Assassination*/, 24591 /*Changing of the Gar'dul*/, 24945 /*Three Little Pygmies*/, 25027 /*You Flicked a Fine Vine to Leaf Me*/, 25129 /*Sarkoth*/, 25173 /*From Bad to Worse*/, 25368 /*Verinias the Twisted*/, 25661 /*With a Little Help...*/, 25780 /*Assault on Menethil Keep*/, 26303 /*The Mind's Eye*/, 26366 /*Heads Up*/, 26418 /*The Shell of Shadra*/, 26518 /*Heads Up*/, 26595 /*Kill-Collect*/, 26845 /*Who's In Charge Here?*/, 26855 /*A Pilot's Revenge*/, 27036 /*Vyrin's Revenge*/, 27152 /*Unusual Behavior... Even For Gnolls*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (13515 /*Ending the Threat*/, 13648 /*WANTED: The Dark Iron Spy*/, 14005 /*The Vengeance of Elune*/, 14056 /*Glomp is Sitting On It*/, 14063 /*Mutiny, Mon!*/, 24467 /*Fade to Black*/, 24718 /*The Mighty U'cha*/, 24744 /*The Biggest Egg Ever*/, 24950 /*Captain Dreadbeard*/, 25044 /*Diplomacy By Another Means*/, 25369 /*Stinglasher*/, 25374 /*Sasquatch Sighting*/, 25868 /*Yorla Darksnare*/, 26049 /*The Princess Unleashed*/, 26079 /*Wanted!  Otto and Falconcrest*/, 26263 /*Thornar Thunderclash*/, 26283 /*Prime Slime*/, 26300 /*Nezzliok Will Know*/, 26369 /*Hunt the Keeper*/, 26483 /*Gan'dranda*/, 26490 /*Prime Slime*/, 26526 /*Hunt the Keeper*/, 28470 /*High Chief Winterfall*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `QuestDescription`='A group of Twilight''s Hammer cultists has set up camp southwest of here.  They''re preparing an army of water elementals to use against Lor''danel.$B$BTheir leader, High Cultist Azerynn, has pacts with the dark Old Gods that grant his sect power over the elements.  Go and deal with them before it''s too late, $n.$B$BThe cataclysm has left the elemental spirits in disarray... it''s only a matter of time until they have enough elementals to overcome our defenses.', `VerifiedBuild`=19034 WHERE `ID`=13519; -- The Twilight's Hammer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='The Jadefire satyrs of Felwood have found their way into Darkshore, tainting the land, water, and creatures they encounter. You''ve seen what their corruption has done to my people and their homes. If we do not turn back the satyrs, all of us will share that fate.$B$BWithin the cave to the east is Sharax the Defiler, the satyr responsible for the ills of the Blackwood. Slay him, $n, and free us from his influence. Show the satyr that the Blackwood will not lay down and die so easily.', `VerifiedBuild`=19034 WHERE `ID`=13546; -- The Defiler
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='Aetherion is almost in our world, but he can still be dealt with!$B$BAt the end of the dock floats a ritual orb. I want you to use it to complete the ritual, beckoning the elemental lord down from his vortex.$B$BTrust me, $n, I and the other spirits that you have freed will greatly weaken Aetherion. However, it will be up to you to finish him off for good and save the Kaldorei people of Darkshore from utter destruction.$B$BDeliver his essence to Corvine Moonrise at the refugee camp so he will know.', `VerifiedBuild`=19034 WHERE `ID`=13558; -- Call Down the Thunder
