UPDATE `quest_template` SET `QuestDescription`='My duty here has been fulfilled as best it can.  Send word to Malfurion that I''ll be joining him soon.$B$BGood luck to you, $n.  Good luck to all of us.', `VerifiedBuild`=19034 WHERE `ID`=13585; -- Sworn to Protect
