UPDATE `quest_template` SET `RewardBonusMoney`=9900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=13595; -- Of Their Own Design
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='We''re not fully aware of the intentions of the Twilight''s Hammer cultists to the southwest.  We fear an attack on Lor''danel, however their motives might go well beyond that.$B$BI need you to go to the Twilight Encampment and get your hands on their plans.  Hurry, $n.  We might not have much time.', `VerifiedBuild`=19034 WHERE `ID`=13596; -- Twilight Plans
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (13602 /*Naga of the Strand*/, 13624 /*A Squad of Your Own*/, 13630 /*The Reason Why*/, 13632 /*Rear Guard Duty*/, 13683 /*Stopping the Rituals*/, 13869 /*Recover the Remains*/, 26444 /*Destroy the Legion*/, 26446 /*Reclaiming Felfire Hill*/, 26454 /*A Shameful Waste*/, 26473 /*Bathran's Hair*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=-1, `QuestDescription`='Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.$B$BThere''s an old legend from Grizzly Hills about a maiden cursed with a frog''s form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $n. Otherwise, you''ll catch warts.', `VerifiedBuild`=19034 WHERE `ID` IN (13603 /*A Blade Fit For A Champion*/, 13746 /*A Blade Fit For A Champion*/, 13752 /*A Blade Fit For A Champion*/, 13757 /*A Blade Fit For A Champion*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=146400, `QuestDescription`='Freya''s Sigil is going to be one of the tougher ones, I reckon.$B$BAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil''s integrity will be compromised.$B$BSparing the elders, however, means that Freya will be more powerful when you face her.$B$BWhat can I say, $n.  We''re stuck between a rock and hard place.', `VerifiedBuild`=19034 WHERE `ID` IN (13606 /*Freya's Sigil*/, 13821 /*Heroic: Freya's Sigil*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=146400, `QuestDescription`='Thorim''s not himself, $n.  He''s come under a dark influence.$B$BAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.$B$BYe can''t let him be overcome by this impostor''s spell.  If he does, the location of his sigil might forever be lost!$B$BYer going to have to beat some sense into him and yer going to have to do it quick.$B$BAs always, the Archivum Console will give ye all the gory details... even the ones ye don''t like.', `VerifiedBuild`=19034 WHERE `ID` IN (13610 /*Thorim's Sigil*/, 13823 /*Heroic: Thorim's Sigil*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardFactionID1`=76, `VerifiedBuild`=19034 WHERE `ID` IN (13612 /*Mor'shan Defense*/, 13613 /*Rescue the Fallen*/, 13615 /*Empty Quivers*/, 13618 /*Find Gorat!*/, 13619 /*Final Report*/, 13628 /*Got Wood?*/, 13640 /*Management Material*/, 13651 /*Needs a Little Lubrication*/, 13730 /*Playing With Felfire*/, 13801 /*Dead Elves Walking*/, 13805 /*Pierce Their Heart!*/, 13806 /*Demon Duty*/, 13865 /*Wet Work*/, 13871 /*Security!*/, 13883 /*Lousy Pieces of Ship*/, 13890 /*Keep the Fires Burning*/, 13901 /*Deep Despair*/, 13920 /*Before You Go...*/, 13942 /*Set Us Up the Bomb*/, 13943 /*Breathing Room*/, 13947 /*Blastranaar!*/, 13967 /*Thinning the... Herd?*/, 13980 /*They're Out There!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=146400, `QuestDescription`='You really did it, $n.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.$B$BYou best hurry, $g lad:lass;.  Time is of the essence.', `VerifiedBuild`=19034 WHERE `ID` IN (13614 /*Algalon*/, 13818 /*Heroic: Algalon*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `QuestDescription`='Curse that death knight for breaking my sword!$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice''s exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter''s Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $n.', `VerifiedBuild`=19034 WHERE `ID` IN (13616 /*The Edge Of Winter*/, 13743 /*The Edge Of Winter*/);
UPDATE `quest_template` SET `RewardBonusMoney`=1020, `AllowableRaces`=18875469, `QuestDescription`='$n, I have a friend who could make good use of particular talents. His name is Talen and he''s an archaeologist of sorts. Recently he''s been fascinated with the upheaval of the old city of Zoram and its treasures.$B$BIf you''re willing to lend him a hand, you can find him at the Blackfathom Camp down the path to the west.', `VerifiedBuild`=19034 WHERE `ID`=13617; -- West to the Strand
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardFactionID1`=76, `VerifiedBuild`=19034 WHERE `ID` IN (13620 /*To Dinah, at Once!*/, 13923 /*To Hellscream's Watch*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardFactionID1`=76, `VerifiedBuild`=19034 WHERE `ID`=13621; -- Gorat's Vengeance
UPDATE `quest_template` SET `RewardBonusMoney`=2520, `AllowableRaces`=18875469, `QuestDescription`='Quickly, $n. I will put the Bathran''s Hair into this bag, but you must deliver it to my master, Orendil Broadleaf. You will find him at Maestra''s Post, just south down the road on the left.$B$BBut beware, we''ve received reports that the post is under attack from the Horde!', `VerifiedBuild`=19034 WHERE `ID`=13623; -- Delivery for Orendil
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=73200, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=13625; -- Learning The Reins
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9900, `FlagsEx`=8, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=13626; -- Respect for the Fallen
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=146400, `FlagsEx`=8, `QuestDescription`='We''d best hurry now, $n.  We''re going to have to transmit the reply-code from Dalaran.$B$BTake it to Rhonin, I will meet you there.', `VerifiedBuild`=19034 WHERE `ID` IN (13631 /*All Is Well That Ends Well*/, 13819 /*Heroic: All Is Well That Ends Well*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `Flags`=8, `VerifiedBuild`=19034 WHERE `ID`=13635; -- South Gate Status Report
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='Now that we know there''s no truth to the Black Knight''s stories, we must find a way to connect him to the murdered knights.$B$BI know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer''s crystal, found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, $n, and bring me the crystal it holds.', `VerifiedBuild`=19034 WHERE `ID`=13641; -- The Seer's Crystal
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9900, `AllowableRaces`=18875469, `QuestDescription`='The concoction is not quite complete; it must be bathed within the Light of Elune before we can even think about giving it to the child.$B$BThere is a known location just to the west at Lake Falathim where the goddess''s moonlight always touches down, day or night. Please, $n, I implore you for the sake of Relara, take the concoction and bathe it in Elune''s radiance.$B$BBut beware, strange things have befallen the area of the lake, and I fear that it is no longer safe to go there.', `VerifiedBuild`=19034 WHERE `ID`=13642; -- Bathed in Light
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `QuestDescription`='The crystal will reveal the truth about how three of the tournament''s combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip.$B$BIf indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, $n, for we must be certain these deaths were not accidental.', `VerifiedBuild`=19034 WHERE `ID`=13643; -- The Stories Dead Men Tell
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=13200, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (13644 /*That Which Has Risen*/, 26472 /*Insane Druids*/);
UPDATE `quest_template` SET `RewardBonusMoney`=2760, `AllowableRaces`=18875469, `QuestDescription`='I would ask you to deliver the gem directly to Raene Wolfrunner. Last I heard, she was still in Astranaar to the southeast.$B$BAt least the road between here and there is still relatively safe, so it should be a simple matter of following it there. Of course, if you''d rather, I believe that Sentinel Avana would be willing to loan you one of her nightsabers to swiftly make the trip.$B$BWhatever you choose, good health to you, $n. May our paths cross again soon.', `VerifiedBuild`=19034 WHERE `ID`=13645; -- To Raene Wolfrunner
UPDATE `quest_template` SET `RewardBonusMoney`=1140, `AllowableRaces`=18875469, `QuestDescription`='You have been of great assistance to us, $n. Without you, we would have been wiped out by now.$B$BIt would be my pleasure to offer you one of my nightsabers anytime to ride to Astranaar up and to the southeast. I''m sure that you have very important business to attend to there.$B$BI would consider it a great kindness if you would speak with my sister, Sentinel Luara, when you arrive to tell her that I am well.$B$BJust speak to me again when you are ready to go, and anytime that you need a ride it is yours.', `VerifiedBuild`=19034 WHERE `ID`=13646; -- Astranaar Bound
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardFactionID1`=76, `VerifiedBuild`=19034 WHERE `ID` IN (13653 /*Crisis at Splintertree*/, 13712 /*To the Rescue!*/, 13797 /*Dirty Deeds*/, 13848 /*Bad News Bear-er*/, 13974 /*Tweedle's Tiny Package*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=91500, `QuestDescription`='We must put an end to the Black Knight''s scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered.$B$BBy now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, $n.$B$BUse my argent charger for the battle. It''s housed in the stables.$B$BSpeak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.', `VerifiedBuild`=19034 WHERE `ID`=13664; -- The Black Knight's Fall
