UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='I heard an interesting story from one of the Orgrimmar valiants.$B$BIn southern Crystalsong Forest, overlooking the Crystal Vice''s exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.$B$BBring it to the center of Winter''s Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.$B$BProve your worth and earn the weapon that she has guarded for so long, $n.', `VerifiedBuild`=19034 WHERE `ID`=13675; -- The Edge Of Winter
