UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7200, `AllowableRaces`=16777217, `QuestDescription`='You''ve proven yourself worthy of competing under the banner of Stormwind, $n. Now, you should introduce yourself to Marshal Jacob Alerius, who leads the Stormwind delegation. As Stormwind''s grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant.$B$BIt has been an honor working with you, $n, and I wish you luck in the competition ahead.', `VerifiedBuild`=19034 WHERE `ID`=13684; -- A Valiant Of Stormwind
