UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='I''ve heard that the Alliance champions are seeking after ancient blades for their warriors. We can''t afford to let them have that kind of advantage.$B$BThere''s an old legend from Grizzly Hills about a maiden cursed with a frog''s form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, $n. Otherwise, you''ll catch warts.', `VerifiedBuild`=19034 WHERE `ID` IN (13762 /*A Blade Fit For A Champion*/, 13768 /*A Blade Fit For A Champion*/, 13773 /*A Blade Fit For A Champion*/, 13778 /*A Blade Fit For A Champion*/, 13783 /*A Blade Fit For A Champion*/);
