UPDATE `quest_template` SET `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `QuestDescription`='The coliseum is perched in the most dangerous part of the world, $n. The territory we''ve taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.$B$BGo forth into Icecrown and slay any cultists you encounter. ', `VerifiedBuild`=19034 WHERE `ID`=13789; -- Taking Battle To The Enemy
UPDATE `quest_template` SET `RewardBonusMoney`=73200, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (13790 /*Among the Champions*/, 13793 /*Among the Champions*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='Now that the demon gates have been destroyed, the power of the forest must be replenished. The Forest Heart must be retrieved!$B$BGaivan Shadewalker, a powerful druid of the claw, has gone southwest, past Felfire Hill, to the Dor''Danil Barrow Den. Therein rests the Forest Heart. It is protected by the druids of Ashenvale deep below the ground.$B$BSeek out Gaivan and tell him of what has transpired, $n.', `VerifiedBuild`=19034 WHERE `ID`=13792; -- The Shadewalker
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=12300, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='You must get the Forest Heart to Gnarl at all costs!$B$BDown at the bottom of the Dor''Danil Barrow Den it sits, corrupted by the Horde. Only Gnarl can cleanse it.$B$BIn order to move it, though, you''ll need a Power of Nature. If you collect enough untainted spirits from the Severed druids and keepers, the spirits can be combined into a Power of Nature.$B$BGood luck, $n!', `VerifiedBuild`=19034 WHERE `ID`=13796; -- The Forest Heart
