UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=13800, `AllowableRaces`=18875469, `QuestDescription`='The fires are mostly contained, but we have to do something about those wind riders!$B$BQuick, $n, you have to jump into one of our glaive throwers and return fire!', `VerifiedBuild`=19034 WHERE `ID`=13853; -- Return Fire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=33555378, `QuestDescription`='Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy''s stronghold of Icecrown Citadel.$B$BIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp''rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King''s minions.$B$BDo not fear the masses of boneguard footmen, $n, for they can easily be trampled under your horse''s hooves.', `VerifiedBuild`=19034 WHERE `ID` IN (13856 /*At The Enemy's Gates*/, 13857 /*At The Enemy's Gates*/, 13858 /*At The Enemy's Gates*/, 13859 /*At The Enemy's Gates*/, 13860 /*At The Enemy's Gates*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73200, `AllowableRaces`=18875469, `QuestDescription`='Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy''s stronghold of Icecrown Citadel.$B$BIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp''rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King''s commanders.$B$BDo not fear the masses of boneguard footmen, $n, for they can easily be trampled under your horse''s hooves.', `VerifiedBuild`=19034 WHERE `ID`=13861; -- Battle Before The Citadel
