UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `VerifiedBuild`=19034 WHERE `ID`=25223; -- Trial By Fire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Our army needs water, and luckily the elements gave us plenty of that when the cataclysm hit.  The water that filled up the canyon to the southwest should do the trick.$b$bUnfortunately, the corpses of thunder lizards still sit at the bottom of the canyon, and their electrical discharges are a bit too dangerous.  I''ve got grunts that can lift them out of the water, but we need someone agile enough to attach the other end of the rope.  Are you my $g man: woman;, $n?', `VerifiedBuild`=19034 WHERE `ID`=25236; -- Thunder Down Under
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=780, `Flags`=136314888, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (25243 /*She Loves Me, She Loves Me NOT!*/, 25244 /*What Kind of Name is Candy, Anyway?*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AreaGroupID`=0, `QuestDescription`='$n, this is it! Thrall''s down at the Gallywix Docks fighting the Trade Prince right now!$B$BYou gotta jump into your Ultimate Footbomb Uniform and get over there!', `VerifiedBuild`=19034 WHERE `ID`=25251; -- Final Confrontation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `AreaGroupID`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25257; -- Ghislania
UPDATE `quest_template` SET `QuestDescription`='One of our more useful shaman, Margoz, knows more of the Burning Blade''s corruption.  He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists.$B$BBefore you go to Skull Rock, speak with Margoz.  He is wise and his council is valued.$B$BHe is camped to the southeast, between the coast and Drygulch Ravine.$B$BFollow his advice, but whatever Margoz says, $n, I still want you to crush those cultists!', `VerifiedBuild`=19034 WHERE `ID`=25261; -- Margoz
UPDATE `quest_template` SET `QuestDescription`='$n.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.$B$BBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.$B$BGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.', `VerifiedBuild`=19034 WHERE `ID`=25262; -- Skull Rock
UPDATE `quest_template` SET `LogTitle`='Arnak Fireblade', `LogDescription`='Bring an Example Collar to Arnak Fireblade in Orgrimmar.', `QuestDescription`='The Searing Collars you brought me are powerful demonic implements.  Divining their origin is, I''m afraid, beyond my skills as a shaman.  We will need a warlock to study them.$B$BTake a searing collar to Arnak Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.$B$BYou may find Arnak in Orgrimmar in the Cleft of Shadow.', `VerifiedBuild`=19034 WHERE `ID`=25263; -- Neeru Fireblade
UPDATE `quest_template` SET `RewardBonusMoney`=120, `QuestDescription`='We just can''t thank you enough for all that you''ve done. Now we can all get off of this island before it kills us!$B$BThrall is going to want to speak with you first, $n. I''ll rocket you over there.$B$BSee you on the ship!', `VerifiedBuild`=19034 WHERE `ID`=25265; -- Victory!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=120, `LogDescription`='Deliver the Sealed Package to the Darkspear Loyalist on the docks at Bladefist Bay in Durotar.', `QuestDescription`='The goblins and the Horde have accomplished too much together to part ways now, $c. I intend for the Bilgewater Cartel to become part of the Horde.$B$BI have something that I want you to deliver to the new warchief. Give this package to my Darkspear friend on the dock at Bladefist Bay in Durotar. She will help you to get into Orgrimmar safely.$B$BSpeak with Sassy Hardwrench on the ship when you are ready to set sail.$B$BUntil we meet again. Aka''Magosh, a blessing on you and yours, $n!', `VerifiedBuild`=19034 WHERE `ID`=25266; -- Warchief's Emissary
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=120, `RewardChoiceItemID1`=118217, `RewardChoiceItemID2`=118219, `RewardChoiceItemID3`=118218, `LogTitle`='Message for Vol''jin', `LogDescription`='Deliver the SI:7 Emblem to Vol''jin at Grommash Hold in Orgrimmar.', `QuestDescription`='<The Darkspear loyalist opens the package and reads the letter within. As she finishes the note from Thrall, a hint of a fanged smile appears on her face.>$B$BYa should take dis directly to da Warchief inside Orgrimmar. Be sure ta let Vol''jin know dat de package be from Thrall.$B$BTake me raptor. Hurry, little one, dere be no time ta waste!', `VerifiedBuild`=19034 WHERE `ID`=25267; -- Message for Garrosh
UPDATE `quest_template` SET `RewardBonusMoney`=36900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25268; -- The Voice of Goldrinn
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25269 /*The Voice of Lo'Gosh*/, 26057 /*The Wavespeaker*/, 27442 /*The War Has Many Fronts*/, 27722 /*Warchief's Command: Deepholm!*/, 28296 /*Meetup with the Caravan*/, 28557 /*Warchief's Command: Uldum!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=33555378, `QuestDescription`='The shrine has been taken, $n. We need the tenacity of Lo''Gosh now more than ever.$B$BThese defilers - the lice-ridden wolf-men running rampant over the shrine - dishonor the memory of the wolf god. They arrived with the Twilight''s Hammer, howling with their own twisted religion. They seek to corrupt noble Lo''Gosh to fit their own warped pantheon.$B$BKill them! Kill them and bring me the tools of their worship, a kind of polluted incense. I must understand what they want with the shrine...', `VerifiedBuild`=19034 WHERE `ID`=25270; -- Howling Mad
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25271 /*Goldrinn's Ferocity*/, 25278 /*Cleaning House*/, 25536 /*Cold Welcome*/, 25537 /*Art of Attraction*/, 25538 /*Odor Coater*/, 25539 /*Clamming Up*/, 25540 /*Bellies Await*/, 25579 /*Caught Off-Guard*/, 25580 /*Swift Approach*/, 25581 /*An Occupation of Time*/, 25582 /*A Better Vantage*/, 25583 /*Upon the Scene of Battle*/, 25748 /*Clear Goals*/, 25749 /*Not Entirely Unprepared*/, 25751 /*Properly Inspired*/, 25752 /*Swift Action*/, 25753 /*Fallen But Not Forgotten*/, 25754 /*Gauging Success*/, 25892 /*Losing Ground*/, 25894 /*Hostile Waters*/, 25895 /*Come Prepared*/, 25897 /*Unfurling Plan*/, 25898 /*Honor and Privilege*/, 25918 /*Hopelessly Gearless*/, 25919 /*Body Blows*/, 25920 /*Still Valuable*/, 25922 /*Waking the Beast*/, 26015 /*Phosphora Hunting*/, 26017 /*A Lure*/, 26018 /*Coldlights Out*/, 26103 /*Bio-Fuel*/, 27716 /*Piece of the Past*/);
UPDATE `quest_template` SET `RewardBonusMoney`=73800, `AreaGroupID`=0, `AllowableRaces`=33555378, `QuestDescription`='The actions of these feral dogs are beginning to make sense. The Twilight''s Hammer fears the power of the ancients. They do not want Lo''Gosh to return.$B$BSo they''ve summoned their own wolf god - a perversion of what once was. "Lycanthoth," the corruptor.$B$B$n, Lycanthoth is but a shadow of Lo''Gosh''s power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo''Gosh!', `VerifiedBuild`=19034 WHERE `ID`=25272; -- Lycanthoth the Corruptor
UPDATE `quest_template` SET `RewardBonusMoney`=73800, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='I think I understand what''s happening here. The Twilight''s Hammer fears that the ancients may someday rise up to oppose them. They''ll do anything to stop the return of Goldrinn.$B$BThis "Lycanthoth" is a twisted version of our beloved wolf god, summoned by the Twilight''s Hammer to replace him.$B$BBah! It is but a shadow of Goldrinn''s power. $n, kill this beast so that the true ancient can return. Take this incense and burn it in the Maw of Lycanthoth east of here. Slay that beast and free Goldrinn!', `VerifiedBuild`=19034 WHERE `ID`=25273; -- Lycanthoth the Corruptor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='You''re here at last, $n.  Just in time as well.$B$BNews of Ragnaros'' emergence has spurred a large wave of recruits to seek membership in the Twilight''s Hammer.$B$BIf you''re to infiltrate the cult, the time is now.  We will need recruitment papers -- signed in blood by a referring Twilight member.  Lure one of the new recruits away from the group and hit them with this blackjack.$B$BIf you''re lucky, you''ll be able to steal his recruitment papers.  Bring them back to me and we''ll do our best to alter them.', `VerifiedBuild`=19034 WHERE `ID`=25274; -- Signed in Blood
UPDATE `quest_template` SET `QuestDescription`='Your people be workin'' on the terraforming of Azshara. The land will be remade in the image of the Horde so that all know that Kalimdor be ours!$B$BGo north through the city. On the far side of the Valley of Honor you be findin'' the Orgrimmar Rear Gate. Report to Labor Captain Grabbit outside the gates.$B$BFor the Horde!!!', `VerifiedBuild`=19034 WHERE `ID`=25275; -- Report to the Labor Captain
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `QuestDescription`='There.  Not my best work, but certainly not my worst.  You will be known as "$ndamus" among the cultists.$B$BThese papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors.$B$BGo to the proving grounds and show these to Condenna the Pitiless.  She''s separating the wheat from the chaff.$B$BShow her what you''re made of.', `VerifiedBuild`=19034 WHERE `ID`=25276; -- Your New Identity
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=33555378, `QuestDescription`='We are well on our way to returning the shrine to its former glory, $n. But there is some housecleaning to take care of. On the other side of this meadow, some ogre squatters are setting up camp, led by a thick-headed chunk of ugly by the name of Gar''gol.$B$BKill Gar''gol''s minions and see if we can''t send him packing.', `VerifiedBuild`=19034 WHERE `ID`=25277; -- Cleaning House
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='Yes, $n. I am Goldrinn, the one called "Lo''Gosh" in your tongue. Your persistence in the face of fear has unbound me from twilight''s grasp.$B$BMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.$B$BReturn to Takrik and continue your work here in Hyjal. I will have need of you again soon.', `VerifiedBuild`=19034 WHERE `ID`=25279; -- The Shrine Reclaimed
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='Yes $n, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight''s grasp.$B$BMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.$B$BReturn to Ian and continue your work here in Hyjal. I will have need of you again soon.', `VerifiedBuild`=19034 WHERE `ID`=25280; -- The Shrine Reclaimed
UPDATE `quest_template` SET `RewardMoney`=35, `RewardMoneyDifficulty`=3, `LogDescription`='Test the Scuttling Mechano-Tank''s maneuverability.', `VerifiedBuild`=19034 WHERE `ID`=25289; -- One Step Forward...
UPDATE `quest_template` SET `ItemDropQuantity4`=1, `AllowableRaces`=18875469, `QuestDescription`='It''s getting difficult to keep the cultists out of the public eye and rumors are spreading across the city. I want you to join the cult and learn as much as you can.$B$BApproach one of the doomsayers in Old Town and tell them you wish to join their group. The doomsayer will likely give you clothing and instructions to meet with other cultists in one of the group''s hideouts. Follow those instructions, $n. It''s the only way to gain their confidence.', `VerifiedBuild`=19034 WHERE `ID`=25290; -- Infiltrating the Cult
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `VerifiedBuild`=19034 WHERE `ID` IN (25291 /*Twilight Training*/, 25411 /*A New Master*/, 25430 /*Emerald Allies*/, 25900 /*Making Contact*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=14700, `QuestDescription`='<Nato pulls you aside and speaks in a whisper.>$B$B$n, I have removed the bullet from Gann''s chest, but the bubbles in his blood tell me all I need to know. His lungs are punctured, and the wound grows septic. He is not long for this world.$B$BTake this. It''s the bullet that killed him. His family will want to know what became of their youngest warrior.$B$BSeek out Alto Stonespire. He is posted in Dustwallow Marsh. Go northeast, and follow the roads to Brackenwall Village.', `VerifiedBuild`=19034 WHERE `ID`=25292; -- Next of Kin
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='It''s me, $n, Ortell!$B$BDon''t look directly at the outhouse... you''ll give away my position.$B$BEverything''s going according to plan then?  Excellent!$B$BI''m going to need you to obtain some intelligence while you''re here.  It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy''s next move.', `VerifiedBuild`=19034 WHERE `ID`=25296; -- Gather the Intelligence
UPDATE `quest_template` SET `RewardBonusMoney`=55500, `VerifiedBuild`=19034 WHERE `ID` IN (25297 /*From the Mouth of Madness*/, 25404 /*If You're Not Against Us...*/, 25620 /*The Revered Lady*/, 25794 /*Undersea Sanctuary*/, 25812 /*Spelunking*/, 25824 /*Debriefing*/, 26000 /*Spelunking*/, 26007 /*Debriefing*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=73800, `VerifiedBuild`=19034 WHERE `ID` IN (25298 /*Free Your Mind, the Rest Follows*/, 25467 /*Kliklak's Craw*/);
UPDATE `quest_template` SET `RewardBonusMoney`=36900, `VerifiedBuild`=19034 WHERE `ID` IN (25300 /*The Eye of Twilight*/, 25301 /*Mastering Puppets*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=11100, `VerifiedBuild`=19034 WHERE `ID`=25304; -- The Battle of Sardor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (25308 /*Seeds of Discord*/, 25328 /*Gar'gol's Gotta Go*/, 25440 /*Fathom-Lord Zin'jatar*/, 25599 /*Cindermaul, the Portal Master*/, 25776 /*Sethria's Demise*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25310; -- The Greater of Two Evils
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=18600, `VerifiedBuild`=19034 WHERE `ID`=25312; -- Return to Duskwhisper
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AreaGroupID`=0, `QuestDescription`='Listen, $n.  I found out what they''re doing with Jarod Shadowsong.  He''s scheduled to be sacrificed by the ogres of the Twilight''s Hammer as part of this year''s initiation.$B$BI heard that the initiate charged with delivering the speech ahead of the sacrifice is an ogre named Okrog, but get this: you were a close second.$B$BWe need you to deliver that speech if we''re to free Jarod.  Don''t worry -- I''ll write you some cue cards -- just make sure Okrog has an "accident" as he leaves the Seat of the Chosen.', `VerifiedBuild`=19034 WHERE `ID`=25314; -- Speech Writing for Dummies
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=111000, `QuestDescription`='You''re finally ready, $ndamus.$B$BI am so proud of you and all you''ve accomplished.$B$BToday you will deliver a speech in front of your peers and inspire them to crush our enemies until Hyjal is nothing but a pile of ash.$B$BRemember, $ndamus.  It''ll be important to read your audience''s emotions and use words that best address those emotions.', `VerifiedBuild`=19034 WHERE `ID`=25315; -- Graduation Speech
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `QuestDescription`='$n!  We''ve heard much about you and your previous accomplishments.$B$BIt is good that you''ve come here just as Azeroth finds itself in a time of great need.$B$BDeathwing''s minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world.$B$BAronus will take you to join Malfurion''s forces in Hyjal. Lend them what help you can.', `VerifiedBuild`=19034 WHERE `ID`=25316; -- As Hyjal Burns
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='Make no mistake about this, $n.  The outcome of this war will determine the very survival of our world as we know it.$B$BThe Twilight''s Hammer has become more powerful than ever with Deathwing''s return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.$B$BIt is time we beat back the enemy.  It is time we crushed the Twilight''s Hammer.', `VerifiedBuild`=19034 WHERE `ID`=25319; -- War on the Twilight's Hammer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `QuestDescription`='I''ve heard about you, $n, and the news you brought from the south.  The battle has reached a stalemate.$B$BOne that I fear is about to be broken by the Firelord''s reawakening.$B$BThat is unless we tip the scales in our favor in some way.$B$BThere is a scout that was captured by the Twilight''s Hammer.  I believe she was in possession of valuable intelligence. Find her in the Twilight camp to the west.', `VerifiedBuild`=19034 WHERE `ID`=25320; -- The Captured Scout
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `QuestDescription`='I''d been scouting behind enemy lines for nearly a day when they caught me.$B$BThis attack on our frontlines is not what it appears, $n.$B$BI''ll give you all the details, but first let''s find a way to get me out of here.$B$BOnly the overseers carry keys to these cages.$B$BFrom what I recall, they''re in the middle of the crater, in the thick of it.$B$BSee if you can get a key off of one of them.', `VerifiedBuild`=19034 WHERE `ID`=25321; -- Twilight Captivity
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=73800, `Flags`=136, `VerifiedBuild`=19034 WHERE `ID`=25323; -- Flamebreaker
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `QuestDescription`='The Twilight''s Hammer wants to free Fandral Staghelm?$B$BMalfurion suspected his corruption ran deep... this just cements it.$B$BAt any rate we cannot allow our enemies to get their hands on such a powerful arch druid.$B$BI''ve a plan, $n.  We will move the prisoner through the Emerald Dream.  It will be risky, but with all the cultists present here it might be the only way to guarantee our success.$B$BSpeak to Saynna Stormrunner inside the Barrow Dens to the northeast.  ', `VerifiedBuild`=19034 WHERE `ID`=25324; -- A Prisoner of Interest
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `QuestDescription`='Alysra''s plan might be necessary, $n.  I don''t know how much longer we can hold off the cultists.$B$BFandral Staghelm is bound by powerful spells.  He won''t be able to escape you, even inside the Emerald Dream.$B$BBeware, though, for all we know the nightmare has spread to this part of the world inside the dream.$B$BTake Fandral to the surface and hand him to Alysra.  Let us hope he''s more secure in Moonglade than he is here.', `VerifiedBuild`=19034 WHERE `ID`=25325; -- Through the Dream
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `VerifiedBuild`=19034 WHERE `ID` IN (25330 /*Waste of Flesh*/, 25334 /*The Looming Threat*/, 25597 /*Commander Jarod Shadowsong*/, 25638 /*A Desperate Plea*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=27600, `VerifiedBuild`=19034 WHERE `ID` IN (25333 /*Might of the Sentinels*/, 26117 /*For Southshore*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=23400, `VerifiedBuild`=19034 WHERE `ID`=25337; -- Hippogryph Muisek
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='The wandering forest walkers that can be found meandering through the forest are our next target, $n. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.$B$BSoon we will be able to use this power for our own benefit.$B$BFind three wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.', `VerifiedBuild`=19034 WHERE `ID`=25338; -- Treant Muisek
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=33555378, `QuestDescription`='In my day, I was a seasoned hunter. There wasn''t any creature around that I feared. Until...$B$BI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.$B$BEven now, I can still hear their cries echoing...$B$BI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.$B$BThe Northspring harpies can be found to the west of here. $n, get my revenge. ', `VerifiedBuild`=19034 WHERE `ID`=25339; -- Vengeance on the Northspring
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=21000, `VerifiedBuild`=19034 WHERE `ID` IN (25341 /*The Gordunni Orb*/, 25449 /*The Mark of Quality*/, 25452 /*The Mark of Quality*/);
UPDATE `quest_template` SET `QuestDescription`='$n, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.$B$BHere is the muisek, $n. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.', `VerifiedBuild`=19034 WHERE `ID`=25345; -- Faerie Dragon Muisek
UPDATE `quest_template` SET `RewardBonusMoney`=22200, `VerifiedBuild`=19034 WHERE `ID`=25350; -- The Lost Apprentice
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=18875469, `QuestDescription`='Wonderful work in the hovel, $n. I prayed at the shrine while you were away, and in my visions, Goldrinn was watching you closely.$B$BBut we''ve been on the defensive too long: it''s time to foil the Twilight''s Hammer directly.$B$BFly up to the Lightning Ledge and disrupt their operation. Kill the stormcallers and the monstrosities they''re preparing to unleash!', `VerifiedBuild`=19034 WHERE `ID`=25352; -- Sweeping the Shelf
UPDATE `quest_template` SET `RewardBonusMoney`=73800, `AllowableRaces`=18875469, `QuestDescription`='When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don''t understand what the ancient has planned...$B$B$n, go to the Lightning Ledge. Twilight''s Hammer has been running experiments with something called a "Lightning Channel." Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind... ', `VerifiedBuild`=19034 WHERE `ID`=25353; -- Lightning in a Bottle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.$B$BSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!$B$BFly up to the Lightning Ledge and demolish the Twilight''s Hammer there. Crush them, $n, slay their creations and hurl their bodies from the mountainside!', `VerifiedBuild`=19034 WHERE `ID`=25354; -- Sweeping the Shelf
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=33555378, `QuestDescription`='Lo''Gosh granted me a vision while you were in the hovel, $n. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo''Gosh feels this is of utmost importance. We must not fail the ancient.$B$BUpon the Lightning Ledge, Twilight''s Hammer has been experimenting with devices they call "Lightning Channels."$B$BInvestigate one of these channels, then use this totem to summon the Spirit of Lo''Gosh and learn what the ancient is planning...', `VerifiedBuild`=19034 WHERE `ID`=25355; -- Lightning in a Bottle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=553648264, `VerifiedBuild`=19034 WHERE `ID` IN (25357 /*Buy Us Some Time*/, 25546 /*Traveling on Our Stomachs*/, 25942 /*Buy Us Some Time*/, 25943 /*Traveling on Our Stomachs*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='This is no mere natural occurrence, $n.  There must be a twilight presence behind our lines that we haven''t accounted for.$B$BIt''s possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.$B$BSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy''s illusions.$B$BFeed them the juniper berries that grow nearby to gain their trust.', `VerifiedBuild`=19034 WHERE `ID`=25370; -- Inciting the Elements
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=136, `QuestDescription`='The firestorms up ahead are unbound elementals in the purest form - something I didn''t think could exist outside their own plane. Only very skilled summoners could unleash something like this.$B$B$n, head into the Inferno and seek out Twilight Inferno Lords. They''ve got to be summoning in reinforcements as we speak. Silence them... For good!', `VerifiedBuild`=19034 WHERE `ID`=25382; -- Disrupting the Rituals
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `RewardItem1`=0, `RewardAmount1`=0, `VerifiedBuild`=19034 WHERE `ID`=25388; -- A Case of Crabs
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `VerifiedBuild`=19034 WHERE `ID` IN (25395 /*The Stolen Keg*/, 25721 /*Fight the Flood*/, 25725 /*Fenbush Berries*/, 25726 /*A Dumpy Job*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=21000, `Flags`=8, `VerifiedBuild`=19034 WHERE `ID` IN (25396 /*Tears of Stone*/, 25397 /*The Land, Corrupted*/);
