UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardSpell`=140428, `Flags`=3145728, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25446; -- Frogs Away!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=21000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25447 /*Signs of Change*/, 27167 /*A Mighty Hunger*/, 27168 /*Those That Couldn't Let Go*/, 27211 /*Propaganda War*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=26100, `VerifiedBuild`=19034 WHERE `ID`=25448; -- The Northspring Menace
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=27600, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25458; -- General Skessesh
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=5550, `VerifiedBuild`=19034 WHERE `ID`=25463; -- Report to Silvia
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `QuestDescription`='Ragnaros is not the only powerful elemental that has re-emerged into our world.$B$BThe dreaded Baron Geddon is leading the onslaught and we must put an end to this rampage.$B$BThe Flameseer''s Staff has proven powerful.  Perhaps it is powerful enough to weaken him to the point where our arch druids can bind him where he stands.$B$BGo, $n and be careful.  Baron Geddon is a vengeful and treacherous being.', `VerifiedBuild`=19034 WHERE `ID`=25464; -- The Return of Baron Geddon
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=22200, `Flags`=8, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25468; -- Forces of Nature: Faerie Dragons
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25469 /*Forces of Nature: Mountain Giants*/, 26482 /*True Power of the Rod*/, 26532 /*Shadra the Venom Queen*/, 27291 /*Peace at Last*/, 27429 /*Raze Direhorn Post!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=22200, `FlagsEx`=8, `VerifiedBuild`=19034 WHERE `ID`=25475; -- Find OOX-22/FE!
UPDATE `quest_template` SET `RewardBonusMoney`=44400, `Flags`=2, `VerifiedBuild`=19034 WHERE `ID`=25476; -- Rescue OOX-22/FE!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='$n, these fiends from the Twilight''s Hammer are attempting to scourge this whole mountain clean of all life. Even now they trail behind this inferno, leaving death and ash in their wake.$B$BArch Druid Hamuul Runetotem is behind the fires, trying to salvage the wilderness before it''s blotted permanently from the map. Travel southeast, through The Inferno and down the road beyond. Find and aid the Arch Druid.$B$BOn your way there, clear the roads by killing any Charbringers that you find.', `VerifiedBuild`=19034 WHERE `ID`=25490; -- Smashing Through Ashes
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Vol''jin be gatherin'' his gear and readyin'' de warriors. He ask me to tell ya to meet with him an'' Vanira on de island to de east.$B$BFrom dere, he and de warriors will launch de attack on Zalazane. May de ancestors go wit'' you, $n. Without ya, dis campaign would only be a shadow of what it become. Speak to Handler Marnlek, just to de south, an'' he give you a bat to fly out to de stagin'' area.', `VerifiedBuild`=19034 WHERE `ID`=25495; -- Preparin' For Battle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `QuestDescription`='I don''t know if you''ve picked up on this, but there''s a bit of a rivalry between the ogre members of the Twilight''s Hammer and the rest of us.$B$BFor me... it''s personal.$B$BThis one ogre called Gromm''ko has a pet raptor named "Butcher."  He''s taken out the last three of my corehound pups.$B$BI think this last one will fare differently.  He''s got a real killer''s instinct.$B$BGo to the Seat of the Chosen and challenge Gromm''ko to a match between our two beasts.  Humiliate him for me, $ndamus.', `VerifiedBuild`=19034 WHERE `ID`=25496; -- Grudge Match
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Hey there, $n. I''m Pozzik, world-renowned rocket car pilot. Welcome to my Speedbarge.$B$BI share your concerns about helping all of Thousand Needles. It''s my firm belief that the Speedbarge is the best hope for the entire region.$B$BPerhaps you could help us out a little bit here? I''ll make sure that you''re equipped with what you need to tackle everything else.$B$BAs to that, if you could just run this list of parts over to Razzeric in his shop, you''ll be well on your way.', `VerifiedBuild`=19034 WHERE `ID`=25505; -- Do Me a Favor?
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `QuestDescription`='<The Arch Druid fills the shell fragment with water, which boils instantly. He adds a bundle of herbs and closes his eyes in a silent prayer.>$B$B$n, Tortolla the turtle ancient is ageless, a part of this world since the time of the titans. He speaks a language older than our understanding.$B$BDrink this and find a place of calm within yourself. You will be able to understand the language of Tortolla. Go to him now, in the Ashen Lake. Earn the ancient''s trust. The fate of Hyjal hinges on this. ', `VerifiedBuild`=19034 WHERE `ID`=25510; -- Tortolla Speaks
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=58800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25513; -- Thunderdrome: Grudge Match!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=1048584, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25515 /*Down in the Deeps*/, 27320 /*The Writ of History*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=26100, `Flags`=1048584, `AllowableRaces`=33555378, `QuestDescription`='Well, friend, if Pozzik wants you to have your own boat, the first thing we''re going to need is parts. Now guess who gets to go get them?$B$B<Razzeric smiles as he points downward and then grabs you a spare diving helm and flippers.>$B$BI''m afraid so, $n. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.', `VerifiedBuild`=19034 WHERE `ID`=25516; -- Down in the Deeps
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=26100, `AllowableRaces`=18875469, `QuestDescription`='Those no-good, smelly, green in the gills goblins have got it coming!$B$BI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!$B$BShow them that we''re not going to take any more of their insolence, $n!', `VerifiedBuild`=19034 WHERE `ID`=25517; -- Bar Fight!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Those pint-sized, goober-looking, no-explosion gnomes have got it coming!$B$BI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!$B$BShow them that we''re not going to take any more of their arrogance, $n!', `VerifiedBuild`=19034 WHERE `ID`=25518; -- Bar Fight!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=7500, `VerifiedBuild`=19034 WHERE `ID`=25520; -- An Ancient Awakens
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=43200, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25522; -- Gargantapid
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `QuestDescription`='$n, our enemy is using this grotto in the Firelands to prepare an invasion. We''re going to hit them hard right where they live.$B$BBut first, you''ll need to get your wings. Flight in the Firelands does not work as it does in the outside world. Something about the dense, superheated air. You''ll need some practice!$B$BGet a Twilight Firelance from the rack behind me, equip it, then mount one of Aviana''s Guardians. Practice flying - flap your wings! Visit a flag placed on the ledge below and return. ', `VerifiedBuild`=19034 WHERE `ID`=25523; -- Flight in the Firelands
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=26100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25524; -- In the Outhouse
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='Here they come, $n! The Twilight Knight Riders, astride black buzzards birthed in the scorching sulfurous breeding pools of the Firelands. The only way to defeat them is from the sky!$B$BTake wing once more, $c, and slay them.$B$BRun into enemy riders with your lance to destroy them.$B$BGo forth. Fly, fool. Fly!', `VerifiedBuild`=19034 WHERE `ID`=25525; -- Wave One
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Oh no, $n, the cannonballs are hitting the Speedbarge. I''d say the Southsea pirates are getting more accurate... the ship is on fire!$B$BYou''ve got a river boat now. Please, go speak with Griznak.$B$BExtinguish those fires!', `VerifiedBuild`=19034 WHERE `ID`=25533; -- Pirate Accuracy Increasing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25535 /*A Powerful Need To Eat*/, 25893 /*Desperate Plan*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=33554440, `VerifiedBuild`=19034 WHERE `ID` IN (25541 /*Filling Our Pockets*/, 25849 /*When Archaeology Attacks*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='You''ve stirred up the hornets, $n. The ceiling is coming down on us! And their strongest fighters are taking wing on creatures warped and twisted by this world of flame.$B$BGet back out there and take them down! Watch out for flaming boulders.', `VerifiedBuild`=19034 WHERE `ID`=25544; -- Wave Two
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=572522632, `VerifiedBuild`=19034 WHERE `ID`=25545; -- To Arms!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=55500, `VerifiedBuild`=19034 WHERE `ID`=25547; -- On Our Own Terms
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (25550 /*Magma Monarch*/, 25553 /*Death to the Broodmother*/, 26111 /*... It Will Come*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (25551 /*The Firelord*/, 26130 /*Unplug L'ghorek*/, 26771 /*Testing the Trap*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `QuestDescription`='This egg you recovered is an alarming sign, $n.  The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic.$B$BThis "natural" egg is evidence that one of their matriarchs has become a viable broodmother.  We must destroy her before her brood spreads.$B$BGo to the Ascendant''s Rise where they claim these aberrations are kept and slay one of the juvenile drakes.  We will use its skull to lure out its mother.', `VerifiedBuild`=19034 WHERE `ID`=25552; -- Brood of Evil
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AreaGroupID`=0, `QuestDescription`='According to these tomes, one of Ragnaros'' most powerful lieutenants serves as the sole gatekeeper to Sulfuron Spire.$B$BYou won''t be able to defeat him alone.$B$BSound this horn when you engage in combat with Azralon and any of our forces in the vicinity will come to your aid.$B$BYou must hurry, $n.  It won''t be long before the Firelord realizes what we''re up to.', `VerifiedBuild`=19034 WHERE `ID`=25555; -- The Gatekeeper
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!$B$B$n, you need to go back to Griznak and get on your boat. Use the cannon to sink them before it''s too late!', `VerifiedBuild`=19034 WHERE `ID`=25562; -- Circle the Wagons... er, Boats
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (25571 /*A Natural Occurrence*/, 28733 /*Basic Botany*/, 28747 /*Someone Setup the Pumpkin Bomb*/, 28751 /*Tending the Garden*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='The weapons the Twilight''s Hammer uses against us are crafted by Forgemaster Pyrenduis within these very halls. The metal slices through armor like cheese in the hands of its wielder. Yet, when captured, the steel turns brittle and shatters.$B$BSo be it, $n. I''d rather see those cursed arms smashed than delivered to our enemy.$B$BSeek out the crates of Twilight arms in these caverns and smash them to pieces.', `VerifiedBuild`=19034 WHERE `ID`=25575; -- Forged of Shadow and Flame
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='These searing guardians are murderous! We destroy them, and within minutes, they reignite from the ashes.$B$BI think there''s a way to destroy them permanently, but we''ll need someone who can fight through the front ranks.$B$B$n, kill the searing guardians and take their smoldering cores to the nearby anvils. Smash them on the Twilight Anvils, and destroy them for good!', `VerifiedBuild`=19034 WHERE `ID`=25577; -- Crushing the Cores
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `QuestDescription`='It''ll be crucial to reclaim each of the ancients'' shrines, $n.$B$BFollow the road west of the Verdant Thicket, into Wolf''s Run.$B$BWe have operatives stationed there.  Aid them in any way that you can and work your way to the first shrine.$B$BThe wolf god was known to the elves as Goldrinn and to the orcs as Lo''Gosh.  He will be a fierce ally in our fight against the enemy.', `VerifiedBuild`=19034 WHERE `ID`=25584; -- The Return of the Ancients
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=27600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25585 /*Quiet the Cannons*/, 25588 /*A Little Payback*/, 25609 /*Sunken Treasure*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=27600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25586 /*Quiet the Cannons*/, 25757 /*Get Koalbeard!*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=27600, `AllowableRaces`=18875469, `QuestDescription`='Hey, $n, you haven''t seen my other brother, Wizzle, have you?$B$BI just know that the pirates captured him! He said that he was going to try to sell them some engineering stuff, or something.$B$BWould you please look for him up at the Southsea Holdfast to the east? I''ll bet that no-good goblin he''s always traveling with, Synge, got him into trouble!', `VerifiedBuild`=19034 WHERE `ID`=25590; -- Where's Wizzle?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25595 /*Something Edible*/, 25952 /*Caught Off-Guard*/, 25953 /*Swift Approach*/, 25954 /*An Occupation of Time*/, 25955 /*A Better Vantage*/, 25959 /*Clear Goals*/, 25960 /*Not Entirely Unprepared*/, 25962 /*Properly Inspired*/, 25963 /*Swift Action*/, 25964 /*Fallen But Not Forgotten*/, 25965 /*Gauging Success*/, 25967 /*Losing Ground*/, 25969 /*Hostile Waters*/, 25970 /*Come Prepared*/, 25971 /*Unfurling Plan*/, 25972 /*Honor and Privilege*/, 25992 /*Hopelessly Gearless*/, 25993 /*Body Blows*/, 25994 /*Still Valuable*/, 25996 /*Waking the Beast*/, 26087 /*""Glow-Juice""*/, 26088 /*Here Fishie Fishie*/, 26089 /*Die Fishman Die*/, 26124 /*Secure Seabrush*/, 26125 /*Secure Seabrush*/, 27717 /*Piece of the Past*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='Hey, $n, you haven''t seen our gunsmith, Synge, have you?$B$BI just know that the pirates captured him! He said that he was going to try to sell them some rifles, or something.$B$BWould you please look for him up at the Southsea Holdfast to the east? I''ll bet that no-good gnome he''s always traveling with, Wizzle Brassbolts, got him into trouble!', `VerifiedBuild`=19034 WHERE `ID`=25596; -- Where's Synge?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `AreaGroupID`=0, `QuestDescription`='A terrible evil squats in the heart of this cavern, $n. Forgemaster Pyrendius has personally crafted many of the cursed weapons that Twilight''s Hammer is using in their conquest of the realms above.$B$BBefore we leave these lands of flame... Pyrendius must die.$B$BHe will not go down easy. But, if I''m reading the tome correctly, we can briefly open up small gateways to the Abyssal Maw, the realm of water. Lure Pyrendius onto a portal rune and activate it to weaken him!', `VerifiedBuild`=19034 WHERE `ID`=25600; -- Forgemaster Pyrendius
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `Flags`=136, `QuestDescription`='That settles it, "$ndamus!"  You are head of your class!$B$BYou will get a chance to address a crowd of the most fanatical, bloodthirsty and certifiably insane people on this planet.$B$BGo report to your instructor for the details, but remember: your goal is to exploit the animosity between the ogres at the Seat of the Chosen and the other, less privileged races.$B$BIf all goes well, we will smuggle Jarod out of here during the ensuing riot.', `VerifiedBuild`=19034 WHERE `ID`=25601; -- Head of the Class
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (25604 /*Hammering It Out*/, 25773 /*A Natural Occurrence*/, 28617 /*Flower Power*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=12000, `VerifiedBuild`=19034 WHERE `ID`=25607; -- Ze Gnomecorder
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `QuestDescription`='Victory is possible, $n.$B$BThis portal is not just a means of bringing back Cenarius through the dream.  Think about it, $n.  Once a gateway through the Emerald Dream is open, our forces can use them to move freely from Moonglade, Nordrassil, and even Wyrmrest, to this strategic location.$B$BAll Ysera needs is time. It''ll be up to you to keep the Twilight''s Hammer forces in Darkwhisper Gorge from pulling together and attacking us from the east.$B$BTake one of the emerald drakes and hit them hard, $n.', `VerifiedBuild`=19034 WHERE `ID`=25608; -- Slash and Burn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25611 /*Return from the Firelands*/, 25747 /*Looking Forward*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25612 /*Return from the Firelands*/, 25958 /*Looking Forward*/, 26092 /*Orako's Report*/);
UPDATE `quest_template` SET `RewardBonusMoney`=1200, `VerifiedBuild`=19034 WHERE `ID` IN (25613 /*Do Yourself a Favor*/, 25615 /*Return to Stardust*/);
UPDATE `quest_template` SET `RewardBonusMoney`=12000, `VerifiedBuild`=19034 WHERE `ID` IN (25614 /*The Only Way Down is in a Body Bag*/, 26603 /*Message in a Bottle*/);
UPDATE `quest_template` SET `RewardBonusMoney`=12600, `VerifiedBuild`=19034 WHERE `ID` IN (25616 /*Hellscream's Legacy*/, 25622 /*Burn, Baby, Burn!*/, 25646 /*Windshear Mine Cleanup*/);
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='Atop the Lightning Ledge, the Twilight''s Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.$B$BI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.$B$BBe bold, $n. Find out where that flamegate leads, and destroy whatever lies within.', `VerifiedBuild`=19034 WHERE `ID`=25617; -- Into the Maw!
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='Atop the Lightning Ledge, the Twilight''s Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.$B$BI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.$B$BBe bold, $n. Find out where that flamegate leads, and destroy whatever lies within.', `VerifiedBuild`=19034 WHERE `ID`=25618; -- Into the Maw!
UPDATE `quest_template` SET `RewardBonusMoney`=92400, `VerifiedBuild`=19034 WHERE `ID` IN (25619 /*Reoccupation*/, 25629 /*Her Lady's Hand*/, 25658 /*Built to Last*/, 25858 /*By Her Lady's Word*/, 25859 /*No Trespass Forgiven*/, 25860 /*At All Costs*/, 25861 /*Setting An Example*/, 25896 /*Devout Assembly*/);
UPDATE `quest_template` SET `RewardBonusMoney`=3150, `VerifiedBuild`=19034 WHERE `ID`=25621; -- Field Test: Gnomecorder
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='$n, there you are! Goldrinn has a mission that only his champion can accomplish. Atop the Lightning Ledge, Twilight''s Hammer has erected a flamegate. We don''t know where it leads, but Goldrinn can''t enter. The ancient needs you to be his fangs.$B$BStep into the flamegate and talk to Jordan Olafson when you get inside. He''ll give you a token to allow you to use Goldrinn''s power in that realm. Find out where the flamegate leads!', `VerifiedBuild`=19034 WHERE `ID`=25623; -- Into the Maw!
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='$n! Lo''Gosh needs you. Atop the Lightning Ledge, Twilight''s Hammer has erected a flamegate. We don''t know where it leads, but nobody who''s gone through has returned. You are to venture inside and be the fangs of Lo''Gosh within.$B$BStep into the flamegate and talk to Jordan Olafson when you get inside. He''ll give you a token to allow you to use Lo''Gosh''s power inside that realm. Find out where the flamegate leads!', `VerifiedBuild`=19034 WHERE `ID`=25624; -- Into the Maw!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=147900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25626 /*Visions of the Past: Rise from the Deep*/, 25755 /*Visions of the Past: The Slaughter of Biel'aran Ridge*/, 25760 /*Visions of the Past: The Invasion of Vashj'ir*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25627 /*Two-Tusk Takedown*/, 26024 /*Wanted!  Marez Cowl*/, 27174 /*Combat Training*/, 27318 /*Grimtotem Chiefs: Elder Stormhoof*/, 27323 /*Grimtotem Chiefs: Grundig Darkcloud*/, 27329 /*Invoking the Serpent*/, 28266 /*Trial by Magma*/);
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `QuestDescription`='Do you see it, $n? From the ridge southwest of here... plumes of black smoke curling into the sky.$B$BMount Hyjal is burning.$B$BIf the fires have raced this far up the mountain, surely they threaten the Grove of Aessina and all of our forces there. Can you investigate?$B$BSpeak with Laina Nightsky near the Grove of Aessina. Last I heard, she was fighting off the assault.', `VerifiedBuild`=19034 WHERE `ID`=25630; -- The Fires of Mount Hyjal
UPDATE `quest_template` SET `RewardBonusMoney`=92400, `Flags`=1048712, `VerifiedBuild`=19034 WHERE `ID`=25637; -- To the Fathom-Lord's Call
UPDATE `quest_template` SET `RewardBonusMoney`=1260, `QuestDescription`='Ve have discovered ze vhereabouts of ze gigantic goblin bomb zat you discovered at Silvervind Refuge.$B$BYou remember Boog? Ze gnome you rescued from ze orcish vagon of agony? Vell, he and Minx have tracked ze bomb down to Windshear Mine. Go zhere immediately, $n! Zey''ll be expecting you.', `VerifiedBuild`=19034 WHERE `ID`=25640; -- Bombs Away: Windshear Mine!
UPDATE `quest_template` SET `RewardBonusMoney`=12600, `QuestDescription`='Keep your head down, $n. No need to draw unwanted attention.$B$BLooks like the orcs are piling that balloon up with some type of ore from the mine. Get in there and take the ore from the orcs. Bring me back whatever you manage to grab and I''ll ship it off to the professor for examination.$B$BBefore you go, a word of advice: you can avoid the Krom''gar pretty easily in there as (1) they''re dumb as dirt and (2) they can''t see anything if they''re carrying ore. Of course, you need to kill them to get their ore.', `VerifiedBuild`=19034 WHERE `ID`=25642; -- Don't Look Them in the Eyes
UPDATE `quest_template` SET `RewardBonusMoney`=11100, `VerifiedBuild`=19034 WHERE `ID`=25643; -- The Darkmist Ruins
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `ItemDropQuantity2`=1, `VerifiedBuild`=19034 WHERE `ID`=25644; -- The Twilight Egg
UPDATE `quest_template` SET `RewardBonusMoney`=9600, `VerifiedBuild`=19034 WHERE `ID` IN (25647 /*Illegible Orc Letter*/, 25649 /*Minx'll Fix It*/);
UPDATE `quest_template` SET `RewardBonusMoney`=9600, `QuestDescription`='The letter is actually an order from Horde high command. Someone named Overlord Krom''gar has issued a "strip job" on this mine in order to obtain something called azure iron flake. Presumably this flake is obtained from breaking down the ore.$B$BIt gets worse. They plan to mix the azure flake with the explosives sitting inside the huge bomb outside and blow up Windshear Hold.$B$BWe don''t have a moment to lose, $n! Take this translated copy of the letter and return to Boog! He''ll know what to do next.', `VerifiedBuild`=19034 WHERE `ID`=25650; -- Orders from High Command
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=15900, `QuestDescription`='We don''t have a moment to lose, $n. You''re going to have to commandeer that hot air balloon and stop it!$B$BHow? I have no idea! We don''t have time to argue details! Grab onto that rope ladder and climb up! Just start banging on stuff once you''re inside!$B$BIf you somehow manage to stop the balloon and survive, report to Lord Fallowmere at Windshear Hold in the west.$B$BGood luck, we''re all counting on you. Now if you''ll excuse me I''m going to RUN FOR MY LIFE!', `VerifiedBuild`=19034 WHERE `ID`=25652; -- Commandeer That Balloon!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=26100, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25654; -- Dark Heart
UPDATE `quest_template` SET `RewardBonusMoney`=111000, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25659; -- Not Soon Forgotten
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=12600, `VerifiedBuild`=19034 WHERE `ID`=25662; -- Free Our Sisters
UPDATE `quest_template` SET `RewardBonusMoney`=36900, `QuestDescription`='Although the guardian of all winged creatures is no longer with us in body, I sometimes hear her voice in the whisper of swaying leaves.$B$B$n, we ask much of you as you set out to preserve this mountain. Before going on, take a moment to reflect.$B$BTake this offering of nectar to Aviana''s burial circle, a circle of stones just outside the main door of the shrine. Perhaps some time alone with Aviana''s memory will help sharpen your focus.', `VerifiedBuild`=19034 WHERE `ID`=25663; -- An Offering for Aviana
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AreaGroupID`=0, `QuestDescription`='A winged visage? Could it be...?$B$B$n, there''s no time to waste. You may have been speaking to Aviana herself, trying to return to us.$B$BI''ll need something from Aviana''s past to reach out to her. High atop the ridge overlooking this shrine, you''ll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he''s been mad with grief.$B$BGo to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.', `VerifiedBuild`=19034 WHERE `ID`=25664; -- A Prayer and a Wing
UPDATE `quest_template` SET `RewardBonusMoney`=16500, `QuestDescription`='Prepare yourself, $n! The Warlord comes! Kill him and take his key. Use the key to release me.$B$BShould we make it out of here, report the following to Lord Fallowmere at Windshear Hold:$B$BThe Horde has aborted their plans to destroy Windshear Hold due to the efforts of one of our heroes. They now plan to move the bomb to Battlescar Valley and drop it on our armies battling the Horde at that location.$B$BThey must be stopped!', `VerifiedBuild`=19034 WHERE `ID`=25669; -- Rumble in the Lumber... Mill
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=24300, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25676; -- Heartstrike
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25685; -- The First Step
