UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=61200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25708; -- Our Fallen Friends
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25709 /*Curtail the Darktail*/, 25712 /*Nethergarde Reigns*/, 25715 /*A Closer Look*/, 26157 /*Kasim Sharim*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=36600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25710; -- Minor Distractions
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=61200, `AllowableRaces`=18875469, `QuestDescription`='The Horde are a nuisance that we will deal with, but they are proving more difficult than previously expected.  You are to put a stop to this.$b$bTo the west of Nethergarde, the Okril''lon main forces press on our defenses.  They currently hold the Nethergarde Mines, and they mean to move into the supply camps and, eventually, the Keep.  Thin their numbers and delay their advance, $n.', `VerifiedBuild`=19034 WHERE `ID`=25711; -- Eliminate the Okril'lon
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48900, `AllowableRaces`=18875469, `QuestDescription`='Say there... $n, is it?  I''ve got a proposition for you which involves explosions.  Interested?$b$bI couldn''t help but overhear your conversation with the quartermaster.  You see... I''ve been working on an explosive device.  It''s not very effective against other creatures, but devastating against artillery.  If you''re heading back into the field to visit those orcs, find some enemy supplies and give this thing a try.  Who knows... maybe they like explosions too.', `VerifiedBuild`=19034 WHERE `ID`=25713; -- Remove Their Arms
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=4950, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25714; -- Watcher Mahar Ba
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=67500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25717; -- The Demons and the Druid
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=81000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25719; -- Demoniac Vessel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=111600, `AreaGroupID`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25720; -- The Downfall of Marl Wormthorn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='The cataclysm has thrown the balance of power in Dun Morogh into question, $n. Without warning, a wave of troggs emerged from the caves near Gnomeregan and overran the Frostmane trolls. The trolls have been migrating east ever since.$B$BThere has always been a Frostmane presence up on Shimmer Ridge, to the northwest, but with the migration, the trolls now surround us. We can''t allow the trolls to use this position to their advantage. While my men hold the line in the east, strike against Shimmer Ridge.', `VerifiedBuild`=19034 WHERE `ID`=25724; -- Frostmane Aggression
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25727; -- Drungeld Glowerglare
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=19800, `VerifiedBuild`=19034 WHERE `ID`=25728; -- Mr. P's Wild Ride
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=13200, `QuestDescription`='<The Gnomecorder comes to life with a loud buzz.>$B$BCome in, $n! Are you zhere? I have noted on ze map that you are near ze Cragpool Lake vater vheel, is that correct?$B$BIt vould appear that ze Venture Co. has holed up at ze vheel. Have a look around vhile you are up zhere. If you happen to zee a traitorous gnome by ze name of Gerenzo Wrenchwhistle, put your boot firmly up his keester for me and for Gnomeregan! I vill pay handsomely!', `VerifiedBuild`=19034 WHERE `ID`=25729; -- Gerenzo the Traitor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=19800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25730; -- BEWARE OF CRAGJAW!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='It''s time to get to the bottom of this. We need to interrogate the matron of these beasts, Marion Wormwing. We''ll capture her alive. Here''s the plan:$B$BThe harpies communicate across the ridge using a series of signal fires. If we extinguish one, Marion is sure to come investigate.$B$BYou fight her as a distraction while I sneak up behind and grab her. I''ll leave the questioning to you. Let''s get her, $n! ', `VerifiedBuild`=19034 WHERE `ID`=25731; -- A Bird in Hand
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=13200, `VerifiedBuild`=19034 WHERE `ID`=25741; -- Preparations for the Future
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='$n, great job defending the Speedbarge! I''ve got something else that I need you to help out with.$B$BI''ve sent Crazzle Sprysprocket and Kravel Koalbeard northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!$B$BI figure those smelly half horses won''t know what they''ve got and we''ll get the rights to pump up that black gold for a song, but I''d feel better if you took charge of the talks.$B$BWhat do you say?', `VerifiedBuild`=19034 WHERE `ID`=25744; -- Negotiations
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='$n, great job defending the Speedbarge! I''ve got something else that I need you to help out with.$B$BI''ve sent Riznek and Trackmaster Zherin northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!$B$BI figure those smelly half horses won''t know what they''ve got and we''ll get the rights to pump up that black gold for a song, but I''d feel better if you took charge of the talks.$B$BWhat do you say?', `VerifiedBuild`=19034 WHERE `ID`=25745; -- Negotiations
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=28800, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25762; -- The Ancient Brazier
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='Skylord Omnuron wants us to find Aviana''s Egg, and I can almost guarantee you it''s cloaked by one of Sethria''s shadow devices.$B$BSearch around the camp for shadow cloak generators and shut those things down until you find the egg.$B$BOnce you''ve unveiled it, I''ll call out to the other druids. Defend that egg until we can carry it off to safety.$B$BGo get that egg, $n!', `VerifiedBuild`=19034 WHERE `ID`=25764; -- Egg Hunt
UPDATE `quest_template` SET `RewardBonusMoney`=20400, `VerifiedBuild`=19034 WHERE `ID`=25766; -- Arcane Legacy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=13800, `QuestDescription`='The great cataclysm has unearthed a forgotten Highborne city within Stonetalon Mountains. You must venture southwest to the Ruins of Eldre''thar. Once you are there, search the area for ancient relics. Return the relics to me so that I may study them, $n.$B$BGo! Lest we keep the arcanist waiting!', `VerifiedBuild`=19034 WHERE `ID`=25767; -- Capturing Memories
UPDATE `quest_template` SET `RewardBonusMoney`=3450, `QuestDescription`='Scout Commander Barus, stationed at Mirkfallon Post, to the northwest, has spotted the Horde bomb. The Krom''gar hot air balloon, with bomb attached, is currently at the new goblin fueling station at Mirkfallon Lake. This might be the opportunity we need to take that thing out once and for all.$B$BGather your things, $n, and move out! Scout Commander Barus awaits your arrival at Mirkfallon Post.$B$BAnd $n, your tenacity is a testament to the strength and fortitude of the Alliance!$B$BGlory be unto you!', `VerifiedBuild`=19034 WHERE `ID`=25768; -- Bombs Away: Mirkfallon Post!
UPDATE `quest_template` SET `RewardBonusMoney`=1380, `VerifiedBuild`=19034 WHERE `ID` IN (25769 /*Fallowmere Beckons*/, 25793 /*The Deep Reaches*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='We definitely DO NOT have the kind of gold that the Horde is offering. $n, we have to do something or we''re not going to be able to get those drilling rights!$B$BWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That''s it!$B$BHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.', `VerifiedBuild`=19034 WHERE `ID`=25774; -- Fool's Gold
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='We definitely DO NOT have the kind of gold that the Alliance is offering. $n, we have to do something or we''re not going to be able to get those drilling rights!$B$BWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That''s it!$B$BHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.', `VerifiedBuild`=19034 WHERE `ID`=25775; -- Fool's Gold
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=27600, `Flags`=8, `AllowableRaces`=18875469, `QuestDescription`='It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.$B$BUnfortunate for them, that is.$B$BThey''ve spit in our faces, $n. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.$B$BClear the centaur off of the Splithoof Heights. The oil must flow!', `VerifiedBuild`=19034 WHERE `ID`=25796; -- Eminent Domain
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=33555378, `QuestDescription`='It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.$B$BUnfortunate for them, that is.$B$BThey''ve spit in our faces, $n. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.$B$BClear the centaur off of the Splithoof Heights. The oil must flow!', `VerifiedBuild`=19034 WHERE `ID`=25797; -- Eminent Domain
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=27600, `Flags`=2, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25798; -- Defend the Drill
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=2, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25799; -- Defend the Drill
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25801 /*Claws from the Deep*/, 26530 /*The Shell of Shadra*/, 26731 /*The Altar of Naias*/, 27234 /*Defias in Dustwallow?*/);
UPDATE `quest_template` SET `RewardBonusMoney`=13800, `VerifiedBuild`=19034 WHERE `ID` IN (25806 /*They Put the Assass in... Never Mind*/, 25876 /*It's Up There!*/, 25879 /*The Lumbering Oaf Problem*/);
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `QuestDescription`='I''m convinced that YOU are the herald of Aviana, $n. It was you who first saw her and rescued her essence from the claws of a dragon.$B$BYes, I believe Aviana is to be reborn into our world. And you shall have the honor of ushering her over the threshold.$B$BTake this incense and burn it before Aviana''s egg in the room just above me.$B$BThe ancient awaits, $n. Our deliverance is here!', `VerifiedBuild`=19034 WHERE `ID`=25807; -- An Ancient Reborn
UPDATE `quest_template` SET `RewardBonusMoney`=17100, `QuestDescription`='<The Gnomecorder crackles with energy. You can hear Lieutenant Paulson on the other end.>$B$BStupid gnome junk... Is ANYBODY there? $n, are you there?$B$BMaybe $g he''s:she''s; dead.$B$BListen, if you can still hear me, we just got word that a Horde master assassin is in the mines, directing the other assassins. Find her, kill her, report back to me.$B$BPaulson, out.', `VerifiedBuild`=19034 WHERE `ID`=25808; -- Is This Thing On?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=17100, `QuestDescription`='Horde monsters!$B$B<Corporal Wocard spits.>$B$BLook at this place! They''ve wiped out innocents! Civilians!$B$BListen, $n, you''ve got to help us. Go into the Deep Reaches and look for surviving miners. If any are still alive they''re probably scared witless! Check in the nooks and crannies of the mine. Maybe in mine carts! There are bound to be some left alive and in hiding.', `VerifiedBuild`=19034 WHERE `ID`=25809; -- Leave No Man Behind! 
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `QuestDescription`='$n! Choluna spoke true: the goddess has returned! A miracle in our midst.$B$BWhile you were able to kill the twilight dragon Sethria, we have not yet located all of the eggs that the harpies had delivered to her. Thisalee and I have tracked them to a great hatchery constructed within the Firelands. It is not of this realm, so Aviana cannot accompany you.$B$BFly south and enter the flamegate in the center of the valley. Farden Talonshrike has been sent ahead and will be waiting for you within.', `VerifiedBuild`=19034 WHERE `ID`=25810; -- The Hatchery Must Burn
UPDATE `quest_template` SET `RewardBonusMoney`=17100, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `VerifiedBuild`=19034 WHERE `ID`=25811; -- Shuttin Her Down
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.$B$BI''ve seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.$B$BGo blow that horn, $n.', `VerifiedBuild`=19034 WHERE `ID`=25813; -- Go Blow that Horn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=33555378, `QuestDescription`='That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.$B$BI''ve seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.$B$BGo blow that horn, $n.', `VerifiedBuild`=19034 WHERE `ID`=25814; -- Go Blow that Horn
UPDATE `quest_template` SET `RewardBonusMoney`=5250, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25816; -- Cursed to Roam
UPDATE `quest_template` SET `RewardBonusMoney`=1380, `QuestDescription`='You''ve done an admirable job down here, $n. Force Commander Valen has taken notice and requested that you see him immediately. He''s got a special mission lined up for you - one that''ll hopefully put a cold stop on the Horde''s incursion into Stonetalon.', `VerifiedBuild`=19034 WHERE `ID`=25821; -- A Special Kind of Job
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=13800, `QuestDescription`='I am going to need to put you in harm''s way once more, $n. To the east you will find a mineral rich excavation site that was recently overrun by the Horde. At that site are crates of our weaponry, scattered about all over the place. The Horde has only recently taken over, so it is unlikely that they''ve found all of our supplies.$B$BGet in there and get our Grimtotem friends some weapons!', `VerifiedBuild`=19034 WHERE `ID`=25822; -- Armaments for War
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=13800, `QuestDescription`='While it is of utmost importance that you secure weapon crates immediately, we need the Unearthed Grounds to the east clear of Horde. If we are to open a supply line for our Grimtotem allies, we''re going to need full access to the dig site.$B$BKill all Horde that you come across at the Unearthed Grounds, $n. For the glory of the Alliance!', `VerifiedBuild`=19034 WHERE `ID`=25823; -- The Unrelenting Horde
UPDATE `quest_template` SET `Flags`=262144, `AllowableRaces`=18875469, `QuestDescription`='Alright, $n, I need you to get this oil back to Fizzle on the Speedbarge, and let him know the good news!', `VerifiedBuild`=19034 WHERE `ID`=25825; -- Deliver the Goods
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `Flags`=262144, `AllowableRaces`=33555378, `QuestDescription`='Alright, $n, I need you to get this oil back to Pozzik on the Speedbarge, and let him know the good news!', `VerifiedBuild`=19034 WHERE `ID`=25826; -- Deliver the Goods
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `QuestDescription`='You have awakened the ancients, $n, but the wilderness spirit Aessina remains silent. With her help, we can turn the tide of this attack and undo the damage Twilight''s Hammer has done.$B$BThere may be one who can help us. The oldest of the trees, Nordu, stood in the center of what is now the Flamewake for thousands of years. His wisdom is as old as this mountain. If that old tree still lives, perhaps he can awaken Aessina... seek him out.', `VerifiedBuild`=19034 WHERE `ID`=25830; -- The Last Living Lorekeeper
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `Flags`=136, `QuestDescription`='$n, you''ve done all you can here. This whole cavern is about to collapse in on itself!$B$BI''ll gather up the last of our feathered steeds and ensure that the flamegate is sealed behind me.$B$BYou should go on ahead and let Aviana know that this abominable hatchery is no more!', `VerifiedBuild`=19034 WHERE `ID`=25832; -- Return to Aviana
UPDATE `quest_template` SET `RewardBonusMoney`=1440, `QuestDescription`='Can you hear them fighting down below, $n? It would appear that the Grimtotem tauren are no longer in the good graces of the Horde. I don''t know what happened, but we can turn this to our advantage.$B$BI will arrange a meeting with an ambassador from the Grimtotem. What I need you to do is put together a peaceful offering.$B$B<Force Commander Valen points to Cookie.>$B$BTalk to "Cookie," $n. He''s already been briefed on what we need to do.', `VerifiedBuild`=19034 WHERE `ID`=25834; -- Death by Proxy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25841 /*Strike From Above*/, 26285 /*Get Me Explosives Back!*/, 26547 /*A Mangy Threat*/, 26932 /*Buzz Off*/, 26961 /*Gathering Idols*/);
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='You heard the commander, $n. Deliver me perfect offerin'' to the Grimtotem ambassador! Him and his crew be waitin'' for you at the bottom of the southeastern path.$B$BThis is sure to put us in the good graces of their chieftain!', `VerifiedBuild`=19034 WHERE `ID`=25844; -- Sating the Savage Beast
UPDATE `quest_template` SET `RewardBonusMoney`=1440, `VerifiedBuild`=19034 WHERE `ID`=25845; -- Terms of Service
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='The Grimtotem chieftain awaits your arrival, $n. Take the weapon crates with you and head to Grimtotem Post, south of here.$B$BGood luck, $n. Should anything happen to you I will personally notify your next of kin and let King Wrynn know what you have done for the Alliance.', `VerifiedBuild`=19034 WHERE `ID`=25846; -- Grundig Darkcloud, Chieftain of the Grimtotem
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=21900, `VerifiedBuild`=19034 WHERE `ID`=25848; -- Downfall
UPDATE `quest_template` SET `RewardBonusMoney`=1500, `QuestDescription`='Pack up your gear, $n, it''s time to join up with the rest of the Northwatch forces in Southern Barrens. Your first mission in Southern Barrens should be fairly straightforward.$B$BTwo days ago we received a distress signal from Commander Walpole. He and his battalion are pinned down in Stonetalon Pass, just outside of Honor''s Stand. They''ve got Horde all over the place! Get there and help him out. I''ll forward news of our alliance with the Grimtotem to Northwatch command.', `VerifiedBuild`=19034 WHERE `ID`=25852; -- All's Clear
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=25857; -- Hunting Horrorjaw
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=28800, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25871; -- Save the Sentinel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=37800, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=25873; -- Horn of the Traitor
UPDATE `quest_template` SET `RewardBonusMoney`=6900, `QuestDescription`='RUN! Get out of here, $n. Get back to Barus and inform him of what you''ve discovered. He''ll arrange for you to get safely across Battlescar Valley to Thal''darah Overlook.$B$BIt''s not too late to save those young druids!', `VerifiedBuild`=19034 WHERE `ID`=25877; -- No Time for Goodbyes!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=13800, `VerifiedBuild`=19034 WHERE `ID`=25878; -- Schemin' That Sabotage
UPDATE `quest_template` SET `RewardBonusMoney`=1440, `Flags`=1310728, `QuestDescription`='There are dozens of students at Thal''darah Grove. Most of them have no means of defending themselves, ripe for the slaughter.$B$BYou must get word to Master Thal''darah of the Horde''s plans. He will direct you in what you must do next.$B$BFiora Moonsoar has granted you the use of her fastest hippogryph. Take it now to Thal''darah Overlook! Don''t look back, $n! The Horde must be stopped!', `VerifiedBuild`=19034 WHERE `ID`=25880; -- Warn Master Thal'darah
UPDATE `quest_template` SET `RewardBonusMoney`=17700, `QuestDescription`='My poor, defenseless young students are stranded at Thal''darah Grove. With the battle raging across Battlescar Valley, they have no means of escaping. We must save the children before the Horde drops their bomb!$B$BTake my hippogryph and use it to rescue the young druids of Thal''darah Grove. Drop them off at the hippogryph post here in town.$B$BSave them all, $n! You truly are our only hope.', `VerifiedBuild`=19034 WHERE `ID`=25889; -- Save the Children!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `QuestDescription`='It is clear to me at this point what must be done, $n.$b$bThe naga can only be obtaining these pearls from one place: Nespirah, the ancient, shelled creature that rests outside of this cave.  Why Nespirah would submit to the naga, however, is beyond my understanding.$b$bWe can enter Nespirah''s body cavity through a small tube near the exit to this cave.  I must first fetch my master, then we can meet you on the inside.  We will convene in Nespirah''s northwestern entrance.', `VerifiedBuild`=19034 WHERE `ID`=25890; -- Nespirah
UPDATE `quest_template` SET `RewardBonusMoney`=14100, `VerifiedBuild`=19034 WHERE `ID`=25891; -- Last Ditch Effort
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=136, `ItemDropQuantity1`=1, `VerifiedBuild`=19034 WHERE `ID`=25908; -- Stick it to Them
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25909 /*Capture the Crab*/, 26005 /*A Breath of Fresh Air*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='This cavern is an abomination, $n. And it''s filled with horrors from the depths.$B$BI don''t want any of these - things - getting through the portal to the outside world. Slay everything!', `VerifiedBuild`=19034 WHERE `ID`=25910; -- The Time for Mercy has Passed
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25911 /*Welcome News*/, 25916 /*Breaking Through*/, 26019 /*Enormous Eel Egg*/);
UPDATE `quest_template` SET `RewardBonusMoney`=14100, `QuestDescription`='The world is unraveling around us, $n. Old enemies seek to destroy us from one end, while ancient forces close in on the other.$B$B<Elder Sareth''na sighs.>$B$BI have seen better days - brighter days, and I long for them...$B$BAcross Stonetalon Peak lies the ruins of our old outpost - now overrun with darkness. If you happen to go that way, could you search for my sketch book? It holds many happy memories. I would reward you well for its return.', `VerifiedBuild`=19034 WHERE `ID`=25912; -- Seen Better Days
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=14100, `VerifiedBuild`=19034 WHERE `ID`=25913; -- Putting Them to Rest
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=14100, `VerifiedBuild`=19034 WHERE `ID`=25914; -- Back to the Depths!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `QuestDescription`='The dark usurper Nemesis fled here when the fires of Hyjal receded. We are not yet strong enough to defeat Nemesis, $n, but we may be able to turn his own strength against him.$B$BI will send a child of Tortolla with you, one of the children you freed earlier from the Twilight''s corruption.$B$BSearch the depths of this cave for a Nemesis Crystal, and allow the young turtle to examine it.$B$BSee me if you lose your companion!', `VerifiedBuild`=19034 WHERE `ID`=25915; -- The Strength of Tortolla
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `AllowableRaces`=18875469, `QuestDescription`='<Duarn closes his eyes, pauses, and nods.>$b$bNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Alliance slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah''s heart.$b$bGo find them, $n, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.$b$bI will remain here, should you need anything.', `VerifiedBuild`=19034 WHERE `ID`=25917; -- We Are Not Alone
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=111000, `AreaGroupID`=0, `QuestDescription`='My men are flagging, $n.  We won''t last much longer against these naga, I''m afraid.  With the Idra''kess'' weapons, and Nespirah''s pearls, we should be ready to bust out of here.$b$bFollow the wall to the southeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah''s awakening.  Hopefully both.$b$bIf you feel strong enough, head up to the top of the shell and look for some answers.', `VerifiedBuild`=19034 WHERE `ID`=25921; -- Overseer Idra'kess
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=21900, `QuestDescription`='We must attempt to establish communication with Farwatcher Glen, to the south. Our Darnassian glaive throwers are at your disposal, $n. Use them to cut a swath through the encroaching Horde forces and clear a path to Farwatcher Glen.$B$BI only hope we''re not too late to save the Glen. Should Farwatcher Glen be intact, find Hierophant Malyk and inform him of our status.', `VerifiedBuild`=19034 WHERE `ID`=25925; -- Thal'darah's Vengeance
UPDATE `quest_template` SET `RewardBonusMoney`=14700, `Flags`=1245196, `VerifiedBuild`=19034 WHERE `ID`=25930; -- Ascending the Vale
UPDATE `quest_template` SET `RewardBonusMoney`=14700, `Flags`=1179656, `QuestDescription`='<The Gnomecorder buzzes.>$B$BBe very careful, $n. You do not want to rouse that black dragon.$B$BNow, look around you. If this is a nest then there must be black dragon eggs nearby. Search the premises for eggs and destroy any that you see.$B$BReturn to me should you find and destroy Seldarria''s eggs.$B$BGoldrinn watch over you.', `VerifiedBuild`=19034 WHERE `ID`=25931; -- Brood of Seldarria
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `QuestDescription`='Thank you again for all your help here, $n.$B$BI have a cousin who used to work in the mines beneath the Gol''Bolar Quarry, but he hasn''t been able to work since troggs flooded into the mines and took control. The quarry and its camp are just to the southeast of the ranch. Would you be willing to check in with the foreman there and see if there''s anything to be done?', `VerifiedBuild`=19034 WHERE `ID`=25933; -- Help for the Quarry
UPDATE `quest_template` SET `RewardBonusMoney`=3600, `QuestDescription`='I''ve received a disturbing message from Nijel''s Point in Desolace. It would seem as if the great upheaval has created some new problems for them, which they are ill-equipped to handle. I was given no further information.$B$BReport to Office Jankie in Desolace. She will direct you to Nijel''s Point.$B$BGood luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=25938; -- Help for Desolace
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=35651720, `VerifiedBuild`=19034 WHERE `ID`=25944; -- Girding Our Loins
UPDATE `quest_template` SET `RewardBonusMoney`=3150, `QuestDescription`='You''re in Hellscream''s army now, $n, and in Hellscream''s army we kick butt and take names. Gone are the days of our people starving in the streets of Orgrimmar as we sign treaties with elves. We take what we need now. Kalimdor belongs to the Horde!$B$BThe Alliance attempts to stop our expansion every chance they get. Unsatisfied with owning most of the Eastern Kingdoms, those pig-lickers want it all!$B$BOverlord Krom''gar has called for more troops in Stonetalon. Get on the caravan west of here and go!', `VerifiedBuild`=19034 WHERE `ID`=25945; -- We're Here to Do One Thing, Maybe Two...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=18875469, `QuestDescription`='You''re the $n everyone''s been talking about? Good to meet ya, love. Let''s have a butcher''s hook.$B$BWell, enough rabbit, right? Let''s get down to it. I need you to swim out northwest to the Sira''kess Front and read and write them snakes something quick.$B$BNothing fancy. They''re looking for a bother, and we''ll give ''em a right good one in the ol'' boat race.', `VerifiedBuild`=19034 WHERE `ID`=25950; -- Sira'kess Slaying
UPDATE `quest_template` SET `RewardBonusMoney`=111000, `LogTitle`='Final Judgment', `VerifiedBuild`=19034 WHERE `ID`=25951; -- Final Judgment
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=262280, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25956; -- Upon the Scene of Battle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=147900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25957 /*Visions of the Past: The Invasion of Vashj'ir*/, 25966 /*Visions of the Past: The Slaughter of Biel'aran Ridge*/, 26135 /*Visions of the Past: Rise from the Deep*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=25968; -- Desperate Plan
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25973 /*Welcome News*/, 25990 /*Breaking Through*/, 26090 /*I Brought You This Egg*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=33555378, `QuestDescription`='So, you''re the $n everyone''s been talking about? It''s good to finally meet you.$B$BWell, enough talk, right? Let''s get down to it. I need you to swim out northwest to the Sira''kess Front and kill those naga real quick.$B$BNothing fancy. They''re looking for a fight, and we''ll give them one! Well, you will.', `VerifiedBuild`=19034 WHERE `ID`=25974; -- Sira'kess Slaying
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (25975 /*Treasure Reclamation*/, 26070 /*Clearing the Defiled*/, 26132 /*Fiends from the Netherworld*/, 26144 /*Prisoners*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=33555378, `QuestDescription`='Blood and thunder! We have our reinforcements, but they still need to be paid. They won''t be cheap.$B$BUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. It''s time to reclaim some of it for the Horde.$B$BHellscream''s eyes are upon you, $n!', `VerifiedBuild`=19034 WHERE `ID`=25976; -- Treasure Reclamation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=18875469, `QuestDescription`='$n, the snakes are after our daft and barmy. Go back northwest to Deepfin Ridge and plant some do me good in that pot and pan pitch and toss of theirs.$B$BThey''ll kick and prance away with their alderman''s nails tucked between their nutmegs when they see that. Not that they''ve got any nutmegs mind you.', `VerifiedBuild`=19034 WHERE `ID`=25977; -- A Standard Day for Azrajar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=33555378, `QuestDescription`='$n, the naga are after our forces. I need you to go back northwest to Deepfin Ridge and stick our standard in their general, Fathom-Caller Azrajar.$B$BThey''ll swim away with their tails tucked between their... er. Well, I guess they don''t have any legs, now do they?', `VerifiedBuild`=19034 WHERE `ID`=25980; -- A Standard Day for Azrajar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=18875469, `QuestDescription`='$n, there are these demon squid-things out there that are eating gilblins'' heads and then taking them over! That''s one way to get slaves.$B$BThink you could swim out northwest onto Deepfin Ridge or into the Sira''kess Front and bring me back some of those Merciless things?', `VerifiedBuild`=19034 WHERE `ID`=25981; -- Those Aren't Masks
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=33555378, `QuestDescription`='$n, there are demon squids out there that are eating gilblins'' heads and then taking them over! They better not come in here!$B$BThink you could swim out northwest onto Deepfin Ridge or into the Sira''kess Front and bring me back some of those Merciless things? Preferably dead, I think.', `VerifiedBuild`=19034 WHERE `ID`=25982; -- Those Aren't Masks
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='$n, I need you to get this information to Legionnaire Nazgrim on Promontory Point. He''s up there to the northwest with Erunak Stonespeaker and those Earthen Ring people.', `VerifiedBuild`=19034 WHERE `ID`=25984; -- Promontory Point
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `QuestDescription`='$n, is it true you''re going to try to commune with the ancients?$B$BSouthwest of here is the Shrine of Aviana, the matron of all flying creatures. It''s the home of my favorite instructor, Choluna. I''ve never encountered one who was so deeply in touch with the spirits of this world. You could learn a lot from her!$B$BThe recent attacks have isolated the shrine. But it''s easily accessible from the air - look for the second biggest tree on Hyjal. Good luck!', `VerifiedBuild`=19034 WHERE `ID`=25985; -- Wings Over Mount Hyjal
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `Flags`=5243010, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=18875469, `QuestDescription`='Hey, $n, I''ve got an idea for a disguise! Take one of these merciless whatchamacallits and put it on your head.$B$BWhat could possibly go wrong?$B$BReady to put it on?', `VerifiedBuild`=19034 WHERE `ID`=25987; -- Put It On
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `Flags`=5243010, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=33555378, `QuestDescription`='I''ve got an idea for a sweet disguise, but I''m going to need your help, $n! Take one of these merciless corpses and put it on your head.$B$BI know, I know, but it''s dead, so what could possibly go wrong other than you smelling bad for a day or two?$B$BReady to put it on?', `VerifiedBuild`=19034 WHERE `ID`=25988; -- Put It On
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=55500, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (25989 /*Capture the Crab*/, 26006 /*A Breath of Fresh Air*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `AllowableRaces`=33555378, `QuestDescription`='<Duarn closes his eyes, pauses, and nods.>$b$bNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Horde slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah''s heart.$b$bGo find them, $n, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.$b$bI will remain here, should you need anything.', `VerifiedBuild`=19034 WHERE `ID`=25991; -- We Are Not Alone
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=111000, `AreaGroupID`=0, `AllowableRaces`=33555378, `QuestDescription`='My men are flagging, $n.  We won''t last much longer against these naga, I''m afraid.  With the Idra''kess'' weapons, and Nespirah''s pearls, we should be ready to bust out of here.$b$bFollow the wall northeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah''s awakening.  Hopefully both.$b$bIf you feel strong enough, head up to the top of the shell and look for some answers.  Hellscream''s eyes are upon you!', `VerifiedBuild`=19034 WHERE `ID`=25995; -- Overseer Idra'kess
UPDATE `quest_template` SET `QuestDescription`='Filthy, good-for-nothin'' night elves have managed to disarm our entire minefield in Talondeep Pass. Somebody is gonna have to go back up there and re-arm them all! A perfect task for a worthless grunt like you, $n. Here''s to hopin'' you don''t blow yourself up in the process.$B$BYou''ll find our "Elf Killers" scattered across Talondeep Pass, directly north of here. Take this wrench and get to work, maggot.', `VerifiedBuild`=19034 WHERE `ID`=25999; -- Barrier to Entry
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='Our main base of operations in Stonetalon Mountains is Krom''gar Fortress. It is from there that Overlord Krom''gar oversees all Horde military activity in the region. Krom''gar reports everything that happens directly to the Warchief.$B$BThe attack plans you brought back detail an assault that''s supposed to take place against Krom''gar Fortress soon. Take the plans and head to the fortress, southwest of here. Give them to the Overlord.$B$BSo long, $n. Truly, Hellscream''s eyes are upon you.', `VerifiedBuild`=19034 WHERE `ID`=26004; -- Krom'gar Fortress
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=19800, `VerifiedBuild`=19034 WHERE `ID`=26009; -- Seek and Destroy
UPDATE `quest_template` SET `Flags`=1048584, `QuestDescription`='The Alliance have grown bold. Just west of here, in Windshear Valley, Northwatch troops have set up camp. No doubt they are preparing for the assault you warned us of, $n. They will never get the chance!$B$BTake this flame thrower. It is the same flame thrower my incinerators use to burn our enemies out of hiding in the forests. Use it to destroy the Northwatch tents. Leave only ashes in your wake!', `VerifiedBuild`=19034 WHERE `ID`=26010; -- Ashes to Ashes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='My scouts have tracked the cause of this latest fiasco to one man: Marshal Paltrow. He commands the Northwatch forward camp that has established itself in Windshear Valley, west of here. Take him out and you remove a powerful Alliance field commander from the equation.$B$BPaltrow must die, $n.', `VerifiedBuild`=19034 WHERE `ID`=26011; -- Enemy of the Horde: Marshal Paltrow
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `VerifiedBuild`=19034 WHERE `ID` IN (26013 /*Assault on the Sanctum*/, 26096 /*Scalding Shrooms*/, 26140 /*Communing with the Ancient*/, 26259 /*Blood of the Earthwarder*/, 26260 /*The Forgemaster's Log*/, 26261 /*Question the Slaves*/, 26499 /*Stonefather's Boon*/, 26500 /*We're Surrounded*/, 26537 /*Shatter Them!*/, 26564 /*Fixer Upper*/, 26591 /*Battlefront Triage*/, 26861 /*Block the Gates*/, 27010 /*Quicksilver Submersion*/, 27100 /*Twilight Research*/, 27136 /*Elemental Energy*/, 27934 /*One With the Ground*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='Private $n, at attention!  Ve are havink a small problem!$b$bVe have sent Humphrey and Oskar Digsong out to Underlight Canyon, to the northvest, but they are not comink back.  They vere supposed to scout out the area, but ve have lost all contact with them.$b$bYour assignment, Private $n, is to locate our comrades and, if they live, bring them back to me!', `VerifiedBuild`=19034 WHERE `ID`=26014; -- The Brothers Digsong
UPDATE `quest_template` SET `QuestDescription`='We must prepare for the impending attack. I will have our soldiers prepare the bomb for transport. I want you to report to Chief Blastgineer Bombgutz. She has been working to fix our anti-air cannons, but has thus far failed. Make sure that she is properly motivated to repair our guns, $n.', `VerifiedBuild`=19034 WHERE `ID`=26020; -- Report to Bombgutz
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `AllowableRaces`=18875469, `QuestDescription`='Those eels ate my brother.  My brother, $n!  It''s time someone showed ''em who''s boss.$b$b<Humphrey removes several sticks of dynamite from his vest and shoves them through the egg''s outer membrane.>$b$bThe great-eels to the south are too tough to fight one-on-one, but with this egg, we should be able to even the odds.  Place it near one of those creatures, then... kablooie!$b$bIf the bomb doesn''t kill the eel outright, it should be near enough to death for you to finish it off.', `VerifiedBuild`=19034 WHERE `ID`=26021; -- The Brothers Digsong 2: Eel-Egg-Trick Boogaloo
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=19800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (26022 /*First Blood*/, 26053 /*Clearing the Highlands*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=112200, `RewardCurrencyID1`=0, `RewardCurrencyQty1`=0, `AllowableRaces`=52430847, `QuestDescription`='This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.$B$BZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra''s twisted experiments been seen.$B$BSlay him, $n, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.', `VerifiedBuild`=19034 WHERE `ID`=26034; -- The Twilight Destroyer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `QuestDescription`='Hey, $n. Sorry to be so short with ye earlier... and no, that ain''t a pun.$B$BI figured out where Trelane''s first item ended up: Kor''gresh has it in Boulderfist Hall. An'' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin'' out how to use all of its powers.$B$BBoulderfist Hall''s south of here an'' then east of Thandol Span. Find the ogre an'' get back that wand.$B$BWhile you''re gone, I''ll figure out what we''re gonna do about Stromgarde.', `VerifiedBuild`=19034 WHERE `ID`=26036; -- Wand over Fist
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=21300, `QuestDescription`='My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.$B$BPlease help me.  Allies of the giants, the Drywhisker kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather motes of Myzrael from the kobolds and apply them to it.$B$BI beg you, $n, aid me!', `VerifiedBuild`=19034 WHERE `ID`=26039; -- The Princess Trapped
UPDATE `quest_template` SET `AreaGroupID`=0, `QuestDescription`='Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.$B$BYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.$B$B$n, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!', `VerifiedBuild`=19034 WHERE `ID`=26042; -- Breaking the Keystone
UPDATE `quest_template` SET `QuestDescription`='Whew, that was tough. I didn''t think we''d make it, $n. We better get these parts back to Chief Blastgineer Bombgutz. I think I hear the gnome flying machines buzzing outside. We haven''t got a minute to lose!', `VerifiedBuild`=19034 WHERE `ID`=26048; -- Spare Parts Up In Here!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `QuestDescription`='There''s no time left. Here they come! Take control of a heavy gun and shoot the gnomes out of the sky! If that bomb takes too many hits it will blow, taking us all with it!$B$BDefend the base, $n! You''re our only hope!$B$BIf we somehow make it out of this in one piece, report to Overlord Krom''gar.', `VerifiedBuild`=19034 WHERE `ID`=26058; -- In Defense of Krom'gar Fortress
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='If I am to invoke voodoo, I will need several special reagents. Bring me horns from the Stonetalon rams of the region, $n! Without the horns we are done for!', `VerifiedBuild`=19034 WHERE `ID`=26061; -- Da Voodoo: Ram Horns
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='The troops are hungry, $n. With our supply lines cut off, we''re steadily running out of food. I can cook the soldiers a feast if you can get me some ingredients.$B$BHead into the woods west of here and look for Kalimdor eagle nests. Steal the eggs from the nests and bring them back to me.', `VerifiedBuild`=19034 WHERE `ID`=26064; -- Fight On Their Stomachs
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=93600, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AreaGroupID`=0, `QuestDescription`='Those tentacle horrors rising from the depths have trapped that poor beast. Please, $n, can you save it by destroying those things?$B$BWill you free Wil''hai?$B$BHere, take my totem and plant it near the tentacles. The cold it emanates will cause major shrinkage on those monsters and then you''ll be able to destroy them.', `VerifiedBuild`=19034 WHERE `ID`=26065; -- Free Wil'hai
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `QuestDescription`='Ah, it is done! Now to test it out.$B$BTravel to the main point of conflict within Greatwood Vale and use my voodoo stick on the Krom''gar marauders battling the Grimtotem. My voodoo magic should renew their vigor and allow them to crush our enemies!$B$BGo now, $n!', `VerifiedBuild`=19034 WHERE `ID`=26067; -- Jin'Zil's Blessing
UPDATE `quest_template` SET `RewardBonusMoney`=21900, `QuestDescription`='We now command the kobold armies of Stonetalon! It almost sounds impressive. Almost.$B$B<Devo sighs.>$B$BThe Alliance base camp north of here is tightly guarded. It is nigh impregnable, save for the entry point by the Unearthed Grounds, northeast of here. Take this kobold war horn and head towards the Unearthed Grounds. Enter from the east, $n! Once there, head west until you arrive at the location I have marked upon your map. Use the horn there to unleash kobold fury upon the Alliance!', `VerifiedBuild`=19034 WHERE `ID`=26068; -- Kobold Fury!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (26071 /*Clearing the Defiled*/, 26133 /*Fiends from the Netherworld*/, 26149 /*Prisoners*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `Flags`=128, `VerifiedBuild`=19034 WHERE `ID` IN (26072 /*Into the Totem*/, 26501 /*Sealing the Way*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `QuestDescription`='Return now to Overlord Krom''gar, $n. Inform him of our status and of what you have done to ensure that Malaka''jin does not fall.$B$BWe thank you for all that you have done. Perhaps some day soon you will have your own region to command.', `VerifiedBuild`=19034 WHERE `ID`=26073; -- All's Quiet on the Southern Front
UPDATE `quest_template` SET `QuestDescription`='Champion, we have acquired a new target. Our scouts in Battlescar Valley report that the night elves are preparing their own weapon of mass destruction and hiding it within an ancient tree. They will never be given the chance to use their weapon against us.$B$BYou are to escort the bomb to the Sludgewerks for refueling and then to Cliffwalker Post, from which we will detonate the bomb and kill all of our enemies.$B$BGo now, $n. Report to Jibbly Rakit when you arrive at the Sludgewerks. ', `VerifiedBuild`=19034 WHERE `ID`=26074; -- Beginning of the End
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='We''ve got another problem, $n. Alliance spies are all over the place! You haven''t seen any? That''s because they''re invisible! Cloaked! I have a solution, but I need muscle like you to go out there and follow through with my plan.$B$BUse this gas bomb on the cloaked spies and it will reveal them. Once revealed, send them back to their maker.$B$BYou''ll know a cloaked spy by the effect they leave in the air. Look closely!', `VerifiedBuild`=19034 WHERE `ID`=26076; -- Spy Infestation
UPDATE `quest_template` SET `QuestDescription`='Overlord Krom''gar sends word from the base. You are to get back on the Krom''gar hot air balloon and take it to Cliffwalker Post. From there, the plan is to unleash the payload on the Alliance at Battlescar Valley.$B$BYou better get going, $n. It''s not wise to keep Krom''gar waiting.$B$BSpeak to General Grebo when you arrive at your destination. He''ll be able to brief you on the next course of action.', `VerifiedBuild`=19034 WHERE `ID`=26077; -- Final Delivery
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='$n, I''m gonna need ya to bring this back to Captain Glovaal.  With my condition, it''ll take me a week to get back to Darkbreak Cove, and we don''t have any time to waste.', `VerifiedBuild`=19034 WHERE `ID`=26080; -- One Last Favor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=262152, `VerifiedBuild`=19034 WHERE `ID`=26081; -- Alina's Reward
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=6600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=26083; -- Hello Lolo
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=6600, `VerifiedBuild`=19034 WHERE `ID`=26084; -- Hammerfall
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='<Captain Verne looks down at his watch.>$b$bWhere is that hunter?  I sent Orako to Underlight Canyon to prepare a recon report a week ago!  Sure, he''s a handful, and I didn''t mind getting him out of my hair, but I need his report.$b$bSay, what''s your name?  $n?  Would you be willing to go track him down?  It seems strange to send a $c to find a hunter, but I''m running out of options.', `VerifiedBuild`=19034 WHERE `ID`=26086; -- Orako
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=92400, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=26091; -- Here Fishie Fishie 2: Eel-Egg-Trick Boogaloo
UPDATE `quest_template` SET `QuestDescription`='He was a good boy, $n. Young, loving. He would have never killed any of the young druids. They were his friends! No... Not Orthus.$B$BThe General must be called to answer for this crime. I will have justice!', `VerifiedBuild`=19034 WHERE `ID`=26099; -- Is This Justice?
UPDATE `quest_template` SET `QuestDescription`='Perhaps if you spoke to Overlord Krom''gar, $n. Maybe he would listen to what you had to say? You are a Champion in his army, after all. You saw everything. Please help us, $n. We simply wish to be left alone - in peace.$B$BTalk to Overlord Krom''gar and try to help him see that we did not mean for any of this to happen.', `VerifiedBuild`=19034 WHERE `ID`=26100; -- The General is Dead
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='With you leading the way, we''ve finally broken the momentum of the Dark Iron attack. General Grimaxe, the Dark Iron leader, is attempting to rally his troops from the center of their lines on the frozen lake to the south.$B$BHe stands atop one of their new dark iron golems, shouting orders to his men. If he succeeds in rallying them, they may still be able to overpower us. You must prevent that, $n. Destroy the golem guarding him, then kill General Grimaxe himself. He is the key to our victory.', `VerifiedBuild`=19034 WHERE `ID`=26102; -- Grimaxe's Demise
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `Flags`=8, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26105; -- Claim Korthun's End
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=18875469, `QuestDescription`='How much do you know about fuel, $n?  Constructing the perfect fuel is a tricky job, as there''s plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that''s only naming a few.$b$bHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you''re done.', `VerifiedBuild`=19034 WHERE `ID`=26106; -- Fuel-ology 101
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=20400, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=26110; -- Just Like Old Times
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `QuestDescription`='Stand by me, $n, and watch as our mighty weapon destroys our enemies!$B$BLearn what it means to be Horde!', `VerifiedBuild`=19034 WHERE `ID`=26115; -- To Be Horde...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='All right, $n. I''m ready if you are.$B$BShall we?', `VerifiedBuild`=19034 WHERE `ID`=26116; -- Kinelory Strikes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=33555378, `QuestDescription`='Have you ever smelled submarine fuel, $n?  It''s nasty stuff.  Unfortunately, we need to burn huge amounts of it to get the Verne to move, and it''s both bad-smelling AND deadly to the local wildlife.  We need to be more environmentally conscious.$b$bThe sea creatures nearby have particularly oily flesh.  Take this device up to Seabrush - just above this cave - and use it on the corpses of terrapins, remoras, and hammerhead sharks.  Their oil might save the lives of hundreds of other sea creatures.', `VerifiedBuild`=19034 WHERE `ID`=26122; -- Environmental Awareness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=33555378, `QuestDescription`='How much do you know about fuel, $n?  Constructing the perfect fuel is a tricky job, as there''s plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that''s only naming a few.$b$bHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you''re done.', `VerifiedBuild`=19034 WHERE `ID`=26126; -- The Perfect Fuel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `AllowableRaces`=-1, `QuestDescription`='Listen, $n.  For the first time since the civil war I agree with Greymane.  Now is the time to put aside our quarrel.$B$BIt sure doesn''t look like these beasts care much whether you''re a rebel or a royal.$B$BSend word back to Greymane.  My men will join his.$B$BThere''s a safehouse not far from here, in Josiah''s cellar.  My lads stashed some heavy artillery there.$B$BTell our king that my arsenals are now at his disposal.', `VerifiedBuild`=19034 WHERE `ID`=26129; -- Brothers In Arms
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `AllowableRaces`=18875469, `QuestDescription`='I''ve been waiting for the council to hear my plea for hours, and it''s not looking good. Moira''s greatest desire seems to be to paralyze the council.$B$BMeanwhile, Loch Modan suffers. Our enemies are many and our resources are few. Please, $n, perhaps you will hear me if the council will not. Speak to Gryth Thurden, Ironforge''s gryphon master. He''s in the eastern part of the Great Forge. He''ll provide a free flight to the South Gate Pass. Introduce yourself to Pilot Hammerfoot once you arrive.', `VerifiedBuild`=19034 WHERE `ID`=26131; -- Reinforcements for Loch Modan
UPDATE `quest_template` SET `RewardBonusMoney`=7200, `QuestDescription`='There is nothing left for you here, $n. As for me, I must lay Masha''s body to rest. Once I have done that I will go to the bombing site and begin the process of regrowth. Perhaps one day a new grove will bloom - a grove infused with the spirit of my child and the fallen night elf youths.$B$BIf you wish to travel to Desolace, I hear word of a blood elf named Furien seeking adventuring partners. Perhaps you should seek him out.$B$BFarewell, friend, I will never forget you.', `VerifiedBuild`=19034 WHERE `ID`=26134; -- Nothing Left for You Here
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `Flags`=136, `VerifiedBuild`=19034 WHERE `ID` IN (26141 /*Runestones of Binding*/, 26142 /*Ascend No More!*/, 26245 /*Gunship Down*/, 26410 /*Explosive Bonding Compound*/, 26502 /*Thunder Stones*/, 26857 /*Abyssion's Minions*/, 27933 /*Elemental Ore*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=113400, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID` IN (26143 /*All that Rises*/, 26971 /*The Binding*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='We need to protect the Loch, $n! With so many of the King''s soldiers fighting valiantly on remote battlefields, we''ve become overwhelmed on the home front. Troggs are tunneling up from every crevice! The trogg infestation poses the largest threat to Ironforge.$b$bWe need you, brave adventurer, to venture forth and lay waste to the trogg threat. Slay twelve Stonesplinter troggs and venture back.', `VerifiedBuild`=19034 WHERE `ID`=26146; -- In Defense of the King's Lands
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='The Mountaineers tell me you are quite brave and capable, $n.  We need a $r like you around here.  The Trogg problem isn''t getting any better.  The reserves have been called to the front and we''re all alone out here.  But now that we have a seasoned $c here, let''s see what you can do.$b$bGo out and kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers. You should find them in and around the caves in the southern mountains.$B$BLet''s see if you live up to your reputation, Trogg-Slayer.', `VerifiedBuild`=19034 WHERE `ID`=26147; -- Bigger and Uglier
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `QuestDescription`='It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug. He''s the biggest of all the troggs here, lurking deep within the darkness of the caves to the north.$b$bIf you feel yourself worthy, $n, I want you to lead the assassination mission on Grawmug.', `VerifiedBuild`=19034 WHERE `ID`=26148; -- A Decisive Strike
UPDATE `quest_template` SET `QuestDescription`='You seem like the helpful type, $n. How about doing an old man a favor?$B$BThe last time I was over at the Maclure Vineyards I overheard Maybell crying in her cottage. Would you be so kind as to go check up on her? I''m a little worried.', `VerifiedBuild`=19034 WHERE `ID`=26150; -- A Visit With Maybell
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `RewardCurrencyID1`=81, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (26153 /*Penny's Pumpkin Pancakes*/, 26192 /*Orphans Like Cookies Too!*/);
