UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardCurrencyID1`=81, `AllowableRaces`=-1, `VerifiedBuild`=19034 WHERE `ID` IN (26183 /*The King's Cider*/, 26220 /*Everything Is Better with Bacon*/, 26227 /*Careful, This Fruit Bites Back*/, 26235 /*Even Thieves Get Hungry*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=67500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26184; -- Wormthorn's Dream
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `AllowableRaces`=18875469, `QuestDescription`='I believe that the taint of the Blasted Lands has finally exerted its influence over my friend Wormthorn.  His experiment has failed, and his great-tree now only serves as a focus for the demons to rally around.$b$bThe tree must come down, and Wormthorn with it.  Speak with the Cenarion Observer on the other side of town; she should have some idea how to proceed.$b$b$n: the act we are about to commit must not be made known to the townspeople of Surwich.  Morale is low enough as-is.', `VerifiedBuild`=19034 WHERE `ID`=26185; -- Advice from the Cenarion Circle
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=81000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26186; -- Demoniac Vessel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (26187 /*The Downfall of Marl Wormthorn*/, 27204 /*Aradne*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=8, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26189; -- The Angerfang Menace
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardCurrencyID1`=81, `AllowableRaces`=-1, `QuestDescription`='If there is one meal I know the King likes, it''s fresh catfish.  Catfish are easy to prepare but hard to catch.  That''s where you come in!  We have a good population of Gigantic Catfish here in the waters of Stormwind but the competition to catch them is intense to say the least.  I need you to figure out a way to "acquire" some of these fine catfish for our King.  You will find fisherman at the small canal docks around town.  You should be able to figure out the rest of the plan on your own.', `VerifiedBuild`=19034 WHERE `ID`=26190; -- A Fisherman's Feast
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=112200, `Flags`=2097352, `LogDescription`='Kill any 15 naga in the Abyssal Breach.', `QuestDescription`='The whispers of the elements are crowding my thoughts, $n...$b$bThe Throne of Tides is under siege!$b$bI cannot stand idly by while the naga threaten Neptulon''s realm. We must find a way to join forces with him.$b$bCaptain Taylor will escort me to the depths where I can commune directly with Neptulon.$b$bI must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides.$b$bMay the spirits see us through, $n.', `VerifiedBuild`=19034 WHERE `ID`=26193; -- Defending the Rift
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=112200, `Flags`=2097352, `LogDescription`='Kill any 15 naga in the Abyssal Breach.', `QuestDescription`='The whispers of the elements are crowding my thoughts, $n...$b$bThe Throne of Tides is under siege!$b$bI cannot stand idly by while the naga threaten Neptulon''s realm. We must find a way to join forces with him.$b$bNazgrim will escort me to the depths where I can commune directly with Neptulon.$b$bI must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides.$b$bMay the spirits see us through, $n.', `VerifiedBuild`=19034 WHERE `ID`=26194; -- Defending the Rift
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (26197 /*The Future of Gnomeregan*/, 26199 /*The Future of Gnomeregan*/, 26203 /*The Future of Gnomeregan*/, 26206 /*The Future of Gnomeregan*/);
UPDATE `quest_template` SET `MinLevel`=1, `QuestInfoID`=21, `RewardMoneyDifficulty`=4, `AllowableRaces`=18875469, `LogDescription`='Reach level 3 to learn Frost Nova. Once you''ve learned the spell, successfully cast it twice at a Training Dummy in New Tinkertown.', `QuestDescription`='As you go on wild adventures and grow your power, you''ll start to develop new connections to the arcane, granting you new spells.

You''ll see. Go do it! Show me what you learn! I''ll be here.', `VerifiedBuild`=19034 WHERE `ID`=26198; -- The Arts of a Mage
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=4, `AllowableRaces`=18875469, `LogDescription`='Reach level 3 to learn Shadow Word: Pain. Use it 5 times on training dummies in New Tinkertown.', `QuestDescription`='You know, as you go out into this crazy world and get more powerful, you''ll also start to discover new powers that you didn''t know before.$B$BWhy don''t you go out, get some more experience, and then come back and show me what you''ve learned!', `VerifiedBuild`=19034 WHERE `ID`=26200; -- The Arts of a Priest
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardXPDifficulty`=4, `RewardMoney`=40, `RewardMoneyDifficulty`=4, `RewardBonusMoney`=120, `RewardFactionValue1`=4, `AllowableRaces`=-1, `LogDescription`='Reach level 3 to learn Corruption, then cast it on a Training Dummy in New Tinkertown 5 times.', `QuestDescription`='I''m not at all surprised that a warlock like you fought your way out of Gnomeregan. Few people, even among the gnomes, truly understand the nature of the power we wield.

As you become more powerful, you''re going to start hearing the fel voices revealing their secrets to you, teaching you new spells.

I want you to go get some more experience. Once you learn something new, show me.', `VerifiedBuild`=19034 WHERE `ID`=26201; -- The Power of a Warlock
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=3, `AllowableRaces`=23069773, `VerifiedBuild`=19034 WHERE `ID`=26202; -- The Future of Gnomeregan
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=4, `AllowableRaces`=18875469, `LogDescription`='Reach level 3 to learn Charge. Locate a Training Dummy in New Tinkertown and use Charge on it.', `QuestDescription`='Learning is the best way to improve. As you learn more, you''ll start to discover you can do things you never realized!$B$BGo, get some more experience, and learn a new technique. Then, come back and demonstrate it on a training dummy.', `VerifiedBuild`=19034 WHERE `ID`=26204; -- The Arts of a Warrior
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `RewardMoneyDifficulty`=4, `AllowableRaces`=18875469, `LogDescription`='Reach level 3 to learn Eviscerate, then find a training dummy in New Tinkertown and practice using Eviscerate 3 times.', `QuestDescription`='As you learn more and become a better rogue, you''ll start to learn new abilities.$B$BOne of the most potent ones is to chain together moves in a combination, exploiting your enemy''s weakness and opening up the opportunity to use stronger maneuvers.

Go, get some more experience and figure out how to do it. Once you can, come back here and try it out.', `VerifiedBuild`=19034 WHERE `ID`=26207; -- The Arts of a Rogue
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=1080, `Flags`=8, `VerifiedBuild`=19034 WHERE `ID`=26214; -- Hot On the Trail: Murlocs
UPDATE `quest_template` SET `RewardBonusMoney`=270, `VerifiedBuild`=19034 WHERE `ID`=26215; -- Meet Two-Shoed Lou
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardCurrencyID1`=81, `AllowableRaces`=-1, `QuestDescription`='There are a number of small lakes scattered around Orgrimmar.  These lakes fill up with crawfish every year.  That''s where you come in, $n.  I need you to catch some of those delicious crustaceans and return to me when you are done.  Assuming your catch is successful, our Horde army will feast tonight.', `VerifiedBuild`=19034 WHERE `ID`=26226; -- Crawfish Creole
UPDATE `quest_template` SET `RewardBonusMoney`=780, `VerifiedBuild`=19034 WHERE `ID`=26228; -- Livin' the Life
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=1620, `VerifiedBuild`=19034 WHERE `ID`=26232; -- Lou's Parting Thoughts
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardCurrencyID1`=81, `AllowableRaces`=33555250, `QuestDescription`='As you know, $n, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the trolls keep it stored in barrels near their structures.  Retrieve these barrels of Darkspear rice for me and I should be able to finish up. ', `VerifiedBuild`=19034 WHERE `ID`=26233; -- Stealing From Our Own
UPDATE `quest_template` SET `RewardMoney`=75, `RewardMoneyDifficulty`=5, `RewardCurrencyID1`=81, `QuestDescription`='As you know, $n, Garrosh has relegated the goblins of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the goblins keep it stored in barrels near their structures.  Retrieve these barrels of Kezan rice for me and I should be able to finish up. ', `VerifiedBuild`=19034 WHERE `ID`=26234; -- Stealing From Our Own
UPDATE `quest_template` SET `RewardBonusMoney`=210, `VerifiedBuild`=19034 WHERE `ID`=26236; -- Shakedown at the Saldean's
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=2160, `VerifiedBuild`=19034 WHERE `ID`=26237; -- Times are Tough
UPDATE `quest_template` SET `RewardBonusMoney`=2160, `VerifiedBuild`=19034 WHERE `ID` IN (26241 /*Westfall Stew*/, 26252 /*Heart of the Watcher*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `QuestDescription`='We''re in the plane of earth, $n.  Everything is absorbed by the land eventually.$B$BThe Storm''s Fury will soon be turned to dust and we won''t be able to gain any insight from its remains.$B$BGo and destroy the elementals that are dismantling the ship.  We''re only delaying the inevitable, but we need to buy ourselves some time if we''re to track down all the pieces of the World Pillar.', `VerifiedBuild`=19034 WHERE `ID`=26244; -- The Earth Claims All
UPDATE `quest_template` SET `RewardBonusMoney`=37500, `Flags`=136, `VerifiedBuild`=19034 WHERE `ID`=26246; -- Captain's Log
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=37500, `QuestDescription`='The Earthen Ring is a neutral organization, $n.  We cannot pick sides in the war between the Horde and the Alliance.$B$BLook around you -- our members come from all backgrounds.  Our mission would be compromised should racial tensions be put above our goal.  Let''s try to keep this under wraps until we have more information.$B$BWe must not jump to conclusions just yet.  I''ll send you and one of our new members to look for the Alliance gunship.$B$BFind out what you can without dragging us into the conflict.', `VerifiedBuild`=19034 WHERE `ID`=26247; -- Diplomacy First
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `QuestDescription`='Something''s wrong here, $n.$B$BThe ship''s crew has been slain.  Yet there is no bloodshed or damage to the ship''s structure.$B$BThis was not the Horde''s doing.$B$BWe will find the answers we seek by speaking to the spirits of the dead.  They have not yet left this world.$B$BTake this totem and place it near the corpses of the fallen.  You will have a few seconds to listen to their last few thoughts.$B$BBeware, however!  There is no telling how the spirits of the dead will react to our prodding.', `VerifiedBuild`=19034 WHERE `ID`=26248; -- All Our Friends Are Dead
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=37500, `QuestDescription`='It''s possible we''ll find further clues inside the admiral''s cabin. You will find it directly below us.$B$BSee if there are any survivors or information that will lead us closer to the World Pillar fragment.  Be careful, $n.  Whoever got the crew might still be out there.', `VerifiedBuild`=19034 WHERE `ID`=26249; -- The Admiral's Cabin
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56100, `AreaGroupID`=0, `QuestDescription`='It''s not too late, $n.  The cultists are probably still here.$B$BGo below decks, find out who''s in charge and subdue them.$B$BWe will obtain answers to our questions, one way or another.', `VerifiedBuild`=19034 WHERE `ID`=26250; -- On Second Thought, Take One Prisoner
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `QuestDescription`='It looks like the Twilight''s Hammer''s still on the ship.  Go below decks and take them out.$B$BBe careful, $n.  I''ve a feeling they''re not here for a spiritual retreat, if you know what I mean.', `VerifiedBuild`=19034 WHERE `ID`=26251; -- Take No Prisoners
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56100, `QuestDescription`='Hop on, $n.  Let''s see what Mr. Ogreface has to say for himself.$B$BDon''t be shy, Stormbeak''s only ever dropped a passenger a couple of times before.', `VerifiedBuild`=19034 WHERE `ID`=26254; -- Some Spraining to Do
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56100, `VerifiedBuild`=19034 WHERE `ID` IN (26255 /*Return to the Temple of Earth*/, 26258 /*Deathwing's Fall*/, 26427 /*Without a Captain or Crew*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56100, `QuestDescription`='The Twilight''s Hammer are wielding foul magic here, $n.  They animate and energize the remains of Deathwing''s blood, so that instead of drying out and disappearing it thrives and becomes more abundant.$B$BTake out one of the bloodshapers, see if they have any clues as to where we can find this "forgemaster."', `VerifiedBuild`=19034 WHERE `ID`=26256; -- Bleed the Bloodshaper
UPDATE `quest_template` SET `RewardBonusMoney`=3300, `VerifiedBuild`=19034 WHERE `ID` IN (26257 /*It's Alive!*/, 26271 /*Feeding the Hungry and the Hopeless*/, 26371 /*The Legend of Captain Grayson*/);
UPDATE `quest_template` SET `RewardBonusMoney`=1620, `VerifiedBuild`=19034 WHERE `ID` IN (26266 /*Hope for the People*/, 26353 /*Captain Sanders' Hidden Treasure*/, 26354 /*Captain Sanders' Hidden Treasure*/, 26355 /*Captain Sanders' Hidden Treasure*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=3300, `QuestDescription`='It''s been many years since anyone has offered to lend us aid, $n. Had you not come along, we might not have made it through the coming winter. You have proven yourself to be a selfless individual - a person that we can trust. I only wish we had something of value to offer you.$B$BWhile I have no information to assist you in your crusade to bring the Furlbrow''s murderer to justice, perhaps my wife can help. Speak to Salma inside and she will tell you what you need to know before you leave.', `VerifiedBuild`=19034 WHERE `ID`=26270; -- You Have Our Thanks
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=4, `LogDescription`='Reach Level 3 to Learn Corruption. Practice using Corruption 5 times against a Tiki Target.', `QuestDescription`='I tink I have something I should let ya know.$B$BAs ya'' get more powahful, yo'' gonna staht hearin'' da voices - teachin'' you new tings, new spells.$B$BGo, get some more experience, ''den come back an show me what ya learned.', `VerifiedBuild`=19034 WHERE `ID`=26274; -- The Arts of a Warlock
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=12000, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=26278; -- The Defense of Grom'gol: Raptor Risk
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=524288, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26284; -- Missing in Action
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=3300, `QuestDescription`='After my tour of duty was over in Grizzly Hills, I returned to Westfall, only to find the land in worse condition than when I left.$B$BThe price of our war left thousands of citizens homeless. They now migrate here and squat upon the deserted farmhouses and towns of the region.$B$BTo make matters worse, we are now under attack by the gnolls. The Westfall Brigade needs your help, $n. Slay the attacking gnolls and recover their orders. Someone is pulling their strings and we need to find out whom!', `VerifiedBuild`=19034 WHERE `ID`=26286; -- In Defense of Westfall
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=3300, `QuestDescription`='We were once known as the People''s Militia. These days, though, we fight under the banner of Stormwind, with the full support of King Varian Wrynn. Our goals here in Westfall are many: to clean up the mess left behind by the Defias, to expand the reach of the Alliance and to maintain order. So far we are failing on all fronts.$B$BTimes are worse now than when the Defias ran amok. Now with the indigenous gnolls of the region up in arms, we find ourselves backed into a corner. Help us, $n!', `VerifiedBuild`=19034 WHERE `ID`=26287; -- The Westfall Brigade
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=4650, `VerifiedBuild`=19034 WHERE `ID` IN (26288 /*Jango Spothide*/, 26291 /*Big Trouble in Moonbrook*/, 26295 /*Propaganda*/);
UPDATE `quest_template` SET `RewardBonusMoney`=480, `QuestDescription`='SI: 7 has been tracking Helix Gearbreaker since he entered Alliance territory two weeks ago. The letter I received from Mathias Shaw explained that he sent an agent by the name of Kearnen to Westfall to shadow Helix. Find Agent Kearnen and you''ll find Helix Gearbreaker.$B$BKearnen came into town for supplies two days ago. She mentioned that she would be near Mortwake''s Tower, southeast of here, on the Dust Plains.$B$BGet going, $n.', `VerifiedBuild`=19034 WHERE `ID`=26289; -- Find Agent Kearnen
UPDATE `quest_template` SET `RewardBonusMoney`=4650, `QuestDescription`='Helix has got himself holed up inside Klaven Mortwake''s old tower. I won''t lie to you, $n, it''s heavily guarded. I count six armed mercenaries just on the outside. There''s no way you''re getting inside that tower by yourself. Lucky for you, Claire and I are here.$B$B<Kearnen pats her sniper rifle.>$B$BI''ll cover your entry.$B$BTake this shrouding potion, you''ll need it once you get inside. Use it as soon as you enter the tower and head upstairs. Find out what Helix is hiding up there!', `VerifiedBuild`=19034 WHERE `ID`=26290; -- Secrets of the Tower
UPDATE `quest_template` SET `RewardBonusMoney`=480, `QuestDescription`='We have had a camp near Moonbrook for quite some time now, $n. One of my best soldiers works the area along with a company of Sentinel Hill troopers. Report to Captain Alpert now and find out if he has any news about the happenings in Moonbrook.$B$BAnother ally of mine is also at the Moonbrook camp. His name is Thoralius. I met Thoralius in Northrend during my time in Valgarde. He is a wise and powerful shaman. Perhaps his abilities could help us solve this mystery.', `VerifiedBuild`=19034 WHERE `ID`=26292; -- To Moonbrook!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=19200, `QuestDescription`='Far to da east de "Worldbreakers" lay hidden in da Twilight Highlands. We must end their threat and we gonna do it with da most powerful army ever!
Our new allies, de goblins, dey be making us new machines of war but I hear dat der be problems wid da quality. We can''t fight wid broken machines. Speak ta Foreman Glibbs an'' make sure me machines be ready for battle.', `VerifiedBuild`=19034 WHERE `ID`=26293; -- Machines of War
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `Flags`=136, `QuestDescription`='<Glibbs mops sweat from his brow with a greasy handkerchief.>$B$BVol''jin isn''t happy with our work? This is very bad. My boys need to step it up.$B$BMaybe you can help set an example. A set of Hellscream Demolishers just rolled off the blocks and are ready for inspection. Give them a thorough going-over, and if you find any problems, give the Chief Engineer a good thrashing. Remind them that the warchief is depending upon them!', `QuestCompletionLog`='Return to Vol''jin at Grommash Hold in Orgrimmar.', `VerifiedBuild`=19034 WHERE `ID`=26294; -- Weapons of Mass Dysfunction
UPDATE `quest_template` SET `RewardBonusMoney`=4650, `VerifiedBuild`=19034 WHERE `ID` IN (26296 /*Evidence Collection*/, 29075 /*A Time to Gain*/, 29371 /*A Time to Lose*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=4800, `QuestDescription`='It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, $n.$B$BGo to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.', `VerifiedBuild`=19034 WHERE `ID`=26297; -- The Dawning of a New Day
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='We must find if Yenniku is dead.$B$BSlay the Bloodscalps of Zuuldaia and take from them their shrunken heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku''s head is not among them.$B$BAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan''zulah!$B$BGo, $n.  You will find the heads at the ruins of Zuuldaia, along the coast to the north.', `VerifiedBuild`=19034 WHERE `ID`=26299; -- Headhunting
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=21600, `VerifiedBuild`=19034 WHERE `ID`=26309; -- Dark Vessels
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `VerifiedBuild`=19034 WHERE `ID` IN (26311 /*Unfamiliar Waters*/, 26337 /*Beating the Market*/, 26374 /*Ready the Ground Troops*/, 26388 /*Twilight Skies*/, 26549 /*Madness*/, 26608 /*Negotiations Terminated*/, 26788 /*Cementing Our Victory*/, 27038 /*Missing Parts*/, 27072 /*The Old Barracks*/, 27177 /*Salvage Operation*/, 27200 /*Siren's Song*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `VerifiedBuild`=19034 WHERE `ID` IN (26312 /*Crumbling Defenses*/, 26313 /*Core of Our Troubles*/, 26314 /*On Even Ground*/, 26315 /*Imposing Confrontation*/, 26375 /*Loose Stones*/, 26437 /*Making Things Crystal Clear*/, 26438 /*Intervention*/, 26439 /*Putting the Pieces Together*/, 26578 /*Doomshrooms*/, 26579 /*Gone Soft*/, 26581 /*A Head Full of Wind*/, 26585 /*Corruption Destruction*/, 26656 /*Don't. Stop. Moving.*/, 26710 /*Lost In The Deeps*/, 26752 /*Audience with the Stonemother*/, 26755 /*Keep Them off the Front*/, 26770 /*Mystic Masters*/, 26827 /*Rallying the Earthen Ring*/, 26833 /*Word In Stone*/, 26875 /*Undying Twilight*/, 27046 /*Fear of Boring*/, 27047 /*Motes*/, 27048 /*Underground Economy*/, 27049 /*Soft Rock*/, 27051 /*Through Persistence*/, 27126 /*Rush Delivery*/, 27141 /*Premature Explosionation*/);
UPDATE `quest_template` SET `QuestPackageID`=597, `RewardMoneyDifficulty`=5, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=18875469, `QuestDescription`='My team has finished settin'' up th'' powder kegs and th'' detonator at the bottom o'' th'' cave in th'' western part of Frostmane Hold. All you need to do is venture down there and activate th'' detonator to explode the powder and collapse those tunnels.$B$BThat''ll stop th'' flow of troggs from th'' deep parts of th'' earth. Mekkatorque''ll have an easier time of dealin'' with the remainin'' troggs if you can take out their leader, who calls ''imself Boss Bruggor. Good luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=26318; -- Finishin' the Job
UPDATE `quest_template` SET `RewardBonusMoney`=660, `VerifiedBuild`=19034 WHERE `ID`=26319; -- Secrets Revealed
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=6300, `QuestDescription`='This incense will put your body and mind in a deep meditative state. Once the trance begins you will be pulled into the spirit world. Do not fight the trance once it has begun, $n. Allow the spirits to show you what they know.$B$BYou must leave now. Go to the Deadmines, a place which I am told holds great significance in the history of Westfall. Once inside, use the incense.$B$BYou may enter the Deadmines through the old farmhouse south of here. Follow the homeless. $B$BReturn to Gryan with your discovery.', `VerifiedBuild`=19034 WHERE `ID`=26320; -- A Vision of the Past
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=9600, `QuestDescription`='I had no idea that VanCleef had a daughter, $n. If there was one thing that man was exceptionally skilled at, it was keeping secrets.$B$BHow tragic. Poor thing witnessed a horrible act. Had I only known.$B$BWhat was that? Did you hear something? It seems as if the gnolls are pulling back... where are my guards?$B$BON GUARD, $n!', `VerifiedBuild`=19034 WHERE `ID`=26322; -- Rise of the Brotherhood
UPDATE `quest_template` SET `RewardBonusMoney`=12600, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=26323; -- Favored Skull
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=57300, `QuestDescription`='Da Highlands be da home of de Dragonmaw orcs. If we show dem our might they would ally with us against da Twilight''s Hammer for sure.

Da fleet be gathering at Bilgewater Port in Azshara but there be reports of delays.
Ya did good wid getting da goblins ta work, I be needing ya skills here too.
Find Warlord Krogg in Azshara and see what be taking so long.', `VerifiedBuild`=19034 WHERE `ID`=26324; -- Where Is My Warfleet?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='<The skull speaks to you.>$b$bI live?  No, I do not... but I can.$b$bThat raptor you have is wise to have found my skull among what must have been so many.  In life, I was strong, powerful, a lord among trolls.  With your help, I can be a lord once more.$b$bThe Bloodscalps at Zuuldaia hoard magical fetishes that can help me return.  They hide these artifacts under the sand.  Use your hatchling to find these artifacts, $n... then throw them in the pot.', `VerifiedBuild`=19034 WHERE `ID`=26325; -- A Nose for This Sort of Thing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18900, `QuestDescription`='<Norsala reaches to the ground in an attempt to discern Diamant''s location, but jumps back in shock after a moment''s contact.>$B$BMy! Dat was unexpected. Diamant ain''t far at all. When I reached out ta him, he spoke back wit me and told me where we could be finin'' him. Head towards tha northeastern edge of the Jagged Wastes - Diamant will be expectin'' ya.$B$B$n, be careful. It may be unlike an earth bein'' to lay an ambush, but it was unlike dem to siege the temple in da first place.', `VerifiedBuild`=19034 WHERE `ID`=26328; -- Rocky Relations
UPDATE `quest_template` SET `QuestPackageID`=598, `RewardMoneyDifficulty`=5, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26333; -- No Tanks!
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `QuestDescription`='Hellscream expects an armada of ships for his invasion, but the docks here are weeks behind schedule. Costs are rampant and quality is poor. Corruption is the problem, $n! And I need you to root it out.$B$BThe Foebreaker, a warship berthed at the northwest pier, should have been outfitted days ago. Something reeks. Go there and oversee the construction yourself.$B$BFind out who''s disrupting our naval preparations and deal with them!', `VerifiedBuild`=19034 WHERE `ID`=26335; -- Ready the Navy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=6900, `LogDescription`='Find Shakes O''Breen at Faldir''s Cove in Arathi Highlands.', `VerifiedBuild`=19034 WHERE `ID`=26336; -- Shakes O'Breen
UPDATE `quest_template` SET `Flags`=262152, `VerifiedBuild`=19034 WHERE `ID`=26341; -- The Stone Shards
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26349; -- The Coastal Menace
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='I may be of Darkspear birth, but I spent my childhood here, in Stranglethorn Vale.  I''ve seen everything there is to see here in Stranglethorn, but the most offensive is the devastation that the Venture Company has done to the riverbed.$b$bTo make things worse, Foreman Cozzle and his crew have been increasing their activity, and I suspect they have some new plan.  Succeed where I failed, $n: Kill Cozzle, obtain his key, and steal the blueprints from his apartment.', `VerifiedBuild`=19034 WHERE `ID`=26352; -- Cozzle's Plan
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=3300, `VerifiedBuild`=19034 WHERE `ID`=26356; -- Captain Sanders' Hidden Treasure
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `QuestDescription`='I gave Hellscream my personal guarantee that I''d have his airfleet ready this week, but our flagship - The Spear of Durotar - still doesn''t have its primary engines installed.$B$BFleep promised me a dangerously shiny new engine last week. Go to her junkyard behind the bank and find out what the holdup is.$B$BThe airfleet is waiting on us, $n!', `VerifiedBuild`=19034 WHERE `ID`=26358; -- Ready the Air Force
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AreaGroupID`=0, `QuestDescription`='It was the Captain who insisted his new engines use an induction samophlange.$B$BThose things hadn''t even been invented yet!$B$BI tasked Smoot with creating one based on some stolen Venture Company schematics, and he''s finally built a working model.$B$BNow that he''s got his samophlange, he''s drunk with power. He''s running all over town with it like a goblin possessed.$B$BSmack Smoot and snag my samophlange, $n.', `VerifiedBuild`=19034 WHERE `ID`=26361; -- Smoot's Samophlange
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=17700, `AllowableRaces`=33555378, `QuestDescription`='Mind Control, very powerful, yes.$b$bWith luck, you can help Ohgan''aka escape from Zul''Gurub.$b$bThen, Ohgan''aka becomes $n''aka again!$b$bSpeak to Priestess, yes, and help $n''aka escape.', `VerifiedBuild`=19034 WHERE `ID`=26362; -- Be Raptor
UPDATE `quest_template` SET `QuestPackageID`=599, `RewardMoneyDifficulty`=6, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=26364; -- Down with Crushcog!
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='The Defias Brotherhood are not a force to be taken lightly, $n. What you witnessed was the birth of a ruthless organization of criminals that will stop at nothing to see Stormwind turned to rubble.$B$BI need you to return to Sentinel Hill and let Gryan know that I am sending him troops. I hope it''s not too late.', `VerifiedBuild`=19034 WHERE `ID`=26370; -- Return to Sentinel Hill
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `Flags`=136, `VerifiedBuild`=19034 WHERE `ID`=26372; -- Pre-Flight Checklist
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `Flags`=134217864, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=26376; -- Hatred Runs Deep
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `Flags`=131208, `VerifiedBuild`=19034 WHERE `ID`=26377; -- Unsolid Ground
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=18600, `VerifiedBuild`=19034 WHERE `ID`=26382; -- Can't Make An Omelette Without...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=16778317, `VerifiedBuild`=19034 WHERE `ID`=26383; -- Breaking Waves of Change
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `RewardChoiceItemQuantity5`=0, `AllowableRaces`=2147483647, `QuestDescription`='The orcs have begun burning down the forest, $n! They have taken over the vineyard to the east and are planning their final assault against us! They must be stopped!$B$BHead east, across the river, and kill the rampaging Blackrock orcs. Collect their weapons as proof of their demise and return to me.$B$BYou''re our only hope, $n!', `VerifiedBuild`=19034 WHERE `ID`=26389; -- Blackrock Invasion
UPDATE `quest_template` SET `QuestPackageID`=556, `RewardMoneyDifficulty`=6, `Flags`=134742048, `FlagsEx`=16, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=26390; -- Ending the Invasion!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardSpell`=140428, `Flags`=3670016, `QuestDescription`='Times like these make me long for when the Defias were still around. The cataclysm has opened a pathway from the Burning Steppes and now Blackrock orcs pour into Northshire Valley! They have taken over my vineyard and are burning it to the ground! TO THE GROUND!$B$BPlease, $n, that vineyard is all I have. Take my fire extinguisher and extinguish the flames at the vineyard. There still might be hope for that land!', `VerifiedBuild`=19034 WHERE `ID`=26391; -- Extinguishing Hope
UPDATE `quest_template` SET `QuestDescription`='$n, I gathered into this crate everything Argus asked for.  Can you take it to him?$B$BIf you''ve already spoken to Bartlett at Goldshire, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.$B$BSpeak with Dungar, then get this crate to Argus as fast as you can.  We don''t want our fighting men and women in Goldshire to go without fresh equipment!', `VerifiedBuild`=19034 WHERE `ID`=26395; -- Dungar Longdrink
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `LogDescription`='Take the Mark of Bloodhoof to the Warchief, located in Grommash Hold in Orgrimmar.$B$BYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin.', `QuestDescription`='Much has changed outside of Mulgore, $n. The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do.$B$BYou must go, $n, and be this example. Go to Orgrimmar. Tell the Warchief how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.$B$BTal at the Skytower will send you on your way. Go in peace, and never forget your people.', `VerifiedBuild`=19034 WHERE `ID`=26397; -- Walk With The Earth Mother
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `ItemDropQuantity2`=1, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (26399 /*The Mosh'Ogg Bounty*/, 26400 /*The Universal Key*/);
