UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `Flags`=2097288, `VerifiedBuild`=19034 WHERE `ID`=27060; -- Unholy Cow
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18600, `QuestDescription`='The dragon they''re speaking of is Abyssion, $n.  It''s not going to be easy to get the fragment off of him.$B$BMeet with Mylra again.  She is operating nearby at the Twilight Overlook.$B$BShe will tell you what our next move will be.', `VerifiedBuild`=19034 WHERE `ID`=27061; -- The Twilight Overlook
UPDATE `quest_template` SET `RewardNextQuest`=0, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=3000, `VerifiedBuild`=19034 WHERE `ID`=27063; -- Looming Threat
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=57300, `Flags`=136, `QuestDescription`='$n, it almost seems like Samuelson is trying to intentionally waste your time. The dockworkers don''t know anything. More importantly, explosives are missing from Stormwind Harbor!$B$BYou know what I think? I bet Samuelson knows more than he''s letting on. He probably has a lead on Twilight''s Hammer and wants all the credit and glory for himself.$B$BWe should peek through his records at the SI:7 headquarters. Take me there and I should be allowed to look at his files and find out what he really knows. ', `VerifiedBuild`=19034 WHERE `ID`=27064; -- He's Holding Out on Us
UPDATE `quest_template` SET `QuestDescription`='Our reinforcements from Kalimdor arrived last night. Three orc gunships full of supplies, weapons and soldiers. Three orc gunships lost to Bloodfang''s damned worgen.$B$BHow could an entire orc fleet lose to a small band of enemy combatants that lack any siege weaponry? An important question that you will answer for me.$B$BGather your gear and report to the orc admiral, Hatchet, at the Forsaken Rear Guard, southwest of here.$B$BGet those orcs operational, $n.$B$BI await your full report.', `VerifiedBuild`=19034 WHERE `ID`=27065; -- The Warchief's Fleet
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `AllowableRaces`=32, `LogTitle`='Learning the Word', `LogDescription`='Reach level 3 to learn Shadow Word: Pain. Practice using it 5 times on Training Dummies in Camp Narache.', `QuestDescription`='As you become more skilled, your skills will expand, and you will gain access to many new powers.

Go - get some experience out there, and come back to me when you''ve learned something new. You can demonstrate on the training dummies nearby.', `VerifiedBuild`=19034 WHERE `ID`=27066; -- Learning the Word
UPDATE `quest_template` SET `MinLevel`=2, `QuestInfoID`=21, `Flags`=524288, `LogTitle`='Moonfire', `LogDescription`='Reach level 3 to learn Moonfire. Practice using it on a Training Dummy in Camp Narache.', `QuestDescription`='As you develop your skills, druid, you will begin to feel your connection to the Earthmother deepening. You will begin to understand new secrets of nature, and learn to cast new spells.

Go now, get more experience, and return to me when you''ve learned a new spell. Demonstrate what you''ve learned.', `VerifiedBuild`=19034 WHERE `ID`=27067; -- Moonfire
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=7000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=39300, `VerifiedBuild`=19034 WHERE `ID`=27068; -- Chief Ukorz Sandscalp
UPDATE `quest_template` SET `Flags`=3145736, `QuestDescription`='We may not have to live down the shame of this defeat, $n. The Warchief will likely have us all executed instead.$B$BI''ll be damned if we don''t go down without a fight. Although the whole beachhead is overrun by Bloodfang worgen, there may still be hope. I want you to accompany one of our sea pups to the beachhead, directly west of here, and recover our supplies. Return to me when the pup can carry no more.', `VerifiedBuild`=19034 WHERE `ID`=27069; -- Steel Thunder
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=7000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=37800, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `VerifiedBuild`=19034 WHERE `ID`=27070; -- A Fool's Errand
