UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=8, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (27075 /*Servants of Cho'gall*/, 27077 /*Clutching at Chaos*/, 27201 /*Val'kyr Incursion*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `Flags`=8, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=27078; -- Gor'kresh
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `AllowableRaces`=33555378, `QuestDescription`='Word is in from Andorhal, $n.  The battle has resumed.$b$bIt has become somewhat well-known among the Forsaken that you are a hero of the first battle of Andorhal.  Koltira has requested your presence immediately.', `VerifiedBuild`=19034 WHERE `ID`=27083; -- The Battle Resumes!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=33555378, `QuestDescription`='To the west, deep within Alliance-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.$b$bHunt down and slay these commanders, $n.  The humans won''t stand a chance.', `VerifiedBuild`=19034 WHERE `ID`=27086; -- Ashes to Ashes
UPDATE `quest_template` SET `AllowableRaces`=33555378, `LogDescription`='With the Enthralled Val''kyr by your side, kill 5 Frightened Provincial Minutemen so that they can be turned into Forsaken Troopers.  Then find Thassarian in western Andorhal.', `QuestDescription`='You have no idea how difficult it was to stay disguised while I watched Koltira let this war slip away from us.  Even now, those infernal farmers threaten to overwhelm us.  All because he refused to slay a friend.$b$bTake my val''kyr again, $n.  With her by your side, kill these farmers, convert them to Forsaken, and mobilize them.  Then take a group of them into Alliance-held western Andorhal and hunt down this death knight, Thassarian.$b$bWe will win this war yet.', `VerifiedBuild`=19034 WHERE `ID`=27089; -- Ace in the Hole
UPDATE `quest_template` SET `MinLevel`=2, `LogDescription`='Reach level 3 to learn Charge. Locate a Training Dummy outside the Sunspire and practice using Charge.', `QuestDescription`='Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.$B$BGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.', `VerifiedBuild`=19034 WHERE `ID`=27091; -- Charge!
UPDATE `quest_template` SET `RewardBonusMoney`=95400, `AreaGroupID`=0, `QuestDescription`='Don''t worry about me, $c. I''ve uncovered the Twilight''s Hammer plot. They''ve been stealing and stockpiling explosives coming into Stormwind harbor. Somehow, they''ve gotten access to the catacombs underneath the Cathedral of Light. I''ve heard talk of someone called "The Black Bishop."$B$BThere''s no time to warn the guard, $n! You''ve got just minutes to get into the catacombs and disarm that bomb. Go! Now! Or THOUSANDS of PEOPLE will DIE!', `VerifiedBuild`=19034 WHERE `ID`=27092; -- Cataclysm in the Catacombs
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=2097160, `QuestDescription`='Some would say that we are lucky to be alive. Those people would be idiots. At least had we died we would not have had to face the Warchief''s wrath. Alas, what''s done is done! Now we must attempt to regain our lost honor.$B$BThe third ship in our fleet sank off the coast of the Skittering Dark, northwest of here. Those that made it to shore quickly found themselves swarmed by the giant spiders of the area and encased in webbing.$B$BIf there are survivors we must free them! Go, $n! To the Skittering Dark!', `VerifiedBuild`=19034 WHERE `ID`=27093; -- Lost in the Darkness
UPDATE `quest_template` SET `Flags`=65536, `QuestDescription`='Vengeance is all consuming, $n! Our third ship sank off the coast of the Skittering Dark, northwest of here. The men that made it off that boat were either captured or killed by the Skitterweb spiders of the region. For that, the spiders must die! ALL OF THEM!$B$BTravel to the Skittering Dark and crush those insects!$B$BBe on the lookout for their matriarch. Perhaps if we find her we can end this menace forever!', `VerifiedBuild`=19034 WHERE `ID`=27095; -- Skitterweb Menace
UPDATE `quest_template` SET `QuestDescription`='<Admiral Hatchet hands you an envelope sealed with the mark of the Horde.>$B$BThis is your commendation letter. It''s the least I could do for you given the circumstances.$B$BReturn to Lady Sylvanas Windrunner with the letter and inform her of our status. Let her know that we will be ready to march on her command.$B$BGoodbye, $n. You are an excellent soldier.$B$BNortheast, $g lad:ma''am;. To Forsaken High Command!', `VerifiedBuild`=19034 WHERE `ID`=27096; -- Orcs are in Order
UPDATE `quest_template` SET `QuestDescription`='Fenris Isle stands defiantly at the heart of Lordamere Lake - a cruel memory of a time long since passed.$B$BThough no longer infested by gnoll vermin, a new threat has emerged.  Human refugees, driven from their holdings in Hillsbrad, have fled to Fenris Isle in hopes of escaping defeat at our hands. A critical error on their part.$B$BYou are to take Agatha with you to Fenris Isle and slaughter all humans. She will raise the fallen as Forsaken, bolstering our forces in the process.$B$BDo not fail me, $n.', `VerifiedBuild`=19034 WHERE `ID`=27097; -- Rise, Forsaken
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `QuestDescription`='Ride with me to the Sepulcher, $n. There are many things I wish to discuss with you. It is imperative that you understand the history of Lordaeron and the plight of the Forsaken.', `VerifiedBuild`=19034 WHERE `ID`=27098; -- Lordaeron
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `QuestDescription`='You must strike at their leaders, $n. You will find them holed up in the old keep. Battle your way inside and find the holdouts! Turn them for your queen!$B$BNone shall escape the mighty grasp of the Forsaken!', `VerifiedBuild`=19034 WHERE `ID`=27099; -- No Escape
