UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `Flags`=134217736, `AllowableRaces`=33555378, `QuestDescription`='Gandling has brought his lieutenant, the Ravenian, with him.  This lumbering brute is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.$b$bYou will find the Ravenian within a tower near the southern end of town.  I recommend caution before fighting him, $n.  He will not be a pushover.', `VerifiedBuild`=19034 WHERE `ID`=27117; -- Brute Strength
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `Flags`=262280, `QuestDescription`='I knew you''d heed our call, $n.  When Deathwing was first defeated by the other dragon aspects, he retreated to Deepholm, the realm of earth.$B$BDeathwing''s return to our world left a rift open between Azeroth and Deepholm.$B$BIf we don''t mend the breach, this land will be torn asunder.$B$BWe''re doing our best to contain the damage on this side of the rift.  Aggra will take you through the rift so you can help repair the damage from the other side.$B$BGet on her wyvern when you''re ready.', `VerifiedBuild`=19034 WHERE `ID`=27123; -- Deepholm, Realm of Earth
UPDATE `quest_template` SET `RewardXPDifficulty`=8, `Float10`=0.25, `RewardBonusMoney`=18000, `VerifiedBuild`=19034 WHERE `ID`=27124; -- Unfinished Gordok Business
