UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `Flags`=131208, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=27135; -- Something that Burns
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=22500, `Flags`=16384, `VerifiedBuild`=19034 WHERE `ID` IN (27140 /*Alexi's Gambit*/, 27143 /*Barov Family Fortune*/, 27147 /*Kirtonos the Herald*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=22500, `Flags`=16384, `QuestDescription`='One of Kel''Thuzad''s most trusted students oversees the operations in Scholomance. You must confront the lich, Ras Frostwhisper, in his lair. The door to his chamber is adjacent to the viewing room.$B$BDestroy him, $n. Leave no trace of his existence so that he may never again bring such horrors into our world.', `VerifiedBuild`=19034 WHERE `ID`=27142; -- The Lich, Ras Frostwhisper
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=22500, `Flags`=16384, `QuestDescription`='Doctor Theolen Krastinov is responsible for the deaths of thousands. His nickname, The Butcher, is well earned for the atrocities he takes joy in executing. He must be punished, justice must be meted out.$B$BFind him and exact upon him the agony he has inflicted upon countless innocents, including me and my husband. Once he is destroyed, burn our remains. Turn them to ashes, $n. Release our grieving souls.', `VerifiedBuild`=19034 WHERE `ID`=27146; -- Doctor Theolen Krastinov, the Butcher
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=23700, `Flags`=134234112, `VerifiedBuild`=19034 WHERE `ID`=27148; -- School's Out Forever
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `QuestDescription`='Magus Bisp is one of Hearthglen''s most preeminent arcanists.  To imagine that he would be interacting with gnolls... and dabbling in necromancy?  Unthinkable.$b$bYou''ll find him atop the tower near Hearthglen''s main gate.  Hopefully he''ll have an explanation for all of this.  If not, well... I wouldn''t go to the top of that tower unprepared, $n.', `VerifiedBuild`=19034 WHERE `ID`=27154; -- Bagging Bisp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=27600, `AreaGroupID`=0, `QuestDescription`='Say, I never caught your name.  $n?  Pleased to meet you, $n.$b$bI''ve got one more problem that needs fixing, and you have a look about you that just screams "I''m a problem-fixer".$b$bThere''s a small mine on the northern edge of Hearthglen, where we get most of the ore that the town needs.  My drudges who work the mine normally do a decent job.$b$bUnfortunately, it seems that a larger-than-average spider has taken up residence within this cave.  Think you can clear things up for me?', `VerifiedBuild`=19034 WHERE `ID`=27157; -- Drudges... <Sigh>
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=4950, `Flags`=8, `AllowableRaces`=18875469, `QuestDescription`='Hurry, $n... there isn''t time to waste.$b$bThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I''m sure he can use all the help he can get.  With Arthas dead, now is the time for the Alliance to start to retake Lordaeron.$b$bSpeak with the gryphon master, Bibilfaz Featherwhistle, when you are ready, and he will put you on the first flight out there.', `VerifiedBuild`=19034 WHERE `ID`=27158; -- The Battle for Andorhal
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `Flags`=134217736, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27162; -- Scholomancer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `Flags`=134217736, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='Gandling has brought his lieutenant, Rattlegore, with him.  This clattering horror is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.$b$bYou will find Rattlegore within an old town-hall building, near the center of town.  I recommend caution before fighting him, $n.  He will not be a pushover.', `VerifiedBuild`=19034 WHERE `ID`=27163; -- Brute Strength
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=134217736, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (27164 /*Araj the Summoner*/, 27327 /*Grimtotem Chiefs: The Chief of Chiefs*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=1980, `Flags`=8, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27165; -- Victory, For Now
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='We must always be prepared for battle, $n.  Whether that battle is against the Forsaken in Andorhal, against the Scourge in the east, or against some yet-unknown foe is unknown.  What is known, is that we must be ready.$b$bWe are low on arrows.  I can obtain the shafts and heads, but I still need feathers.  The birds that circle to the northwest typically molt this time of year.  Would you mind traveling out into the field and gathering some of these feathers for our camp?', `VerifiedBuild`=19034 WHERE `ID`=27166; -- Go Fletch!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=15600, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27169; -- Uther's Blessing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=2220, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (27175 /*The Menders' Stead*/, 27233 /*The Menders' Stead*/);
UPDATE `quest_template` SET `RewardBonusMoney`=18900, `Flags`=150995072, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=27176; -- Just the Tip
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `QuestDescription`='They''ve come slithering up from the ocean depths, $n. The naga. I think their intent is to reinforce the Bastion of Twilight, probably by heading inland via the Verrall river. We can''t let that happen!$B$BTeach them that these shores are ours now, and send them scurrying back to the lightless depths.$B$BKill the Blackscale naga worming their way through the Obsidian Breakers! ', `VerifiedBuild`=19034 WHERE `ID`=27178; -- Naga Reinforcements
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `Flags`=16777352, `VerifiedBuild`=19034 WHERE `ID`=27179; -- Field Work
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=6500, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=34800, `VerifiedBuild`=19034 WHERE `ID` IN (27185 /*Cutting the Competition*/, 27305 /*Of Love and Family*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `QuestDescription`='In my years as an herbalist, I''ve often observed that nature will provide subtle cures to the most vexing of problems. I''ve read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.$B$BIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, $n. It may be our only hope.', `VerifiedBuild`=19034 WHERE `ID`=27189; -- The Witch's Bane
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=6500, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=34800, `QuestDescription`='Men as far as Kul Tiras spoke of the legendary Fras Siabi''s premium tobacco. It was a delicacy enjoyed by every single person of importance that visited Stratholme. King Terenas, Uther the Lightbringer, Highlord Fordring...yes, they all enjoyed Siabi''s specialty.$B$BSadly, Fras stayed in his shop when Stratholme was invaded, swearing on his life that the Scourge would never touch his tobacco. Venture forth and see if even one bit remains here...it is worth its weight in gold, I assure you.', `VerifiedBuild`=19034 WHERE `ID`=27192; -- The Great Fras Siabi
UPDATE `quest_template` SET `QuestDescription`='<The Banshee Queen''s voice invades your thoughts once more.>$B$BSearch the nearby farmhouses for Alliance stragglers. Keep an eye out for any information that could lead us to Crowley and Bloodfang. Seek and destroy all that would stand in your way, $n!', `VerifiedBuild`=19034 WHERE `ID`=27193; -- Seek and Destroy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=3300, `QuestDescription`='<The Banshee Queen speaks through your mind.>$B$BWe must act quickly, $n. They mustn''t be given the chance to flee. I am dispatching a squadron of my most powerful troopers to the Deep Elem Mine. I''m also sending the Horseman with them to ensure that nothing goes wrong. Meet him at the Deep Elem Mine, east of Olsen''s Farthing, and CRUSH those rats.', `VerifiedBuild`=19034 WHERE `ID`=27194; -- Cornered and Crushed!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `QuestDescription`='The mistress has put me in charge of this lot. Our primary mission is to get in there, corner the rats, and kill ''em all, including Bloodfang.$B$BYou''ve done us a solid service in gettin'' the information, $n. Join in the glory and help us drive a sword through their miserable skulls!$B$BLet me know when you''re ready and I''ll call for the charge.', `VerifiedBuild`=19034 WHERE `ID`=27195; -- Nowhere to Run
UPDATE `quest_template` SET `RewardBonusMoney`=18900, `VerifiedBuild`=19034 WHERE `ID`=27196; -- On to Something
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=2640, `AllowableRaces`=18875469, `QuestDescription`='Word is in from Andorhal, $n.  The battle has resumed.$b$bIt has become somewhat well-known among the Alliance forces that you''re a hero of the first battle of Andorhal.  Thassarian has requested your presence immediately.', `VerifiedBuild`=19034 WHERE `ID`=27197; -- The Battle Resumes!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=32700, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (27198 /*Supporting the Troops*/, 27202 /*Brother Against Brother*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=26100, `AllowableRaces`=18875469, `QuestDescription`='To the east, deep within Forsaken-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.$b$bHunt down and slay these commanders, $n.  The Forsaken won''t stand a chance.', `VerifiedBuild`=19034 WHERE `ID`=27199; -- Ashes to Ashes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `Flags`=1310856, `QuestDescription`='Thank the spirits you''re here, $n.$B$BWe''re not sure how much longer we can maintain the rift in the Maelstrom.$B$BOur most powerful members, led by Thrall, are barely preventing the tear.$B$BLast I heard, our only hope was to go through the breach and attempt to stabilize it from the other side.$B$BI will conjure a portal.  Take it and report to Thrall as soon as you can.', `VerifiedBuild`=19034 WHERE `ID`=27203; -- The Maelstrom
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=2640, `AllowableRaces`=18875469, `QuestDescription`='We nearly have this battle won, $n.  I can taste victory.  The Forsaken never stood a...$b$bWhat the hell is that!?', `VerifiedBuild`=19034 WHERE `ID`=27205; -- The Depravity of the Forsaken
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=7000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=36300, `VerifiedBuild`=19034 WHERE `ID` IN (27208 /*The Dreadlord Balnazzar*/, 27223 /*Retribution*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=26100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27213; -- The End of the Deserters
UPDATE `quest_template` SET `RewardBonusMoney`=10500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27219; -- Is it Real?
UPDATE `quest_template` SET `RewardSpell`=140428, `Flags`=3145736, `QuestDescription`='Thank the Warchief that you''re here, $n. I''ve made a critical error with the sea dogs and need your help to rectify the situation.$B$BYou see, I sent them out against the worgen coming from Fenris Isle stone cold sober. They attacked the beasts and promptly got their butts handed to them. Many of them died, but a few still live, barely clinging on to dear life.$B$BTake this barrel of ale to the Decrepit Fields, east of here, and force it down the throats of fallen sea dogs.', `VerifiedBuild`=19034 WHERE `ID`=27226; -- Hair of the Dog
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=7500, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=42300, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `RewardChoiceItemQuantity4`=0, `VerifiedBuild`=19034 WHERE `ID`=27227; -- Lord Aurius Rivendare
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=7500, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `VerifiedBuild`=19034 WHERE `ID` IN (27228 /*Man Against Abomination*/, 27230 /*Weapons for War*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=22200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (27236 /*Secondhand Diving Gear*/, 27237 /*Recover the Cargo!*/);
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there''s no telling who it might be or if the person is still alive!$B$BOne thing is for certain, $n. The Defias wouldn''t go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You''ll find her at the top of the mage tower at Theramore''s center.', `VerifiedBuild`=19034 WHERE `ID`=27238; -- Jaina Must Know
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.$B$BI can use my magic to expedite your trip to Stormwind. Just speak to me when you''re prepared to go, $n.', `VerifiedBuild`=19034 WHERE `ID`=27240; -- Proof of Treachery
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='Captain Vimes should see the orc report you found, $n.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!$B$BThe captain is in the barracks, on the northeastern side of Theramore Isle.', `VerifiedBuild`=19034 WHERE `ID`=27247; -- Captain Vimes
UPDATE `quest_template` SET `RewardBonusMoney`=12300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27248; -- Mission to Mudsprocket
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=960, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27266; -- Wulf Calls
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `QuestDescription`='I have an urgent message for you from Stormwind, $n. It seems that High Priestess Laurena has asked to speak with you at the Cathedral of Light in Stormwind''s Cathedral Square. The messenger did not say what the matter concerned, but that you should travel to Stormwind with all haste.', `VerifiedBuild`=19034 WHERE `ID`=27268; -- Make Haste to the Cathedral
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `QuestDescription`='I have an urgent message for you from Stormwind, $n. It seems Farseer Umbrua has asked to speak with you the next time you''re in the city.$B$BThe messenger gave no explanation for the farseer''s invitation, but you should travel to Stormwind and find Farseer Umbrua at the Golden Keg in the Dwarven District as soon as you can.', `VerifiedBuild`=19034 WHERE `ID`=27270; -- An Audience with the Farseer
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `QuestDescription`='I just received a message from Stormwind, $n. One of Stormwind''s most renowned mages, Maginor Dumas, has requested that you visit him in the Mage Quarter inside Stormwind. You will be able to find him inside the Wizard''s Sanctum atop the large tower in the heart of the Mage Quarter.$B$BI do not know what he has planned, but it sounds like he has been impressed with your rapid progress. ', `VerifiedBuild`=19034 WHERE `ID`=27271; -- Journey to the Wizard's Sanctum
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `QuestDescription`='It seems that the elders in our ranks have taken notice of your progress and dedication, $n. Demisette Cloyce, one of the oldest and most respected members of our circle, has sent word that she wishes to speak with you. You should not take such an invitation lightly. Most only speak with her in the course of their lessons, but if she has asked to see you personally, it must be an important matter.$B$BHurry back to Stormwind and look for her beneath the Slaughtered Lamb in the Mage Quarter.', `VerifiedBuild`=19034 WHERE `ID`=27272; -- Demisette Sends Word
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=960, `AllowableRaces`=18875469, `QuestDescription`='You just missed the messenger from Moonglade, $n. He said little, except that he carried an urgent message from Loganaar, one of the honored trainers of the Cenarion Circle. Head to Moonglade as quickly as you can, $n. The matter sounds important.$B$BLook for Loganaar in the village of Nighthaven.', `VerifiedBuild`=19034 WHERE `ID`=27273; -- An Invitation from Moonglade
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='I have an urgent message for you from Stormwind, $n. Chief Surgeon Gashweld has asked to meet with you in Stormwind. The message didn''t say what the chief surgeon wanted to discuss, but you should make your way to Stormwind as quickly as you can. Look for Chief Surgeon Gashweld in the Dwarven District of the city.', `VerifiedBuild`=19034 WHERE `ID`=27274; -- The Chief Surgeon
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `QuestDescription`='I''ve received an urgent message from Orgrimmar for you, $n. The renowned mage, Ureda, wants you to meet with her in Orgrimmar. I''m not sure what this is about, but if I was you, I would travel to the capital as fast as possible and seek out Ureda in the Cleft of Shadow.', `VerifiedBuild`=19034 WHERE `ID`=27277; -- An Audience with Ureda
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `QuestDescription`='A messenger just arrived from Orgrimmar bearing a communication for you. Gordul, the senior rogue trainer in Orgrimmar, has sent for you. You must head to Orgrimmar immediately and meet with him in the Cleft of Shadow.$B$BWhen Gordul summons you, the prudent thing to do is obey. Do not keep him waiting, $n.', `VerifiedBuild`=19034 WHERE `ID`=27279; -- The Shattered Hand
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `LogTitle`='The Earthbreaker Calls', `LogDescription`='Speak with Terga Earthbreaker in Orgrimmar''s Valley of Wisdom.', `QuestDescription`='News travels upon the winds, young shaman.  Your deeds have not gone unnoticed!  It seems Terga Earthbreaker wishes to discuss something with you.  Make your way to Orgrimmar as quickly as you can and speak with her in the Valley of Wisdom.  She will be among the others who offer training.', `VerifiedBuild`=19034 WHERE `ID`=27280; -- The Dreamseeker Calls
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `QuestDescription`='I just received word that you are needed in Orgrimmar, $n. Grezz Ragefist, the honored trainer of warriors in the city, has sent for you. It would not be wise to ignore such a summons.$B$BTravel quickly to Orgrimmar and the Valley of Honor where Grezz awaits your arrival.', `VerifiedBuild`=19034 WHERE `ID`=27281; -- Grezz Ragefist
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `LogTitle`='Kranosh''s Behest', `LogDescription`='Speak with Kranosh in the Cleft of Shadow.', `QuestDescription`='$n, I have received word that you are needed back in Orgrimmar. Kranosh, one of the senior warlock trainers in the Cleft of Shadow, has something important that he wishes to discuss with you. It seems like the kind of thing that cannot wait.$B$BMake your way back to Orgrimmar and speak with him as soon as you can.', `VerifiedBuild`=19034 WHERE `ID`=27282; -- Zevrost's Behest
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='The time has come to destroy Crowley, Bloodfang and every dog at their command. To do this, though, will require cunning and planning the likes of which they would never dare dream!$B$BAs one of my most trusted soldiers, $n, I need you to go to Forsaken Forward Command, located in Gilneas, and report to Deathstalker Commander Belmont. I have sent Belmont ahead with my plans. He awaits your arrival.$B$BArthura will escort you to Forward Command. Tell me when you are ready and I will send you on your way.', `VerifiedBuild`=19034 WHERE `ID`=27290; -- To Forsaken Forward Command
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='Master Pyreanor, a senior Blood Knight and advisor to the warchief, requires your presence in Orgrimmar. He has taken an interest in your training, $n, and it is imperative that you speak with him immediately.$B$BThe message I received didn''t mention the reason he requested your visit, but you should set out for Orgrimmar right away. Master Pyreanor can be found in the keep in the center of the Valley of Strength.', `VerifiedBuild`=19034 WHERE `ID`=27298; -- Seek Out Master Pyreanor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='It won''t be takin'' much convincin'' to turn us against da Twilight - dat''s already our goal. We''ve already come to battle here though, so we may be needin'' ya help before we can turn towards dere fortress.$B$BDa Twilight have already brought Iso''rath up from da ground to the south, I''m sure ya noticed. Its tentacles have been burstin'' from da ground all around us. We could use a hand beatin'' them down if you be willin''.', `VerifiedBuild`=19034 WHERE `ID`=27299; -- Torn Ground
