UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=33555378, `LogDescription`='Slay Isha Gloomaxe.', `QuestDescription`='Basic brave philosophy dictates that if you kill the leaders of your enemy''s forces, they will soon fall into disarray. We are going to do just that, $c.$B$BIsha Gloomaxe is the closest of the Grimtotem chiefs. We will test her and her axe, and she will be found wanting.', `VerifiedBuild`=19034 WHERE `ID`=27315; -- Grimtotem Chiefs: Isha Gloomaxe
