9381 /*FLAG - Teleport to Hyjal*/, 29391 /*Guardians of Hyjal: Call of the Ancients*/, 29395 /*FLAG - Teleport to Uldum*/, 29399 /*Shopping Around*/, 29411 /*What Now?*/, 29592 /*Caster Legendary BREADCRUMB TRACKER*/, 30561 /*[DNT] Fun for the Little Ones TRACKER*/, 30562 /*[DNT] A Fizzy Fusion TRACKER*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=1048584, `AllowableRaces`=18875469, `QuestDescription`='Whatever the Grimtotem are doing with these Drums of War, we don''t want them to have them.$B$BDon''t worry, $n, we''ll figure it all out. But first, we need to gather all of the pieces of the puzzle.', `VerifiedBuild`=19034 WHERE `ID`=27325; -- The Drums of War
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=1048584, `AllowableRaces`=33555378, `QuestDescription`='Whatever it is that the Grimtotem are doing with the Drums of War, we do not want them to keep them.$B$BDo not worry, $n, we will figure out what is going on here. But first, we need to gather all of the artifacts.', `VerifiedBuild`=19034 WHERE `ID`=27326; -- The Drums of War
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=134217736, `AreaGroupID`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=27328; -- Grimtotem Chiefs: The Chief of Chiefs
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=32, `QuestDescription`='I just received word that you are needed in Orgrimmar, $n. Seer Liwatha has asked for you to return to the city as quickly as you are able. Her message didn''t include any other information, and the matter seemed urgent.$B$BLook for Seer Liwatha in Orgrimmar''s Valley of Wisdom.', `VerifiedBuild`=19034 WHERE `ID`=27331; -- The Seer's Call
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='Shadow-Walker Zuru requires your presence in Orgrimmar right away, $n. Do not keep him waiting, as it sounds like a matter of some importance.$B$BYou can find the shadow-walker in the Valley of Spirits inside Orgrimmar.', `VerifiedBuild`=19034 WHERE `ID`=27332; -- Seek the Shadow-Walker
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=8, `AllowableRaces`=52430847, `QuestDescription`='I don''t know how much longer we can hold out for, $n. Crowley and Bloodfang''s worgen know every hidey hole and safe spot in Gilneas. One minute they''re standing in front of you and the next minute they''re gone! We''re gonna lose this war to attacks of opportunity, even though we have a superior military presence.$B$BBut momma didn''t raise no quitter! Forsaken until the end, my friend.$B$BHead west into the headlands and help our soldiers on the front line. Kill the attacking worgen rebels!', `VerifiedBuild`=19034 WHERE `ID`=27333; -- Losing Ground
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='I just received a message from Dark Cleric Cecille in Orgrimmar. She requests that you join her in the audience chamber in Grommash Hold, where you can find her with the delegation from Undercity. The cleric didn''t mention the purpose of your visit, but it is clearly important. Make haste, $n.', `VerifiedBuild`=19034 WHERE `ID`=27334; -- Dark Cleric Cecille
UPDATE `quest_template` SET `QuestInfoID`=21, `QuestDescription`='A messenger just asked me to pass along an invitation. It is from Tyelis, a priest trainer and emissary from Silvermoon.$B$BHe asks you to meet him inside Grommash Hold in Orgrimmar. You should make your way there immediately, $n. It sounds important.', `VerifiedBuild`=19034 WHERE `ID`=27335; -- Journey to Orgrimmar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=2147483647, `VerifiedBuild`=19034 WHERE `ID` IN (27336 /*The Grimtotem Weapon*/, 27409 /*The Essence of Enmity*/);
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='From your earliest days, $n, your trainers identified you as a natural talent. Your rapid progress and dedication have made you an example.$B$BIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.$B$BLegend has it that the cursed Shadowfang Keep in Silverpine Forest is home to a variety of materials that you will need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27337; -- A Fitting Weapon
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27338 /*Our Boys on the Shore*/, 27514 /*Bird Down! Bird Down!*/, 27516 /*Wings Over Highbank*/, 27545 /*The Way is Open*/, 27607 /*The Southern Flank*/, 27621 /*Firebeard's Patrol*/, 27629 /*The Vizier's Vote*/, 27640 /*Dunwalds Don't Die*/, 27807 /*Clan Mullan*/, 27809 /*Firebeard Bellows*/, 27816 /*Personal Request*/, 28001 /*A Coward's Due*/, 28233 /*The Lost Brother*/, 28294 /*The Kirthaven Summit*/, 28849 /*Twilight Skies*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `Flags`=140, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27341; -- Scouting the Shore
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='The Dark Lady has sent you and Arthura here for a very specific purpose. Before I tell you more, we must make preparations.$B$BHead east into the forest of Gilneas and search near the trees and rocks of the region for a special plant known as wolfsbane. Gather as much of the wolfsbane as you can carry and return to me.$B$BOur mission here goes far beyond the scope of the battlefield, $n. In time, all will be revealed.', `VerifiedBuild`=19034 WHERE `ID`=27342; -- In Time, All Will Be Revealed
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=18875469, `QuestDescription`='I have been watching your progress, $n, and I can only conclude that the Light shines brightly upon you. You are becoming an exemplary $c.$B$BTo honor your dedication, King Wrynn has commissioned the royal armorer to forge a special weapon.$B$BThe materials to make your weapon are unique, and only found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27343; -- The Hand of the Light
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=18875469, `QuestDescription`='I am not the only one impressed by your progress $n. Your mastery of bow and pet and your dedication to the Alliance have reached the ears of King Wrynn.$B$BIn recognition of your service, the king has commissioned the royal bowyer to craft a special weapon.$B$BThe cursed Shadowfang Keep in Silverpine Forest is home to the unique materials needed for your weapon. Travel there and obtain the scope from Lord Godfrey''s gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27344; -- A Well-Earned Reward
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=52430847, `QuestDescription`='Communications are down with all of our frontline outposts, $n. As of right now I don''t have a damn clue as to the status of our troops in Gilneas. We need to re-establish communications.$B$BI need you to head west into the headlands and find our outpost on the coast. By now the soldiers there are likely all dead, but their F.C.D. might be operational. Grab the device and get back to me.', `VerifiedBuild`=19034 WHERE `ID`=27345; -- The F.C.D.
UPDATE `quest_template` SET `RewardBonusMoney`=6000, `AllowableRaces`=52430847, `QuestDescription`='I''m not gonna lie to you, $n. What I''m about to ask you to do is suicide. Chance of failure is about 95%.$B$BAll communication from Dreadwatch Outpost has been severed. With the worgen constantly rushing us we have no means by which to get to Dreadwatch to check on our soldiers. I need you to head south to the outpost and check on our soldiers. I''ll keep in contact through the Forsaken communication device - F.C.D. - from here on out.$B$BKEEP CLEAR OF THE MAIN ROAD.', `VerifiedBuild`=19034 WHERE `ID`=27349; -- Break in Communications: Dreadwatch Outpost
UPDATE `quest_template` SET `RewardBonusMoney`=4650, `AllowableRaces`=52430847, `QuestDescription`='<The F.C.D. hums.>$B$BOur next outpost is Rutsak''s Guard, located due east of Dreadwatch. Make your way to Rutsak''s while avoiding the worgen rushers, $n. You don''t want to deal with those monsters by yourself.$B$BIf you make it there in one piece, look for Captain Rutsak.$B$BJust be prepared for the worst.', `VerifiedBuild`=19034 WHERE `ID`=27350; -- Break in Communications: Rutsak's Guard
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=7500, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27352 /*Liquid Gold*/, 27359 /*Argent Reinforcements*/);
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=18875469, `QuestDescription`='Your talent has attracted much attention in shamanic circles, $n. Word of your mastery of the elements and dedication to the Alliance has even reached the palace.$B$BIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.$B$BThe materials for your weapon can only be found in Silverpine Forest''s cursed Shadowfang Keep. Travel there and retrieve Lord Walden''s talisman, the Book of Lost Souls, and the essence of the ghosts haunting the castle.', `VerifiedBuild`=19034 WHERE `ID`=27353; -- Blessings of the Elements
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=18875469, `QuestDescription`='The Cenarion Circle is pleased with your progress, $n. You are a credit to all druids and we look to you and your peers as the future of of our brotherhood.$B$BThe circle has decided to honor you with the creation of unique staff.$B$BThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden''s collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27356; -- The Circle's Future
UPDATE `quest_template` SET `RewardBonusMoney`=6300, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27360; -- Vengeance for Our Soldiers
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=18875469, `QuestDescription`='The Light truly shines in you and your dedication to the Alliance, $n. You serve as an example to your fellow priests and comrades in arms.$B$BIn recognition of your deeds, King Wrynn has commissioned the royal enchanter to create a special staff.$B$BThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27361; -- Favored of the Light
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `VerifiedBuild`=19034 WHERE `ID` IN (27362 /*Favored of Elune*/, 27437 /*The Dark Cleric's Bidding*/);
