UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27393 /*The Call of the Blade*/, 27394 /*The Call of the Blade*/, 27630 /*The High Priest's Vote*/, 27685 /*Good Deed Left Undone*/, 27999 /*The Fate of the Doyles*/, 28198 /*The Weakest Link*/, 28363 /*Stirred the Hornet's Nest*/, 28845 /*The Vortex Pinnacle*/, 28866 /*Into the Stonecore*/, 28869 /*Pebble*/, 28909 /*Sauranok Will Point the Way*/, 29066 /*Good News... and Bad News*/);
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=33555378, `QuestDescription`='You have picked up the ways of the hunter quickly, $n. Your skills have made you a credit to the Horde and an example to the younglings.$B$BAs a reward for your progress and hard work, the warchief has commissioned his personal bowyer to create a unique weapon.$B$BThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials we''ll need. Travel there and retrieve the scope from Lord Godfrey''s gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27395; -- A Marksman's Weapon
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Many members of the Shattered Hand do not survive their training, $n. Not only have you survived, but you will soon become a feared blade of the Horde.$B$BAs a reward for your progress, the warchief has commissioned his personal smith to forge a weapon.$B$BThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you''ll need. Travel there and recover Commander Springvale''s sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27396; -- Blade of the Shattered Hand
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=33555378, `LogTitle`='Terga''s Task', `QuestDescription`='The elements and spirits speak to you with clear voices, $n. You have become a powerful shaman and an example to others wishing to serve the Horde.$B$BWord has even reached the warchief, and he has commissioned his personal smith to forge a special weapon for you.$B$BThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you''ll need. Travel there and obtain Lord Walden''s talisman, the Book of Lost Souls, and essence from the ghosts haunting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27397; -- Dreamseeker's Task
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='We''ve defeated the enemy''s forces here, $n.  But Hyjal is not the only place where our foes are moving against us.$B$BI''ve been informed that our allies in the Earthen Ring have put out a call for aid in a matter I''ve been assured is most critical.$B$BSpeak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City for further instructions.', `VerifiedBuild`=19034 WHERE `ID`=27398; -- The Battle Is Won, The War Goes On
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='We''ve defeated the enemy''s forces here, $n.  But Hyjal is not the only place where our foes are moving against us.$B$BI''ve been informed that our allies in the Earthen Ring have put out a call for aid in a matter I''ve been assured is most critical.$B$BSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.', `VerifiedBuild`=19034 WHERE `ID`=27399; -- The Battle Is Won, The War Goes On
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=33555378, `QuestDescription`='All of your trainers agree, $n, you show an amazing amount of talent for a journeyman. Even the warchief has heard of your rapid progress.$B$BAs a reward for mastering your studies, the warchief has commissioned his master enchanter to create a staff for you.$B$BThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you''ll need. Travel there and find a magical heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27400; -- Mastering the Arcane
UPDATE `quest_template` SET `RewardBonusMoney`=8100, `AllowableRaces`=52430847, `QuestDescription`='<The F.C.D. buzzes.>$B$BLook around the Cathedral Quarter. There should be a telescope nearby that the 7th Legion uses for spying. Find it and use it to scout the harbor. We need to find out how the 7th Legion got past our fleet.$B$BHurry, $n. We can''t hold these beasts back much longer.$B$BWhat does tomorrow bring?', `VerifiedBuild`=19034 WHERE `ID`=27401; -- What Tomorrow Brings
UPDATE `quest_template` SET `RewardBonusMoney`=18600, `AllowableRaces`=33555378, `QuestDescription`='Your mastery of our ways continues to grow quickly, $n, and I am far from the only one impressed by your progress. Even the warchief has taken note of your deeds.$B$BAs a reward for your dedication, the warchief has commissioned his personal enchanter to craft a staff.$B$BThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you''ll need. Travel there and retrieve the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27402; -- Token of Power
UPDATE `quest_template` SET `AllowableRaces`=32, `QuestDescription`='I have watched your training, $n. Yours is the path of an exemplary Sunwalker, a brave defender of the Horde and a follower of our ways.$B$BAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.$B$BThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you''ll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27403; -- A True Sunwalker
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='The Cenarion Circle is pleased with your progress, $n. You are a credit to all druids and we look to you and your peers as the future of our brotherhood.$B$BThe circle has decided to honor you with the creation of unique staff.$B$BThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden''s collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.', `VerifiedBuild`=19034 WHERE `ID`=27404; -- The Circle's Future
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=9600, `Flags`=786432, `AllowableRaces`=52430847, `QuestDescription`='<The F.C.D. buzzes.>$B$B<Howls can be heard in the background.>$B$B$n, do you read me? Come in, $n. This is likely my final transmission. The worgen have overrun Forsaken Forward Command. It is now only a matter of time before the base is lost. Belmont and the val''kyr, Arthura, have left. Belmont mentioned that they will rendezvous with you at Emberstone Village, located to the northeast. Find Belmont, $n. Our mission - our very existence - depends on it.$B$BYou are our final hope.', `VerifiedBuild`=19034 WHERE `ID`=27405; -- Fall Back!
UPDATE `quest_template` SET `RewardBonusMoney`=10500, `AllowableRaces`=52430847, `QuestDescription`='Lord Vincent Godfrey spent his life defending the kingdom of Gilneas. When the worgen curse ravaged this land, Godfrey was one of the first Gilneans to take up arms against the beasts. It is said that upon discovering that his king was afflicted by the curse, Godfrey took his own life. He would rather be dead than serve the very creatures that he had defended his home against.$B$BWe are going to give him a second chance, $n. Together we will battle southeast towards Tempest''s Reach to collect his corpse.', `VerifiedBuild`=19034 WHERE `ID`=27406; -- A Man Named Godfrey
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `QuestDescription`='When the dragons came and took over Brogg''s old home, Stonemaul ogres fled and left everything behind, including clan''s banner.$B$BBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it''s called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.$B$BBrogg''s clan''s old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, $n.', `VerifiedBuild`=19034 WHERE `ID`=27408; -- Banner of the Stonemaul
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=37200, `AllowableRaces`=2147483647, `QuestDescription`='Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. $n, you have been very helpful in preparing for this moment. Will you help?$B$BTake Brogg''s clan banner and travel east until you see a cave like a dragon''s mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg''s challenge to Onyxia.$B$BBrogg and the Stonemaul will have their lands back!', `VerifiedBuild`=19034 WHERE `ID`=27411; -- Challenge to the Black Flight
UPDATE `quest_template` SET `AllowableRaces`=2147483647, `VerifiedBuild`=19034 WHERE `ID` IN (27416 /*The Brood of Onyxia*/, 28965 /*Candy Bucket*/, 28967 /*Candy Bucket*/, 28981 /*Candy Bucket*/, 28982 /*Candy Bucket*/);
