UPDATE `quest_template` SET `RewardBonusMoney`=3000, `AllowableRaces`=18875469, `QuestDescription`='Heya, $n, Kelsey Steelspark down in Tanaris left a message for you. She says that the gnomes down there in Gadgetzan heard about what you''ve been doing up here.$B$BAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I''m certain they could use your help.', `VerifiedBuild`=19034 WHERE `ID`=27446; -- Tanaris is Calling
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Heya, $n, Megs Dreadshredder down in Tanaris left a message for you. She says that the goblins down there in Gadgetzan heard about what you''ve been doing up here.$B$BAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I''m certain they could use your help.$B$BBesides, that Megs is a hottie!', `VerifiedBuild`=19034 WHERE `ID`=27447; -- Tanaris is Calling
