UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27466 /*Argent Call: Northdale*/, 27906 /*Neeka Bloodscar*/, 28305 /*The Fate of Bloodvenom Post*/, 28306 /*Whisperwind Grove*/, 28373 /*Timbermaw Hold*/, 28534 /*Descendants of the Highborne*/, 28535 /*Descendants of the High Elves*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `QuestDescription`='The Noxious Glade is a quagmire, both literally and figuratively.  There''s enough Scourge up there to give us trouble for the rest of both of our lifetimes.$b$bThey can re-animate the weaker ones when they die, $n.  They will never stop coming if we don''t do something.$b$bTake these blades and drive them through the corpses of any Scourge troopers you find.  The blade is simple, but its enchantment will prevent the dead bones from being reanimated.  Forever.', `VerifiedBuild`=19034 WHERE `ID`=27467; -- Buried Blades
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=5400, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27469 /*Friends on The Other Side*/, 27470 /*A Potential Ally*/, 27471 /*Blackrock Anomaly*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `RewardBonusMoney`=13800, `AllowableRaces`=52430847, `QuestDescription`='You are unwavering in your loyalty to the Forsaken, $n. Know that what you have done for us - for the Horde - will not go unnoticed. With Lord Godfrey and his men recovered, we will have a great advantage over the Gilneas Liberation Front and the rest of the Alliance dogs.$B$BNow stand by my side as Lord Godfrey is reborn as one of us. Together we will bring him and his men into the fold.', `VerifiedBuild`=19034 WHERE `ID`=27472; -- Rise, Godfrey
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=9600, `Flags`=8, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27474; -- Breaking the Barrier
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=52430847, `QuestDescription`='The magi of Ambermill have employed foul magic to keep us away. Elemental servitors, created with immunities that we cannot breach, protect their territory.$B$BVenture east to Ambermill and slay the unyielding elemental servitors that guard the town and recover their cores. Bring their cores back to me so that I may devise a method by which we are able to destroy them all!', `VerifiedBuild`=19034 WHERE `ID`=27475; -- Unyielding Servitors
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='Take the codex and travel north to the Sepulcher. Once there, find Dalar Dawnweaver. Dalar is a former archmage of the Kirin Tor. Surely he will be able to bring down the protective wards surrounding this codex and pry its secrets loose.$B$BHurry, $n.', `VerifiedBuild`=19034 WHERE `ID`=27476; -- Dalar Dawnweaver
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27477 /*The Corpulent One*/, 27487 /*Ix'lar the Underlord*/, 27523 /*Duskwing, Oh How I Hate Thee...*/, 27962 /*A Lumbering Relic*/, 28056 /*Rise, Obsidion*/, 28518 /*Legacy of the High Elves*/);
UPDATE `quest_template` SET `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27478 /*Relios the Relic Keeper*/, 27713 /*The Day that Deathwing Came*/, 28330 /*Trail of Filth*/, 28485 /*Yetimus the Yeti Lord*/, 28643 /*The Durnholde Challenge: Zephyrus*/, 28644 /*The Durnholde Challenge: Teracula*/, 28645 /*The Durnholde Challenge: Bloodvenom*/, 28646 /*The Durnholde Challenge: Infernus*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `QuestDescription`='The Mossflayers of Zul''Mashar spit in the face of the Light!  They cannibalize, they criminalize, they prioritize the forces of evil over good!  I advise that you remove their eyes, and give rise to the demise and the goodbyes of the unwise!$b$bYou will travel north, and you will rain down on them with righteous justice and indignation, $n.  The fury that they have wrought in the eyes of the Light shall be channeled through you.', `VerifiedBuild`=19034 WHERE `ID`=27479; -- Righteous Indignation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=10200, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27480; -- Ley Energies
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='It is time that I asked a favor of you, $n.$b$bFar to the north of Eastwall Tower, hidden among the hills, is the Mossflayer capital city of Zul''Mashar.  It was here that I was born, and here that I died.$b$bThe traitor, Thresh''jin, sits atop Zul''Mashar''s ziggurat.  It was my every right to be there, but he took the seat from me with treachery and deceit.  He is not strong.  He is weak.$b$bI will meet you in Zul''Mashar, and we will kill him.  Your strength and mine.  Together.', `VerifiedBuild`=19034 WHERE `ID`=27481; -- Out of the Ziggurat
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `QuestDescription`='This is the last time you will see me, $n.  I am leaving the caravan.$b$bIf you want to continue fighting by my side, hang on to Thresh''jin''s body.  I can wait for a while longer.  When you are ready to say goodbye, throw the body into the bonfire atop Zul''Mashar''s ziggurat.$b$bThank you for your companionship, $n.  You were strong.', `VerifiedBuild`=19034 WHERE `ID`=27482; -- Into the Flames
