UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `AllowableRaces`=18875469, `QuestDescription`='Now that the attack is underway, it''s time to deal with the Twilight Citadel. If you don''t mind, I''d like for you to escort the SI:7 forces to Master Mathias Shaw.$B$BHe''s hiding somewhere up top. The SI:7 squad commander can tell you where.$B$BThank you, $n. We look forward to joining you in the assault upon the Citadel!', `VerifiedBuild`=19034 WHERE `ID`=27502; -- Up to the Citadel
