UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=75600, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27541; -- Lessons From the Past
UPDATE `quest_template` SET `RewardBonusMoney`=8700, `AllowableRaces`=52430847, `QuestDescription`='Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops.$B$BThe Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands.$B$BLet''s get this nonsense over with, $n. Pyrewood is directly southwest of the Forsaken Front.', `VerifiedBuild`=19034 WHERE `ID`=27547; -- Of No Consequence
UPDATE `quest_template` SET `RewardBonusMoney`=8700, `Flags`=8, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27548; -- Lessons in Fear
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `Flags`=3145864, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27549; -- By the Light of the Stars
UPDATE `quest_template` SET `RewardBonusMoney`=10800, `Flags`=2097160, `AllowableRaces`=52430847, `QuestDescription`='The attacks against our front are a distraction. With our attention turned towards the worgen onslaught, the Alliance has managed to take Pyrewood Village from our occupying forces.$B$B<Godfrey hands you a bundle of torches.>$B$BIt must be purged.$B$BWith these torches we will burn Pyrewood Village to the ground, leaving only ashes for the enemy to hide behind.$B$BLet us not waste another minute. Pyrewood Village is located southwest of the Forsaken Front. Lead us there, $n.', `VerifiedBuild`=19034 WHERE `ID`=27550; -- Pyrewood's Fall
