UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='Let''s go fishing, $n! Now that the mortars are ready, we can take out the leader of this invasion.$B$BFathom-Lord Heth''Jatar rules over the Blackscale warrior caste. Go to the Heth''Jatari Banners just northeast of here and honk this conch shell. It''s like a dog-whistle. For fish.$B$BWhen Heth''Jartar shows up, I''ll order the mortars to concentrate fire. You''ll see the targets of the incoming shells.$B$BLure Heth''Jatar into our mortar fire and pummel him into submission!  ', `VerifiedBuild`=19034 WHERE `ID`=27606; -- Blast Him!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=134217736, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='The fate of the Scarlet Crusade is tragic, if somewhat ironic.  At one point, they led the charge of humanity against the undead.  Now, they resemble those corpses that they once hunted.  What caused their descent into undeath isn''t certain, but it doesn''t make them any less dangerous.$b$bOne of their deadliest was an assassin who went by the name of Rohan.  We have intel that places him atop the bell tower in this very abbey.  Find him and kill him, $n.  And try not to die on the way.', `VerifiedBuild`=19034 WHERE `ID`=27613; -- The Assassin
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=52430847, `QuestDescription`='This battle was won before it started.  Right now, we''re just shooting for style points.$b$bWithin these barracks, the sniveling Scarlet Crusaders cling to their priceless artifacts, even though some of the objects are too holy for their now-undead hand to touch.  So they keep them in chests, hidden from the world.$b$bYou will find these artifacts, and bring them back to me.  They belong to the Argent Crusade.  They belong in the hands of the righteous.', `VerifiedBuild`=19034 WHERE `ID`=27614; -- Scarlet Salvage
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=134217736, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27615 /*The Wrathcaster*/, 27616 /*The Huntsman*/, 27619 /*The Commander*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `Flags`=262152, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27617 /*Befouled No More*/, 27618 /*Argent Upheaval*/);
