UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `Flags`=136, `AllowableRaces`=52430847, `QuestDescription`='$n, I''ve got plans for a better shredder. But my engineers can''t wade into a combat zone alone.$B$BGo locate a salvageable shredder in the Twilight Shores, and use it to signal one of my salvage experts to join you. Defend the shredder while we make some "upgrades."$B$BThe Alliance won''t know what hit them! At least, not until my marketing campaign kicks in!', `VerifiedBuild`=19034 WHERE `ID`=27622; -- Mo' Better Shredder
UPDATE `quest_template` SET `RewardBonusMoney`=113400, `RewardItem1`=0, `RewardAmount1`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27627; -- Just a Fancy Cockroach
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56700, `AllowableRaces`=52430847, `QuestDescription`='Hurry, $n.  We must speak to my brother, the king.$B$BHe is bent on averting war with Al''Akir and the Neferset.  He has foolish hopes that there is a diplomatic solution to this problem.$B$BMaybe once he hears what occurred here he will see reason.', `VerifiedBuild`=19034 WHERE `ID`=27628; -- Send Word to Phaoris
UPDATE `quest_template` SET `RewardBonusMoney`=37800, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27631 /*The High Commander's Vote*/, 27983 /*Lunk's Adventure: Cranky Little Dwarfs*/);
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=8000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=47400, `AllowableRaces`=52430847, `QuestDescription`='Hakkar... The mere mention of The Soulflayer''s name will send many running. In the Sanctum of the Fallen God the Atal''ai have recovered a significant portion of his skeleton and seek to restore him to life. Already his children have begun to show up in the area.$B$BPlace this egg in that sanctum, and it will force his summoning prematurely. $n, do not hesitate. Strike once his avatar appears!', `VerifiedBuild`=19034 WHERE `ID`=27633; -- The Blood God Hakkar
UPDATE `quest_template` SET `RewardNextQuest`=27674, `RewardMoneyDifficulty`=4, `Flags`=16777224, `QuestDescription`='You''ve been down here in Gnomeregan for a long time, $n, and it''s amazing that you''ve survived and kept your wits so long! We need to get you out.$B$BBefore we can send you to the surface to join the rest of the gnomes, you have to go through the decontamination process. Just head into the next room and board the Sanitron 500. It will do the rest! It shouldn''t even hurt... much.$B$BWhen you''re all done, check in with Technician Braggle and he''ll make sure you get some suitable gear.', `VerifiedBuild`=19034 WHERE `ID`=27635; -- Decontamination
