UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `AllowableRaces`=52430847, `QuestDescription`='Look, if there''s one thing I know, it''s elementals. I''ve been able to really gain an appreciation for how they feel. Let me tell you, they don''t appreciate being enslaved one bit!$B$BSo, what I''m saying here is that if you were to free the enslaved elementals, I''m sure that not only would they show their gratitude, they''d also likely turn on their masters.$B$BSounds like a win-win to me, $n.', `VerifiedBuild`=19034 WHERE `ID`=27662; -- Unbinding
