UPDATE `quest_template` SET `RewardXPDifficulty`=6, `RewardMoneyDifficulty`=5, `FlagsEx`=512, `QuestDescription`='My name is Nevin Twistwrench and I''m the commander of the Survivor Assistance Facilitation Expedition, or S.A.F.E.$B$BI don''t know how you managed to survive the radiation down here, $n, but most of the others haven''t fared so well. My team is rounding up the survivors, but the radiation-addled leper gnomes are too numerous for us to hold back much longer. They''ve lost their minds!$B$BIf you''re still strong enough to wield a weapon or cast a spell, would you help us clear out some of these leper gnomes?', `VerifiedBuild`=19034 WHERE `ID`=27670; -- Pinned Down
UPDATE `quest_template` SET `RewardXPDifficulty`=7, `RewardMoneyDifficulty`=5, `VerifiedBuild`=19034 WHERE `ID`=27671; -- See to the Survivors
