UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=96600, `Flags`=136, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='There are three candidates for Ascendancy that we need to eliminate: Dame Alys Finnsson, Master Klem, and Mia the Rose.$B$BI''d like for you to serve as my distraction. When the time is right, I''ll step in and finish them off from behind.$B$BWhatever you do, $n, do not underestimate them. Each got to where they are by being ruthless and very good at what they do.', `VerifiedBuild`=19034 WHERE `ID`=27688; -- Distract Them for Me
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=96600, `Flags`=136, `AreaGroupID`=0, `AllowableRaces`=33555378, `QuestDescription`='There are three candidates for Ascendancy that need killing: Dame Alys Finnsson, Master Klem, and Mia the Rose.$B$BI want you to serve as a distraction. When the time is right, I''ll step in to finish them off from behind.$B$BJust make sure that whatever you do, you don''t underestimate them, $n. Each of those lunatics got to where they are by being ruthless and very good at what they do.', `VerifiedBuild`=19034 WHERE `ID`=27689; -- Distract Them for Me
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=52430847, `QuestDescription`='$n, the stronghold at Bloodgulch is the heart of the Dragonmaw empire in the Highlands. It is just up the river. Narkrall Rakeclaw is using his considerable power to amass a wing of drake-riders there.$B$BFor the Dragonmaw to succeed, Bloodgulch must succeed. Go to Narkrall and make sure it is so.', `VerifiedBuild`=19034 WHERE `ID`=27690; -- Narkrall, the Drake-Tamer
