UPDATE `quest_template` SET `RewardXPDifficulty`=7, `Float10`=0.25, `RewardMoney`=3500, `RewardMoneyDifficulty`=8, `Float13`=0.25, `RewardBonusMoney`=6900, `AllowableRaces`=52430847, `QuestDescription`='$n, I require your assistance immediately! I am Zaetar, son of Cenarius, and I am trapped here after an unfortunate series of events! Before saving me is an option, you must help me clean out the corruption that runs so rampant through Maraudon.$B$BLord Vyletongue is the satyr ruler of the purple crystal caverns. He is an insidious agent of the Burning Legion and his continued presence can only lead to chaos and death. He can live no longer!', `VerifiedBuild`=19034 WHERE `ID`=27697; -- Corruption in Maraudon
UPDATE `quest_template` SET `RewardXPDifficulty`=8, `Float10`=0.25, `RewardMoney`=3825, `RewardMoneyDifficulty`=8, `Float13`=0.25, `RewardBonusMoney`=10500, `AllowableRaces`=52430847, `QuestDescription`='Princess Theradras, my former mate, has used her enormous power to corrupt the very nature of Maraudon. Even now her creations run rampant here, and I fear that they may soon escape into the open world to sow the seeds of death and destruction.$B$B$n, venture forth and kill Noxxion and Razorlash. They are two of her most powerful minions and their deaths would cause the callous Princess much deserved grief and suffering of her own. Then, perhaps, you can help free my spirit from her grasp.', `VerifiedBuild`=19034 WHERE `ID`=27698; -- Servants of Theradras
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=73800, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27699 /*Shark Weak*/, 27729 /*Once More, With Eeling*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `Flags`=1048712, `AllowableRaces`=18875469, `QuestDescription`='Look at that. Lirastrasza''s destroying them!$B$BThere are drakes that she''s downing that need finishing off, $n. Wouldn''t want the Twilight''s healers to get them back up into the air.$B$BTime for a little Coup de Grace.', `VerifiedBuild`=19034 WHERE `ID`=27702; -- Coup de Grace
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `Flags`=1048712, `AllowableRaces`=33555378, `QuestDescription`='Look at that. Lirastrasza''s destroying them!$B$BThere are still drakes that she''s downing that need finishing off, $n. We don''t want the stinking Twilight healers to get them back up into the air.$B$BTime for a little Coup de Grace.', `VerifiedBuild`=19034 WHERE `ID`=27703; -- Coup de Grace
