UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=94500, `Flags`=786560, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27738; -- The Pit of Scales
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=1800, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=12000, `AllowableRaces`=52430847, `QuestDescription`='$n, I''m afraid I must ask of you the impossible.$B$BI received my eyepatch because he willed it so. Countless thousands have perished to his wrath. It was only by sheer miracle that we were able to imprison him here.$B$BDoing so was a grave mistake. We held out as long as we could, but then they came. From the shadows and darkness, gnolls in service of Hogger ripped my best men to pieces.$B$BYou must defeat the Gnoll King, lest he mounts another attack and slaughters us all in cold, bloodthirsty rage.', `VerifiedBuild`=19034 WHERE `ID`=27739; -- The Gnoll King
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `Flags`=3145856, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27744; -- Rune Ruination
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=96600, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='That''s Magmatooth, my estranged fire elemental. $n, you gotta kill him or he''s gonna kill me!$B$BIt was all just a big misunderstanding. How was I to know he''d be mad about me "borrowing" his heart down in Deepholm? He can''t die... not permanently anyway!$B$BHe''s got the controller to the portal on him for sure. You gotta get the controller and then use it in the Fire portal to take us back to the entrance.', `VerifiedBuild`=19034 WHERE `ID`=27745; -- A Fiery Reunion
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='This war has taken its toll on us as a people. We have lost much to secure our place as the rightful rulers of Lordaeron. And though the moment is won, the battle continues to rage in other parts of the Eastern Kingdoms.$B$BI must return to the Undercity to recuperate. I want you to go to Hillsbrad Foothills in my stead, $n. As my most trusted soldier, you will lead our forces to absolute domination against our enemies in Hillsbrad.$B$BReport to High Executor Darthalia at Southpoint Blockade, to the east.', `VerifiedBuild`=19034 WHERE `ID`=27746; -- Empire of Dirt
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='Supplies are short, $n. We''ve got refugees coming into Thundermar from up and down the ridge - that''s a lot of mouths to feed.$B$BPlenty of food stores were left behind as people pulled their families to safety. We need that food!$B$BScour the Thundermar ruins south, east, and southwest of here for food stores.$B$BCareful, $c! The fighting around the ruins is pretty intense.', `VerifiedBuild`=19034 WHERE `ID`=27753; -- Never Leave a Dinner Behind
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27755 /*The Curse of the Tombs*/, 28488 /*Beneath the Surface*/);
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=800, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27756; -- The Foreman
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=800, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='<Bzzzzzzzzzzzzt.>$B$BHello, can you hear me? Excellent!$B$BIt looks like Helix is in charge of building an enormous mast. You don''t think they''re trying to finish the Defias Juggernaut, do you?$B$BYou''d better go investigate $n, and don''t be afraid to get your hands dirty! You have clearance to use deadly force if necessary and, let''s face it, it''s probably going to be necessary.', `VerifiedBuild`=19034 WHERE `ID`=27758; -- The Carpenter
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `Flags`=136, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27761; -- A Disarming Distraction
UPDATE `quest_template` SET `RewardBonusMoney`=3300, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27762; -- Fuselight, Ho!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=16500, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=27764; -- A Strange Request
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=52430847, `QuestDescription`='Nyxondra is being held against her will.  She is hidden from her brood, right in the middle of their breeding grounds.  She lays eggs, but they will be taken away before she can see them hatch.$b$bCruel?  Perhaps... but not nearly as cruel as the treatment that their dragonflight showed my mistress.$b$bShow me that I can trust you, $n.  Take Nyxondra''s eggs, and bring them here.  You will need to beat Nyxondra into submission before you can take them.', `VerifiedBuild`=19034 WHERE `ID`=27771; -- Third Sample: Implanted Eggs
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=52430847, `QuestDescription`='I made a calculated decision in revealing my identity to you, $n.  I needed you to trust me, but I can no longer stay here in Lethlor Ravine, as my cover has quite clearly been blown.$b$bYou may be able to slip away unnoticed, however.  Here, take the results of our research, and bring them west.  At Agmond''s End, you will find a gnome who knows what to do with these samples.$b$bHurry, $n!  You mustn''t loiter here any longer than necessary!', `VerifiedBuild`=19034 WHERE `ID`=27772; -- The Venerable Doctor Blam
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `Flags`=136, `AllowableRaces`=52430847, `QuestDescription`='The expedition''s numbers are extremely large, user $n.$B$BDealing with them by conventional means would take you an estimated 2,700,136.5 hours.$B$BWe can make use of a powerful source of energy held within expedition''s crawler vehicle.$B$BWe will need the fusion core''s access codes to accomplish this.$B$BMekgineer Twizzleflux has these codes and can be found at the Starwatch Tower to the southeast.$B$BI''ve uploaded jamming frequencies to a scrambler.  Use it to temporarily disable Twizzleflux''s defenses.', `VerifiedBuild`=19034 WHERE `ID`=27777; -- Core Access Codes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `AllowableRaces`=52430847, `QuestDescription`='It is true.  New expedition crews have arrived by sea.$B$BMy scanners detect that they already have been afflicted by the curse phenomenon.$B$BYou must hurry and go aboard the M.A.C. Diver.  The access codes will give us control over the fusion core''s functions, but there is still a layer of security we must bypass.$B$BUser $n, I must ask you to hack a very sophisticated mainframe known as the "Wibson."$B$BDo not worry I will provide you with further instructions.', `VerifiedBuild`=19034 WHERE `ID`=27778; -- Hacking the Wibson
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=94500, `AllowableRaces`=52430847, `QuestDescription`='I have downloaded my program to the fusion core and have complete control over it.$B$BI''ve created a small pocket of air inside to avoid vaporizing user $n.$B$BI will yield control of all movement functions so I can dedicate my cycles to keeping the core stable.$B$BGo down the hill and neutralize as many of the expedition members as possible.$B$BMy analysis reveals you might feel... "guilt" as a result of such high fatality numbers.$B$BUser $n, you must be assured that expedition members are without hope.', `VerifiedBuild`=19034 WHERE `ID`=27779; -- Gnomebliteration
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=800, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='<Bzzzzzzzzzzzzt.>$B$B<Bzzzzzzzzzzzzt.>$B$BHe-hello? $n, are you there? Are you still alive? Hello?$B$BOh good, you''re still there! What in the name of Lordareon are they building? It''s some sort of mechanized monstrosity! You have to stop them from completing that...that...thing! $B$BThrow out the rules, do whatever you have to do to thwart them!', `VerifiedBuild`=19034 WHERE `ID`=27781; -- The Machination
UPDATE `quest_template` SET `RewardBonusMoney`=7800, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27782; -- Mathias Needs You
UPDATE `quest_template` SET `RewardBonusMoney`=7800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=27783; -- Garona Needs You
UPDATE `quest_template` SET `RewardBonusMoney`=77100, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27784; -- The Hammer of Twilight
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=800, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=6900, `AllowableRaces`=18875469, `QuestDescription`='<Bzzzzzzzzzzzzt.>$B$BI can''t believe it...they''re almost done rebuilding it! We don''t have much time, $n.$B$BAdmiral Ripsnarl, Vanessa''s right hand man, is bound to be on board. We''ll never get to her if he''s still alive to do anything about it. You''re going to need to scale the unfinished Juggernaut, find Ripsnarl, and kill him so we can get to Vanessa''s private quarters on the top deck.$B$BBe careful, the Admiral bears the worgen curse and would take much pleasure in digging his claws into you!', `VerifiedBuild`=19034 WHERE `ID`=27785; -- The Admiral
UPDATE `quest_template` SET `RewardBonusMoney`=77100, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=27786; -- The Hammer of Twilight
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=115800, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27787; -- Skullcrusher the Mountain
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=115800, `AreaGroupID`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=27788; -- Skullcrusher the Mountain
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=900, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='Hello there, $n. I''ve heard a great deal about you. Listen closely, you''re only going to have one solid shot at this.$B$BThe new Defias Kingpin must be inside the hut orchestrating this entire operation. I want you to go inside and take her down, for the sake of the hundreds of innocent people the organization her father started has killed and terrorized.$B$BI''m shocked that she would let you get so close to her domain without fleeing and waiting until more favorable conditions, but it seems we''re in luck.', `VerifiedBuild`=19034 WHERE `ID`=27790; -- The Defias Kingpin
