UPDATE `quest_template` SET `Flags`=1048584, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (27828 /*Eric, the Utility Dwarf*/, 27834 /*Baelog, the Glass Cannon*/, 27835 /*Olaf, the Big Fella'*/);
UPDATE `quest_template` SET `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='Hello, $n.  It looks like you four have had time to become well-acquainted.$b$bI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.$b$bYou will find him and his minions at the Dustbowl, northeast of Dragon''s Mouth.  Hunt him down and defeat him.  You will likely need the help of your new dwarven allies.', `VerifiedBuild`=19034 WHERE `ID`=27829; -- The Wrath of a Dragonflight
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='I''d say we have a dragon problem, but it seems like they''re a little more interested in New Kargath than they are in our small encampment.  Nevertheless, I''ve got top men focused on keeping the dragons at bay.$b$bOne problem that has gone unchecked, however, is the ogre camp to our southwest.  A small army of combatants seems to have appeared outside of their hovel.$b$bWe can''t sit and wait for them to flank us, soldier.  Thin their ranks before they thin ours.', `VerifiedBuild`=19034 WHERE `ID`=27833; -- Half-Ton Holdouts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `AllowableRaces`=52430847, `QuestDescription`='Slaying the foul creatures that plague the river will not be enough, $n.$B$BA new generation of these monstrosities already threatens to spawn within our holy waters.$B$BSeek their foul eggs and destroy them.', `VerifiedBuild`=19034 WHERE `ID`=27836; -- Stopping the Spread
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='You might have dealt with the symptoms of our problem, $n.  But I''ve been studying these foul beasts and the eggs are not laid here by them.$B$BThe stream from the current carries their eggs to the dam, but whatever is laying them will be found upstream.$B$BGo northeast, to the river''s main source, and deal with the root of the corruption.', `VerifiedBuild`=19034 WHERE `ID`=27838; -- The Root of the Corruption
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=47400, `VerifiedBuild`=19034 WHERE `ID`=27840; -- Draenethyst Crystals
