UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=70800, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27849 /*Assault on Stonard*/, 27851 /*Cutting Supply*/);
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=900, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `QuestDescription`='The Shattered Hand has laid mostly quiet for years now.$B$BNo more!$B$BYou will be the instrument of our rebirth, $n. Slay the Defias Kingpin and commandeer her ship for the Horde! We will outfit it as a proper orc warship and use it to finally lay waste to Stormwind$B$BAny survivors will spread word of our unstoppable power across all of Azeroth, and all will tremble before our might!$B$BGo now, VanCleef''s death will be your greatest triumph yet hero.', `VerifiedBuild`=19034 WHERE `ID`=27850; -- The Defias Kingpin
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=47400, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27860; -- The Lost Ones
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=115800, `AllowableRaces`=52430847, `QuestDescription`='I was wondering when you''d show up, $n! Having a past champion of the Ring of Blood here will be a huge draw! We''re gonna be rich, buddy! RICH!$B$BAnyway, this is some old Dragonmaw fighting pit. Didn''t take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!$B$BYou know the drill, $n. When you''re ready, let me know and we''ll get this show on the road!', `VerifiedBuild`=19034 WHERE `ID`=27861; -- The Crucible of Carnage: The Bloodeye Bruiser!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=115800, `AllowableRaces`=52430847, `QuestDescription`='Well well, if it isn''t the once champion of anguish, $n! I''m seeing good money in the future now that you''re here! We''re gonna be rollin in the dough, buddy! Filthy RICH!$B$BAnyway, this is some old Dragonmaw fighting pit. Didn''t take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!$B$BYou know the drill, $n. When you''re ready, let me know and we''ll get this show on the road!', `VerifiedBuild`=19034 WHERE `ID`=27862; -- The Crucible of Carnage: The Bloodeye Bruiser!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=115800, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27863 /*The Crucible of Carnage: The Bloodeye Bruiser!*/, 27866 /*The Crucible of Carnage: Calder's Creation!*/, 27867 /*The Crucible of Carnage: The Earl of Evisceration!*/, 29135 /*All-Seeing Eye*/, 29234 /*Delegation*/, 29239 /*Nordrassil's Bough*/, 29285 /*Alignment*/, 29307 /*Heart of Flame*/, 29308 /*Heart of Flame*/, 29309 /*The Stuff of Legends*/, 29312 /*The Stuff of Legends*/, 29432 /*Delegation Tracker*/);
