UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=36900, `AllowableRaces`=52430847, `QuestDescription`='Your expertise is needed elsewhere, $n.$B$BJust southwest of the World Tree you will find the Shrine of Aviana, home to the Druids of the Talon. Aviana, the matron of all winged creatures, gave her life for this world ten thousand years ago.$B$BI sense her shrine is being threatened, as are the druids who guard it. Seek out Choluna, one of the wisest of the winged druids, deep within the shrine. ', `VerifiedBuild`=19034 WHERE `ID`=27874; -- Aviana's Legacy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=48900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27875 /*Prayerblossom*/, 27876 /*Secrets of the Mire*/, 27902 /*The Purespring*/, 27904 /*Breath of Mist*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='I need your help in a little project I''m working on, $n.  It falls into a realm I like to call "defensive archaeology".$b$bI like to bury non-magical items in conspicuous places to fool those Alliance idiots into thinking they''ve found something valuable.$b$bHmm... Dark Iron dwarves wander Hammertoe''s Digsite and Angor Fortress, to the north.  Bring their heads back to me.  Yes, that''s right, their heads.$b$bOnce the flesh is stripped, we can use those skulls to interfere with the dwarves'' work.', `VerifiedBuild`=19034 WHERE `ID`=27877; -- The Morons' League
UPDATE `quest_template` SET `RewardBonusMoney`=25800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (27883 /*The Warden's Pawn*/, 27884 /*The Sentinel's Pawn*/);
