UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Hello, $n.  It looks like you four have had time to become well-acquainted.$b$bI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.$b$bYou will find him and his minions at the Dustbowl, east of New Kargath.  Hunt him down and defeat him.  You will likely need the help of your new mercenary allies.', `VerifiedBuild`=19034 WHERE `ID`=27894; -- The Wrath of a Dragonflight
