UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=24300, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (27918 /*The Harborage*/, 28859 /*The Dunes of Silithus*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=24300, `AllowableRaces`=52430847, `QuestDescription`='We appreciate your assistance here in this swamp, $n.  I would like to inform you that I have received correspondence from Nethergarde Keep.$b$bEnohar Thunderbrew has requested help in investigating the shipwrecks of the Red Reaches, but we have had none willing to make the journey, and I could not leave the Harborage.$B$BNethergarde Keep sits in the Blasted Lands, south of the Swamp of Sorrows.  Do not journey too close to Stonard on your way.', `VerifiedBuild`=19034 WHERE `ID`=27919; -- Onward to the Blasted Lands
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=1100, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=8700, `AllowableRaces`=18875469, `QuestDescription`='We''ve hit an unexpected snag in our assault on the keep, $n. It seems the servants that tended to Baron Silverlaine and Commander Springvale in life do so now in death as well, and Godfrey has placed them directly between us and him.$B$BNot to worry, we won''t let them be anything more than a minor inconvenience. Eliminate Silverlaine and Springvale both and not only will their guards no longer have masters to direct them, it will place us that much closer to our final goal.', `VerifiedBuild`=19034 WHERE `ID`=27920; -- Armored to the Teeth
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=1200, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=9300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=27921; -- Fighting Tooth and Claw
