UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=94500, `QuestDescription`='I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar.$B$BKeep the fragment safe, $n. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible!$B$BKnow that you are always welcome here.', `VerifiedBuild`=19034 WHERE `ID`=27938; -- The Middle Fragment
