UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=36300, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='You''ve arrived just in time.$b$bHere''s the skinny: the Dark Iron dwarves in the gorge have been acting strangely, and the Thorium Brotherhood intends to find out why.  Overseer Oilfist doesn''t like surprises.$b$bWe suspect that they''re following orders from some new leader.  I have reason to believe that Gravius Grimesilt, just south of here, knows who it is.$b$bEven here in Searing Gorge, we''ve begun to hear tales of your exploits, $n.  You should have no problem with Grimesilt.', `VerifiedBuild`=19034 WHERE `ID`=27963; -- A New Master... But Who?
