UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=2097160, `AllowableRaces`=52430847, `QuestDescription`='That Overseer Oilfist couldn''t''a picked a worse time to ask me to join a fight.  My summit''s already under siege!$b$bIt''s nothin'' my guards can''t handle, but still, it won''t be easy for me to just pick up and send some dwarves into that infernal gorge.$b$bTell ya what: you take out their marksmen that''re holding our fortress under siege, and I''ll consider your offer.  Ye''ll find ''em slinkin'' around the flats to the east.', `VerifiedBuild`=19034 WHERE `ID`=28028; -- Siege!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=35651592, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28030; -- They Build a Better Bullet
UPDATE `quest_template` SET `RewardBonusMoney`=2760, `AllowableRaces`=18875469, `QuestDescription`='I have a new business partner, my best buddy, Brivelthwerp. Even as we speak, he''s building up the infrastructure for our new ice cream empire!$B$BHe took our coolant tug, inventory, and employees southwest to the Sunken Dig Site. Unfortunately, I don''t currently have a way to deliver something to him... something extremely important: our super-secret I-Scream Cryocannon!$B$BYou don''t mind taking it to him, do you, $n?', `VerifiedBuild`=19034 WHERE `ID`=28031; -- Special Delivery for Brivelthwerp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=39300, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28032 /*The Mysteries of the Fire-Gizzard*/, 28383 /*Wisps of the Woods*/, 28385 /*Oil and Irony*/, 28387 /*Burnout*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=3900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28033 /*Deceit*/, 28035 /*The Mountain-Lord's Support*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=19500, `AllowableRaces`=52430847, `QuestDescription`='Lunk not smart, but Lunk notice things.  Today, Lunk notice that Mountain-Dwarf likes to watch people dance.$b$bLunk like to dance!  $n like to dance!  Probably!$b$bMaybe we find some more dwarfs that like to dance.  Then we go talk to Mountain-Dwarf, and he will listen to $n.', `VerifiedBuild`=19034 WHERE `ID`=28034; -- Lunk's Adventure: Rendan's Weakness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38700, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28038 /*Blood in the Highlands*/, 28171 /*And the Sky Streaked Red*/, 28712 /*Enter the Dragon Queen*/, 29225 /*Actionable Intelligence*/, 29452 /*Your Time Has Come*/, 29453 /*Your Time Has Come*/);
UPDATE `quest_template` SET `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='You can hold your own on the ground, $n. I''ll give you that.$B$BBut we Dragonmaw dominate the skies as well as land. Until you can prove to me you can handle a drake as well as a Dragonmaw, your Horde is nothing to me.$B$BLet''s see if you can wrangle one back to Bloodgulch.$B$BFirst you''ll need bait. Go out and kill one of the gryphons that wander the woods west or northeast of here. Make sure it''s untamed! Drakes hate the stink of dwarf on their food.$B$BGet the gryphon carcass and you''ll know what to do.', `VerifiedBuild`=19034 WHERE `ID`=28041; -- Bait and Throttle
UPDATE `quest_template` SET `RewardBonusMoney`=2760, `AllowableRaces`=33555378, `QuestDescription`='I recently came into possession of something that needs to be delivered to a gnome that goes by the name, Brivelthwerp. It''s more like Briveltwerp if you ask me.$B$BI want you to take it to him in the southwest, down at the Sunken Dig Site. He''s up to something and there''s moolah involved... I can smell it!$B$BKeep an eye on what he''s doing, $n, and see if you can''t get a cut of his profits. A big cut!', `VerifiedBuild`=19034 WHERE `ID`=28042; -- Special Delivery for Brivelthwerp
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=58800, `AllowableRaces`=52430847, `QuestDescription`='I''m putting you on a flying machine, $n.$b$bYou''ll be responsible for softening our landing into the slag pit.  Speak with your flight master here in Thorium Point, then fly down to the gorge.$b$bOnce you near your landing point, there will undoubtedly be hordes of Dark Iron dwarves waiting for you.  Use our flying machine''s guns to take out as many of them as you can, then land at the cavern''s entrance.  Rendan should be waiting for you by the time you arrive.', `VerifiedBuild`=19034 WHERE `ID`=28052; -- Operation: Stir the Cauldron
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `AllowableRaces`=52430847, `QuestDescription`='It''s a little known fact that dwarves, particularly of the Dark Iron variety, need rest! Lots of rest!$B$BNow I ask you; How can they sleep without pillows?  Exactly, $n, they can''t.  This is why you must steal their pillows.$b$bOnce you''ve finished your cushion-thievery, talk with Taskmaster Scrange.  He''s a bit deeper in the cave, working on a covert project with Hansel.', `VerifiedBuild`=19034 WHERE `ID`=28057; -- Kill 'em With Sleep Deprivation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28060; -- Twisted Twilight Ties
UPDATE `quest_template` SET `RewardBonusMoney`=51000, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='Archduke Calcinder squirms in the back of this very cavern.  We are close to killing him... but that is not what we are going to do.$b$bSlaying Calcinder here means nothing.  His acolytes can easily revive him.  Instead, we are going to banish him.$b$bI asked you to gather a precious stone from the Twilight''s Hammer earlier.  You will now use it against Calcinder.  Engage him, weaken him, then use this device on him.  He will be banished from this realm.$b$bGood luck, brave $n.', `VerifiedBuild`=19034 WHERE `ID`=28062; -- From Whence He Came
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=61200, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28064; -- Welcome to the Brotherhood
UPDATE `quest_template` SET `RewardBonusMoney`=3150, `AllowableRaces`=52430847, `QuestDescription`='Thank you for your help, $n. You should speak with Pao''ka Swiftmountain at Highperch to the southwest.$B$BPerhaps he will know the whereabouts of the Elder Crone?', `VerifiedBuild`=19034 WHERE `ID`=28085; -- Trouble at Highperch
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=1048584, `AllowableRaces`=52430847, `QuestDescription`='The trappers are rounding up all of the young wind riders. $n, will you go out there and free the pridelings?', `VerifiedBuild`=19034 WHERE `ID`=28086; -- Free the Pridelings
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=52430847, `QuestDescription`='There''s only one answer for those filthy Twilight''s Hammer trappers! Death!$B$BBring me their nets, $n.', `VerifiedBuild`=19034 WHERE `ID`=28087; -- Death to all Trappers!
