UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='Twilight Skymaster Richtofen is at the Twilight Aerie up above and to the southeast. No matter what we do down here, if he''s not dealt with, all hope is lost for Highperch.$B$BWhile Heartrazor is too injured to help you with the fight, he can fly you up there. The rest is up to you, $n.$B$BGood luck. ', `VerifiedBuild`=19034 WHERE `ID`=28098; -- The Twilight Skymaster
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='Based on this information you''ve delivered, I believe that one of this "Archduke''s" minions may already have turned its eyes toward Thorium Point.$b$bHis name is Rasha''krak, and he patrols the lava pools just to our south.  He looks like the latent fire elementals that rage nearby, except for one small difference: the bracers of binding that encircle his wrists.$b$bFind him and bring these bracers to me, $n.  I need proof that we are in danger before we involve ourselves in elemental wars.', `VerifiedBuild`=19034 WHERE `ID`=28099; -- Rasha'krak
