UPDATE `quest_template` SET `Flags`=262152, `AllowableRaces`=52430847, `QuestDescription`='Productivity from our spider farm at the Azurelode Mine is at a standstill. Captain Keyton has requested that we send help immediately. Keyton claims that the mine spiders refuse command and are running rampant. Furthermore, a group of coastal murlocs are raiding our supplies. I want you to go down there and check things out. Help out Keyton and the spider-handler, $n.$B$BYou''ll find Azurelode Mine to the southeast, near the coast.', `VerifiedBuild`=19034 WHERE `ID`=28111; -- Trouble at Azurelode
UPDATE `quest_template` SET `RewardBonusMoney`=56700, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28112 /*Escape From the Lost City*/, 28622 /*Three if by Air*/);
