UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=57300, `AllowableRaces`=52430847, `QuestDescription`='Narkrall revealed to me the secret of his influence over the drakes in this area. I thought the Demon Chain was a myth, but he''s had it all along.$B$BAnd now the fool is about to lose it!$B$BHis life is meaningless to me but the Dragonmaw can''t afford to lose that artifact. Follow him north, up to Thundermar. The city will be in chaos, so you may be able to land undetected. Return to me with the Demon Chain, even if you have to remove it from Narkrall''s corpse.$B$BFind that artifact, $n!', `VerifiedBuild`=19034 WHERE `ID`=28123; -- The Demon Chain
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='$n, while you and the pridelings were taking care of the skymaster, Lakota Windsong came by. She told me to tell you to meet her east at the Twilight Bulwark.$B$BThat must be where they''re holding Magatha Grimtotem.', `VerifiedBuild`=19034 WHERE `ID`=28124; -- On to the Bulwark
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=34800, `Flags`=134545416, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28129; -- The Demon Prince
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=18900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28132; -- Efficient Excavations
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=95400, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28133; -- Fury Unbound
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56700, `AllowableRaces`=52430847, `QuestDescription`='Listen, $n.  What struck Orsis was no natural sandstorm.  It was the minions of Al''Akir.$B$BThe elemental lord of air is firmly allied with Deathwing and it was only a matter of time before he set his subjects upon my people.$B$BOrsis has been attacked as a warning to us.  We must move quickly to offer our brethren what aid we can.$B$BMeet with Nadun at the Arsad Trade Post outside of Mar''at.  I will begin preparations to take care of the displaced and wounded.', `VerifiedBuild`=19034 WHERE `ID`=28135; -- Al'Akir's Vengeance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='The three leaders of the Bulwark are powerful and not to be underestimated, $n. Fortunately for us, you now have a disguise to make you look like one of the Twilight cultists.$B$BYou should put the disguise on and speak with Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion each alone. Get them to turn their backs on you, and when they do, strike quickly!', `VerifiedBuild`=19034 WHERE `ID`=28136; -- Behind You!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AllowableRaces`=52430847, `QuestDescription`='$n, the bonds holding Magatha are specially encoded. She can only be released if we get those codes.$B$BThere''s a device near Codemaster Deethuk in the Bulwark to the southeast. It contains the codes.$B$BPlease obtain them.', `VerifiedBuild`=19034 WHERE `ID`=28139; -- Codemaster's Code
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=52430847, `QuestDescription`='You have the code. Now all you have to do is head to the eastern section of the Bulwark and free the Elder Crone.$B$BGood luck, $n. Thank you for all you''ve done.', `VerifiedBuild`=19034 WHERE `ID`=28140; -- The Elder Crone
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=536870920, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28144; -- Thieving Little Monsters!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `AllowableRaces`=52430847, `LogDescription`='Fill the Antidote Vial with the poison of 8 Venomblood Scorpid corpses.', `VerifiedBuild`=19034 WHERE `ID`=28145; -- Venomblood Antidote
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=3450, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28150; -- An Arcane Ally
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `AllowableRaces`=52430847, `QuestDescription`='Your disguise is ready, $n. Whenever you go north into Glopgut''s Hollow now, your Twilight''s Hammer regalia will fool the ogres.$B$BThe rest of the plan is simple: you kill a bunch of Glopgut ogres, and they blame the cult. Are you ready to create some havoc in the ogre camp? I thought so.', `VerifiedBuild`=19034 WHERE `ID`=28151; -- Dressed to Kill
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=34800, `AllowableRaces`=52430847, `QuestDescription`='Shadow Lord Fel''dan awaits further in the depths, $n.$B$BHis wrath will be unmatched now that you have slain his beloved pets. Even without Moora and Salia at his side, he is a terrible force to be reckoned with.$B$BBeware his dark powers; he is nearly more demon than orc by now.', `VerifiedBuild`=19034 WHERE `ID`=28153; -- Shadow Lord Fel'dan
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=51900, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28155; -- Lord Banehollow
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28158; -- Unbound
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=49800, `AllowableRaces`=18875469, `QuestDescription`='For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.$B$BAnd $n, if we ever cross paths again, you will die.', `VerifiedBuild`=19034 WHERE `ID`=28160; -- Spread the Word
