UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=256, `QuestDescription`='I just received word that you are needed in Orgrimmar, $n. Brother Silverhallow has asked for you to return to the city as quickly as you are able. His message didn''t include any other information, and the matter seemed urgent.$B$BLook for Brother Silverhallow in the Goblin Slums of Orgrimmar.', `VerifiedBuild`=19034 WHERE `ID`=28164; -- Seek Brother Silverhallow
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `QuestDescription`='I''m going to start preparing my men to leave this place. We can''t hold out here any longer. I want you to move to a forward position in the middle of the large room ahead.$B$BYou should find Carvo Blastbolt there. He''ll give you further instructions. Good luck, $n, and I''ll see you on the surface.', `VerifiedBuild`=19034 WHERE `ID`=28167; -- Report to Carvo Blastbolt
