UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `Flags`=2097160, `AllowableRaces`=18875469, `QuestDescription`='Hope you''re not afraid of getting dirty.  Judging by the looks of you, that won''t be a problem.$b$bTo the north, at the lava''s edge, you''ll find piles of dark mud.  I need it.$b$bIt''d be best if you didn''t ask questions, and focused your efforts on following orders, $n.', `VerifiedBuild`=19034 WHERE `ID`=28179; -- Mud Hunter
