UPDATE `quest_template` SET `Flags`=8, `AllowableRaces`=52430847, `QuestDescription`='We must destroy all of the evidence, $n! Did I say evidence? I meant crazed undead! Anyway, discretion is key. We must not let the rampaging undead make it out of the Sludge Fields and no one outside of this institution must know about what happened here!$B$BDirectly southeast of here in what used to be the old mushroom farm you''ll find a reanimated fiend known as Citizen Wilkes and his cohort, Clerk Horrace Whitesteed. They have been causing huge problems for my guards. Find them and kill them!', `VerifiedBuild`=19034 WHERE `ID`=28197; -- Discretion is Key
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AllowableRaces`=5, `VerifiedBuild`=19034 WHERE `ID`=28202; -- A Perfect Costume
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AllowableRaces`=18875392, `VerifiedBuild`=19034 WHERE `ID`=28203; -- A Perfect Costume
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `VerifiedBuild`=19034 WHERE `ID` IN (28204 /*A Perfect Costume*/, 28205 /*A Perfect Costume*/, 28460 /*Threat of the Winterfall*/, 28474 /*Twilight Scheming*/);
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='It was only yesterday that I sent her out to investigate the farm directly east of here, but it feels like an eternity has passed!$B$BI knew it was true love the minute I saw her. Her lovely blonde locks and the way they framed her perfect blood elf face... She melted my shriveled heart. I didn''t want to send her out, but she was so demanding! I had to give her what she asked for! Who could refuse such a vision?$B$BAlas, poor Jenny Awesome has not returned! I fear the worst, $n. Find her!', `VerifiedBuild`=19034 WHERE `ID`=28206; -- Little Girl Lost
UPDATE `quest_template` SET `RewardChoiceItemID2`=65673, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28209; -- Freedom for Lydon
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='First things first: We''re going to need ammunition. Ammunition powerful enough to pierce the armored hide of a black drake. $B$BWest of Thundermar is a Wildhammer town that''s been overrun with unbound fire elementals. Any weapons left behind in that conflagration will have been tempered in elemental flame. Tougher than anything I could whip up at this forge!$B$BFind me spears in the Humboldt Conflagration, $n. The pointier the better.', `VerifiedBuild`=19034 WHERE `ID`=28211; -- Tempered in Elemental Flame
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=2686976, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28219 /*Buzzers for Baby*/, 28221 /*These Roots Were Made For Stompin'*/);
