UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=539820032, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28222; -- Singin' in the Sun
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28227; -- Golem Training
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `ItemDropQuantity1`=1, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28229; -- Nature and Nurture
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=4194312, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28235; -- Burnside Must Fall
UPDATE `quest_template` SET `Flags`=7340032, `AllowableRaces`=52430847, `QuestDescription`='With the undead outbreak contained, the time has come for Stillwater and his followers to answer for their crimes. Though we averted a tragedy the likes of which has not been seen since the Scourge invaded, we must ensure that such a thing can never happen again. They will all face true death!$B$BCome, $n! I will have Stillwater''s head!', `VerifiedBuild`=19034 WHERE `ID`=28237; -- A Blight Upon the Land
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=18875469, `QuestDescription`='The time has come, $c. With Stormwind secure, we will take this fight to the enemy. To the Highlands!$B$BThe bulk of our navy has already shipped out, thanks to your work earlier. But Fargo Flintlocke has prepared a seaplane that can make the journey in double-time.$B$BSpeak with Flintlocke down at the harbor and tell him that you are to accompany him to the Highlands. He will be by the water''s edge. Safe journeys, $n.', `VerifiedBuild`=19034 WHERE `ID`=28238; -- Twilight Shores
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=20400, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28239; -- Into the Black Tooth Hovel
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `RewardChoiceItemID1`=63797, `RewardChoiceItemID2`=63796, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=52430847, `QuestDescription`='I''ll be honest, $n. That thing gives me the willy-willies. But seein'' as you went to all the trouble of bringin'' it here, I s''pose we ought to put it to use.$B$BYou first.$B$BPeer into the eye and ask it to show you inside Cho''gall''s Bastion of Twilight. We''ll find out what that fat two-headed bugger is up to, and use it against him. ', `VerifiedBuild`=19034 WHERE `ID`=28244; -- Eye Spy
UPDATE `quest_template` SET `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='<Static> $n... $n, can you hear me?  It''s Troteman.$b$bListen, we''ve just received the final bit of intel for your next mission.  There are three marks that we''d like you to take down.  The first is Voodooist Timan, whom you''ll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.$b$bYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.', `VerifiedBuild`=19034 WHERE `ID`=28246; -- Strategic Cuts
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=96600, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28247 /*Last of Her Kind*/, 28758 /*Battle of Life and Death*/, 29128 /*The Protectors of Hyjal*/, 29194 /*Through a Glass, Darkly*/, 29201 /*Through the Gates of Hell*/, 29203 /*Into the Depths*/, 29243 /*Strike at the Heart*/, 29305 /*Strike at the Heart*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=19200, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28248; -- Victors' Point
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=19200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28249; -- Crushblow
UPDATE `quest_template` SET `RewardBonusMoney`=51000, `Flags`=65544, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28252; -- The Kodocaller's Horn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=2621440, `AllowableRaces`=18875469, `QuestDescription`='$n, it''s Troteman.  I want you to hold onto that horn.  I''m sure we can improvise and find a way to work it into the plan.$b$bI''m more than a little concerned about what Kaoshin said about attacking Redridge.  We knew another attack was imminent, but our timetables were off by several days.$b$bReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You''re not done with your undercover work yet.', `VerifiedBuild`=19034 WHERE `ID`=28253; -- Taking the Horn For Ourselves
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=4050, `AllowableRaces`=18875469, `QuestDescription`='You and I can''t take on an army, $n.  They''ll overwhelm us.  That''s why we''ve got to stick to Troteman''s plan.$b$bThe next part of the plan is going to require a bit of subtlety... something that I''m not terribly good at.  That''s where you come in.$b$bSpeak with Thelaron Direneedle, the tailor here in town.  I''ve already given him the hides and mud that we''ve collected.  He''s going to need to size you.$b$bThat''s right, $n: you''re going undercover.', `VerifiedBuild`=19034 WHERE `ID`=28254; -- A Needle in a Hellhole
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=18875469, `QuestDescription`='Ander Germaine sent a message for you. He wants you to join him at his headquarters in the Command Center in Stormwind''s Old Town as quickly as you can. It sounded important, $n.', `VerifiedBuild`=19034 WHERE `ID`=28258; -- Meet with Ander Germaine
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `ItemDropQuantity1`=1, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28264; -- Navarax's Gambit
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `Flags`=1310856, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28269; -- Meet Me In Vir'sar
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=37800, `AllowableRaces`=52430847, `QuestDescription`='Listen, $n.  Before you give up on me, there''s something I''d like to show you.$B$BYou see, I''m not much of a fighter.  I''m not very coordinated.$B$BI''m more of a tactical mind.$B$BMeet me at the southern end of the ridge and I''ll show you.', `VerifiedBuild`=19034 WHERE `ID`=28276; -- Salhet's Secret
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='$n?  Troteman here.$b$bIt sounds like you have earned Thorg''izog''s trust, and he''s assigned you to discipline duty.  This is fortunate.$b$bWe need you to take out his sergeants.  You''ll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You''ll have to act fast, because if they realize you''re not one of them, they can unmask you.  Strike quickly and ferociously, $n.$b$bTroteman out.', `VerifiedBuild`=19034 WHERE `ID`=28279; -- Abuse of Power
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='Egah! They''re here, $n. They''re here!$B$BI had hoped to equip a whole army with my shoulder-mounted drake-droppers, but all I have is a single, extremely expensive and wholly untested prototype. Here, take it!$B$BShoot the Dragonmaw black drakes that are circling Thundermar, and drop them from the sky!', `VerifiedBuild`=19034 WHERE `ID`=28280; -- Tear Them From the Sky!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=95400, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='There''s one Dragonmaw among this lot, the one they call "Narkrall: The Drake-Tamer." I don''t know where he gets his power over those beasts, but the black terror he rides is as nasty a brute as ever took the skies over the Highlands.$B$B$n, Narkrall is the fiend who took my father''s life and left Thundermar in my hands.$B$BI can''t take him on alone, but I''ve seen what you''re capable of, $c. Maybe together we can end this.$B$BLet me know when you''re ready, and we''ll fight Narkrall together!', `VerifiedBuild`=19034 WHERE `ID`=28282; -- Narkrall, The Drake-Tamer
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='I just received a scroll from the Cathedral of Light, $n. High Priestess Laurena sends word that she wishes to speak with you. You should meet with her as soon as you can.', `VerifiedBuild`=19034 WHERE `ID`=28285; -- Meet with High Priestess Laurena
UPDATE `quest_template` SET `RewardBonusMoney`=4050, `AllowableRaces`=18875469, `QuestDescription`='Farseer Umbrua''s messenger just reached me, $n. She has an important matter she wishes to discuss with you and sends word that you should meet her at the Golden Keg in the Dwarven District of Stormwind as soon as you can make it there.', `VerifiedBuild`=19034 WHERE `ID`=28287; -- Meet with Farseer Umbrua
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardBonusMoney`=4050, `QuestDescription`='I have received word that our brothers in Moonglade have requested your help, $n. You should travel there and speak with Loganaar in Nighthaven. He will tell you all you need to know.', `VerifiedBuild`=19034 WHERE `ID`=28289; -- Moonglade Calls
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `QuestDescription`='Grezz Ragefist sent an urgent message for you, $n. He wants you to join him immediately in Orgrimmar''s Valley of Heroes. He must have a mission of importance for you.', `VerifiedBuild`=19034 WHERE `ID`=28290; -- Meet with Grezz Ragefist
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=56700, `AllowableRaces`=52430847, `QuestDescription`='What do you think, $n?  Maybe the High Commander will give me a few men to command.$B$BMaybe we can marshal a regiment together.  What do you think?', `VerifiedBuild`=19034 WHERE `ID`=28291; -- Return to Camp
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=18875469, `QuestDescription`='That pyramid at the Maker''s Terrace in Uldum is nothing of the sort. It''s a giant machine that can be reconfigured for any number of uses.$B$BDeathwing was going to have the Twilight''s Hammer turn it into a massive weapon!$B$B$n, you have to take the portal to get this information to Harrison Jones in Stormwind. He''ll know what to do.', `VerifiedBuild`=19034 WHERE `ID`=28292; -- That's No Pyramid!
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `Flags`=262280, `AllowableRaces`=33555378, `QuestDescription`='That pyramid at the Maker''s Terrace in Uldum is nothing of the sort. It''s a giant machine that can be reconfigured for any number of uses.$B$BDeathwing was going to have the Twilight''s Hammer turn it into a massive weapon!$B$B$n, you have to take the portal to get this information to Belloc Brightblade at Grommash Hold in Orgrimmar. He''ll know what to do.', `VerifiedBuild`=19034 WHERE `ID`=28293; -- That's No Pyramid!
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='I received a scroll for you from Ormak Grimshot in Orgrimmar. He wants you to make your way to the Valley of Honor and speak with him as soon as you can. It sounded urgent, $n.', `VerifiedBuild`=19034 WHERE `ID`=28297; -- Meet with Ormak Grimshot
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `QuestDescription`='Gordul, leader of the rogues of the Shattered Hand in Orgrimmar, wishes to meet with you. Make your way to Orgrimmar quickly, $n and seek him in the Cleft of Shadow. He must have an important mission for you.', `VerifiedBuild`=19034 WHERE `ID`=28298; -- Meet with Gordul
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `LogTitle`='Meet with Kranosh', `LogDescription`='Speak with Kranosh in Orgrimmar''s Cleft of Shadow.', `QuestDescription`='I have just received word from Kranosh, Orgrimmar''s foremost warlock trainer. He wishes you to travel to Orgrimmar and speak with him in the cleft of shadow. It sounds like he has an important mission for you.', `QuestCompletionLog`='Speak with Kranosh in Orgrimmar''s Cleft of Shadow.', `VerifiedBuild`=19034 WHERE `ID`=28299; -- Meet with Zevrost
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='I just received a scroll for you from Orgrimmar, $n. It''s from Ureda, one of the mage trainers there. She wants you to meet with her in Orgrimmar''s Cleft of Shadow next time you''re in the city.', `VerifiedBuild`=19034 WHERE `ID`=28300; -- Meet with Ureda
UPDATE `quest_template` SET `QuestInfoID`=21, `AllowableRaces`=33555378, `LogTitle`='Meet with Terga Earthbreaker', `LogDescription`='Speak with Terga Earthbreaker in Orgrimmar''s Valley of Wisdom.', `QuestDescription`='An urgent message just arrived for you, $n.  It''s from Terga Earthbreaker, one of the shaman trainers in Orgrimmar.  She requests your presence as soon as possible.', `QuestCompletionLog`='Speak with Terga Earthbreaker in Orgrimmar''s Valley of Wisdom.', `VerifiedBuild`=19034 WHERE `ID`=28301; -- Meet with Kardris Dreamseeker
UPDATE `quest_template` SET `RewardBonusMoney`=4050, `AllowableRaces`=32, `QuestDescription`='You should make your way to Orgrimmar as soon as you can, $n. Sunwalker Atohmo has sent word that he wishes to speak with you about a matter of importance to the Horde. Look for him the Valley of Wisdom.', `VerifiedBuild`=19034 WHERE `ID`=28302; -- Meet with Sunwalker Atohmo
UPDATE `quest_template` SET `QuestDescription`='Master Pyreanor sent an urgent message for you, $n. He asks you to join him at Grommash Hold in Orgrimmar''s Valley of Strength the next time you''re in the city. It sounds as though he must have an important assignment for you.', `VerifiedBuild`=19034 WHERE `ID`=28303; -- Meet with Master Pyreanor
UPDATE `quest_template` SET `QuestDescription`='Dark Cleric Cecille, a member of the Banshee Queen''s delegation to Orgrimmar, has requested to meet with you next time you''re in the city. You can find her inside Grommash Hold in Orgrimmar''s Valley of Strength. It must be an important matter for her to send for you so directly, $n.', `VerifiedBuild`=19034 WHERE `ID`=28304; -- Meet with Dark Cleric Cecille
UPDATE `quest_template` SET `QuestDescription`='Tyelis, a member of the Silvermoon delegation to Orgrimmar, has requested to meet with you next time you''re in the city. You can find him inside Grommash Hold in Orgrimmar''s Valley of Strength. It must be an important matter for him to send for you so directly, $n.', `VerifiedBuild`=19034 WHERE `ID`=28307; -- Meet with Tyelis
UPDATE `quest_template` SET `AllowableRaces`=32, `QuestDescription`='Seer Liwatha sends her greetings from the Valley of Wisdom in Orgrimmar, $n. She asked me to convey an invitation to visit her next time you''re in the city. It sounded like she has something of importance to discuss with you.', `VerifiedBuild`=19034 WHERE `ID`=28308; -- Meet with Seer Liwatha
UPDATE `quest_template` SET `AllowableRaces`=128, `QuestDescription`='Shadow-Walker Zuru, a revered priest trainer, has asked to meet with you in Orgrimmar. You can find him in the Valley of Spirits with the other Darkspear trainers. It must be an important matter for him to send for you so directly, $n.', `VerifiedBuild`=19034 WHERE `ID`=28309; -- Meet with Shadow-Walker Zuru
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=42300, `AllowableRaces`=18875469, `QuestDescription`='I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we''re going to do this, we''re going to do it right, and that means being prepared.$b$bI need ash, $n.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the northwest.  The stuff is deep, deep black, which is what we need for our next disguise.$b$bDon''t worry, you''ve already got a disguise.  This one is for someone... well, someTHING... else.', `VerifiedBuild`=19034 WHERE `ID`=28311; -- Blackened Ashes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=42300, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (28312 /*Latent Demons of the Land*/, 28313 /*A Heap of Delicious Worg*/, 28316 /*A Deal With a Dragon*/);
UPDATE `quest_template` SET `RewardBonusMoney`=52800, `AllowableRaces`=18875469, `QuestDescription`='My legs are getting a little restless again.  You interested in taking a little tour, $n?$b$bWe''re going to take a trip around Dreadmaul Rock.  I''d like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we''re on the way.', `VerifiedBuild`=19034 WHERE `ID`=28314; -- Blood Tour
UPDATE `quest_template` SET `RewardBonusMoney`=52800, `AreaGroupID`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28315; -- Draconic Vanguard
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=21000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (28317 /*A Delivery for Thorg'izog*/, 28319 /*A Delivery for Xi'lun*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=21000, `Flags`=3145736, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28318; -- A Delivery for Neeralak
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=66000, `AllowableRaces`=18875469, `QuestDescription`='This is it, $n.  This is where it hits the fan.  Where all the pieces come together.$b$bStrap in, and come with me.  We''re going to go talk to Acride and call in that favor that he owes us.  Then we''ll stop this invasion of Redridge before it even starts.', `VerifiedBuild`=19034 WHERE `ID`=28320; -- Assault on Dreadmaul Rock
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `Flags`=3145736, `AreaGroupID`=0, `AllowableRaces`=18875469, `QuestDescription`='You and Keeshan are going back to that mountain.  There''s three orcs who survived the attack, and we won''t rest until they''re dead.$b$bThat''s right, I''m talking about the Big Three.$b$bGeneral Thorg''izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain''s peak.  Xi''lun is in the back of the Skull Warren, plotting with his fellow warlocks.$b$bLeave your mark, $n.  Hunt down those sniveling Blackrocks, and teach them the might of Redridge!', `VerifiedBuild`=19034 WHERE `ID`=28321; -- Glory Amidst Chaos
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='We''ve toppled a giant today, $n.  While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near Redridge anytime soon.  You and Keeshan saw to that.$b$bI''d say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.$b$bThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.', `VerifiedBuild`=19034 WHERE `ID`=28322; -- The Spoils of War
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=18875469, `QuestDescription`='$n.  It sounds like you and Keeshan have finished with your tasks.  I''ve also finished mine.$b$bReturn to Morgan''s Vigil.  I''ve prepared a few packages to deliver to the Big Three: Thorg''izog, Neeralak, and Xi''lun.  You''ve already met General Thorg''izog.  This will be your chance to meet the other two.$b$bThat is, before we kill them.', `VerifiedBuild`=19034 WHERE `ID`=28326; -- Placing the Pawns
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=18875469, `QuestDescription`='$n, come in.  Can you read me?$b$bThe battle is about to start.  I hope you''ve delivered all of those packages.$b$bI need you here in Morgan''s Vigil, NOW.', `VerifiedBuild`=19034 WHERE `ID`=28327; -- Locked and Loaded
UPDATE `quest_template` SET `Flags`=137953280, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28329; -- Angry Scrubbing Bubbles
UPDATE `quest_template` SET `Flags`=8, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28331; -- Helcular's Rod Giveth...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=48900, `QuestDescription`='There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.$B$BThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.$B$BPlease, $n - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.', `VerifiedBuild`=19034 WHERE `ID`=28338; -- Deadwood of the North
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=52430847, `QuestDescription`='All my workers got driven straight out of the cavern here by those big swamp-lookin'' things! Darla''s sent me here to pick up the pieces, but have you seen it in there? I ain''t goin'' in!$B$BThere''s a ton of explosives left behind that we can''t just leave layin'' around.$B$B I''ll make you a deal: You run in there and get those explosives gathered up, and I will stay here and not get killed by swamp-things, and if you don''t either, I''ll pay ya! How''s that sound?', `VerifiedBuild`=19034 WHERE `ID`=28340; -- A Bomb Deal
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `QuestDescription`='The infernals that lurk in Shatter Scar Vale are formidable, but not invincible. Much progress has been made in thinning their numbers.$B$BDestroying them is only part of the solution, however. I''ve found that the stone that infernals are made of still contains large amounts of fel magic even after the infernal''s death.$B$BThe rubble of slain infernals now litters Shatter Scar Vale, leeching its corruption back into the ground. If you could collect it and bring it to me, I would be grateful.', `VerifiedBuild`=19034 WHERE `ID`=28342; -- Fel To Pieces
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AllowableRaces`=2147483647, `QuestDescription`='$n, we have learned that a missing Cenarion artifact has surfaced in the hands of a Twilight''s Hammer pyromancer. Pyromancer Loregrain has taken this artifact, the Breath of Cenarius, into Blackrock Depths and uses its power to open elemental gates.$B$BWe must act to keep Loregrain from summoning elementals to bolster the ranks of his Dark Iron allies. Recover the artifact from him and use its power to close the gates that Loregrain has been using.', `VerifiedBuild`=19034 WHERE `ID`=28343; -- The Breath of Cenarius
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `Flags`=3145738, `AllowableRaces`=52430847, `QuestDescription`='*GURGLE*$B$BHELP!*GASP*$B$BORKUS IS DROWNING! HELP ME, QUEST GIVER $n!$B$B*GLUB*$B$BDwarf threw Orkus into the water! Must not die!$B$B*GURGLE*$B$BThe shame would be too great.', `VerifiedBuild`=19034 WHERE `ID`=28345; -- *Gurgle* HELP! *Gurgle*
UPDATE `quest_template` SET `RewardBonusMoney`=19200, `AllowableRaces`=52430847, `QuestDescription`='We need to make this work, $n. The answer is in the blood! Family bonds have kept these Wildhammer clans apart from one another. It''ll take family bonds to glue ''em back together. It''s a long shot, but we''re going to have to play matchmaker!$B$BI''ll track down Colin Thundermar and talk with him. You''re a smooth one - you should talk to Keegan Firebeard inside. He''s sharp enough to understand a political marriage. Go find out if he fancies anyone!', `VerifiedBuild`=19034 WHERE `ID`=28346; -- The Bachelor
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=1048578, `AllowableRaces`=52430847, `QuestDescription`='I tracked down the decrepit necromancer, Helcular, in hopes of getting a lead on Alliance movement within Hillsbrad.$B$BHelcular tasked me with finding and killing worgen. Ordinarily this would not be a problem for Orkus, but I had just eaten several helpings of Dirge''s Kickin'' Chimaerok chops, causing my bowels to cry out in anguish. That''s when the trouble began and how I ended up in the water.$B$BHear Orkus out, $n.', `VerifiedBuild`=19034 WHERE `ID`=28348; -- Stormpike Rendezvous
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7500, `Flags`=262280, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28353; -- Jonesy Sent For You
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='Kasha will fly again, $n. She must if we are to claim vengeance! Sadly, Orkus must stay here with Kasha. You must help us. I beg of you!$B$BListen carefully, quest giver. When I first arrived here I flew around for days to learn the lay of the land. There is a farm east of here that has long since been abandoned and is now overrun by gnolls. On this farm grows a special type of mushroom known as the mudsnout. Go to the stead and gather mudsnout for Kasha. Return here when your pack is full.', `VerifiedBuild`=19034 WHERE `ID` IN (28354 /*Kasha Will Fly Again*/, 28371 /*[DND] ORKUS QUEST FLAG [DO NOT LOCALIZE]*/);
UPDATE `quest_template` SET `RewardBonusMoney`=13200, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28355; -- Terrible Little Creatures
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=4194312, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28357 /*Take it to the Tree*/, 28370 /*Wisp-napping*/);
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='The time of vengeance has come, $n. Kasha can once more fly, thanks to you. She will take us to Purgation Isle so that we may confront the Stormpike dwarf general, Vanndar Stormpike, and his captain, Balinda Stonehearth. BOTH will pay for what they have done.$B$BAre you ready? Orkus cannot do this alone.', `VerifiedBuild`=19034 WHERE `ID`=28375; -- The Road to Purgation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `RewardBonusMoney`=113400, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28376; -- Myzerian's Head
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38700, `AllowableRaces`=52430847, `QuestDescription`='Well speak of the devil in a blue dress. Fanny''s gone and gotten herself kidnapped by ogres!$B$BI don''t trust the Thundermars to be able to mount a rescue on their own. I''ll round up my gryphon riders and provide some air support.$B$BI''m sure they can use an extra $c down there, $n. Grab your gear and look for Colin Thundermar in the Glopgut ogre camp. It''s southwest of here, below the cliffs. Hurry now!', `VerifiedBuild`=19034 WHERE `ID`=28377; -- Rescue at Glopgut's Hollow
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `AllowableRaces`=52430847, `QuestDescription`='We''ve started tearing this camp apart, $n, but there''s no sign of Fanny. Maybe you can find her.$B$BWe haven''t checked the cave just behind me, to the northwest. See if you can find Fanny in the cave!', `VerifiedBuild`=19034 WHERE `ID`=28378; -- Find Fanny
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=48900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28386; -- Borrowed Bombs
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=39300, `Flags`=8, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28388; -- Bloody Wages
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=94500, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28390; -- Glop, Son of Glop
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=94500, `Flags`=134221960, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28391; -- The Restless Brood
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=9900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28392; -- The Timbermaw Tribe
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `QuestDescription`='SI:7''s latest report about Twilight''s Hammer and Dark Iron activity worries me, $n. There''s evidence that they are preparing a joint attack from within Blackrock Mountain. We''ll be hard-pressed to turn back such a combined force, but if we act before they''re ready to strike, we might be able to blunt the attack.$B$BYou must go into Blackrock Depths and capture the Twilight''s Hammer attack plans from General Angerforge in the West Garrison. Do not hesitate to take out the elementals supporting his forces.', `VerifiedBuild`=19034 WHERE `ID`=28393; -- A Dangerous Alliance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `QuestDescription`='The latest SI:7 intelligence on Blackrock Depths is troubling, $n. It appears Twilight''s Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could prove to be a devastating weapon if used against us.$B$BYou must prevent that from happening, $n. Find the Manufactory in Blackrock Depths, capture the blueprints he''s using to make those golems, and recover the elemental modules he''s using to power them.', `VerifiedBuild`=19034 WHERE `ID`=28394; -- The Golem Lord's Creations
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=52430847, `QuestDescription`='They made a mistake by not killing me when they had the chance. Perhaps they thought Orkus would drown. HAH! Now they will pay the price for their carelessness.$B$BYou and I will tear this island apart, $n. They will never expect this! Once all of their soldiers are dead we will confront the leaders. Be on the lookout for attack plans. If we can get our hands on their plans we will be able to put a stop to their whole invasion!$B$BLet''s go, $n!', `VerifiedBuild`=19034 WHERE `ID`=28397; -- They Will Never Expect This...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (28398 /*The Pyromancer's Grimoire*/, 28401 /*Slaves of the Firelord*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `ItemDropQuantity2`=1, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28399; -- Stones of Binding
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `AllowableRaces`=52430847, `QuestDescription`='Now to find their battle plans and take out their leaders! Should we succeed there is an orc high warlord who served in the war in Silverpine that is now stationed at Tarren Mill - located in the heart of Hillsbrad. He will grant both of us commendations for this! We will be heroes of the Horde, $n!$B$BOnward! Together we will defeat the Alliance filth!', `VerifiedBuild`=19034 WHERE `ID`=28400; -- Heroes of the Horde!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=18900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28403; -- Bad Datas
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28405; -- Weapons of Darkness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity1`=1, `AllowableRaces`=18875469, `QuestDescription`='Things are getting interesting in Blackrock Mountain, $n. Our sources report that the Dark Iron dwarves have formed closer ties with Twilight''s Hammer and both are preparing for a major offensive.$B$BI''ve made the contents of the report known to key leaders in Stormwind and I want you to help deal with this emerging Dark Iron threat.$B$BThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths. Take this poison and apply it to their grain reserves.', `VerifiedBuild`=19034 WHERE `ID`=28406; -- The Dark Iron Army
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=52430847, `QuestDescription`='Firebeard? Marry my sister!? I swear the world''s gone mad, $n!$B$BStill, maybe Kurdran is right. A nice normal wedding would ease everyone''s mind... and maybe cool off Firebeard a little. It was great to actually work together here against the ogres.$B$BRight then! It''s all up to Fanny. Something tells me she won''t want to be tied down.$B$BFly back to Kirthaven and see if she''s game. I''ll finish up the nasty business with the ogres here.', `VerifiedBuild`=19034 WHERE `ID`=28407; -- The Bachelorette
UPDATE `quest_template` SET `RewardMoneyDifficulty`=4, `RewardBonusMoney`=57300, `AllowableRaces`=52430847, `QuestDescription`='I''ve written many an epic tune in my lifetime, $n, but this upcoming wedding deserves a very special ballad. And fast!$B$BShould I write a love song? A lighthearted ditty? A bawdy drinking song?$B$BI could use some help with the lyrics, if you fancy a go at it.$B$BTalk to me and we''ll write a song together!', `VerifiedBuild`=19034 WHERE `ID`=28413; -- Words and Music By...
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardChoiceItemID4`=0, `RewardChoiceItemQuantity4`=0, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28415; -- SEVEN! YUP!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `AllowableRaces`=18875469, `QuestDescription`='$n... is that you?  I thought you were dead, with the rest of them!$b$bNo, you were always strong, even back then, even in Redridge.$b$bOur fight''s not over, $n.  They already attacked our homeland once.  I''m here to make sure it doesn''t happen again.$b$bIf you can still fight like you did back in the day, then join me.  You can start by heading south, to the Whelping Downs, and slaying their whelpers and their hatchling black dragons.$b$bIt''ll be like old times.', `VerifiedBuild`=19034 WHERE `ID`=28416; -- Burning Vengeance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `Flags`=2097160, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (28419 /*Stocking Up*/, 28420 /*A Future Project*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `Flags`=2097160, `AllowableRaces`=33555378, `QuestDescription`='Hope you''re not afraid of getting dirty.  Judging by the looks of you, that won''t be a problem.$b$bTo the north, at the lava''s edge, you''ll find piles of dark mud.  I need it.$b$bIt''d be best if you didn''t ask questions, and focused your efforts on following orders, $n.', `VerifiedBuild`=19034 WHERE `ID`=28421; -- Mud Hunter
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=8, `AreaGroupID`=0, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28424; -- Shadow Boxing
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `Flags`=2097160, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28425; -- Return to Ariok
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `AllowableRaces`=33554464, `VerifiedBuild`=19034 WHERE `ID`=28429; -- A Perfect Costume
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=40800, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28433; -- Grunt Work
UPDATE `quest_template` SET `RewardBonusMoney`=51000, `AreaGroupID`=0, `AllowableRaces`=33555378, `QuestDescription`='<You hear a buzzing in your ear.>$b$b$n?  It''s Eitrigg.$b$bWe''ve just received the final bit of information for your next mission.  There are three marks that we''d like you to take down.  The first is Voodooist Timan, whom you''ll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.$b$bYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.', `VerifiedBuild`=19034 WHERE `ID`=28434; -- Strategic Cuts
UPDATE `quest_template` SET `Flags`=327688, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28435; -- The Kodocaller's Horn
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `Flags`=2621440, `AllowableRaces`=33555378, `QuestDescription`='$n, it''s Eitrigg.  I want you to hold onto that horn.  I''m sure we can improvise and find a way to work it into the plan.$b$bI''m more than a little concerned about what Kaoshin said about attacking Redridge.  We knew an attack was imminent, but not this soon!$b$bReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You''re not done with your undercover work yet.', `VerifiedBuild`=19034 WHERE `ID`=28436; -- Taking the Horn For Ourselves
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='$n?  Eitrigg here.$b$bIt sounds like you have earned Thorg''izog''s trust, and he''s assigned you to discipline duty.  This is fortunate.$b$bWe need you to take out his sergeants.  You''ll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You''ll have to act fast, because if they realize you''re not one of them, they can unmask you.  Strike quickly and ferociously, $n.', `VerifiedBuild`=19034 WHERE `ID`=28440; -- Abuse of Power
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=33555378, `QuestDescription`='I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we''re going to do this, we''re going to do it right, and that means being prepared.$b$bI need ash, $n.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the southeast.  The stuff is deep, deep black, which is what we need for our next disguise.$b$bDon''t worry, you''ve already got a disguise.  This one is for someone... well, someTHING... else.', `VerifiedBuild`=19034 WHERE `ID`=28443; -- Blackened Ashes
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='My legs are getting a little restless again.  You interested in taking a little tour, $n?$b$bWe''re going to take a trip around Dreadmaul Rock.  I''d like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we''re on the way.', `VerifiedBuild`=19034 WHERE `ID`=28446; -- Blood Tour
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=42300, `AllowableRaces`=33555378, `QuestDescription`='<You hear a buzzing in your ear.>$b$b$n.  It sounds like you and Ariok have finished with your tasks.  I''ve also finished mine.$b$bReturn to Flame Crest.  I''ve prepared a few packages to deliver to the Big Three: Thorg''izog, Neeralak, and Xi''lun.  You''ve already met General Thorg''izog.  This will be your chance to meet the other two.$b$bThat is, before you kill them.', `VerifiedBuild`=19034 WHERE `ID`=28449; -- Placing the Pawns
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `Flags`=3145736, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28451; -- A Delivery for Neeralak
UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=33555378, `QuestDescription`='$n, come in.  Can you read me?$b$bThe battle is about to start.  I hope you''ve delivered all of those packages.$b$bI need you here in Flame Crest, NOW.', `VerifiedBuild`=19034 WHERE `ID`=28453; -- Locked and Loaded
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AllowableRaces`=33555378, `QuestDescription`='This is it, $n.  A sad day... but a day in which the Blackrock orcs will learn a powerful lesson.  Today, our plan comes to fruition.$b$bCome with me.  We''re going to go talk to Acride and call in that favor that he owes us.  Then we''ll stop this invasion of Redridge before it even starts.', `VerifiedBuild`=19034 WHERE `ID`=28454; -- Assault on Dreadmaul Rock
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `Flags`=3145736, `AreaGroupID`=0, `AllowableRaces`=33555378, `QuestDescription`='You and my son are going back to that mountain.  There''s three orcs who survived the attack, and we won''t rest until they''re dead.$b$bThat''s right, I''m talking about the Big Three.$b$bGeneral Thorg''izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain''s peak.  Xi''lun is in the back of the Skull Warren, plotting with his fellow warlocks.$b$bLeave your mark, $n.  Topple these corrupt Blackrock orcs once and for all.', `VerifiedBuild`=19034 WHERE `ID`=28455; -- Glory Amidst Chaos
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity2`=1, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID` IN (28457 /*A Dangerous Alliance*/, 28461 /*The Golem Lord's Creations*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `ItemDropQuantity2`=1, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28458; -- The Pyromancer's Grimoire
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AllowableRaces`=33555378, `QuestDescription`='The Shattered Hand has discovered increased collaboration between Twilight''s Hammer and the Dark Iron dwarves in Blackrock Depths. We have an opportunity to strike at our enemies and empower ourselves, $n.$B$BTwilight''s Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!', `QuestCompletionLog`='Return to Kranosh in Orgrimmar''s Cleft of Shadow.', `VerifiedBuild`=19034 WHERE `ID`=28459; -- Stones of Binding
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity1`=1, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28463; -- The Dark Iron Army
UPDATE `quest_template` SET `RewardBonusMoney`=40800, `VerifiedBuild`=19034 WHERE `ID`=28464; -- Falling to Corruption
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity2`=1, `AllowableRaces`=33555378, `QuestCompletionLog`='Return to Terga Earthbreaker in Orgrimmar''s Valley of Wisdom.', `VerifiedBuild`=19034 WHERE `ID`=28465; -- Slaves of the Firelord
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `ItemDropQuantity1`=5, `AllowableRaces`=32, `VerifiedBuild`=19034 WHERE `ID`=28466; -- Weapons of Darkness
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=51000, `AreaGroupID`=0, `QuestDescription`='Very interesting, $n...$B$BWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.$B$BWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.', `VerifiedBuild`=19034 WHERE `ID`=28469; -- Winterfall Runners
