UPDATE `quest_template` SET `RewardBonusMoney`=1500, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (28551 /*Hero's Call: Southern Barrens!*/, 28702 /*Hero's Call: The Cape of Stranglethorn!*/);
UPDATE `quest_template` SET `RewardBonusMoney`=1980, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28552; -- Hero's Call: Dustwallow Marsh!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `AllowableRaces`=33555378, `QuestDescription`='I have one final dispatch to deliver to you, $n.  It comes from Dreadmaul Hold, to the south, in the Blasted Lands.$b$bWarmatron Okrilla is waging battle against the Alliance forces of Nethergarde Keep, and she needs the assistance of a stout $c.  You immediately sprung to mind.$b$bTravel south into the Blasted Lands, then head west.  Good luck, $n.', `VerifiedBuild`=19034 WHERE `ID`=28553; -- Okrilla and the Blasted Lands
UPDATE `quest_template` SET `RewardBonusMoney`=14400, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28556; -- Breaking the Hand
UPDATE `quest_template` SET `AllowableRaces`=33555378, `LogDescription`='Report to Arcanist Vandril at Tranquillien in the Ghostlands.', `QuestDescription`='All able bodied members of the Horde are hereby ordered to report to Arcanist Vandril at Tranquillien in the Ghostlands.$B$BYour help is needed to turn back the numberless Scourge invaders and secure the help of the Forsaken in fighting our common enemy.$B$BTo reach Tranquillien, follow the road south from Fairbreeze Square and into the Ghostlands.$B$BDestiny calls!', `VerifiedBuild`=19034 WHERE `ID`=28560; -- Warchief's Command: Ghostlands!
UPDATE `quest_template` SET `AllowableRaces`=18875469, `QuestDescription`='By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Horatio Laine at the Jansen Stead.$B$BWestfall has been overrun by beggars and transients, leading to a massive increase in criminal activity. Your help is needed to restore order to the populace. You can reach the Jansen Stead in Westfall by traveling west from Elwynn Forest.$B$BFor the glory and honor of the Alliance!', `VerifiedBuild`=19034 WHERE `ID`=28562; -- Hero's Call: Westfall!
UPDATE `quest_template` SET `RewardBonusMoney`=960, `Flags`=262152, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28564; -- Hero's Call: Duskwood!
UPDATE `quest_template` SET `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='<Melisara''s image appears before you.>$B$BThe Stormpike forward camp sits atop Corrahn''s Dagger, west of Sofera''s Naze. You must enter the camp and slaughter every dwarf that you see. They must be taught what it means to fear and there is no finer lesson than absolute decimation.$B$BNo survivors, $n. Even their captain - especially their captain - must die.$B$BI will be in contact.', `VerifiedBuild`=19034 WHERE `ID`=28566; -- Decimation
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=4350, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28570; -- The Bogpaddle Bullet
UPDATE `quest_template` SET `RewardBonusMoney`=2640, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28578; -- Hero's Call: Eastern Plaguelands!
UPDATE `quest_template` SET `RewardBonusMoney`=3750, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28582; -- Hero's Call: Searing Gorge!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=52430847, `QuestDescription`='This new shredder design is tops, $n. Tops! Next step is to protect my intellectual property. There are patents to file, traders to mark, ceases to desist. Oh, and the bribes!$B$BHere, take this patent application to Captain Krazz at the Krazzworks. He survived the destruction of his zeppelin, so he''s probably hungry for new business opportunities.$B$BThe Krazzworks is due north of here, atop a perfectly safe mountain peak. Go ahead, kid. Chop chop!', `VerifiedBuild`=19034 WHERE `ID`=28583; -- Krazzworks
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='This jerk across from me is getting all of our people killed!$B$BBrett "the Bummer" unpacked the Krazzworks in the wrong place and now it''s highly unstable. The explosions from the instability are throwing our laborers off of the platforms and into the water below.$B$BYou don''t mind flying down there and rescuing them with some pool ponies, $n?', `VerifiedBuild`=19034 WHERE `ID`=28586; -- Pool Pony Rescue
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='I will study the Stormpike battle plans and prepare for an assault. I need you to go to Alterac Valley and enlist the aid of the Frostwolf Clan: the very clan of our former warchief, Thrall. They will help us battle the Stormpike dwarves! Together, we will crush the invaders and see them driven out of Lordaeron for good!$B$BGo now, $n. Alterac Valley is northeast of Tarren Mill. Find Voggah Deathgrip and tell him that the Horde requires the aid of the Frostwolf!$B$BLOK''TAR!', `VerifiedBuild`=19034 WHERE `ID`=28587; -- Aid of the Frostwolf
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `Flags`=1310856, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28590; -- Reprisal
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `Flags`=16777352, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28591; -- Off The Wall
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `Flags`=136, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28593; -- Of Utmost Importance
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `Flags`=1048712, `AllowableRaces`=52430847, `QuestDescription`='Har! We get to jump right inta the action, $n. Looks like Highbank has whatcha call a zeppelin problem: that airship is poundin'' the crap outta the walls.$B$BListen, I''ve got me an idear so stupid it''s genius. I just need some cannon powder.$B$BCollect as much as you can find around Highbank an'' meet me by the trade area!', `VerifiedBuild`=19034 WHERE `ID`=28597; -- Burnin' at Both Ends
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=95400, `AllowableRaces`=52430847, `QuestDescription`='Lookie here, $n. I found the biggest gun in Highbank! We''re gonna try a technique handed down ta me by my pappy, from his pappy, from his pappy, shortly before he got blowed up.$B$BIt''s called the "$c-shot."$B$BYou take a $r $c, and load $ghim:her; inta a gigantic cannon, and then ya - oh relax. This usually works.$B$BTake these explosives, then wait here next ta me. As soon as that blimpy comes around I''ll blast you onto tha deck. Plant the explosives in ''er belly and, oh I dunno, make it up as you go.', `VerifiedBuild`=19034 WHERE `ID`=28598; -- Aiming High
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=52430847, `QuestDescription`='It looks like the attack stopped, $n. Which is a shame, ''cuz we never got to use the $c-rocket.$B$BAnyways, Kurdran Wildhammer is up in the top of the keep an'' I''m sure he''ll be wantin'' to gives ya a hero''s welcome. Yeh earned it! Go talk to ''im!$B$BI''ll move on ahead and scout out the beach.', `VerifiedBuild`=19034 WHERE `ID`=28599; -- Kurdran's Waitin'
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `StartItem`=0, `Flags`=16777352, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28602; -- Be Prepared
UPDATE `quest_template` SET `Flags`=7929856, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28603; -- Infiltration
UPDATE `quest_template` SET `Flags`=4194304, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28604; -- Deception and Trickery
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='I''m pleased to see that you''re up and walking around, $n.  You''ve held up nicely, especially after being dead for so long!$b$bOthers weren''t as lucky.  If you wouldn''t mind, I need you to fetch my embalming fluid and some twine to stitch up these bodies.  You''ll find both in the Shadow Grave, the building just behind me.$b$bHere, Darnell will join you.  He knows the way.', `VerifiedBuild`=19034 WHERE `ID`=28608; -- The Shadow Grave
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='Ah, I can already see more clearly, $n.$B$BWe are right to be wary of the evil Neferset.  I can already sense that they''re behind the forces that corrupt the river.$B$BGo underwater once more and find the Murkdeep Cavern.  You will find the Neferset are performing a foul ritual of corruption.$B$BStop them so the river is cleansed once again.', `VerifiedBuild`=19034 WHERE `ID`=28611; -- The Defilers' Ritual
UPDATE `quest_template` SET `RewardBonusMoney`=94500, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28612; -- Harrison Jones and the Temple of Uldum
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `AllowableRaces`=52430847, `QuestDescription`='Before we continue, let us have a moment of silence for our fallen brother, Orkus, for without him, we would have been destroyed by the Stormpike onslaught. This is for you, brother!$B$B<Cromush takes a knee.>$B$BNow, $n, do not think that I forgot your part in all of this! That is why you get the honors of detonating the goblin pocket-nukes.$B$BAre you ready? FOR THE HORDE!', `VerifiedBuild`=19034 WHERE `ID`=28616; -- Stormpike Apocalypse
UPDATE `quest_template` SET `RewardBonusMoney`=1200, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28619; -- Warchief's Command: Arathi Highlands!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38100, `AllowableRaces`=52430847, `QuestDescription`='Our work is done here, $n.  Against all odds, we stopped the Neferset advance on Nahom.$B$BLet us join the forces pushing west, lest they take all the glory for themselves.$B$BThey must''ve reached the outskirts of Neferset City by now.', `VerifiedBuild`=19034 WHERE `ID`=28623; -- The Push Westward
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=54900, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28625; -- Chop Chop
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=8, `QuestDescription`='My friends are always coming up with great ideas. I''ve never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I''ll let you in on the secret... $B$BI''m going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they''ll be impressed!$B$BI need thick yeti fur from the Ice Thistle yeti. There''s plenty of them in the Ice Thistle Hills to the southeast.', `VerifiedBuild`=19034 WHERE `ID`=28629; -- Are We There, Yeti?
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `Flags`=134217736, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=28631; -- The Perfect Horns
UPDATE `quest_template` SET `RewardMoneyDifficulty`=7, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28639; -- Ursius
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=57000, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28640; -- Fresh Frostsabers
UPDATE `quest_template` SET `RewardMoneyDifficulty`=8, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28647; -- The Durnholde Challenge: D-1000
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardTalents`=0, `QuestDescription`='We got here, tore the place apart, and headed toward the prison house. We weren''t expecting what we found in there, $n. Seems the Crusade''s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there''s a real feisty worgen in there that I think you''ll take great pleasure in executing.', `VerifiedBuild`=19034 WHERE `ID`=28649; -- A Special Surprise
UPDATE `quest_template` SET `QuestInfoID`=21, `RewardMoneyDifficulty`=5, `RewardTalents`=0, `QuestDescription`='We got here, tore the place apart, and headed toward the prison house. We weren''t expecting what we found in there, $n. Seems the Crusade''s been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.$B$BI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there''s a real feisty goblin in there that I think you''ll take great pleasure in executing.', `VerifiedBuild`=19034 WHERE `ID`=28650; -- A Special Surprise
UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='Are you still here, $n?  You know, I''m only a deathguard.  I don''t have many tasks I can hand out to passers-by like you.$b$bI''d recommend that you talk to Shadow Priest Sarvis.  I remember, he helped me get on my feet after I was plucked out of that tomb.  I''m sure he''ll do the same for you.$b$bYou''ll find him just inside the chapel, here on the west side of town.', `VerifiedBuild`=19034 WHERE `ID`=28653; -- Shadow Priest Sarvis
UPDATE `quest_template` SET `RewardMoney`=86000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=75600, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28654; -- The Heart of the Matter
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=95400, `AllowableRaces`=52430847, `QuestDescription`='We are ready to begin, $n!$B$BBut I have it on good authority that the Twilight''s Hammer may try to disrupt the ceremony, so as to demoralize and destroy the Wildhammer. Things could get dangerous!$B$BFor this reason, I will be performing the ceremony myself, so that I can keep the bride and groom close to me. Sound like a plan? Good!$B$BSince her father is dead and her brother the best man, Fanny has asked that you walk her down the aisle. What an honor! Talk to me when you''re ready to begin.', `VerifiedBuild`=19034 WHERE `ID`=28655; -- Wild, Wild, Wildhammer Wedding
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=52800, `VerifiedBuild`=19034 WHERE `ID`=28656; -- Strange Life Forces
UPDATE `quest_template` SET `Flags`=262152, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID` IN (28666 /*Hero's Call: Burning Steppes!*/, 28673 /*Hero's Call: Blasted Lands!*/, 28675 /*Hero's Call: Swamp of Sorrows!*/);
