UPDATE `quest_template` SET `AllowableRaces`=33555378, `QuestDescription`='All able bodied members of the Horde are hereby ordered to report to Lieutenant General Orion at the Stair of Destiny.$B$BYour skills are needed to fight the Burning Legion''s presence on the shattered remnants of Outland.$B$BGo to Orgrimmar''s Cleft of Shadow and use the portal near the mage trainers to reach Hellfire Peninsula.$B$BDestiny calls!', `VerifiedBuild`=19034 WHERE `ID`=28705; -- Warchief's Command: Outland!
UPDATE `quest_template` SET `Flags`=262152, `AllowableRaces`=18875469, `QuestDescription`='By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Commander Duron in Hellfire Peninsula.$B$BThe expeditionary forces require your help to overcome the demonic armies of the Burning Legion! Use the portal on the middle level of the tower in the Mage District to travel to the Stair of Destiny in Outland.$B$BFor the glory and honor of the Alliance!', `VerifiedBuild`=19034 WHERE `ID`=28708; -- Hero's Call: Outland!
UPDATE `quest_template` SET `RewardBonusMoney`=6600, `Flags`=262152, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28709; -- Hero's Call: Northrend!
