UPDATE `quest_template` SET `RewardBonusMoney`=6600, `Flags`=262152, `AllowableRaces`=33555378, `VerifiedBuild`=19034 WHERE `ID`=28711; -- Warchief's Command: Northrend!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `FlagsEx`=512, `QuestDescription`='Greetings, $n. I am Ilthalaine. My purpose in Shadowglen is to train young $cs like you and to ensure that the balance of nature is maintained.$b$bThe spring rains were particularly heavy this year, causing some of the forest''s beasts to flourish while others suffered. Unfortunately, the nightsaber numbers grew too large, and they will devastate the other populations if they are not culled.$B$BJourney forth, young $c, and thin saber populations so that nature''s harmony will be preserved.', `VerifiedBuild`=19034 WHERE `ID`=28713; -- The Balance of Nature
UPDATE `quest_template` SET `QuestPackageID`=600, `RewardMoneyDifficulty`=5, `Flags`=524288, `RewardChoiceItemID1`=0, `RewardChoiceItemID2`=0, `RewardChoiceItemID3`=0, `RewardChoiceItemQuantity1`=0, `RewardChoiceItemQuantity2`=0, `RewardChoiceItemQuantity3`=0, `AllowableRaces`=2147483647, `VerifiedBuild`=19034 WHERE `ID`=28714; -- Fel Moss Corruption
UPDATE `quest_template` SET `RewardBonusMoney`=7500, `AllowableRaces`=33555378, `LogDescription`='Report to Vol''jin at Grommash Hold in Orgrimmar.', `QuestDescription`='All able-bodied members of the Horde are hereby ordered to report to Vol''jin in Grommash Hold.$B$BThe Warchief requires your help to prepare for the glorious assault on the Twilight Highlands and our dual enemies, the Alliance and Twilight''s Hammer.$B$BMeet with the Warchief in Grommash Hold at the center of Orgrimmar''s Valley of Strength.$B$BDestiny calls!', `VerifiedBuild`=19034 WHERE `ID`=28717; -- Warchief's Command: Twilight Highlands!
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=57000, `AllowableRaces`=52430847, `QuestDescription`='Many find the meat of the Shardtooth bears to be too gamy for their taste. I disagree, though I''m not one to judge the tastes of others.$b$bThe Shardtooth Maulers, however - their brown-furred cousins, to the south - have much more tender flesh, particularly in their paws. And I''ve heard that the snout is also considered a delicacy.$b$bContinue your hunt, $n. Let''s see if you can bag those maulers for ol'' Francis.', `VerifiedBuild`=19034 WHERE `ID`=28719; -- A Little Gamy
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=66000, `QuestDescription`='It''s all ready, $n!$B$BNow, I told my friend Legacki that I have a surprise for her. This is where you come in!$B$BI''m going to give you my mechanical yeti, and you''ll get the honor of using it to surprise her. She''s just on the other side of Everlook, near the inn.$B$BGo up to her and turn the yeti on... I''ll be watching from here!', `VerifiedBuild`=19034 WHERE `ID`=28722; -- Yetiphobia
