UPDATE `quest_template` SET `QuestSortID`=6066, `AllowableRaces`=52430847, `QuestDescription`='In life, my brothers and I fought against all the forces of the Scourge, but none were so reviled as the necromancers. It was not enough for them raise our dead comrades and send them against us; no, they created twisted golems of bone with scythes for hands.$B$BThese aberrations slew many of my brothers, and yet we could not destroy them all. I ask you, $n, to carry on the task of the fallen. Venture into the Ossuary of Scholomance and slay the largest and most dangerous of these abominable creatures.', `VerifiedBuild`=19034 WHERE `ID`=28756; -- Aberrations of Bone
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `PortraitGiver`=40147, `LogDescription`='Kill 6 Blackrock Worgs.', `QuestDescription`='So you''re the new recruit from Stormwind, eh? I''m Marshal McBride, commander of this garrison. Glad to have you on board...$B$B<McBride looks through some papers.>$B$B$n. It is $n, right?$B$BYou''ve arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.$B$BHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!', `PortraitGiverText`='Blackrock Battle Worgs are fierce predators.', `VerifiedBuild`=19034 WHERE `ID` IN (28757 /*Beating Them Back!*/, 28762 /*Beating Them Back!*/, 28765 /*Beating Them Back!*/, 28766 /*Beating Them Back!*/);
