UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `AllowableRaces`=1, `QuestDescription`='While you were out training I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, $n!$B$BFind Sergeant Willem north of the abbey at the command tent. Go!', `VerifiedBuild`=19034 WHERE `ID` IN (28780 /*Join the Battle!*/, 28784 /*Join the Battle!*/, 28785 /*Join the Battle!*/, 28786 /*Join the Battle!*/, 28787 /*Join the Battle!*/, 28788 /*Join the Battle!*/, 28789 /*Join the Battle!*/);
