UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `AllowableRaces`=1, `QuestDescription`='Have you ever seen a goblin, $n? They''re wretched little green-skinned monsters that love only two things: gold and themselves.$B$BThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.$B$BI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!', `VerifiedBuild`=19034 WHERE `ID` IN (28791 /*They Sent Assassins*/, 28792 /*They Sent Assassins*/, 28793 /*They Sent Assassins*/, 28794 /*They Sent Assassins*/, 28795 /*They Sent Assassins*/, 28796 /*They Sent Assassins*/, 28797 /*They Sent Assassins*/);
UPDATE `quest_template` SET `RewardBonusMoney`=73200, `Flags`=136, `AllowableRaces`=52430847, `QuestDescription`='Greetings, $n.$b$bYes, you are known to the Earthen Ring by name.$b$bYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.$b$bI am but a messenger. A familiar presence seeks audience with you.$b$bPeer into the Waters of Farseeing and behold the fate of our world.', `VerifiedBuild`=19034 WHERE `ID`=28805; -- The Eye of the Storm
