UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `Flags`=786432, `AllowableRaces`=1, `QuestDescription`='Excellent work, $n! The rear is now officially clear. We''ll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.$B$BFarewell, $c.', `VerifiedBuild`=19034 WHERE `ID` IN (28817 /*The Rear is Clear*/, 28818 /*The Rear is Clear*/, 28819 /*The Rear is Clear*/, 28820 /*The Rear is Clear*/, 28821 /*The Rear is Clear*/, 28822 /*The Rear is Clear*/, 28823 /*The Rear is Clear*/);
UPDATE `quest_template` SET `Float10`=0.25, `RewardMoney`=90000, `RewardMoneyDifficulty`=8, `Float13`=0.25, `RewardBonusMoney`=38100, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='One of my children is not with me, $n.$B$BHe stayed behind with the Twilight''s Hammer at the Stonecore deep within the Temple of Earth.$B$BI sent my other children to free him from the dark magic that was surely keeping him from returning here, but... no such magic was placed upon him.$B$BGo into the Stonecore and destroy Ozruk.  He must be reclaimed by the earth.', `VerifiedBuild`=19034 WHERE `ID`=28824; -- Wayward Child
UPDATE `quest_template` SET `RewardBonusMoney`=73200, `Flags`=136, `AllowableRaces`=52430847, `QuestDescription`='Greetings, hero of Azeroth.$b$bWe of the Earthen Ring know you by name, $n.$b$bYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.$b$bI am but a messenger. A powerful presence seeks audience with you.$b$bPeer into the Waters of Farseeing and behold the dilemma of our world.', `VerifiedBuild`=19034 WHERE `ID`=28826; -- The Eye of the Storm
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `QuestDescription`='My mysterious benefactors gave me more than one task. The second task took me farther south, to the Frostwhisper Gorge. I was surprised to learn that the gorge''s bridge had been broken in two, preventing land travel from one side to the other.$b$bIn addition, the juvenile Frostmaul tumblers were separated from their stronger adult parents. I thought that I could defeat them in battle.$b$bI was incorrect. I was forced to run away in shame.$b$bTeach these tumblers a lesson, $n. Fight them, and win.', `VerifiedBuild`=19034 WHERE `ID`=28830; -- Chips off the Old Block
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardChoiceItemID1`=67172, `RewardChoiceItemID2`=67189, `RewardChoiceItemID3`=67206, `RewardChoiceItemID4`=67221, `RewardChoiceItemID5`=0, `RewardChoiceItemQuantity5`=0, `AreaGroupID`=0, `VerifiedBuild`=19034 WHERE `ID`=28831; -- Damn You, Frostilicus
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=82000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=74700, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28833 /*Rescue the Earthspeaker!*/, 28834 /*Rescue the Earthspeaker!*/, 28836 /*Sins of the Sea Witch*/, 28843 /*Sins of the Sea Witch*/);
UPDATE `quest_template` SET `AllowableRaces`=52430847, `QuestDescription`='I don''t want our gambit to fail, $n. Such a failure would only draw attention to our efforts, giving Umbranse an opportunity to hone his defenses. No, we have to do this right the first time.$b$bThe Frostwhisper Gorge, to the south, provides us access to powerful ice elementals. The water within these elementals'' hulls should amplify the power of your dreamcatcher, ensuring our efforts.$b$bObtain this water, $n. Then return to our small camp.', `VerifiedBuild`=19034 WHERE `ID`=28840; -- Winterwater
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=94000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `AreaGroupID`=0, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID` IN (28853 /*Kill the Courier*/, 28854 /*Closing a Dark Chapter*/, 29168 /*Secondary Targets*/, 29172 /*The Beasts Within*/, 29173 /*Secondary Targets*/, 29175 /*Break Their Spirits*/, 29241 /*Break the Godbreaker*/, 29242 /*Putting a Price on Priceless*/);
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=24300, `Flags`=262152, `AllowableRaces`=18875469, `VerifiedBuild`=19034 WHERE `ID`=28857; -- Blasted Lands: The Other Side of the World
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=76500, `AllowableRaces`=52430847, `QuestDescription`='<Blundy upends his cup.>$B$BI''m all outta ale, $n!$B$BHead out into the Thundermar Ruins and see if there''s any left, before those grungy Dragonmaw get their mouths on it.$B$BFeel free to have a few sips, yerself. A mug of ol'' Thundermar''s finest will fortify yer fightin'' skills.', `VerifiedBuild`=19034 WHERE `ID`=28861; -- Fight Like a Wildhammer
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=95400, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='He''s at it again, $n. Warlord Halthar... terror of the shire. He and his drake were spotted causing trouble to the south, among the Thundermar Ruins.$B$BKill Halthar, $n! We''ll send in some warbrands to help out once you engage.', `VerifiedBuild`=19034 WHERE `ID`=28863; -- Warlord Halthar is Back
UPDATE `quest_template` SET `RewardBonusMoney`=11700, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=28865; -- Call of the Warmatron
UPDATE `quest_template` SET `RewardMoneyDifficulty`=6, `RewardBonusMoney`=95400, `AreaGroupID`=0, `AllowableRaces`=52430847, `QuestDescription`='Our scouts in the field report that High Shaman MacKilligan has moved out of Thundermar and is fighting amidst the Thundermar Ruins northwest of here, across the river.$B$BHe''s a dangerous one, $n, responsible for the deaths of many a Dragonmaw. He WILL be destroyed, that is not the question.$B$BThe question is: will you be the one to earn the glory of the kill?', `VerifiedBuild`=19034 WHERE `ID`=28875; -- Bring Down the High Shaman
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `AllowableRaces`=52430847, `QuestDescription`='There''s an orc who lives in the west. At the frayed edge of the cataclysm''s swath of destruction.$B$BThey call him Swiftdagger, $n. They call him that because ... his ... actually I think that''s just his name.$B$B<Nozzlepot shrugs.>$B$BAnyway, he''s a harpy-killing machine. He kills harpies. Loves it. It''s a living. Go and see him! See how it''s done. Live the dream. You might make a career out of it.', `VerifiedBuild`=19034 WHERE `ID`=28877; -- They Call Him Swiftdagger. He Kills Harpies.
UPDATE `quest_template` SET `RewardChoiceItemID1`=116202, `RewardChoiceItemQuantity1`=1, `QuestDescription`='We had the best time with you, $n. We wish you could be our $g daddy : mama; now, but you have to take us back to Orphan Matron Aria in Dalaran.$B$BMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!$B$BWe going to miss you, $n. We promise to write letter sometime, oki? ', `VerifiedBuild`=19034 WHERE `ID`=28879; -- Back To The Orphanage
UPDATE `quest_template` SET `RewardChoiceItemID1`=116202, `RewardChoiceItemQuantity1`=1, `QuestDescription`='Know what? You not so bad after all, $n. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.$B$BYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.$B$BKekek gotta go back to orphan-lady Aria now, back in purple human city.', `VerifiedBuild`=19034 WHERE `ID`=28880; -- Back To The Orphanage
