UPDATE `quest_template` SET `QuestDescription`='Potions, potions, potions.  Can I teach you about potions!$b$bYou''re going to have to bring me samples of your work, so I know you''re ready.$b$bRemember $n, you can only learn ONE specialization, so if you complete your potion training, then elixir and transmutation specialization will no longer be available.', `VerifiedBuild`=19034 WHERE `ID`=29067; -- Potion Master
