UPDATE `quest_template` SET `QuestDescription`='Elixirs are all about potency!  If you want to become an elixir master, I can teach you.$b$bI can''t just train anyone, and I require proof that you are devoted before we continue.  Several flasks should be sufficient to show your dedication.$b$bRemember $n, you can only learn ONE specialization, so if you complete your elixir training, then potion and transmutation specialization will no longer be available.', `VerifiedBuild`=19034 WHERE `ID`=29481; -- Elixir Master
UPDATE `quest_template` SET `QuestDescription`='Iron to gold, water to fire... if you want to become an transmutation master, then I can show you the way.$b$bThe training is very expensive, so you''ll have to bring me some of the finest transmuted materials in the world.$b$bRemember $n, you can only learn ONE specialization, so if you complete your transmutation training, then potion and elixir specialization will no longer be available.', `VerifiedBuild`=19034 WHERE `ID`=29482; -- Transmutation Master
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `Flags`=0, `QuestCompletionLog`='Return to Professor Thaddeus Paleo at the Darkmoon Faire.', `VerifiedBuild`=19034 WHERE `ID`=29507; -- Fun for the Little Ones
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `QuestDescription`='People don''t just come to the faire for fun and fortunes, $n. Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets.$B$BFor that, I need a steady supply of soothsayer''s dust. Take a look around the grounds and you''ll see a lot of discarded weapons. Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?', `VerifiedBuild`=19034 WHERE `ID`=29510; -- Putting Trash to Good Use
UPDATE `quest_template` SET `RewardBonusMoney`=9300, `QuestDescription`='Working the Darkmoon Faire is a dangerous job, $n. It''s no surprise that many of our workers get injured setting up, taking down, and transporting all of its attractions.$B$BSome of the injured workers can be found around here, near the wagons. Others have gone to the healing tent for treatment. Would you take these bandages and see if you can help any of the injured workers?', `VerifiedBuild`=19034 WHERE `ID`=29512; -- Putting the Carnies Back Together Again
