UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=6300, `AllowableRaces`=18875469, `QuestDescription`='I''m a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen.$B$BDo they call me those things? No.$B$BBut you have one run-in with an ethereal and all of the sudden everyone and their mother calls you "the mad".$B$BI saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!', `VerifiedBuild`=19034 WHERE `ID`=29583; -- Eckert the Mad
