UPDATE `quest_template` SET `RewardBonusMoney`=6300, `QuestDescription`='You''ve had quite an adventure, $n. And before you''ve even set foot inside of the Auchenai Crypts.$B$BI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar''s vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.$B$BWhat I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.', `VerifiedBuild`=19034 WHERE `ID`=29595; -- Everything Will Be Alright
