UPDATE `quest_template` SET `RewardBonusMoney`=6600, `AllowableRaces`=18875469, `QuestDescription`='Welcome to Northrend, $n. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there.$B$BRide the gryphon to Dalaran and once you land, make your way to our inn there, A Hero''s Welcome. Find Isirami Fairwind and speak with her immediately.$B$BShe can help you bind your hearthstone to the city so you can use the Silver Enclave''s portal to travel back to Stormwind quickly.', `VerifiedBuild`=19034 WHERE `ID`=29608; -- Allies in Dalaran
