UPDATE `quest_template` SET `RewardBonusMoney`=142800, `QuestDescription`='With this tournament we grow ever closer to our final confrontation with the Lich King.$B$B$n, fight with valor and honor. Every fighter here has gathered for the common good.$B$BTogether, we will stop Arthas!', `VerifiedBuild`=19034 WHERE `ID`=29851; -- Champion of the Tournament
