UPDATE `quest_template` SET `RewardMoneyDifficulty`=2, `RewardBonusMoney`=19200, `Flags`=8388608, `AllowableRaces`=52430847, `QuestDescription`='If the egg is in Ravenholdt Manor, we can''t risk torching it in an all-out assault. I''ll need someone slippery to get in there and find out for sure.$B$BThat''s you, $n.$B$BMostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!', `VerifiedBuild`=19034 WHERE `ID`=29934; -- To Ravenholdt
UPDATE `quest_template` SET `Flags`=9437184, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=30092; -- Our Man in Gilneas
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `Flags`=13631488, `AllowableRaces`=52430847, `QuestDescription`='The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out.$B$BOnly a surgical assassination can end this!$B$BThe bridge behind me is relatively unguarded. Slip in through merchant''s square and head south - you''ll find Creed in the middle of the military district.$B$BI''ll keep an eye on you and pull you out if there''s any trouble.$B$B...There WILL be trouble!', `VerifiedBuild`=19034 WHERE `ID`=30093; -- Assassinate Creed
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7800, `AllowableRaces`=33555378, `QuestDescription`='Nozdormu, the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details.$b$bIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.$b$bHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.', `VerifiedBuild`=19034 WHERE `ID`=30094; -- The End Time
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7800, `AllowableRaces`=18875469, `QuestDescription`='Nozdormu, the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details.$b$bIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.$b$bHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.', `VerifiedBuild`=19034 WHERE `ID`=30095; -- The End Time
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=94000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `QuestDescription`='If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me.$b$bThe creature that blocks us from accessing this time passage is named Murozond. He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing.$b$bThis is why you were brought here, $n.', `VerifiedBuild`=19034 WHERE `ID`=30096; -- Murozond
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=94000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `QuestDescription`='From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us.$b$bWe believe that the most interesting and valuable elements of this future are the powerful "echoes" that roam the dragonshrines.$b$bTake this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight''s depository.', `VerifiedBuild`=19034 WHERE `ID`=30097; -- Archival Purposes
UPDATE `quest_template` SET `RewardMoneyDifficulty`=1, `RewardBonusMoney`=7800, `VerifiedBuild`=19034 WHERE `ID` IN (30098 /*The Well of Eternity*/, 30102 /*The Hour of Twilight*/);
