UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=71000, `RewardMoneyDifficulty`=4, `RewardBonusMoney`=77100, `VerifiedBuild`=19034 WHERE `ID`=30103; -- To Wyrmrest!
UPDATE `quest_template` SET `RewardXPDifficulty`=5, `RewardMoney`=94000, `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `QuestDescription`='You... $n, was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative.$b$bI require more information for our archive. While you and Nozdormu don''t intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data.$b$bI require information on Captain Varo''then, one of Azshara''s pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?', `VerifiedBuild`=19034 WHERE `ID`=30104; -- Documenting the Timeways
UPDATE `quest_template` SET `RewardMoneyDifficulty`=3, `RewardBonusMoney`=38700, `Flags`=11534336, `AllowableRaces`=52430847, `VerifiedBuild`=19034 WHERE `ID`=30106; -- The Deed is Done
UPDATE `quest_template` SET `RewardMoneyDifficulty`=5, `RewardBonusMoney`=77100, `Flags`=44040192, `AllowableRaces`=52430847, `QuestDescription`='The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind.$B$BI need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight''s Hammer to control the most powerful of elementals.$B$BA great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing''s minions and bring the gems to me.', `VerifiedBuild`=19034 WHERE `ID`=30107; -- Cluster Clutch
